INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('ff057d86-47bc-de16-f0f9-a7b808b968e3', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', NULL, 'AI 生成候选（n3 · 文字词汇）', 'AI 批量生成的待审核知识点分类。', '导入后需人工审核。', '', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('0035e544-a81a-5e7a-9233-bc5a75ee07e9', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '1af448c1-54cf-2f94-01b5-e8bc77a97f94', '～ないこともない（也不是不…）', '双重否定，表示“也不是完全不…”，比～ないことはない更委婉，常表示有保留的肯定。', '与～ないことはない混淆，本句型语气更弱；接续为动词ない形+こともない。', '日本語：彼の気持ちも分からないこともないが、やはり許せない。；说明：表示并非完全不能理解，但仍有保留。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('0090a02c-babe-50eb-9147-3ff0df10c23b', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '2c18e7e1-4ef0-65e3-24a7-6c97d562a122', '～（よ）うが～（よ）うが', '表示无论前项如何，后项都不受影响，相当于「～ても～ても」。接续：动词意志形＋が＋动词意志形＋が。', '注意前后两项常为对立或对比关系，且后项多为否定或不受影响的表达。', '雨が降ろうが風が吹こうが、試合は決行する。；说明：无论下雨还是刮风，比赛都照常进行。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('00b044e6-f51e-5736-b4cb-8ddc113b8bfa', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', 'ff057d86-47bc-de16-f0f9-a7b808b968e3', '同源词族（如「決める/決まる/決定」）', '识别N3中由同一汉字或词根派生出的词族，如「決める（他動詞）」「決まる（自動詞）」「決定（名詞）」，理解其词性和用法差异。', '将名词直接当动词用，如「決定する」误作「決定」；混淆自他动词的语态。', '日语例句：会議で日程を決めた。日程が決まった。；说明：決める是他动，決まる是自动。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('00f3b410-2202-589e-b627-2f0a73fb97d9', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '1af448c1-54cf-2f94-01b5-e8bc77a97f94', '～てはいけない（禁止・规则）', '表示禁止，语气较强，多用于规则、规定。与已有「～てはいけない（禁止）」重复？但本条目侧重与「～てはならない」「～ないでください」的语感差异。', '「～てはならない」更书面、更严肃；「～ないでください」是请求，语气较软。', '日本語例：ここにゴミを捨ててはいけません。；说明：禁止在此扔垃圾。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('00fcbce0-1f3b-5712-94dd-d0c0a41451bf', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '1d183755-02b3-4a6d-b727-082af1ef377c', '6f1477f5-00be-f963-76b6-5165f568e88e', '否定疑问句理解', '理解“ではないか”“ではないだろうか”等否定疑问句在文中常表示肯定或委婉的提议、反问，而非单纯的否定疑问。', '按字面理解为否定疑问，误解作者意图。', '日语例句：この問題について、もう一度考えてみてはどうだろうか。说明：实际是提议“再考虑一下”，带有建议语气。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('01040cba-4032-54fd-b876-df4766196837', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '2c18e7e1-4ef0-65e3-24a7-6c97d562a122', '～というまでもなく', '表示“不用说～”，后接当然的结果或众所周知的事实，用于加强语气。接名词或动词辞书形。', '与「～までもなく」混淆，后者更强调“没必要做”；此句型强调“当然”。', '言うまでもなく、健康が一番大切だ。；说明：不用说，健康最重要。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('012a00b4-d6e1-564c-976d-73b4f6dc3e6c', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '0545d0ec-89d1-a8aa-99f9-78b30fcbacb1', '词族派生（接头辞・接尾辞）', '理解N2常见接头辞（如「非」「無」「再」）和接尾辞（如「～的」「～性」「～化」）的意义，能推测派生词的含义。', '忽视接尾辞带来的词性变化，如「経済的」是形容动词；或混淆「無」与「非」的细微差别。', '日语例句：この問題は非現実的だ。；说明：「非」表示否定，「的」使名词变为形容动词。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('017f04a6-6151-517a-8651-61ea06a0214e', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', 'dd4e968a-3d37-98a7-3819-a5fc4c117122', '～てはだめ（不可以…）', '口语中表示禁止，比～てはいけない更随意，常用于家人朋友之间。接续：动词て形＋は＋だめ。', '在正式场合使用显得失礼；误用为～てはいい；与～てはいけない混淆。', 'ここで遊んではだめ。说明：不可以在这里玩。／触ってはだめだよ。说明：不可以碰哦。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('0182cf6f-8d05-5e3d-950c-eb8bbce491e9', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', 'ff057d86-47bc-de16-f0f9-a7b808b968e3', 'N3动词て形与补助动词的组合（扩展）', '掌握「～ている」「～てある」「～ておく」「～てしまう」「～てみる」「～てほしい」等组合的用法和区别。', '混淆「～てある」与「～ておく」，前者表示状态，后者表示事先准备。', '日语例句：窓が開けてある。；说明：「てある」表示有人预先打开的状态。；日语例句：旅行の前に切符を買っておきます。；说明：「ておく」表示事先做好。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('0186c9bf-e9db-56d4-9a6b-78192b325f20', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '1af448c1-54cf-2f94-01b5-e8bc77a97f94', '～てあるか（状态存续・确认）', '以疑问形式确认某状态是否已准备好。接续：动词て形+あるか。多用于口语。', '与～てある（状态存续）混淆，该形式带确认语气。注意～てあるか常与～ておく对应。', '日本語：部屋の掃除はしてあるか。；说明：确认“房间打扫好了吗？”', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('0200cd4f-a928-54eb-922a-f65e8630c7b9', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '1d183755-02b3-4a6d-b727-082af1ef377c', 'fc58533f-fd29-5132-8f21-fd381828e3c8', '区分意见与事实', '在阅读中识别作者的主观意见（〜と思う、〜べきだ）与客观事实（〜だ、〜である）的表述。', '将作者意见当作事实；忽略「〜かもしれない」等推测表达。', '日语例句：この町は人口が減っている。これは事実だ。しかし、将来は増えるかもしれない。说明：前句为事实，后句为推测意见。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('0228716f-e19a-59c9-81f8-2f07ab5fb6e3', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', 'ff057d86-47bc-de16-f0f9-a7b808b968e3', 'N3表达意图和打算的词汇（扩展）', '掌握「つもり」「予定」「つもりでいる」「～ようと思う」等表达意图的词汇，注意「つもり」与「予定」的区别。', '将「つもり」用于客观预定，如说「明日雨が降るつもり」；应使用「予定」或「らしい」。', '日语例句：来年留学するつもりです。；说明：「つもり」表示个人打算。；日语例句：会議は3時からの予定です。；说明：「予定」表示日程安排。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('02915e57-917c-5cee-8f59-1ae82e246434', '9221fc32-a051-42cb-86b1-6a9917aa004e', '42de0c7b-50d9-4159-918a-4e618d83342d', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', 'ef36118d-0ba3-29ce-b2b3-76eaeb6542ca', 'なくてもいい（不必）', '动词ない形去い+くてもいい表示不必做某事。接续：ない形+くてもいい。', '与なければならない混淆；误用为禁止。', '明日来なくてもいいです。说明：明天不来也可以。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('03610a70-f6c8-5380-bc78-e26bc15e5566', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', 'dd4e968a-3d37-98a7-3819-a5fc4c117122', '～てもいいですか（请求许可）', '用于礼貌地请求许可，比～てもいいですか更正式。接续：动词て形＋も＋いいですか。', '在正式场合使用～てもいい？显得失礼；忘记使用疑问句形式；与～てもかまいませんか混淆。', 'ちょっと休んでもいいですか。说明：可以稍微休息一下吗？／この本を借りてもいいですか。说明：可以借这本书吗？', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('03aca7fc-a703-59b0-832d-39b78ddfa624', '9221fc32-a051-42cb-86b1-6a9917aa004e', '42de0c7b-50d9-4159-918a-4e618d83342d', '1d183755-02b3-4a6d-b727-082af1ef377c', '37a506cf-ef62-8ccc-3210-ab64e8561a4d', '天气与季节词汇的理解', '能够理解常见天气词（晴れ、雨、雪）和季节词（春、夏、秋、冬）在短文中的描述，并推断适合的活动。', '混淆季节与天气，如将雨理解为季节。', '例句：冬は雪が降ります。说明：理解冬天会下雪。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('03e6589a-8893-5f4b-8ab3-c49ce50fed84', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '1d183755-02b3-4a6d-b727-082af1ef377c', '6f1477f5-00be-f963-76b6-5165f568e88e', '指示词指代内容', '准确判断「それ」「この」「その」等指示词在上下文中的具体指代对象。', '指代范围过大或过小；忽视前文最近的名词或句子。', '日语例句：彼は毎日運動している。それに加えて、食事にも気をつけている。说明：「それ」指代“每天运动”这件事。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('03fabdf5-0c01-5442-8b49-6f6f3d58aec0', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '5b34d8b5-bde9-c4c6-c736-84adaaae3603', '「鼓」的读音与词义', '「鼓」读「こ」，表示鼓、敲鼓、鼓起。N1中「鼓動（こどう）」「鼓舞（こぶ）」等需注意。', '将「鼓舞」误读为「こぶ」；混淆「鼓動」与「脈拍」的语义。', '彼の言葉に鼓舞された。（受到鼓舞）说明：「鼓舞」指激励。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('04133b8a-48bb-556c-b840-c31b3f2b2d4a', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '5b34d8b5-bde9-c4c6-c736-84adaaae3603', '「点」「天」「店」等「てん」同音汉字的读音与词义区分', '「てん」读音的汉字包括「点（てん）」「天（てん）」「店（てん）」「展（てん）」「転（てん）」等。本知识点帮助学习者区分这些汉字在词语中的具体意义。', '学习者可能将「天気」误写为「点気」，或将「店舗」与「点舗」混淆；需注意「点」表示点或分数，「天」表示天空，「店」表示商店。', E'日语例句：天気（てんき）がいい。；说明：「天」读「てん」，表示天气。\\n日语例句：店舗（てんぽ）を経営する。；说明：「店」读「てん」，表示店铺。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('0414f437-38f0-5694-a476-445973373d17', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', 'ff057d86-47bc-de16-f0f9-a7b808b968e3', 'N3常见片假名外来语', '掌握日常生活和初级新闻中常见的片假名外来语，如「アポイント」「レジ」「ニュース」等，理解其原语和日语中的缩略用法。', '将外来语与和语词混淆，或错误记忆长音和促音，如把「コーヒー」写成「コーヒ」。', '日语例句：明日のアポイントを確認してください。；说明：アポイント是appointment的缩略，意为预约。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('047959e9-771f-56a8-ac77-cf38b4bbdfac', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', 'ff057d86-47bc-de16-f0f9-a7b808b968e3', 'N3正式与口语同义词的转换（扩展三）', '掌握N3中正式与口语同义词的转换，如「しかし→でも」「だから→なので」「非常に→すごく」「～ないといけない→～なければならない」等，并注意使用场合。', '在正式写作或演讲中使用口语词，如「でも」代替「しかし」；在口语中过度使用书面语，如「非常に」代替「すごく」，显得生硬。', '例句：しかし、問題がある。说明：「しかし」正式，书面；例句：でも、問題がある。说明：「でも」口语，日常对话；例句：非常に重要だ。说明：「非常に」正式，而「すごく」口语。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('04a286b6-c271-5343-ba5d-43e7f653c676', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '2c18e7e1-4ef0-65e3-24a7-6c97d562a122', '～と相まって', '表示“与……相结合、相辅相成”的意思，接续：名词＋と相まって。', '注意「と相まって」后项常为积极或自然的结果，且主语多为抽象事物。', '日语例句：美しい景色と相まって、その建物は一層引き立った。；说明：与美丽的景色相辅相成，那座建筑更加出众。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('050b55ce-6460-5edb-ad96-297dd8cc8494', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '2c18e7e1-4ef0-65e3-24a7-6c97d562a122', '～につけても～につけても（接续用法）', '此条为「～につけても～につけても」在句中作修饰成分时的接续形式，后接名词或形式名词，强调“无论哪种情况下的……”。', '注意后接名词时需用「の」连接，且整体作定语；不要与「～につけても」单独使用混淆。', '日本語：成功につけても失敗につけてもの経験は、すべて成長の糧となる。；说明：无论成功还是失败的经验，都会成为成长的养分。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('05493959-00ba-5b6e-8d4e-6f9a7a925a57', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '1af448c1-54cf-2f94-01b5-e8bc77a97f94', '～てはいけない／～てはならない（禁止）', '表示禁止，相当于“不可以…”。～てはいけない多用于口语、日常规则；～てはならない多用于书面语、规则、道德义务，语气更正式、强烈。接续：动词て形＋は＋いけない／ならない。', '容易混淆两者语气：～てはいけない更口语，～てはならない更书面、严肃。另外，～てはならない不能用于轻松的日常提醒。', '日本語：ここでタバコを吸ってはいけません。；说明：表示“不可以在这里吸烟”，日常规则。
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('0568bf57-198e-55d8-a100-438e941a2475', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '0545d0ec-89d1-a8aa-99f9-78b30fcbacb1', '表示条件的「～ば」「～たら」「～と」「～なら」的用法区分', 'N2阶段需区分四种条件表达：「～ば」用于一般条件或恒常条件；「～たら」用于特定条件或完成条件；「～と」用于必然结果或发现；「～なら」用于话题条件或建议。', '学习者常将「～と」用于意志表达，如「行くと買う」错误，应使用「行ったら買う」或「行くなら買う」。', '日本語例：春になれば花が咲く。（一到春天花就开）／時間があったら行きます。（有时间就去）／ここを押すと出ます。（按这里就出来）／行くなら早くしたほうがいい。（要去的话最好快点）。说明：各条件句的语境不同。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('0571edb7-be54-54c1-89d6-c4e7b96f3534', '9221fc32-a051-42cb-86b1-6a9917aa004e', '42de0c7b-50d9-4159-918a-4e618d83342d', '1d183755-02b3-4a6d-b727-082af1ef377c', '37a506cf-ef62-8ccc-3210-ab64e8561a4d', '比较句的理解', '能够理解AはBより～、AよりBのほうが～等比较结构，判断比较对象和结果。', '颠倒比较对象，将より前后的内容混淆。', '例句：日本は中国より小さいです。说明：比较对象是中国，结果是日本更小。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('05a88433-8552-5dae-b452-667ceb78d88e', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '2c18e7e1-4ef0-65e3-24a7-6c97d562a122', '～ことこの上ない', '表示“无比……、非常”的意思，接续：动词て形／形容词＋ことこの上ない。', '注意与「～この上ない」的区别，但「ことこの上ない」更强调程度极高。', '日语例句：合格できて、嬉しいことこの上ない。；说明：能合格，无比高兴。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('062d7861-5216-5ec3-b5b3-7d64f0fe92f4', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '1af448c1-54cf-2f94-01b5-e8bc77a97f94', '～てはいけないですか（委婉禁止・反问）', '以礼貌反问形式表达“不可以…吗？”实际用于委婉禁止或确认。接续：动词て形+はいけないですか。', '与～てはいけませんか混淆，后者更正式。注意该形式语气委婉，但可能带有责备。', '日本語：ここで遊んではいけないですか。；说明：委婉反问“不可以在这里玩吗？”（实际表示禁止）。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('065efaea-455f-5a95-87ee-35f1acbedd27', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '5b34d8b5-bde9-c4c6-c736-84adaaae3603', '「一緒」与「一層」的读音区分', '区分「いっしょ」与「いっそう」的读音及意义。', '将「一層」误读为「いっしょ」。', '日本語：一緒に行きましょう。；说明：一起。日本語：一層努力します。；说明：更加。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('066ebfba-faae-555c-a17d-a6d92652257b', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '1d183755-02b3-4a6d-b727-082af1ef377c', '40ed56d1-acbd-4a8b-6284-2df8b9423e8e', '过渡段与承上启下功能', '识别段落中起承上启下作用的句子或段落，理解其如何连接前文与后文，把握文章整体结构。', '忽略过渡句，导致前后逻辑断裂；将过渡句误认为主题句；不理解“一方”“ところで”等连接词的作用。', '日语例句：以上が問題の現状である。では、その解決策を考えてみよう。说明：第一句总结前文，第二句引出后文，是典型的过渡功能。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('06921ed3-492b-5d0c-8cc0-336873462429', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', 'baa9b5c2-5b94-4f9b-7ced-3a8c3cde4cb3', '常见拟声拟态词的语义与使用场景', 'N4阶段常见拟声拟态词如「にこにこ（微笑貌）」「わくわく（兴奋）」「ぴかぴか（闪闪发光）」等，需理解其修饰动作或状态的方式。', '混淆相近拟态词，如「にこにこ」与「にやにや」语感不同；误将拟声词用于不适当的动词搭配。', '日语例句：彼はいつもにこにこしています。；说明：「にこにこ」表示面带笑容的样子，常用于形容人。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('06f034a7-a3ef-541c-80b3-e15d6671c140', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '0545d0ec-89d1-a8aa-99f9-78b30fcbacb1', '近义名词的语感差异（如「意見」与「考え」、「問題」与「課題」）', 'N2词汇题常考近义名词在语感、使用域上的细微差别。例如「意見」强调个人主张，「考え」更中性；「問題」指需解决的困难，「課題」指分配的任务或研究主题。', '忽略语体正式度；在固定搭配中误用近义词；不区分抽象与具体。', '日本語：彼の意見に反対だ。；说明：「意見」用于正式表态。／日本語：この課題は難しい。；说明：「課題」指具体任务。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('0737dd5c-5829-5937-a79d-02f2538f6a59', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '5b34d8b5-bde9-c4c6-c736-84adaaae3603', '「同じ」与「同」的读音与用法区分', '「同じ」读作「おなじ」，是形容词/副词，表示相同；「同」读作「どう」，多用于书面语、复合词，如「同一」「同時」。', '混淆读音，将「同じ」读成「どうじ」；或将「同」单独使用。', '日本語：彼は同じ本を二冊買った。；说明：此处「同じ」读「おなじ」，修饰名词。「同」在「同一人物」中读「どう」。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('07669d4e-14e4-5df3-80d5-c1b8be94049f', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '1d183755-02b3-4a6d-b727-082af1ef377c', '40ed56d1-acbd-4a8b-6284-2df8b9423e8e', '段落结构与主题句识别', '识别段落中主题句（常位于段首或段尾）与支撑句的关系，理解总分、分总、并列等常见结构。', '认为每段首句必是主题句，忽略段尾总结或转折后的主题。', '日语例句：段落：日本では、電車の中で化粧をする人が増えている。これは、周りの人に不快感を与えることがある。また、マナーとしても問題だ。说明：首句为现象，第二、三句为评论，主题句在最后一句“マナーとしても問題だ”。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('076be123-35ef-5767-97ff-4df6a9e79db9', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '5b34d8b5-bde9-c4c6-c736-84adaaae3603', '「直ちに」与「すぐに」的语体区分', '「直ちに」书面语、正式，表示“立即、立刻”，强调不拖延；「すぐに」口语常用，也可表示距离近。', '在口语中过度使用「直ちに」显得生硬；「すぐに」不能用于正式公文。', '日语例句：直ちに行動を開始する。；说明：书面语“立即开始行动”。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('0790229f-7d6e-5951-b083-d181e0a9dad4', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', 'baa9b5c2-5b94-4f9b-7ced-3a8c3cde4cb3', '常用量词与名词的搭配选择（扩展）', 'N4阶段除基本量词外，还需掌握如「冊（さつ）」用于书、「本（ほん）」用于细长物、「枚（まい）」用于薄平物、「匹（ひき）」用于小动物等，注意读音变化。', '将量词用于错误类别，如用「本」数纸张；忽略量词读音的浊化（如「三匹（さんびき）」）。', '日语例句：本を三冊買いました。；说明：「冊」用于书，三冊读作「さんさつ」，注意促音。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('07ab743c-7e08-5062-b366-0b6a084d4144', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '1d183755-02b3-4a6d-b727-082af1ef377c', 'fc58533f-fd29-5132-8f21-fd381828e3c8', '理解对比与让步关系', '掌握「しかし」「でも」「〜が」「〜けど」「〜のに」等表达，区分对比、转折和逆接。', '混淆「〜のに」的意外语气与「〜けど」的单纯转折；忽略「しかし」用于正式书面语。', '日语例句：彼は若いのに、とてもしっかりしています。说明：「のに」表达与预期相反的意外感。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('07b758af-5811-5483-bdf4-02fe1e35c94e', '9221fc32-a051-42cb-86b1-6a9917aa004e', '42de0c7b-50d9-4159-918a-4e618d83342d', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', 'ef36118d-0ba3-29ce-b2b3-76eaeb6542ca', 'てもいいですね（许可确认）', '确认对方是否允许自己做某事，带有征求同意的语气。', '与「てもいいですか」混淆，后者更直接。', '少し休んでもいいですね。；说明：我可以休息一下吧。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('07b8c891-9be0-5e88-8200-ff23d913db36', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', 'ff057d86-47bc-de16-f0f9-a7b808b968e3', '抽象汉字复合词的理解', '掌握N3中由两个汉字构成的抽象名词，如「環境」「影響」「経験」等，理解其含义并能在句子中正确使用。', '望文生义，如将「影響」理解为“影子响声”；忽视复合词的整体意义。', '日语例句：環境問題は私たちに影響を与える。；说明：環境指环境，影響指影响。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('07f10707-ed18-5783-a26e-f2bf3e97d1b0', '9221fc32-a051-42cb-86b1-6a9917aa004e', '42de0c7b-50d9-4159-918a-4e618d83342d', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '0e03a921-5aff-e4be-f477-4d55640b198b', '家庭成员的数法', '掌握数家庭成员时用「人（にん）」，但「一人暮らし（ひとりぐらし）」等固定用法；兄弟姐妹数法用「人」，但「一人っ子（ひとりっこ）」特殊。', '将「一人っ子」读作「いちにんっこ」；将「二人兄弟」读作「ににんきょうだい」而非「ふたりきょうだい」。', '日本語：私は一人っ子です。；说明：一人っ子读作「ひとりっこ」。日本語：兄弟が二人います。；说明：二人读作「ふたり」。日本語：家族は四人です。；说明：四人读作「よにん」。)', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('0830afc8-adc0-52fe-a7ef-34e306496d33', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '1d183755-02b3-4a6d-b727-082af1ef377c', 'fc58533f-fd29-5132-8f21-fd381828e3c8', '识别时间顺序标记词', '在叙述文中，通过「まず」「次に」「そして」「最後に」等标记词把握事件发生的先后顺序。', '忽略标记词，仅凭内容猜测顺序；混淆「そして」与「それから」的细微差别。', '日语例句：まず材料を切ります。次に、鍋で炒めます。そして、調味料を加えます。说明：通过「まず」「次に」「そして」清晰把握操作步骤。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('09616a50-4590-59dd-ac94-cd714ce9de20', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '1af448c1-54cf-2f94-01b5-e8bc77a97f94', '～ように（目的・样态）', '表示目的“为了达到某种状态”，前接非意志动词或可能形；也可表示“像…一样”的样态。', '与～ために区别：～ように前接非意志动词或可能形，～ために前接意志动词辞书形。', '合格できるように毎日勉強しています。（为了能合格每天学习。）／彼のように歌いたい。（想唱得像他一样。）', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('09a5418f-342c-5ec7-95aa-07475ac71982', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '1d183755-02b3-4a6d-b727-082af1ef377c', 'fc58533f-fd29-5132-8f21-fd381828e3c8', '理解基本敬语表达', '在阅读中识别「〜ます」「〜です」「お〜になる」「〜いただく」等敬语形式，理解说话人与听话人的关系。', '混淆尊敬语与谦让语；忽视「お〜になる」的尊敬含义。', '日语例句：先生はもうお帰りになりました。说明：「お帰りになる」是「帰る」的尊敬语。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('09e45a43-019f-53e9-9b56-de112bbd2705', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '3760dfca-44d9-3445-01cd-85de1f860da1', '～にかけては', '表示在……方面，具有自信或特长。接续：名词＋にかけては。', '与「に関しては」不同，强调某方面的能力或特长。', '料理にかけては、彼女の右に出る者はいない。；说明：在烹饪方面，没有人能胜过她。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('0a279fb7-4b06-544c-86a0-4c4cf6894d7a', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '1d183755-02b3-4a6d-b727-082af1ef377c', '40ed56d1-acbd-4a8b-6284-2df8b9423e8e', '寻读定位具体信息', '在通知、广告、说明书等材料中快速找到所需的具体信息（时间、地点、价格、条件等），忽略无关内容。', '从头到尾细读，效率低；容易忽略表格或注释中的附加条件。', '日语例句：案内文に「申し込み締め切りは3月15日（必着）」とある。说明：若问截止日期，直接找“締め切り”即可，不必读全文。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('0a822c00-f34e-59b2-a88a-19b4435556fd', '9221fc32-a051-42cb-86b1-6a9917aa004e', '42de0c7b-50d9-4159-918a-4e618d83342d', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '0e03a921-5aff-e4be-f477-4d55640b198b', '顺序与等级的量词「番」「目」', '掌握「番（ばん）」表示编号顺序，如一番、二番；「目（め）」接在数量词后表示第几个，如一人目、二回目、三番目。', '将「一番目」与「一番」混淆；将「一人目」读作「いちにんめ」而非「ひとりめ」。', '日本語：一番好きな食べ物は寿司です。；说明：一番表示最。日本語：三人目が田中さんです。；说明：三人目读作「さんにんめ」。日本語：二回目の試験に合格しました。；说明：二回目读作「にかいめ」。)', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('0a860d15-d13b-5caa-8d02-0cda49d205dc', '9221fc32-a051-42cb-86b1-6a9917aa004e', '42de0c7b-50d9-4159-918a-4e618d83342d', '1d183755-02b3-4a6d-b727-082af1ef377c', '37a506cf-ef62-8ccc-3210-ab64e8561a4d', '短文中方向指示的理解', '能够理解表示移动方向或路径的句子（如右へ曲がる、まっすぐ行く），并在地图上定位。', '混淆左右或前后，忽略起点与终点。', '例句：駅を出て、右へ曲がってください。说明：理解出站后右转。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('0acc9918-9301-5ac4-a1c5-6e84717d50a2', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '5b34d8b5-bde9-c4c6-c736-84adaaae3603', '「語」的多种读音与词义', '「語」在N1中常见读音「ご」，词义包括“语言”“词语”“讲述”等。如「語彙（ごい）」「語源（ごげん）」「語学（ごがく）」「物語（ものがたり）」「用語（ようご）」。', '「語彙」读「ごい」而非「ごえ」；「物語」读「ものがたり」而非「ぶつご」。', '語彙（ごい）を増やす。说明：語彙指词汇。；この物語（ものがたり）は面白い。说明：物語指故事。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('0b714d26-d442-54d2-b146-1d12c02e2976', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '5b34d8b5-bde9-c4c6-c736-84adaaae3603', '「ちょっと」与「かなり」的程度差异', '「ちょっと」表示“稍微、一点”，也可用于委婉拒绝；「かなり」表示“相当、颇”，程度高于「ちょっと」。', '在需要表达“相当”时误用「ちょっと」；「ちょっと」在拒绝时需注意语气。', '日语例句：この問題はかなり難しい。；说明：表示“这题相当难”。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('0bd6e2de-b4f5-5dea-9b82-1a31c298eee7', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', 'dd4e968a-3d37-98a7-3819-a5fc4c117122', '～てはいけませんか（禁止・反问）', '用于礼貌地询问“不可以……吗？”，带有试探、请求许可的语气，比～てもいいですか更委婉。', '误以为只能用于禁止，实际可用于请求；注意接续和语气。', '日本語：ここでタバコを吸ってはいけませんか。；说明：这里不可以吸烟吗？', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('0bf83a9d-6217-5888-979f-43437498eb7f', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', 'dd4e968a-3d37-98a7-3819-a5fc4c117122', '～ておく（事先准备）', '表示为了将来某个目的而预先做某事，也可表示放任不管。', '忘记其“事先”含义，误用于无目的的动作。', '日本語：旅行の前に、ホテルを予約しておく。；说明：事先预订酒店。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('0c3f964b-b30a-5c1d-ada9-53f2b0acd2d8', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '1d183755-02b3-4a6d-b727-082af1ef377c', '6f1477f5-00be-f963-76b6-5165f568e88e', '并列结构理解', '掌握文章中多个并列成分或并列句的识别，理解其共同作用或递进关系，避免遗漏信息。', '误将并列成分当作主次关系，或忽略并列连词如「そして」「また」「それに」等，导致信息提取不全。', '日本語：この商品はデザインが優れているし、価格も手頃だ。；说明：通过「し」并列两个优点，阅读时需同时把握两方面。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('0c99a2c8-c55c-5717-86e9-dbf8e2ee5095', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '2c18e7e1-4ef0-65e3-24a7-6c97d562a122', '～はともかく', '表示“暂且不论”，先搁置前项，后项优先。接续：名词+はともかく。', '与「～はさておき」类似，但「はともかく」更常用。', '結果はともかく、努力したことは評価したい。说明：结果暂且不论。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('0cfe2c76-432a-5f2f-a46e-487991f0eb63', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '1d183755-02b3-4a6d-b727-082af1ef377c', '40ed56d1-acbd-4a8b-6284-2df8b9423e8e', '比较对照信息提取', '能阅读包含两个或以上对象比较的文章，提取各自特点、异同点，并理解比较的目的。', '只记住一方特点，忽略比较基准；混淆“Aに対してB”中的主次。', '日语例句：A社の製品は安いが、壊れやすい。一方、B社の製品は高いが、長持ちする。说明：需分别提取价格和耐用性两个维度上的差异。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('0d2663a7-3820-52fd-a681-2b84946a019f', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '5b34d8b5-bde9-c4c6-c736-84adaaae3603', '「感」的读音与词义', '「感」在「感じる」「感情」「感心」等词中读「かん」，但需注意「感じ」的训读「かんじ」，以及「感づく」等派生词。', '将「感づく」读作「かんづく」或误用「感じ」与「気持ち」的差异。', '例句：彼は危険を感じてすぐに逃げた。说明：「感じる」读「かんじる」，意为感觉。；例句：その言葉に感動した。说明：「感動」读「かんどう」，指感动。；例句：彼女は人の心の変化に敏感で、すぐ感づく。说明：「感づく」读「かんづく」，意为察觉。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('0d3db211-7f55-518f-b4ab-b35dd0400b8d', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '3760dfca-44d9-3445-01cd-85de1f860da1', '～にかかわる権利', '表示“与…相关的权利”，强调权利与某事项的紧密关联。', '容易与“～に関する権利”混用，但本句型更强调权利直接涉及某事物。', '日本語：労働者は安全に働くことにかかわる権利がある。；说明：劳动者有与安全工作相关的权利。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('0d43f792-5cbb-55ed-96ab-a39809604415', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', 'ff057d86-47bc-de16-f0f9-a7b808b968e3', 'N3近义形容词的语感差异（扩展四）', '辨析N3中意思相近但语感不同的形容词，如「うまい」「美味しい」「旨い」的正式度差异，以及「細かい」「詳しい」在描述细节时的侧重。', '学习者常忽略形容词的使用场合和对象，例如「うまい」较口语化，不适合正式文章；「細かい」强调琐碎，而「詳しい」强调详尽。', '日语例句：この料理はとても美味しいです。；说明：「美味しい」是标准说法，正式。日语例句：彼は細かいところまで気がつく。；说明：「細かい」指细节琐碎。日语例句：詳しい説明をお願いします。；说明：「詳しい」指内容详尽。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('0d65a99f-60f1-54af-8028-f60ac622b8ce', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '5b34d8b5-bde9-c4c6-c736-84adaaae3603', '「枠」的读音与词义', '「枠」读「わく」，指框架、范围、限额。N1中常见于「枠を超える」「枠内」「予算の枠」等搭配。', '误读为「さく」；混淆「枠」与「範囲」的语感，「枠」更强调人为设定的界限。', 'この計画は予算の枠を超えている。（超出预算范围）说明：「枠」指设定的范围。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('0d67ea01-16a6-5532-80c4-3507bae3814a', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '5b34d8b5-bde9-c4c6-c736-84adaaae3603', '「端」「橋」「箸」的同音异义', '掌握「はし」在不同语境下的汉字表记及含义。', '混淆「橋」与「箸」的用法，尤其在句子中。', '日本語：橋を渡ります。；说明：表示桥梁。日本語：箸で食べます。；说明：表示筷子。日本語：端に座ります。；说明：表示边缘。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('0d721114-9a99-5bae-958b-64451a875644', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', 'dd4e968a-3d37-98a7-3819-a5fc4c117122', '～てやる（为别人做・口语）', '表示说话人为别人（多为晚辈、动物或关系亲近的人）做某事，带有恩惠给予的语气，比～てあげる更口语化，有时含轻蔑或粗鲁感。接续：动词て形＋やる。', '对长辈或上级使用会失礼；误以为只能用于动物或植物，实际也可用于晚辈或朋友。', '弟に本を読んでやった。；说明：给弟弟读了书（为晚辈做）。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('0d9a8699-8d33-5dd9-8e0a-4465a789208d', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '1d183755-02b3-4a6d-b727-082af1ef377c', '6f1477f5-00be-f963-76b6-5165f568e88e', '时间顺序阅读', '理解文章中表示时间顺序的词语（まず、次に、その後、最後に）以及事件发生的先后关系，把握叙述脉络。', '混淆事件先后顺序，忽略时间标记词。', '日语例句：まず材料を準備し、次に下ごしらえをし、その後で煮込む。説明：通过“まず”“次に”“その後”明确步骤顺序。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('0dd59851-88b8-5957-b728-253c64064dc4', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', 'baa9b5c2-5b94-4f9b-7ced-3a8c3cde4cb3', '接续词表达因果、转折、并列等关系', '掌握「だから、しかし、そして、それに、でも」等接续词，能根据前后句逻辑选择合适连接词，并注意口语与书面差异。', '混用「だから」和「しかし」；在正式文章中使用过于口语的「でも」。', '日语例句：雨が降った。だから、試合は中止だ。；说明：「だから」表示因果，后句为结果。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('0e41ff2c-540d-5224-a9c3-99356559f0b0', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '2c18e7e1-4ef0-65e3-24a7-6c97d562a122', '～に関しては', '表示关于某特定事项，相当于「～については」，但更正式。常用于提出话题或限定范围。', '与「～に関して」相比，「に関しては」有对比或强调的语感，常出现在讨论中。', '日本語：この件に関しては、まだ調査中です。；说明：关于这件事，还在调查中。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('0e4b84dd-9f58-52d6-8af5-c8e8bc097295', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '1d183755-02b3-4a6d-b727-082af1ef377c', '9c37478d-2388-1380-cdea-3b62d82c3fcb', '具体例证的功能细分（说明/反驳/类比）', '区分文中具体例证的功能：是用于解释抽象概念、反驳对立观点，还是进行类比推理，不同功能影响对论证结构的理解。', '将所有例证都视为支持作者观点，忽略例证可能用于反驳或让步；不区分例证与类比。', '日语例句：例えば、ある研究では…。しかし、この例は特殊な場合にすぎない。；说明：例证先被提出，随后被作者限定，可能用于反驳或说明例外。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('0eb7b2e3-fadf-5aa1-888c-49dee4f78157', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '1d183755-02b3-4a6d-b727-082af1ef377c', '40ed56d1-acbd-4a8b-6284-2df8b9423e8e', '文体与写作目的识别', '根据文章的语言风格、结构、用词等，判断其属于说明文、议论文、记叙文、实用文等，并推断作者的写作目的（告知、说服、娱乐等）。', '只凭标题判断文体；忽略实用文（如通知）中的目的；将议论文中的主观观点误认为客观事实。', '日语例句：「この薬は食後に服用してください。副作用がある場合は医師に相談すること。」说明：这是说明/指示类文本，目的是告知使用方法与注意事项。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('0ed331ec-d9f7-5580-8365-dee3e8c400ae', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '2c18e7e1-4ef0-65e3-24a7-6c97d562a122', '～がてら', '表示在做某事的顺便做另一件事，相当于「～ついでに」。接续：动词ます形・サ変名词＋がてら。', '注意前后动作主体相同，且后项是主要目的，前项是顺便行为。', '散歩がてら、スーパーに寄って買い物をした。；说明：散步顺便去超市买了东西。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('0f1c4ee5-415e-5852-95ef-073a24ac2369', '9221fc32-a051-42cb-86b1-6a9917aa004e', '42de0c7b-50d9-4159-918a-4e618d83342d', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', 'ef36118d-0ba3-29ce-b2b3-76eaeb6542ca', 'と（条件/必然）', '动词/形容词终止形+と表示自然条件或必然结果，前件后件顺序固定。接续：动词辞书形/ない形+と。', '与ば、たら混淆；后件不能出现意志、命令。', '春になると花が咲きます。说明：一到春天花就开。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('0f6f2ff6-6ba8-508d-9504-aad806c97080', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '1af448c1-54cf-2f94-01b5-e8bc77a97f94', '～てはいけないよ（禁止・提醒）', '表示禁止并带有提醒或警告语气，口语中常用。接续：动词て形+はいけないよ。', '与～てはいけない（单纯禁止）混淆，后者语气更硬。注意～てはいけないよ常用于朋友或晚辈。', '日本語：そんなことをしてはいけないよ。；说明：提醒“不可以做那种事哦。”', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('0f933172-de9a-513e-8257-ed1c91549c45', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '2c18e7e1-4ef0-65e3-24a7-6c97d562a122', '～が最後', '表示一旦发生了前项，就再也无法挽回或必然导致后项结果。接续：动词た形＋が最後。', '容易与「～たが最後」混淆，注意接续必须是た形，且后项多为消极或不可逆的结果。', '彼は一度遊びに行ったが最後、家に帰ってこない。；说明：表示一旦出去玩了，就再也不回来。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('0fe10728-7e44-5c74-9410-c20f98e82c5e', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '1d183755-02b3-4a6d-b727-082af1ef377c', '6f1477f5-00be-f963-76b6-5165f568e88e', '语气词与态度把握', '通过「だろう」「かもしれない」「に違いない」等语气表达判断作者的确信程度或推测态度，避免将推测当作事实。', '将「かもしれない」等不确定表达误读为肯定事实，或忽略语气词对态度的影响。', '日本語：この計画は実現可能かもしれないが、まだ課題が多い。；说明：「かもしれない」表明作者持保留态度，并非完全肯定。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('10230a70-61dd-5101-a87a-f551184071b4', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '2c18e7e1-4ef0-65e3-24a7-6c97d562a122', '～に対しての', '表示对……的，用于修饰名词。相当于「～への」。', '与「～に対する」相比，「に対しての」更口语化，但两者可互换。', '日本語：お客様に対しての態度が悪いと評判だ。；说明：据说对顾客的态度不好。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('1037b0a7-25d0-51ec-bbbb-782121417f21', '9221fc32-a051-42cb-86b1-6a9917aa004e', '42de0c7b-50d9-4159-918a-4e618d83342d', '1d183755-02b3-4a6d-b727-082af1ef377c', '37a506cf-ef62-8ccc-3210-ab64e8561a4d', '量词在语境中的理解', '能够根据物品类别理解常见量词（人、本、枚、匹、個等）及其与数字的搭配，从而把握数量。', '将量词通用化，如用個数人。', '例句：りんごを三つ買いました。说明：つ用于一般物品计数，此处三个苹果。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('1098096f-d781-5388-b363-d31de986ab43', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', 'baa9b5c2-5b94-4f9b-7ced-3a8c3cde4cb3', '接续词「しかし」「でも」「けど」的转折用法', '「しかし」较正式，「でも」口语，「けど」用于句尾或连接，需根据语体选择。', '在正式书面语中滥用「でも」，或将「けど」用于句首。', '雨が降った。しかし、試合は行われた（下雨了，但比赛照常进行）；说明：「しかし」用于正式转折。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('10c18498-570b-51dd-afb3-2c56d4488dc5', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '1af448c1-54cf-2f94-01b5-e8bc77a97f94', '～ておく（准备・放置）', '表示事先做好某种准备，或让某状态保持下去。接续：动词て形＋おく。', '与～てある的区别：～ておく强调动作主体主动准备，～てある强调状态结果；～ておく常与～前に连用。', '日本語：旅行の前に、ホテルを予約しておきます。；说明：旅行前先预约好酒店。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('10fb30a2-4b4f-560a-850f-2f861abff35c', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '1d183755-02b3-4a6d-b727-082af1ef377c', '9c37478d-2388-1380-cdea-3b62d82c3fcb', '图表与文字的趋势描述整合', '在包含图表的文章中，理解文字如何描述图表中的趋势（上升、下降、波动），并判断文字结论是否与图表数据一致。', '只读文字而忽略图表细节，或只读图表而误解文字说明；忽略图表中的例外或异常点。', '日语例句：グラフによれば、売上は第2四半期に急増したが、その後横ばいとなっている。；说明：需结合图表确认「急増」和「横ばい」的具体区间。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('10ff657a-2e27-5474-8aad-2e6c46dbd7c6', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '1d183755-02b3-4a6d-b727-082af1ef377c', '40ed56d1-acbd-4a8b-6284-2df8b9423e8e', '多重因果与连锁反应理解', '在复杂文本中，梳理多个原因或多个结果之间的连锁关系，区分直接原因与间接原因、近因与远因。', '只找单一原因，忽略多重因素；混淆原因与结果；将连锁反应中的中间环节误认为最终结果。', '日语例句：雨が続いたため、川が増水し、その結果、橋が流された。说明：原因（雨）→中间结果（川増水）→最终结果（桥被冲走），需理清链条。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('110798d1-271d-5d85-9474-21836cf2587c', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '1d183755-02b3-4a6d-b727-082af1ef377c', '9c37478d-2388-1380-cdea-3b62d82c3fcb', '因果关系与逻辑结构分析', '梳理文章中事件或观点的因果链条，区分直接原因、间接原因和结果，理解文章的整体逻辑结构。', '颠倒因果；忽视多因一果；将时间先后误判为因果关系。', '日语例句：環境規制が強化されたため、各社は技術開発を急いだ。说明：「ため」明确因果，但需注意可能是多个原因之一。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('1115a3ef-4cb9-5ea6-958b-7d30b5873f1a', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '0545d0ec-89d1-a8aa-99f9-78b30fcbacb1', '汉字复合词中连浊（連濁）的规则与例外', 'N2需掌握复合词中后位词首清音浊化的现象（连浊），如「時々（ときどき）」「人々（ひとびと）」。连浊受前位词尾、语义关系影响，存在大量例外，需积累常见词。', '学习者常过度类推，将「花火（はなび）」误认为「はなひ」，或将不发生连浊的词如「日本橋（にほんばし）」误读。', '日语例句：山々（やまやま）が連なる。；说明：「山」重复时发生连浊，读作「やまやま」而非「やまやま」。日语例句：手紙（てがみ）を書く。；说明：「手（て）」与「紙（かみ）」复合时「か」浊化为「が」，读「てがみ」。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('114c3957-0944-5e72-a83c-b52d81636972', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '2c18e7e1-4ef0-65e3-24a7-6c97d562a122', '～に関しても', '表示关于某事项也……，相当于「～についても」。用于补充说明或列举。', '与「～に関しては」混淆。「に関しても」表示“也”，而「に関しては」表示“关于”。', '日本語：彼は仕事に関しても、プライベートに関しても、真面目だ。；说明：他无论在工作还是私生活方面都很认真。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('1158df2e-9432-5aaf-876e-7a02b920d552', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '1d183755-02b3-4a6d-b727-082af1ef377c', '6f1477f5-00be-f963-76b6-5165f568e88e', '新闻报道结构理解', '把握新闻类文章的结构（导语、背景、评论），快速提取关键事实。', '将记者评论当作客观事实；忽视时间地点等要素。', '日语例句：昨日、東京で大規模なデモが行われた。主催者発表で5万人が参加した。説明：注意区分事实与主办方主张。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('119d8b8f-aa0a-50cd-ad40-4d98ae152823', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '1af448c1-54cf-2f94-01b5-e8bc77a97f94', '～てもいいですよ（许可・缓和）', '表示许可并带有缓和语气，常用于口语。接续：动词て形+もいいですよ。', '与～てもいいです（单纯许可）混淆，后者不带缓和语气。注意～てもいいですよ常用于安慰或允许对方。', '日本語：心配しなくてもいいですよ。；说明：安慰对方“不用担心也可以哦”。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('120a4dca-b0b7-59c3-9b32-ed2989ee2def', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', 'ff057d86-47bc-de16-f0f9-a7b808b968e3', 'N3片假名外来语的实际用法（扩展二）', '掌握N3阶段常见片假名外来语在具体语境中的搭配和语感，如「イメージ」「リラックス」「マナー」「チャンス」等，注意其与和语、汉语词的微妙差异。', '将外来语与日语固有词完全等同，忽视语感差异；在正式场合误用口语化外来语；混淆形近外来语如「スマート」与「スリム」。', '日语例句：この写真はイメージがいいですね。；说明：「イメージ」指印象、形象，与「印象」相比更偏主观感觉。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('1232f5ce-9982-5f0d-91dd-6c1544c643eb', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '5b34d8b5-bde9-c4c6-c736-84adaaae3603', '「をはじめ」的用法', '掌握「をはじめ」表示“以……为首”。', '与「を中心に」混淆，但「をはじめ」列举代表性例子。', '日本語：日本をはじめ、アジアの国々で人気がある。；说明：以日本为首，在亚洲国家受欢迎。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('127500e3-4a9b-5536-90fe-442c10b5085e', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', 'ff057d86-47bc-de16-f0f9-a7b808b968e3', 'N3片假名外来语的实际用法（扩展三）', '掌握N3中表示抽象概念或动作的片假名外来语，如「イメージ」「リラックス」「トラブル」「チャンス」「ペース」等，并理解其在句中的搭配和语感。', '将「リラックス」误用为「リラクス」；「トラブル」与「問題」混用，忽略外来语更口语化、具体场景的用法。', '例句：音楽を聞いてリラックスする。说明：「リラックス」表示放松，常用「する」；例句：交通トラブルで遅れた。说明：「トラブル」指麻烦、故障，比「問題」更具体。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('12ae24a9-495b-5c01-9589-afa30b66742f', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '2c18e7e1-4ef0-65e3-24a7-6c97d562a122', '～につながる', '表示与某事物相连、导致某结果。接续：名词+につながる。', '注意与「～につながっている」（正处于连接状态）区分。', 'この研究は将来の医療発展につながる。说明：与未来发展相连。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('12d995d7-8627-5d0e-9515-02760927a6a8', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '2c18e7e1-4ef0-65e3-24a7-6c97d562a122', '～に伴って', '表示随着前项的发生或变化，后项也同时发生或变化。相当于「～につれて」，但更正式，且可表示伴随发生的事件。', '与「～に連れて」混淆。「に伴って」可接名词，如「経済成長に伴って」，而「に連れて」多接动词。', '日本語：経済の発展に伴って、環境問題が深刻化した。；说明：随着经济发展，环境问题变得严重。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('134b4334-ecd5-58ac-8297-84b8d5a2fb93', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', 'ff057d86-47bc-de16-f0f9-a7b808b968e3', 'N3复合动词的构成与意义（扩展二）', '掌握N3中更多复合动词，如「～込む（飛び込む、思い込む）」「～出す（思い出す、飛び出す）」「～過ぎる（食べ過ぎる）」「～直す（書き直す）」等，理解前项动词与后项补助动词的语义关系。', '忽视复合动词的整体意义，仅按字面理解；混淆「～込む」表示深入与「～出す」表示开始或向外。', '日语例句：彼は川に飛び込んだ。／そのことを思い出した。；说明：「飛び込む」强调跳入内部，「思い出す」表示从记忆中浮现。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('137f4c92-fc90-5b4b-9f02-3a86019bcec7', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '0545d0ec-89d1-a8aa-99f9-78b30fcbacb1', '时间相关汉字词的特殊读音（如「一日」「二日」「時」）', 'N2时间词中有些特殊读音，如「一日」读ついたち（1日）或いちにち（一天），「二日」读ふつか，「時」在复合词中有时读じ有时读とき。本知识点辨析。', '将「一日」一律读作いちにち，忽略ついたち的读法。', '日语例句：一日（ついたち）に会議があります。；说明：此处「一日」表示日期1号，读ついたち；若表示一天则读いちにち。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('13827d26-2dd6-53c8-a289-bf4996d2afff', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '2c18e7e1-4ef0-65e3-24a7-6c97d562a122', '～かいがあって', '表示努力或付出有了回报，后项多为好的结果。接续：动词た形・名词＋の＋かいがあって。', '注意「かい」前接た形或名词の，且后项必须是积极结果，否则用「かいもなく」。', '三年間練習したかいがあって、やっと優勝できた。；说明：三年努力没有白费，终于获得了冠军。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('13d8988a-9b64-53a8-979e-1c2528f775a7', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '1d183755-02b3-4a6d-b727-082af1ef377c', '9c37478d-2388-1380-cdea-3b62d82c3fcb', '指示词所指内容的确定', '准确判断「これ」「それ」「その」等指示词在上下文中的具体指代对象，包括前指和后指。', '只看紧邻句子，忽略远距离指代；混淆「それ」与「これ」的距离感；未注意指代内容可能是一个句子或段落。', '日语例句：彼は成功した。しかし、それは努力の結果ではなく、偶然だった。说明：「それ」指代前句的「成功した」这一事实。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('13e60751-201e-5067-bed5-628ffb5bb999', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '2c18e7e1-4ef0-65e3-24a7-6c97d562a122', '～ずくめ', '表示清一色、全是某种状态，多用于颜色、好事或特定名词。接续：名词＋ずくめ。', '只能接特定名词，如「黒ずくめ」「幸せずくめ」等，不能接一般名词，且多用于正面或中性。', '今日は朝からいいことずくめだ。；说明：今天从早上开始全是好事。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('141272c2-d803-592e-ac81-8f2203c69eb2', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '2c18e7e1-4ef0-65e3-24a7-6c97d562a122', '～をはじめとする', '表示“以……为首，以及……”，列举代表性例子。接续：名词+をはじめとする+名词。', '注意「をはじめ」后接名词时需加「とする」，但「をはじめとして」也可用；不要漏掉「とする」。', '日本語：社長をはじめとする役員たちが会議に出席した。；说明：以社长为首的管理层出席了会议。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('14129090-60fe-538a-a3cc-0ebccd39aff6', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '1d183755-02b3-4a6d-b727-082af1ef377c', '6f1477f5-00be-f963-76b6-5165f568e88e', '生词词义推测', '根据上下文线索（定义、举例、对比、因果）推测生词或短语的大致含义。', '脱离上下文直接猜测；忽视同义词或反义词提示。', '日语例句：この地域は降水量が少なく、乾燥している。したがって、農業には不向きだ。说明：「不向き」可由因果关系推测为“不适合”。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('14255f92-dafa-5df0-98ae-603eba6f1ca7', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '2c18e7e1-4ef0-65e3-24a7-6c97d562a122', '～にかけては', '表示在某个方面、领域，后项多为评价或能力。接续：名词+にかけては。', '与「～にかけて」（在…期间）混淆，后者表示时间范围。', '料理にかけては、彼女の右に出る者はいない。说明：在烹饪方面无人能及。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('14c8aff0-a29b-5234-b12c-57ef676f5b34', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', 'ff057d86-47bc-de16-f0f9-a7b808b968e3', 'N3相对时间表达（扩展三）', '掌握N3中更多相对时间表达如「この前」「先日」「最近」「そのうち」「いずれ」等，并区分其时间指向和正式程度。', '「この前」指最近过去，但「先日」更正式；「そのうち」表示不久的将来，较模糊；「いずれ」表示迟早，较正式。', '例句：この前、映画を見た。说明：「この前」口语，指前几天；例句：先日はお世話になりました。说明：「先日」正式，指前几天；例句：そのうち連絡します。说明：「そのうち」表示过些时候，不明确。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('14cfc543-4336-5532-8fab-9ac4aeca4234', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '2c18e7e1-4ef0-65e3-24a7-6c97d562a122', '～がてら（已有类似但不同）', '本项为「～がてら」的变体，表示“顺便”但接续不同，此处为「～をかねて」的书面表达，但为避免重复，本项特指「～がてら」的接续为动词ます形，且后项为移动动词，但已有「～がてら」知识点，故本项改为「～をかねて」的用法。', '注意「～をかねて」与「～がてら」的区别，前者更正式，后者口语化。', '日语例句：散歩をかねて、買い物に行った。；说明：顺便散步去买了东西。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('151ec5cf-0fdb-5fe2-bca1-7eb83151937f', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '1d183755-02b3-4a6d-b727-082af1ef377c', '9c37478d-2388-1380-cdea-3b62d82c3fcb', '模糊限制语与作者态度距离', '识别「～と思われる」「～ではないだろうか」「～かもしれない」等模糊限制语，判断作者对主张的确信程度和刻意保持的客观距离。', '将模糊限制语一律视为作者不自信；忽略在学术文章中模糊限制语用于礼貌和严谨。', '日语例句：この結果は、従来の説を覆す可能性があると思われる。；说明：作者用「と思われる」和「可能性がある」双重缓和，表明谨慎态度。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('15409838-3b9b-53bc-a305-9c0355e8c2de', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '2c18e7e1-4ef0-65e3-24a7-6c97d562a122', '～においての', '表示在…场合、时间、领域，后接名词。是～において的连体修饰形式，用于正式书面语。', '与～での（口语）区分；～においての更正式，多用于学术、公文。', '会議においての決定を全員に伝えた。；说明：把会议上的决定传达给了所有人。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('155c75be-b1ee-5d9f-9467-a01093b151bc', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', 'ff057d86-47bc-de16-f0f9-a7b808b968e3', '动词て形与补助动词的组合', '掌握N3中动词て形与「いる」「ある」「おく」「みる」「しまう」等组合的用法，表示持续、准备、尝试、完成等。', '混淆「てある」和「ておく」的区别；将「てしまう」仅理解为完成而忽视遗憾语气。', '日语例句：窓が開けてある。明日のために資料を用意しておく。；说明：てある表示状态，ておく表示事先准备。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('159f0fe3-68db-5fca-a752-231cdfc5d585', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '0545d0ec-89d1-a8aa-99f9-78b30fcbacb1', '尊敬语与谦让语动词的对应选择（如「いらっしゃる」与「参る」）', 'N2要求掌握常用敬语动词的对应，如「行く/来る/いる」的尊敬语为「いらっしゃる」，谦让语为「参る」；「言う」的尊敬语为「おっしゃる」，谦让语为「申す」。本知识点训练正确选用。', '将尊敬语用于自己，或将谦让语用于对方。', '日语例句：先生は明日こちらへいらっしゃいます。；说明：「いらっしゃる」是「来る」的尊敬语，用于老师，不能用于自己。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('15af0338-5bcb-5f7d-8dcb-8fa406e84de4', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', 'dd4e968a-3d37-98a7-3819-a5fc4c117122', '～てもよろしいですか（可以吗・礼貌）', '礼貌地请求许可，比～てもいいですか更正式。接续：动词て形+もよろしいですか。', '多用于正式场合，对上级或客户；注意回答时可用～てもいいです或～けっこうです。', '日本語：ここで写真を撮ってもよろしいですか。；说明：请问可以在这里拍照吗？', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('15d41678-02ac-5725-8969-8e399b61f65d', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '2c18e7e1-4ef0-65e3-24a7-6c97d562a122', '～なくしては', '表示“如果没有～就不（能）”，后接否定或消极结果，强调必要条件。接名词。', '与「～なしには」混淆，两者可互换，但「～なくしては」更书面、语气更强。', 'あなたの協力なくしては、この計画は成功しなかった。；说明：没有你的协助，计划不会成功。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('15df47b0-e9ef-5f30-ade0-385b6af18763', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '3760dfca-44d9-3445-01cd-85de1f860da1', '～に関わる', '表示与某事有关联、涉及。接续：名词＋に関わる。', '与「に関する」不同，「に関わる」强调影响或涉及的程度，而「に関する」多用于说明内容。', 'これは命に関わる重大な問題だ。；说明：这是关系到生命的重要问题。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('1605df8e-a86a-5109-91a3-32ccf8af9341', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', 'dd4e968a-3d37-98a7-3819-a5fc4c117122', '～てはだめですか（禁止・请求）', '用于询问“不可以……吗？”，带有请求许可的委婉语气，比～てはいけませんか更口语。', '误以为只能用于禁止，实际可用于请求；注意接续。', '日本語：少し遅れてはだめですか。；说明：稍微迟到一点不可以吗？', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('1652e4b8-5af0-558f-a973-39d4c7681eb1', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '1d183755-02b3-4a6d-b727-082af1ef377c', 'fc58533f-fd29-5132-8f21-fd381828e3c8', '把握段落间衔接关系', '理解相邻段落或句子之间的逻辑连接（如承接、转折、补充、总结），能判断过渡句的作用。', '只关注单句，忽略连接词（しかし、また、つまり等）提示的关系；把补充当作转折。', '日语例句：最初は難しかった。しかし、練習すればだんだん上手になった。；说明：「しかし」表示转折，前后内容形成对比。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('165f5474-8ce8-56f2-8368-f1b498b57b10', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '1af448c1-54cf-2f94-01b5-e8bc77a97f94', '～について（关于）', '表示话题对象，“关于…”，接名词后。', '与～に関して、～に対して混淆；～について较口语，～に関して较正式。', '日本の文化について話しました。（谈了关于日本文化的话题。）／この問題について考えてください。（请思考这个问题。）', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('167393e1-2871-5d29-bff0-5ae071b4f345', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '5b34d8b5-bde9-c4c6-c736-84adaaae3603', '「図る」与「謀る」的读音与用法区分', '「図る」读「はかる」，表示计划、谋求；「謀る」也读「はかる」，但多指策划阴谋，含贬义。', '将「図る」误读为「ずる」；混淆两者，如「改革を謀る」不自然。', '改善を図（はか）る。；说明：谋求。／反乱を謀（はか）る。；说明：图谋。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('1684f8b7-e38e-5db9-88df-64e51d7c7e99', '9221fc32-a051-42cb-86b1-6a9917aa004e', '42de0c7b-50d9-4159-918a-4e618d83342d', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '0e03a921-5aff-e4be-f477-4d55640b198b', '动词与宾语的固定搭配', '掌握N5常见动宾搭配，如「写真を撮る」「音楽を聞く」「手紙を書く」「料理を作る」等。', '将「聞く」用于“看”音乐；将「撮る」用于“画”照片。', '写真を撮ります。说明：「撮る」与「写真」搭配。／音楽を聞きます。说明：「聞く」与「音楽」搭配。／手紙を書きます。说明：「書く」与「手紙」搭配。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('168e283b-22f9-5d47-9a1d-aa5594b1eadc', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '2c18e7e1-4ef0-65e3-24a7-6c97d562a122', '～たが最後', '表示“一旦……就（无法收拾）”的意思，接续：动词た形＋が最後。', '与「～が最後」相似，但「～たが最後」强调一旦做了某事就导致不好的结果，且后项常为消极。', '日语例句：彼は話し出したが最後、止まらない。；说明：他一开口就停不下来。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('16e62e54-2209-5212-8f02-adbbc51f4846', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '0545d0ec-89d1-a8aa-99f9-78b30fcbacb1', '礼貌语（丁寧語）的动词形式', '掌握N2中礼貌语动词（如「お～する」「ご～になる」）的构成和用法，用于正式场合或对长辈、客户。', '将「お～する」用于尊敬语对象，如对老师说「お教えする」误用；或忽视「ご」与「お」的使用习惯。', '日语例句：ご案内いたします。；说明：「ご案内する」是谦让语，表示自己为对方做某事。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('17bfceac-5b4a-5e52-b19d-b38fa5d11dd1', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '3760dfca-44d9-3445-01cd-85de1f860da1', '～ている（可能）', '表示动作的持续或状态的存续，有时也用于表达可能的状态。', '注意区分「～ている」的持续义和结果状态义。', '彼は今本を読んでいる。；说明：他现在正在读书。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('17e7662b-a7bd-56f7-ac18-3444a67bb97c', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '3760dfca-44d9-3445-01cd-85de1f860da1', '～ように言う（转告）', '表示转告或传达某人的要求、指示，相当于“转告说…”。接动词辞书形/ない形。', '与「～と」直接引用混淆；误用为直接命令。', '先生は早く来るように言った。说明：老师转告说要早点来。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('18775325-db7a-57bd-8146-67e41b5d9bc3', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', 'ff057d86-47bc-de16-f0f9-a7b808b968e3', 'N3同源词族的派生关系（扩展二）', '掌握N3中同源词族的派生规律，如「集める/集まる/集合」「伝える/伝わる/伝説」「比べる/比べ物」等，理解动词、名词、形容词之间的意义关联。', '混淆自动词与他动词的派生方向；将名词形式与动词形式混用，如「集合」与「集まる」的用法。', '日语例句：切手を集めています。／人が駅に集まった。；说明：「集める」为他动词，「集まる」为自动词，同源但用法不同。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('1880d1c2-e160-5739-9905-12e6ec6d2e28', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '1d183755-02b3-4a6d-b727-082af1ef377c', '40ed56d1-acbd-4a8b-6284-2df8b9423e8e', '图表信息与文章结合理解', '能阅读带有图表、表格的文章，将图表数据与文字说明对应，理解趋势、比例和结论。', '只读文字忽略图表，或只看图表不理解其说明的问题。', '日语例句：文章：近年、スマホの利用時間が増加している。右のグラフは年代別の平均利用時間を示したものである。说明：需结合图表判断哪个年代增幅最大，而非仅凭文字。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('1928c255-0c2a-582e-a315-819186ea3e9d', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '1af448c1-54cf-2f94-01b5-e8bc77a97f94', '～てから（先后顺序）', '表示一个动作完成后，再进行另一个动作，强调先后顺序。接续：动词て形＋から。', '不要与～てからでないと混淆；～てから强调顺序，不能用于自然现象或习惯。', '日本語：朝ご飯を食べてから、学校へ行きます。；说明：表示先吃早饭，再去学校。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('19425ede-f0c0-5fdd-a66e-af26889f9d44', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '1af448c1-54cf-2f94-01b5-e8bc77a97f94', '～てはいけない（禁止）', '表示禁止，用于规则、警告或强烈劝阻。接续：动词て形+はいけない。口语中常省略为～ちゃいけない/～じゃいけない。', '与～てはならない混淆，后者更正式；与～てもいい（许可）对应。注意主语为第二人称时语气较强。', '日本語：ここでタバコを吸ってはいけません。；说明：表示“不能在这里吸烟”，用于规则或提醒。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('19945683-d23f-5c65-9ccc-9b39ed68499a', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '1af448c1-54cf-2f94-01b5-e8bc77a97f94', '～ていく（消失・变化）', '表示事物从说话人眼前逐渐消失或向远方变化，也可表示动作持续到未来。', '与“～てくる”相对，注意方向性；不要与“～ていく（空间移动）”混淆。', '日本語：雪が溶けていく。；说明：雪逐渐融化消失。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('19ab764d-50fb-5734-8783-e831b2750852', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '5b34d8b5-bde9-c4c6-c736-84adaaae3603', '「虚偽」与「偽り」的语体区分', '「虚偽」是法律、正式用语，指虚假陈述；「偽り」是普通名词，指谎言、虚假。N1需区分使用场合。', '在口语中误用「虚偽」；混淆「偽り」与「嘘」的语感。', '虚偽の申告は罰せられる。（虚假申报受罚）说明：「虚偽」用于正式。／彼の言葉は偽りだ。（他的话是假的）说明：「偽り」较书面。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('19c82985-59a0-56c7-a1ec-967716a49af0', '9221fc32-a051-42cb-86b1-6a9917aa004e', '42de0c7b-50d9-4159-918a-4e618d83342d', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '0e03a921-5aff-e4be-f477-4d55640b198b', '车辆与机械的量词「台」', '掌握量词「台（だい）」用于数汽车、自行车、电脑、冰箱等机械或交通工具，读音无特殊变化。', '用「個」数汽车；将「一台」读作「いちだい」时误加促音。', '日本語：車を一台持っています。；说明：一台读作「いちだい」。日本語：パソコンが二台あります。；说明：二台读作「にだい」。日本語：自転車を三台買いました。；说明：三台读作「さんだい」。)', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('1a043508-a758-5cee-b591-e1b34bd4f7bc', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '2c18e7e1-4ef0-65e3-24a7-6c97d562a122', '～あっての', '表示“正因为有……才……”的意思，强调前项是后项成立的必要条件。接续：名词＋あっての＋名词。', '容易与「～あってこそ」混淆，但「～あっての」直接接名词，而「～あってこそ」接动词て形或名词＋であってこそ。', '日语例句：あなたあっての私です。；说明：正因为有你才有现在的我。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('1a0dc393-5c05-5160-8569-f26b225daefe', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', 'e9d41203-7c2c-514e-a3a3-f1dbdcd3aaaa', '汉字读音与表记', '掌握 N4/N5 常见汉字的读音、表记和基本词形。', '音读、训读或相似汉字的读音容易混淆。', '毎朝、新聞を読みます。', 'published', '2026-09-03 13:10:31.032213+08', '2026-09-03 13:10:31.032213+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('1a4ddeae-c9bb-560d-ba02-f99233050cde', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', 'dd4e968a-3d37-98a7-3819-a5fc4c117122', '～ても（即使…也）', '表示让步，即使前项成立后项也不受影响。接续：动词て形+も，形容词くて+も。', '与～てもいい的ても不同；注意形容词接续：い→くて+も。', '日本語：雨が降っても、試合は行われます。；说明：即使下雨比赛也会进行。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('1a7c8cc3-320c-5fa4-ab83-ff2167520b1c', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', 'ff057d86-47bc-de16-f0f9-a7b808b968e3', 'N3同源词族的派生关系（扩展）', '掌握N3中同源词族的派生规律，如「決める/決まる/決定/決心」等，理解动词、名词、形容动词之间的转换及使用语境。', '混淆自动词与他动词的派生关系；将名词直接当动词使用。', '日语例句：彼は決心した。说明：決心是名词，但可加する构成动词。；日语例句：決定が発表された。说明：決定是名词。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('1ab4c849-da30-55e8-91d1-bc06bb540382', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '0545d0ec-89d1-a8aa-99f9-78b30fcbacb1', '多义词在具体语境中的词义选择（如「かける」的多种用法）', 'N2动词如「かける」有“挂”“花费”“打电话”“锁”等众多意义，需要根据搭配和语境判断。本知识点训练多义词的语境理解。', '只知其一不知其二，如将「時間がかかる」误解为“时间被挂住”。', '日语例句：この仕事には時間がかかる。；说明：「かかる」在此表示“花费”，不是“挂”的意思。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('1ac456f9-f771-57d2-aafc-938bf5bc303a', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '5b34d8b5-bde9-c4c6-c736-84adaaae3603', '「質」的读音与词义', '「質」在「質疑」「質素」中读「しつ」，表示质量、本质，但「質」在「質屋」中读「しち」，需注意。', '将「質屋」读作「しつや」，或混淆「質」与「量」。', '例句：質の高い教育を求める。说明：「質」读「しつ」，指质量。；例句：質疑応答の時間を設ける。说明：「質疑」读「しつぎ」，指质疑。；例句：彼は質屋に時計を預けた。说明：「質屋」读「しちや」，指当铺。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('1af9b917-5c0e-5d89-9f3a-17a96a28f179', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', 'baa9b5c2-5b94-4f9b-7ced-3a8c3cde4cb3', '反义词的对立关系', '掌握N4常见反义词对，如「高い/低い」「新しい/古い」「多い/少ない」等，并能正确使用。', '混淆「高い」的反义词在价格与高度上的不同（「安い」与「低い」）。', '日语例句：この山は高いですが、あの山は低いです。；说明：「高い」用于高度时反义词是「低い」，用于价格时反义词是「安い」。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('1b1e7d1b-eac2-5f69-b33f-86d52e75724d', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '1d183755-02b3-4a6d-b727-082af1ef377c', '6f1477f5-00be-f963-76b6-5165f568e88e', '对比与比较阅读', '把握文章中两个事物或观点的异同，理解比较的基准。', '只注意差异而忽略相同点；混淆比较对象。', '日语例句：A社は価格重視だが、B社は品質を優先している。说明：对比两公司策略差异。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('1b3716f3-bf67-549c-ade6-828dcf55a4ba', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '2c18e7e1-4ef0-65e3-24a7-6c97d562a122', '～こととて', '表示原因、理由，带有书面语色彩，相当于「～だから」。接续：名词＋の、动词普通形、形容词＋こととて。', '口语中不常用，容易与「～ことだから」混淆，但「こととて」更正式且后项多表示谅解或客观情况。', '初めてのこととて、不慣れで申し訳ありません。；说明：因为是第一次，不熟练，非常抱歉。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('1ba6a899-7246-5e67-a9bf-fd57b758da35', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '3760dfca-44d9-3445-01cd-85de1f860da1', '～ように思う', '表示委婉的看法或感觉，相当于“觉得好像…”。接动词辞书形/た形/ない形。', '与「～と思う」混淆；误用为直接断定。', '彼は何か隠しているように思う。说明：我觉得他好像隐瞒了什么。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('1c36878d-953f-56de-ad87-64c8feb45e44', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '3760dfca-44d9-3445-01cd-85de1f860da1', '～にかかわる危機', '表示“关系到…的危机”，用于强调危机对某事物的重大影响。', '与“～の危機”相比，本句型更突出因果关系和严重性。', '日本語：この事故は会社の存続にかかわる危機だ。；说明：这起事故是关系到公司存亡的危机。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('1c5d2e5c-6fd2-55c3-b68d-f56f21b2a1d3', '9221fc32-a051-42cb-86b1-6a9917aa004e', '42de0c7b-50d9-4159-918a-4e618d83342d', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', 'ef36118d-0ba3-29ce-b2b3-76eaeb6542ca', 'てはいけません（禁止，礼貌）', '「てはいけない」的礼貌形式，用于正式场合或对长辈。', '口语中过度使用会显得生硬；与「てはいけない」混用。', 'ここでタバコを吸ってはいけません。；说明：这里禁止吸烟。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('1c6b7ce3-9147-5548-aeb3-b977d3616863', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', 'baa9b5c2-5b94-4f9b-7ced-3a8c3cde4cb3', '动词て形与补助动词构成的复合意义', '「～ている」「～てある」「～ておく」「～てしまう」等表达持续、结果状态、准备、完成等意义，需区分使用场景。', '混淆「～ている」与「～てある」：前者表动作持续或状态，后者表人为结果状态。', '窓が開いている（窗户开着）；窓が開けてある（窗户被人打开了）；说明：前者强调自然状态，后者强调人为结果。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('1cc10e37-8729-5aec-b099-211b3dbaad79', '9221fc32-a051-42cb-86b1-6a9917aa004e', '42de0c7b-50d9-4159-918a-4e618d83342d', '1d183755-02b3-4a6d-b727-082af1ef377c', '37a506cf-ef62-8ccc-3210-ab64e8561a4d', '提取请求与许可表达', '能够理解～てください（请求）、～てもいいです（许可）、～てはいけません（禁止）在短文中的功能，并判断说话者的意图。', '混淆许可与禁止，将～てはいけません误读为可以。', '例句：ここで写真を撮ってもいいですか。说明：询问许可；例句：ここでタバコを吸ってはいけません。说明：禁止。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('1ce52ef7-93c3-5a12-952a-739e93854a6f', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '0545d0ec-89d1-a8aa-99f9-78b30fcbacb1', '当て字（借字）的读音与意义', '部分日语词汇使用汉字表记但读音与汉字音训无关，如「大人（おとな）」「今日（きょう）」「下手（へた）」等，需整体记忆。', '按汉字字面意思理解或按音读训读推测读音。', '例句：大人は子供を守る。说明：「大人」读「おとな」，意为成人。；例句：彼は下手に歌う。说明：「下手」读「へた」，意为不擅长。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('1d0eeac1-5d79-5fb9-9091-6a1cf5935dd3', '9221fc32-a051-42cb-86b1-6a9917aa004e', '42de0c7b-50d9-4159-918a-4e618d83342d', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '0e03a921-5aff-e4be-f477-4d55640b198b', '礼貌体与普通体的使用语境', '理解です/ます体与普通体（だ/である）在不同场合的使用，如与长辈、陌生人用礼貌体，与朋友用普通体。', '对老师使用普通体；对朋友使用过度礼貌体。', 'これは本です。说明：礼貌体，用于正式场合。／これは本だ。说明：普通体，用于口语或朋友间。／お元気ですか。说明：礼貌体问候。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('1d3cabe9-7ce6-5b30-acd1-ceda5be929b7', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '3760dfca-44d9-3445-01cd-85de1f860da1', '～にわたって', '表示时间或空间的范围，“长达…、涉及…”。接续：名词+にわたって/にわたる。', '与「～にわたり」同义，但「にわたって」后接动词，「にわたる」后接名词。', '3時間にわたって会議が行われた。；说明：会议持续了三个小时。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('1d84a697-8a5a-5e1b-8313-36bf7304009d', '9221fc32-a051-42cb-86b1-6a9917aa004e', '42de0c7b-50d9-4159-918a-4e618d83342d', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', 'ef36118d-0ba3-29ce-b2b3-76eaeb6542ca', 'ていく/てくる（方向/变化）', 'て形+いく/くる表示空间移动方向或时间上的变化过程。接续：て形+いく/くる。', '误用为单纯移动；忽视从过去到现在的用法。', '風が吹いてきました。说明：风开始吹起来（从过去到现在）；これからも頑張っていきます。说明：今后继续努力。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('1e3d5cbd-328b-5b8a-a37f-a78c184a1015', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '5b34d8b5-bde9-c4c6-c736-84adaaae3603', '「経緯」的读音与词义', '「経緯」读作「けいい」，表示事情的来龙去脉、经过。注意不要与「経過」混淆，「経緯」强调背景和过程。', '误读为「けいし」；混淆「経緯」与「理由」。', 'この問題の経緯（けいい）を説明してください。；说明：来龙去脉。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('1e68ed41-e75e-536a-905d-d3a282d24d5d', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '5b34d8b5-bde9-c4c6-c736-84adaaae3603', '「共」的读音与词义', '「共」在「共同」「共通」中读「きょう」，在「共に」中读「ともに」，需掌握音读与训读。', '将「共に」误读为「きょうに」，或混淆「共同」与「共通」的细微差异。', '例句：彼らは共同で研究を進めている。说明：「共同」读「きょうどう」，指共同。；例句：二人は共に歩いた。说明：「共に」读「ともに」，意为一起。；例句：この二つの言語には共通点が多い。说明：「共通」读「きょうつう」，指共通。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('1eb9459c-c0c1-52b5-8f67-7daefec8e6e1', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '2c18e7e1-4ef0-65e3-24a7-6c97d562a122', '～をもって', '表示“以……为手段/时间界限”，正式用法，可表示方式或截止时间。接续：名词+をもって。', '与「～で」混淆，但「をもって」更正式，常用于公告；注意区分「をもって」表示“以……”和「をもって」表示“到……为止”。', '日本語：本日をもって、営業を終了いたします。；说明：到今天为止，本店结束营业。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('1ed4f44f-5818-521c-b3a4-33b1e1ecb858', '9221fc32-a051-42cb-86b1-6a9917aa004e', '42de0c7b-50d9-4159-918a-4e618d83342d', '1d183755-02b3-4a6d-b727-082af1ef377c', '37a506cf-ef62-8ccc-3210-ab64e8561a4d', '对话中是非疑问句的理解', '能够根据问句的肯定/否定形式及回答中的はい/いいえ判断说话者的真实意图。', '忽略否定问句（～ませんか）常表示邀请，回答时需注意实际含义。', '例句：一緒に昼ごはんを食べませんか。说明：虽为否定形式，但表示邀请，回答はい表示接受。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('1f083e6a-a0ba-5b41-9925-8dc9431cfa63', '9221fc32-a051-42cb-86b1-6a9917aa004e', '42de0c7b-50d9-4159-918a-4e618d83342d', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', 'ef36118d-0ba3-29ce-b2b3-76eaeb6542ca', 'てみる（尝试）', '动词て形+みる表示尝试做某事。接续：て形+みる。', '与てみる的过去式混淆；忘记て形变化。', '日本語で話してみます。说明：试着用日语说。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('1f35c4e8-0bb8-5d47-b90d-857a3039f1c1', '9221fc32-a051-42cb-86b1-6a9917aa004e', '42de0c7b-50d9-4159-918a-4e618d83342d', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', 'ef36118d-0ba3-29ce-b2b3-76eaeb6542ca', 'てはいけません（禁止）', '表示禁止，比「てはいけない」更正式，常用于规则、告示。接续：动词て形+は+いけません。', '与「てはいけない」同义，但更礼貌；口语中常说「ちゃいけません」。', '授業中に携帯を使ってはいけません。说明：表示“上课时不能使用手机”，规则。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('1ff0dfee-cbaa-5c3d-82e4-8f957e980314', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '5b34d8b5-bde9-c4c6-c736-84adaaae3603', '「とても」的肯定与否定用法', '掌握「とても」在肯定句中表示“非常”，在否定句中表示“无论如何也”。', '在否定句中误用为“非常”。', '日本語：とても美味しいです。；说明：非常好吃。日本語：とてもできない。；说明：怎么也做不到。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('204e45ce-7f77-5d75-b4a9-5d986a980464', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', 'baa9b5c2-5b94-4f9b-7ced-3a8c3cde4cb3', '量词读音的变音规则', '掌握量词与数字结合时的音变，如「一本（いっぽん）」「三冊（さんさつ）」「六匹（ろっぴき）」，注意促音和浊化。', '不熟悉音变，如把「一本」读成「いちほん」；忽略「人」的读音（一人、二人、三人）。', '日语例句：鉛筆を五本ください。；说明：「五本」读「ごほん」，而「一本」读「いっぽん」。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('206b63d0-29ae-5242-b4db-d182501f9263', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', 'ff057d86-47bc-de16-f0f9-a7b808b968e3', 'N3近义名词的语境区分（扩展二）', '辨析N3中易混名词，如「意見/考え」「理由/わけ」「目的/目標」「方法/手段」等，注意其使用语境和搭配差异。', '将「意見」与「考え」完全等同，忽视「意見」多用于发表主张；「理由」与「わけ」在口语与书面语中的差异。', '日语例句：彼の意見に賛成です。／私の考えでは、それは正しい。；说明：「意見」侧重主张，「考え」侧重个人想法。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('208476df-e2ef-5b6f-bc85-f66d5f9a376b', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '5b34d8b5-bde9-c4c6-c736-84adaaae3603', '「社」的多种读音与词义', '「社」在N1中常见读音「しゃ」，词义包括“公司”“神社”“社团”等。如「社会（しゃかい）」「社長（しゃちょう）」「神社（じんじゃ）」「社殿（しゃでん）」「結社（けっしゃ）」。', '「神社」读「じんじゃ」而非「じんしゃ」；「社殿」读「しゃでん」而非「じゃでん」。', '彼は社長（しゃちょう）に就任した。说明：社長指总经理。；地元の神社（じんじゃ）を参拝する。说明：神社指神社。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('210a86bb-aad8-5324-ba62-89d31e3eed7a', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '5b34d8b5-bde9-c4c6-c736-84adaaae3603', '「故」的读音与词义', '「故」在「故郷」「事故」中读「こ」，表示原因、旧，但「故に」读「ゆえに」，「故人」读「こじん」。', '将「故に」误读为「こに」，或混淆「故郷」与「田舎」。', '例句：彼は故郷を離れて東京で働いている。说明：「故郷」读「こきょう」，指故乡。；例句：事故の原因を調査中だ。说明：「事故」读「じこ」，指事故。；例句：彼は病気故に欠席した。说明：「故に」读「ゆえに」，意为因为。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('212ad106-0415-554a-9568-230b3452c8d5', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '0545d0ec-89d1-a8aa-99f9-78b30fcbacb1', '敬语（尊敬语与谦让语）的词汇选择', '掌握N2常用尊敬语和谦让语动词（如「いらっしゃる」「参る」「申す」）的对应关系，能根据对象和场合正确使用。', '混淆尊敬语与谦让语，如对上级说「私が参ります」正确，但说「私がいらっしゃいます」错误；或过度使用敬语。', '日语例句：先生は明日学校にいらっしゃいますか。；说明：「いらっしゃる」是「来る/行く/いる」的尊敬语。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('21938c67-a8f1-5d3c-974d-7c37fe5f22bf', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '0545d0ec-89d1-a8aa-99f9-78b30fcbacb1', '常用动词与名词的固定搭配（如「話をつける」「用を足す」）', 'N2阶段要求掌握一些动词与名词的固定搭配，这些搭配不能随意替换。例如「用を足す」（办完事/上厕所）、「話をつける」（谈妥）。本知识点集中训练高频搭配。', '将「用を足す」误说成「用をする」；将「話をつける」误说成「話をする」。', '日语例句：ちょっと用を足してから、戻ります。；说明：「用を足す」是固定搭配，表示办完琐事或去厕所，不能改为「用をする」。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('2199bdac-91bf-5148-90eb-b6af00f6e880', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '1af448c1-54cf-2f94-01b5-e8bc77a97f94', '～てもいいですよね（许可・确认）', '在请求许可时，加上「よね」表示向对方确认自己的行为是否被允许，语气更柔和。', '误用为单纯许可表达，忽略确认语气；注意「よね」的确认功能。', 'ちょっと休んでもいいですよね？　说明：确认自己是否可以休息一下。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('21b8a534-e691-5915-b117-4822ed2ca2b0', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '3760dfca-44d9-3445-01cd-85de1f860da1', '～にすぎない', '表示“只不过…”，强调程度低、不值得一提。接续：动词普通形/名词+にすぎない。', '与「～だけだ」相比，「にすぎない」带有评价性，常与「ただ」连用。', 'これは私の個人的な意見にすぎません。；说明：这只不过是我个人的意见。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('21c1e940-9b75-5ef0-835a-045c556c99f3', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '5b34d8b5-bde9-c4c6-c736-84adaaae3603', '「区」的多种读音与词义', '「区」在N1中常见读音「く」，词义包括“区划、区域”“行政区划”等。如「区別（くべつ）」「区分（くぶん）」「区間（くかん）」「区役所（くやくしょ）」「地区（ちく）」。', '「区役所」读「くやくしょ」而非「くやくじょ」；「地区」读「ちく」而非「ちく」注意促音。', '区別（くべつ）がつかない。说明：区別指区别。；区役所（くやくしょ）で手続きをする。说明：区役所指区政府。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('21d3211b-2959-5428-9f92-431866895bd4', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '3760dfca-44d9-3445-01cd-85de1f860da1', '～ざるを得ない', '表示不得不做某事，相当于“不得不……”。接动词ない形去掉ない加ざるを得ない。', '误用于主动选择；注意接续，如“せざるを得ない”是特殊形式。', '日语例句：約束した以上、行かざるを得ない。；说明：既然约好了，就不得不去。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('21e28ddb-7dd3-5adc-bfc5-97b3c8b10ac5', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '5b34d8b5-bde9-c4c6-c736-84adaaae3603', '「趣旨」与「主旨」的用法区分', '「趣旨」指演讲、文章的中心意图；「主旨」指主要意思，两者相近但「趣旨」更强调意图，「主旨」更强调内容要点。', '互换使用虽可，但考试中常考细微差别；「趣旨」常用于通知、会议目的。', '会議の趣旨（しゅし）を述べる。；说明：意图。／文章の主旨（しゅし）をまとめる。；说明：要点。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('225fc472-17f6-5d19-8ac3-9dd5b407e9e7', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '0545d0ec-89d1-a8aa-99f9-78b30fcbacb1', '汉字复合词中的特殊读音（熟字訓）', 'N2需掌握部分复合词使用特殊训读（熟字訓），如「大人（おとな）」「今日（きょう）」「昨日（きのう）」「一人（ひとり）」。这些词不能按单个汉字音训拼读，需整体记忆。', '学习者常按音读拼读，如将「大人」读作「だいじん」，或混淆「一日（ついたち/いちにち）」的不同读音。', '日语例句：大人は子供に優しくする。；说明：「大人」读作「おとな」，为特殊训读，不可拆读。日语例句：今日は学校が休みだ。；说明：「今日」读作「きょう」，为熟字訓，与「本日（ほんじつ）」不同。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('226f08ac-8955-5175-bce7-6e3e0436889c', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', 'ff057d86-47bc-de16-f0f9-a7b808b968e3', '敬语动词的对应关系', '掌握N3中常见的敬语和谦让语动词，如「言う→おっしゃる」「行く→伺う」「食べる→召し上がる」等，并能在适当场合使用。', '混淆尊敬语和谦让语，如对长辈说「伺いますか」；忽视动词的变换规则。', '日语例句：先生は何とおっしゃいましたか。；说明：おっしゃる是言う的尊敬语。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('22a83720-1ee0-5957-bd5d-4522820827b9', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '5b34d8b5-bde9-c4c6-c736-84adaaae3603', '「所」的读音与词义', '「所」在「場所」「所得」中读「しょ」，表示地方，但「所」在「所」字中读「ところ」，需注意音训。', '将「ところ」误写为「所」时读错，或混淆「場所」与「所」。', '例句：会議の場所を確認する。说明：「場所」读「ばしょ」，指地点。；例句：所得が高い人は税金が多い。说明：「所得」读「しょとく」，指收入。；例句：ここは私の好きな所だ。说明：「所」读「ところ」，指地方。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('22c7a5e2-1ef2-56ed-bfe4-61d07f703e92', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '2c18e7e1-4ef0-65e3-24a7-6c97d562a122', '～かたがた', '表示“顺便”的意思，相当于「～を兼ねて」，但更正式，常用于寒暄或书面语。接续：动词ます形去掉ます＋かたがた，或名词＋かたがた。', '注意「かたがた」后项常为移动动词或行为，且前项是主要目的。', '日语例句：お礼かたがた、お見舞いに行った。；说明：顺便道谢，去探望了。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('231d62da-3e9e-5f65-9ee7-4c91ed524bc3', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '1d183755-02b3-4a6d-b727-082af1ef377c', '6f1477f5-00be-f963-76b6-5165f568e88e', '引用与转述理解', '区分作者直接陈述与引用他人观点，理解引用在论证中的作用。', '将引用内容误认为作者观点；忽视引用后的评价。', '日语例句：専門家は「危険だ」と指摘している。しかし、私は必ずしもそう思わない。説明：引用后转折表明作者不同看法。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('234c5bae-23d5-56fc-9a8a-a00fe8e80bb1', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '1af448c1-54cf-2f94-01b5-e8bc77a97f94', '～わけにはいかない（不能・不可以）', '表示从社会常识、义务或心理上不能做某事，强调“不能那么做”。', '与～てはいけない（禁止）混淆，本句型更强调主观或社会约束；接续为动词辞书形/ない形+わけにはいかない。', '日本語：約束した以上、行かないわけにはいかない。；说明：因为约定了，所以不能不去。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('238f7d5d-9a2e-5b64-8d92-fec3767207e3', '9221fc32-a051-42cb-86b1-6a9917aa004e', '42de0c7b-50d9-4159-918a-4e618d83342d', '1d183755-02b3-4a6d-b727-082af1ef377c', '37a506cf-ef62-8ccc-3210-ab64e8561a4d', '图文对应中人物与物品的识别', '在带插图的短文中，能够根据描述将人物、物品与位置对应起来。', '忽略位置词（上、下、前、後ろ）导致对应错误。', '例句：猫は机の上にいます。说明：理解猫在桌子上面。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('23d7d4d5-614a-5cca-a12f-d566137eae38', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '1af448c1-54cf-2f94-01b5-e8bc77a97f94', '～にかぎらず', '表示不仅限于前项，后项也包含在内，相当于“不仅……而且……”。多用于列举或补充说明。', '注意与“～にかぎって”（偏偏、只有）区分；本句型是“不限于”，而“にかぎって”是限定。', 'この店は平日にかぎらず、週末もいつも混んでいる。；说明：这家店不仅平日，周末也总是很拥挤。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('246ea1be-9ab0-57fe-b906-21205d418864', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '2c18e7e1-4ef0-65e3-24a7-6c97d562a122', '～を踏まえた上で', '表示“在考虑～的基础上”，后接行动或决定。接名词。', '与「～を踏まえて」混淆，后者直接接动词；此句型强调先有基础再行动。', 'データを踏まえた上で、結論を出しましょう。；说明：在基于数据的基础上得出结论吧。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('24c2a9eb-933e-5cb3-943c-8f491c8ed484', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', 'ff057d86-47bc-de16-f0f9-a7b808b968e3', 'N3抽象汉字复合词的理解（扩展）', '掌握N3中抽象汉字复合词如「現状」「影響」「関係」「環境」等，理解其抽象含义及在句子中的搭配。', '将抽象词用于具体事物；忽视词与词之间的固定搭配，如「影響を与える」。', '日语例句：環境問題が深刻だ。说明：環境指环境，抽象概念。；日语例句：天気が作物に影響を与える。说明：影響与「与える」搭配。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('25429407-df58-5c58-b787-09090a0c938a', '9221fc32-a051-42cb-86b1-6a9917aa004e', '42de0c7b-50d9-4159-918a-4e618d83342d', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', 'ef36118d-0ba3-29ce-b2b3-76eaeb6542ca', 'てある（结果状态）', '他动词て形+ある表示人为动作的结果状态存续，常与が搭配。接续：て形+ある。', '与ている混淆；てある前用が而非を。', '窓が開けてあります。说明：窗被开着（有人特意开的状态）。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('257ce229-2323-5f0d-818c-5e53054b11dc', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', 'dd4e968a-3d37-98a7-3819-a5fc4c117122', '～たばかり（刚刚）', '表示动作刚完成不久，强调时间近。接续：动词た形+ばかり。', '与～たところ（刚刚）区别，～たばかり可表示主观感觉，～たところ更客观；注意与～ばかり（尽是）区分。', '日本語：ご飯を食べたばかりです。；说明：刚刚吃完饭。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('25e3aea0-8021-5f73-a6ea-84cd800bf5d6', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '1d183755-02b3-4a6d-b727-082af1ef377c', 'fc58533f-fd29-5132-8f21-fd381828e3c8', '把握通知类文本结构', '在通知、告示中，识别标题、日期、对象、事项、注意事项等部分，快速定位所需信息。', '忽略对象限定；将注意事项与主要事项混淆。', '日语例句：学生の皆さんへ。明日の会議は午後2時からです。遅れないでください。说明：先明确对象，再读具体事项。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('263bc8f3-12d1-59d8-969c-6293782b794e', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '3760dfca-44d9-3445-01cd-85de1f860da1', '～ていく（可能）', '表示动作方向或变化，有时也用于表达可能的状态。', '注意「～ていく」与「～てくる」的方向区别。', 'この道をまっすぐ行っていくと、公園がある。；说明：沿着这条路一直走下去，就有公园。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('26691f93-322a-5944-9589-b41a76b355a6', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', 'baa9b5c2-5b94-4f9b-7ced-3a8c3cde4cb3', '量词读音的浊化与促音变', '量词与数字结合时，读音常发生浊化（如「三階」さんかい→さんがい）或促音变（如「六本」ろっぽん），需掌握常见组合。', '忽略浊化规则，如将「三階」读作さんかい；或将「一匹」读作いちひき。', '三階（さんがい）；六本（ろっぽん）；说明：数字与量词结合时，需注意音便。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('26a0706e-0403-5a98-a554-0d00ffecbf88', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '3760dfca-44d9-3445-01cd-85de1f860da1', '～にしても', '表示即使……也……，或让步。接续：动词/形容词普通形＋にしても。', '与「としても」相似，但「にしても」可接名词，且有时表示列举。', '忙しいにしても、連絡くらいはしてほしい。；说明：即使忙，也希望你联系一下。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('26bfa108-22c2-5fcd-84fd-f8e8ae6fb766', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '1d183755-02b3-4a6d-b727-082af1ef377c', '6f1477f5-00be-f963-76b6-5165f568e88e', '生词推断上下文线索', '利用上下文中的同义词、反义词、定义、举例、因果关系等线索推测生词的大致意思，提高阅读流畅度。', '遇到生词立即查词典或放弃，不利用上下文线索；或过度推断导致误解。', '日语例句：彼はいつも穏やかで、怒ることはめったにない。説明：通过“怒ることはめったにない”推断“穏やか”意为温和。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('26f8a793-3039-59e2-9b90-28ab71fb6fa0', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', 'ff057d86-47bc-de16-f0f9-a7b808b968e3', 'N3抽象汉字复合词的理解（扩展二）', '掌握N3中抽象汉字复合词如「影響」「関係」「状態」「環境」「結果」等，理解其抽象含义及在句子中的功能，注意与具体名词的区别。', '将抽象名词与具体名词混用，如「影響」与「効果」；忽视抽象名词常与「与える」「受ける」等搭配。', '日语例句：天気は作物に影響を与える。／この薬は効果がある。；说明：「影響」指影响，「効果」指效果，搭配不同。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('2736e84e-2358-50b0-b014-76e2176517ec', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', 'dd4e968a-3d37-98a7-3819-a5fc4c117122', '～ていく／～てくる（复合动词）', '与动词连用构成复合动词，表示动作的持续、消失、出现等，如「生きていく」「消えていく」。', '只理解方向性，忽略其表示过程或状态的用法。', '日本語：これからも頑張っていきます。说明：表示继续努力下去。
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('27bf185c-3c4f-57b1-8fc1-ed650c30b6ba', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '5b34d8b5-bde9-c4c6-c736-84adaaae3603', '「あわや」的用法', '掌握副词「あわや」表示“险些、差一点”的用法。', '与「あやうく」混淆，但「あわや」更强调紧迫感。', '日本語：あわや事故になるところだった。；说明：险些酿成事故。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('280e14ec-6894-546d-9daa-ef43203eaaa3', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '3760dfca-44d9-3445-01cd-85de1f860da1', '～にもかかわらず', '表示尽管……却……，带有意外、不满的语气。接续：名词/动词普通形＋にもかかわらず。', '与「のに」相似，但「にもかかわらず」更正式，且可接名词。', '彼は病気にもかかわらず、出勤した。；说明：尽管他生病了，还是去上班了。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('282a41b4-d9b3-5c53-a17d-f5fd0371c5d1', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', 'baa9b5c2-5b94-4f9b-7ced-3a8c3cde4cb3', '常用量词与名词的搭配选择', '掌握「本、枚、冊、台、匹、人、回、つ」等量词与不同类别名词的搭配，如细长物用「本」，薄平物用「枚」。', '误用量词，如把猫说成「一匹」正确，但狗也可用「匹」，而兔子常用「羽」；把书说成「一本」应为「一冊」。', '日语例句：りんごを三つ買った。；说明：「つ」用于一般物品（1-9），但10以上用「個」。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('286b18ee-fce2-5fa3-8032-2869a294ef60', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '5b34d8b5-bde9-c4c6-c736-84adaaae3603', '「主」的读音与词义', '「主」在「主人」「主要」中读「しゅ」，表示主人、主要，但「主」在「主」字中读「ぬし」表示持有者。', '将「主」一律读作「しゅ」，混淆「主人」与「主」的用法。', '例句：彼はこの店の主人だ。说明：「主人」读「しゅじん」，指主人、店主。；例句：主要な問題を話し合う。说明：「主要」读「しゅよう」，指主要。；例句：この本の主は誰ですか。说明：「主」读「ぬし」，指所有者。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('29c2127e-652b-5ab0-843f-01d4aa21129e', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '1af448c1-54cf-2f94-01b5-e8bc77a97f94', '～ことになる（客观决定・结果）', '表示公司、学校等外部决定或自然导致的结果，接动词辞书形或ない形。', '与～ことにする混淆；注意有时表示“也就是说”的解释用法。', '来月、大阪に転勤することになりました。（公司决定下月调到大阪。）／この薬を飲めば、熱が下がることになる。（如果吃这个药，烧就会退。）', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('2a38f969-9db2-54f7-bfd0-07542b595042', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', 'dd4e968a-3d37-98a7-3819-a5fc4c117122', '～てもいい（许可）', '表示“可以做……”，接续：动词て形+もいい。口语中可省略も。', '否定形式「～てはいけない」表禁止，不要混用。', '日本語：ここで写真を撮ってもいいですか。；说明：可以在这里拍照吗？', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('2a8ae7b4-93f9-55c9-8ca2-3814db1a248b', '9221fc32-a051-42cb-86b1-6a9917aa004e', '42de0c7b-50d9-4159-918a-4e618d83342d', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', 'ef36118d-0ba3-29ce-b2b3-76eaeb6542ca', 'てください（请求）', '表示请求对方做某事，接动词て形后加ください。', '与てはいけません混淆；动词て形变化错误。', '窓を開けてください。；说明：请打开窗户。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('2b2173c1-8e75-55c8-bee9-140a337c3181', '9221fc32-a051-42cb-86b1-6a9917aa004e', '42de0c7b-50d9-4159-918a-4e618d83342d', '1d183755-02b3-4a6d-b727-082af1ef377c', '37a506cf-ef62-8ccc-3210-ab64e8561a4d', '利用に和で定位场所', '能够区分に表示存在或移动的终点，で表示动作发生的场所，从而正确理解事件发生的地点。', '混淆に和で，导致将动作场所误认为存在位置。', '例句：学校で勉強します。说明：で表示学习发生的场所；例句：教室に机があります。说明：に表示桌子存在的位置。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('2b6081c3-3f04-58a8-80e4-c413038fb619', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '3760dfca-44d9-3445-01cd-85de1f860da1', '～をはじめとして', '表示“以…为首”，列举代表性例子，暗示还有其他同类。接续：名词+をはじめとして/をはじめとする。', '注意后接名词时用「をはじめとする」，后接动词时用「をはじめとして」。', '日本をはじめとして、アジアの多くの国で地震が多い。；说明：以日本为首，亚洲许多国家地震多。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('2b801096-e96a-58de-b5b0-c85a0a0fbd3a', '9221fc32-a051-42cb-86b1-6a9917aa004e', '42de0c7b-50d9-4159-918a-4e618d83342d', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', 'ef36118d-0ba3-29ce-b2b3-76eaeb6542ca', 'から/ので（原因）', 'から主观原因，ので客观原因。接续：普通形+から/ので（名词+なので）。', 'ので后接命令、请求不自然；口语中から常省略。', '雨が降ったから、行きませんでした。说明：因为下雨没去；風邪なので休みます。说明：因为感冒请假。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('2b9261ba-6574-5636-9e7f-268e84f52b28', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', 'ff057d86-47bc-de16-f0f9-a7b808b968e3', 'N3片假名外来语的实际用法（扩展四）', '掌握N3阶段常见但易混淆的片假名外来语，如「リスク」「チャンス」「マナー」「ニュアンス」等，理解其在日常会话和书面语中的具体使用场景及搭配。', '学习者容易将外来语与和语词混用，或忽略外来语的语感差异，例如「リスク」比「危険」更正式且常用于商务语境。', '日语例句：この計画にはリスクが伴います。；说明：「リスク」用于正式场合，表示风险。日语例句：チャンスを逃さないようにしよう。；说明：「チャンス」强调机会，比「機会」更口语化。日语例句：彼の話し方にはニュアンスがある。；说明：「ニュアンス」指微妙的语感差异，不可用「意味」替代。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('2b9ddda8-b86b-5ddf-bf23-7f3274b806f1', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '1d183755-02b3-4a6d-b727-082af1ef377c', 'fc58533f-fd29-5132-8f21-fd381828e3c8', '理解否定表达', '掌握「〜ない」「〜ません」「〜ないで」「〜なくてもいい」等否定形式，注意部分否定与全否定。', '混淆「〜なくてもいい」（不必）与「〜ないでください」（禁止）；忽视双重否定。', '日语例句：明日は来なくてもいいです。说明：表示不必来，而非禁止。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('2ba7a3ea-7edc-511e-86d8-9ee8daf4abca', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', 'ff057d86-47bc-de16-f0f9-a7b808b968e3', '复合动词的构成与意义', '理解N3常见复合动词（如「～始める」「～続ける」「～終わる」「～出す」）的构成，掌握其表示动作开始、持续、结束、突发等含义。', '将「～出す」误用为开始，实际表示突然发生；忽视复合动词的自动词/他动词性。', '日语例句：雨が降り出した。勉強を続けなさい。；说明：降り出す表示突然开始下雨，続ける表示持续。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('2bab65aa-6204-566c-a3a5-8ab5631baf62', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '2c18e7e1-4ef0-65e3-24a7-6c97d562a122', '～であれ／であれ～であれ', '表示“无论……还是……”的意思，接续：名词＋であれ，或名词＋であれ＋名词＋であれ。', '与「～であろうと」相似，但「であれ」更正式，且常成对使用。', '日语例句：結果がどうであれ、努力は無駄ではない。；说明：无论结果如何，努力都不会白费。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('2bc9001c-125f-5156-9de2-a48050f15cef', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', 'dd4e968a-3d37-98a7-3819-a5fc4c117122', '～たらどうですか（建议做…怎么样）', '委婉地建议对方做某事。接续：动词た形+らどうですか。', '比～たほうがいい更委婉；口语中可省略为～たら？', '日本語：一度病院に行ったらどうですか。；说明：去医院看看怎么样？', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('2bd8cdbe-be5f-5ca9-bb35-6d07009b5b18', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '0545d0ec-89d1-a8aa-99f9-78b30fcbacb1', '多义动词「かける」的多种用法', 'N2需掌握「かける」的多义用法：表示悬挂、花费（時間）、施加（压力）、开始（話しかける）、覆盖（布団をかける）等。', '只知“挂”一义；混淆「時間をかける」与「時間がかかる」。', '日语例句：彼に電話をかけた。；说明：「電話をかける」是固定搭配，表示打电话；「時間をかける」表示花费时间。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('2bdeed66-a95d-5488-bb24-f3588f847fa4', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', 'dd4e968a-3d37-98a7-3819-a5fc4c117122', '～てはいけませんよ（禁止・提醒）', '表示“不可以……哦”，用于提醒或警告对方，语气较正式。', '误用为请求许可，实际是禁止；注意与～てはいけません的区别，后者更直接。', '日本語：ここで遊んではいけませんよ。；说明：这里不可以玩耍哦。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('2bebaa31-db3f-5928-bc81-e8253091cf30', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', 'dd4e968a-3d37-98a7-3819-a5fc4c117122', '～ことにする（决定）', '表示“决定做……”，接续：动词辞书形/ない形+ことにする。', '与～ことになる混淆，前者主观决定，后者客观规定。', '日本語：毎日運動することにした。；说明：决定每天运动。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('2bf1d1f3-1236-5381-b936-8395fb799e37', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '5b34d8b5-bde9-c4c6-c736-84adaaae3603', '「差」的多种读音与词义', '「差」在N1中常见读音「さ」，词义包括“差别、差异”“派遣”“差错”等。如「差別（さべつ）」「差額（さがく）」「差し支え（さしつかえ）」「誤差（ごさ）」「差配（さはい）」。', '「差し支え」读「さしつかえ」而非「さしさ」；「差」在「差別」中读「さ」，不要读成「しゃ」。', '両者の差（さ）は大きい。说明：差指差距。；差し支え（さしつかえ）があれば連絡してください。说明：差し支え指妨碍、不便。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('2bfe9099-521a-5ebc-aeda-e6b0174fd903', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '1d183755-02b3-4a6d-b727-082af1ef377c', '40ed56d1-acbd-4a8b-6284-2df8b9423e8e', '反问句与修辞疑问理解', '识别文中反问句、设问句等修辞性疑问，理解其真实含义（通常为强调或否定），而非字面提问。', '把反问句当成真问题去文中找答案；忽略反问句表达强烈肯定或否定的功能；不理解设问句的自问自答结构。', '日语例句：こんな簡単な問題が、どうして解けないだろうか。说明：这是反问句，实际意思是“这么简单的问题应该能解”，表达肯定语气。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('2c39fabf-ea25-5498-aa50-f12c39143acf', '9221fc32-a051-42cb-86b1-6a9917aa004e', '42de0c7b-50d9-4159-918a-4e618d83342d', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '0e03a921-5aff-e4be-f477-4d55640b198b', '特殊量词的汉字读音（非数字组合）', 'N5中量词如「人（にん）」「日（にち）」「月（がつ）」「年（ねん）」在特定数字下的特殊读音，如「一人（ひとり）」「二人（ふたり）」「一日（ついたち）」「一日（いちにち）」。', '将「一人」读成「いちにん」，或「一日」在表示日期时读「ついたち」而表示时长时读「いちにち」。', '日本語例：一人で行きます。说明：「一人」读作「ひとり」，是特殊读音。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('2c800c93-5eba-5ad1-bc61-129d37b786b6', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '5b34d8b5-bde9-c4c6-c736-84adaaae3603', '「愛」的多种读音与词义', 'N1级汉字「愛」除常用音读「あい」外，在「愛でる（めでる）」「愛しい（いとしい）」等词中读训读，需掌握不同读音对应的词义与用法。', '误将「愛でる」读作「あいでる」，或混淆「愛しい」与「可愛い」的语感。', '例句：彼女は庭の花を愛でるのが好きだ。说明：「愛でる」意为欣赏、疼爱，读「めでる」。；例句：愛しい我が子の成長が嬉しい。说明：「愛しい」意为可爱、令人怜爱，读「いとしい」。；例句：母の愛は深い。说明：此处「愛」读「あい」，指抽象的爱。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('2d659838-d7d5-5f3e-ab4d-73d377f76c56', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', 'dd4e968a-3d37-98a7-3819-a5fc4c117122', '～てはなりません（禁止・正式）', '表示禁止，比～てはいけない更正式，常用于书面语或规则。接续：动词て形+はなりません。', '口语中不常用；注意ては常缩约为ちゃ，但此处正式场合不缩约。', '日本語：ここでタバコを吸ってはなりません。；说明：此处禁止吸烟。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('2de7b69f-4dec-52f3-9915-b800e91aa653', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', 'baa9b5c2-5b94-4f9b-7ced-3a8c3cde4cb3', 'い形容词的活用与使用', '掌握N4い形容词的过去、否定、て形等活用，理解其修饰名词和谓语的用法。', '将い形容词过去式误用为「～かったです」与「～でした」混淆；忘记い形容词修饰名词时直接连接。', '日语例句：昨日は暑かったです。；说明：「暑い」的过去式是「暑かった」，注意礼貌体加「です」，但「です」不变化。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('2e0d5c34-f6ec-5fce-a739-89f02624d3f0', '9221fc32-a051-42cb-86b1-6a9917aa004e', '42de0c7b-50d9-4159-918a-4e618d83342d', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', 'ef36118d-0ba3-29ce-b2b3-76eaeb6542ca', 'てはいけないか（确认禁止）', '用于确认是否禁止，但实际使用较少，多用于书面或正式确认。', '口语中多用「てはいけないの？」或「ちゃいけない？」。', 'ここで遊んではいけないか。；说明：这里不能玩吗？', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('2eadc8b1-726c-5835-b6ff-eb10c37577bb', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '2c18e7e1-4ef0-65e3-24a7-6c97d562a122', '～にとっての', '「～にとって」修饰名词的形式，表示“对于…的”。接续：名词+にとっての+名词。', '注意接续，不能直接加名词。', 'これは私にとっての宝物だ。说明：对我来说的宝物。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('2ecdae8b-a4dc-5569-a7b7-8594fc760abf', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '5b34d8b5-bde9-c4c6-c736-84adaaae3603', '「拒絶」与「拒否」的细微差异', '「拒絶」强调拒绝接受、排斥，多用于感情、要求；「拒否」强调拒绝许可、同意，多用于申请、提案。N1需辨析。', '将两者完全互换；忽略「拒絶」有排斥的语感。', '彼女はその申し出を拒絶した。（她拒绝了那个请求）说明：「拒絶」含排斥。／入国を拒否された。（被拒绝入境）说明：「拒否」指官方拒绝。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('2f08189e-db35-5039-a564-a9cfd0277412', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', 'dd4e968a-3d37-98a7-3819-a5fc4c117122', '～てある／～ておく（状态与准备）', '～てある表示动作结果的状态（人为），～ておく表示事先做好某事。', '混淆两者：てある强调状态，ておく强调准备动作。', '日本語：窓が開けてある。说明：窗户开着（有人开的）。
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('2f0e39df-c181-5be5-8089-1dfb4214eb4e', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '3760dfca-44d9-3445-01cd-85de1f860da1', '～にほかならない', '表示“正是…、无非是…”，用于强调原因或本质。接续：名词+にほかならない。', '与「～に違いない」区别：前者表示断定“正是”，后者表示推测“一定”。', '彼の成功は努力の結果にほかならない。；说明：他的成功正是努力的结果。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('2f84f91b-22f3-5432-82ff-4c527eb0ec74', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '2c18e7e1-4ef0-65e3-24a7-6c97d562a122', '～てやまない', '表示强烈希望或祝愿，相当于「非常に～している」。接续：动词て形＋やまない。', '只能接表示愿望或感情状态的动词，如「願う」「期待する」等，且主语多为第三人称。', '彼の成功を心から願ってやまない。；说明：衷心祝愿他成功。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('2fd3e0f2-41c7-515c-a284-69bb11c48b78', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', 'baa9b5c2-5b94-4f9b-7ced-3a8c3cde4cb3', '形容词否定形式的语义与用法', 'い形容词和な形容词的否定形式（如「高くない」「元気ではない」）表达否定意义，需注意其礼貌体（高くありません）及口语缩略（高くない）。', '将「高くない」误用为「高くないです」的省略时忽略「です」；な形容词否定时误用「でない」与「ではない」的语体差异。', '日语例句：この料理は辛くないです。；说明：「辛くない」是「辛い」的否定形，表示“不辣”，注意い形容词否定时词尾い变く。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('3002f125-7bae-5942-b17e-70d41237b1a6', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '2c18e7e1-4ef0-65e3-24a7-6c97d562a122', '～につれて', '表示随着前项变化，后项也相应变化。接续：动词辞书形+につれて。', '与「～に伴って」类似，但「につれて」更口语化。', '年を取るにつれて、朝早く目が覚めるようになった。说明：随着年龄增长。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('30a2e5f2-8ad6-5430-aa8f-f008f6b04440', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '0545d0ec-89d1-a8aa-99f9-78b30fcbacb1', '形容动词（ナ形容词）的活用与搭配', '掌握N2形容动词（如「複雑だ」「適切だ」）的连体、连用、终止形用法，以及常见搭配（如「複雑な事情」）。', '将形容动词误作形容词使用，如「複雑い問題」；或忽视其与名词之间的「な」连接。', '日语例句：これは複雑な問題だ。；说明：「複雑」为形容动词，修饰名词时用「な」。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('30a4a2ac-ce1f-5c28-a98b-f3a12bf7d210', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '1d183755-02b3-4a6d-b727-082af1ef377c', '40ed56d1-acbd-4a8b-6284-2df8b9423e8e', '隐含条件与前提推断', '根据文章内容，推断作者或说话人未明说但隐含的前提条件或背景知识，理解论述的成立基础。', '将隐含前提当作文中明确陈述；推断过度，加入与原文无关的假设；忽略文化或常识背景。', '日语例句：彼は毎日ジョギングしているのに、なぜか痩せない。说明：隐含前提是“每天跑步通常能减肥”，但结果相反，从而引出疑问或转折。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('312bfc99-6285-5fb4-a1ab-2c8cb89db78c', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '2c18e7e1-4ef0-65e3-24a7-6c97d562a122', '～にしては', '表示与通常标准相比，后项出乎意料。接续：名词/动词普通形+にしては。', '与「～にしても」混淆，前者强调“照…来说”，后者强调“即使”。', '初めてにしては、上手にできた。说明：作为第一次来说做得很好。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('31306f8c-79d5-5a3e-a5d2-4f97d670be67', '9221fc32-a051-42cb-86b1-6a9917aa004e', '42de0c7b-50d9-4159-918a-4e618d83342d', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', 'ef36118d-0ba3-29ce-b2b3-76eaeb6542ca', 'てもいいですか（疑问句）', '请求许可的疑问句，注意回答时肯定用「はい、いいです」，否定用「いいえ、だめです」。', '回答时用「てもいいです」表示否定。', 'この本を借りてもいいですか。はい、いいですよ。；说明：可以借这本书吗？可以。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('32053eb0-9741-5013-84a9-e9da4d42a17c', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', 'ff057d86-47bc-de16-f0f9-a7b808b968e3', 'N3表达意图和打算的词汇（扩展三）', '掌握N3中表达意图和打算的词汇如「つもり」「予定」「意向」「心積もり」等，并区分「つもり」与「予定」在确定性和口语性上的差异。', '「つもり」表示主观打算，不一定有具体安排；「予定」表示预定计划，更客观具体；「つもり」有时用于“自以为”的意思。', '例句：来年日本に行くつもりだ。说明：「つもり」表示打算；例句：明日会議の予定がある。说明：「予定」表示预定；例句：彼は自分では正しいつもりだ。说明：「つもり」表示自以为。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('3210f183-11e7-56ee-bbb5-a6afa4d29cbd', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '1af448c1-54cf-2f94-01b5-e8bc77a97f94', '～ところだ（时间点）', '接动词不同形式表示动作即将发生（～するところ）、正在进行（～しているところ）、刚刚结束（～したところ）。', '与～ばかり混淆；注意接续：动词辞书形+ところだ表示即将，ている+ところだ表示进行，た+ところだ表示刚结束。', '今、出かけるところです。（正要出门。）／今、食事をしているところです。（正在吃饭。）／今、帰ったところです。（刚回来。）', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('326e4c72-2baf-5e46-a108-e40815dc715e', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '3760dfca-44d9-3445-01cd-85de1f860da1', '～ことか', '表示感叹，相当于“多么……啊”。接动词或形容词的普通形。', '误用于疑问句；注意与“～ことだろう”相同，但“ことか”更强调感叹。', '日语例句：何度も失敗したことか。；说明：不知失败了多少次啊。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('3291e28d-cf49-5c00-ac53-37e1f28953eb', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '3760dfca-44d9-3445-01cd-85de1f860da1', '～において', '表示在……场合、领域、时间等。接续：名词＋において。', '书面语，口语中常用「で」。', '会議は東京において開催された。；说明：会议在东京召开。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('3299d329-f0a2-5727-b115-2cc5d2b7dc0e', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '2c18e7e1-4ef0-65e3-24a7-6c97d562a122', '～を余儀なくされる', '表示“被迫……，不得不……”，强调由于客观情况而被迫做某事。接续：名词+を余儀なくされる。', '注意被动形式，主动为「～を余儀なくさせる」；不要与「～ざるを得ない」混淆，后者更主观。', '日本語：台風のため、試合は中止を余儀なくされた。；说明：由于台风，比赛被迫中止。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('332a1214-c91d-5006-9c54-29d5feb2bdb6', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', 'baa9b5c2-5b94-4f9b-7ced-3a8c3cde4cb3', '二字汉字复合词的读音规则', '掌握N4常见二字复合词（如：勉強、旅行、食事、電話）的读音，特别是音读组合或音训混读的规律。', '将「勉強」误读为「べんきょ」漏掉长音；或把「手紙」读成「てがみ」但误以为是「しゅし」等。', '日语例句：毎日日本語を勉強します。；说明：「勉強」是音读「べんきょう」，注意长音。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('33f781a0-6e83-50a8-bbfb-83356c1d2f0d', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', 'ff057d86-47bc-de16-f0f9-a7b808b968e3', 'N3常见量词的高级用法（扩展四）', '学习N3中高级量词如「～冊」「～本」「～枚」「～台」等在不同物品上的正确使用，以及特殊量词如「～羽」（兔子）、「～頭」（大型动物）的区分。', '学习者常将「本」用于所有细长物，但「本」用于瓶、笔等，而「枚」用于薄平物，如纸、照片；「頭」用于牛马等大型动物，不用于猫狗。', '日语例句：本を三冊買いました。；说明：「冊」用于书籍。日语例句：鉛筆を二本ください。；说明：「本」用于细长物。日语例句：ウサギを一羽飼っています。；说明：「羽」用于兔子，特殊用法。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('33f8ac94-be3d-5363-8b1f-483e0d14a4ac', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '5b34d8b5-bde9-c4c6-c736-84adaaae3603', '「厚い」「暑い」「熱い」的读音与用法区分', '掌握「あつい」在表示厚度、气温、温度时的不同汉字表记及语境。', '将「厚い」用于气温，或将「暑い」用于物体温度。', '日本語：この本は厚いですね。；说明：表示书本厚度，用「厚い」。日本語：今日は暑いです。；说明：表示天气炎热，用「暑い」。日本語：お湯が熱いです。；说明：表示液体温度高，用「熱い」。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('342bea56-23dd-5d02-b970-df0fae04c655', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '1d183755-02b3-4a6d-b727-082af1ef377c', '9c37478d-2388-1380-cdea-3b62d82c3fcb', '隐含信息的推理', '根据文章上下文和逻辑线索，推断作者未直接言明的信息，如原因、结果、人物关系或事件背景。', '过度推理，脱离文本依据；将可能性当作必然性；忽略文中的限定词（如「かもしれない」）。', '日语例句：彼はその話を聞いて、黙って席を立った。说明：从行为可推断他可能不满或震惊，但不可断言具体情绪，需结合前后文。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('34374b4e-cc91-5979-9f4d-1baf94d208d8', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '1af448c1-54cf-2f94-01b5-e8bc77a97f94', '～てもいいですか（请求许可）', '用于礼貌地请求许可。接续：动词て形+もいいですか。是～てもいい的疑问形式。', '与～てもかまいませんか混淆，后者更正式。注意回答时用はい、いいです或いいえ、～てはいけません。', '日本語：窓を開けてもいいですか。；说明：询问“可以开窗吗？”', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('3455b4b3-4b3b-5413-9873-c9e1a58b55f7', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '0545d0ec-89d1-a8aa-99f9-78b30fcbacb1', '汉字复合词中保留古读或惯用读法的词', 'N2需掌握部分复合词保留古音或惯用读法，如「昨日（きのう）」「今日（きょう）」「明後日（あさって）」「一昨日（おととい）」。这些词不能按现代音读规则拼读。', '学习者常将「明後日」误读为「みょうごにち」或「あさって」混淆，或将「一昨日」误读为「いちさくじつ」。', '日语例句：明後日は試験だ。；说明：「明後日」读「あさって」，为惯用训读，不可按音读「みょうごにち」理解。日语例句：一昨日は雨だった。；说明：「一昨日」读「おととい」，为特殊训读。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('345c31cc-efaa-5ded-a6ef-cb527fd7e1fb', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', 'dd4e968a-3d37-98a7-3819-a5fc4c117122', '～てしまう（完了・遗憾）', '表示动作完成或结束，常带有遗憾、后悔、无奈等感情色彩。', '只理解“完了”，忽略其表达遗憾的功能。', '日本語：ケーキを全部食べてしまった。说明：把蛋糕全吃完了（遗憾）。
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('345c4a89-5e1f-530b-8510-d6489b18f189', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', 'e5877362-1f27-54a5-903f-528a6d53f294', '基本句型与指示词', '掌握判断、存在、指示和疑问等基础句型。', '把指示词、疑问词和助词的功能混在一起。', 'これは新しい本です。', 'published', '2026-09-03 13:10:31.032213+08', '2026-09-03 13:10:31.032213+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('34b30070-5183-5834-8479-fb9c9a69b3f6', '9221fc32-a051-42cb-86b1-6a9917aa004e', '42de0c7b-50d9-4159-918a-4e618d83342d', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', 'ef36118d-0ba3-29ce-b2b3-76eaeb6542ca', 'てはいけませんね（禁止确认）', '确认禁止事项，常用于提醒对方。', '与「てはいけません」混淆，后者直接禁止。', 'ここで走ってはいけませんね。；说明：这里不能跑吧。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('352716b1-d279-516f-a5fd-49d3f2c8ae03', '9221fc32-a051-42cb-86b1-6a9917aa004e', '42de0c7b-50d9-4159-918a-4e618d83342d', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', 'ef36118d-0ba3-29ce-b2b3-76eaeb6542ca', 'てはいけない（禁止）', '动词て形+はいけない表示禁止。接续：て形+はいけない。', '与てもいい混淆；口语中は常省略为ちゃいけない。', 'ここで写真を撮ってはいけません。说明：这里不能拍照。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('35956a22-24f3-5c05-962a-3732c92ef2c6', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', 'ff057d86-47bc-de16-f0f9-a7b808b968e3', 'N3复合动词的构成与意义（扩展）', '理解「～始める」「～続ける」「～終わる」「～出す」「～込む」等后项动词带来的意义变化，如「読み始める」「読み続ける」「読み終わる」。', '混淆「～出す」表示突然开始（如「泣き出す」）与「～始める」的普通开始。', '日语例句：雨が降り出した。；说明：「降り出す」表示突然开始下雨。；日语例句：この本を読み終わった。；说明：「読み終わる」表示读完。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('359d505f-e2e3-55c5-a3cf-6be95736bead', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '1af448c1-54cf-2f94-01b5-e8bc77a97f94', '～というわけではない', '表示并非前项所推测或认为的那样，相当于“并不是说……”。用于否定一种普遍的推论或印象。', '容易与“～わけがない”（不可能）混淆；本句型是部分否定，表示“不一定”，而“わけがない”是强烈否定。', '日本語が上手だからといって、すべての漢字が読めるというわけではない。；说明：虽说日语好，但并不是所有汉字都会读。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('3646c972-2312-599c-8c96-042ec7e608b8', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '1af448c1-54cf-2f94-01b5-e8bc77a97f94', '～ようになる（变化）', '表示状态的变化，逐渐变得能够…或变得习惯…，接动词辞书形或ない形。', '与～ことになる混淆：～ようになる强调能力或习惯的变化，～ことになる强调决定或结果。', '日本語が話せるようになりました。（变得会说日语了。）／毎朝早く起きるようになった。（变得每天早起。）', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('36507257-4c47-5674-8b62-3aca37fb96d6', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', 'ff057d86-47bc-de16-f0f9-a7b808b968e3', 'N3近义形容词的语感差异（扩展二）', '辨析N3中易混形容词，如「うまい/おいしい」「かわいい/きれい」「つらい/苦しい」「眠い/眠たい」等，注意使用对象、主观客观、口语书面等差异。', '将「うまい」用于正式场合评价他人手艺时显得失礼；混淆「つらい」与「苦しい」在精神与肉体痛苦上的侧重。', '日语例句：この料理はとてもおいしいです。／彼は料理がうまい。；说明：「おいしい」侧重味道好，「うまい」更口语且可指技能好。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('36786139-3936-5a3a-be4d-17583f5af4c9', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', 'ff057d86-47bc-de16-f0f9-a7b808b968e3', '表达意图和打算的词汇', '掌握N3中表示意图的词汇和句型，如「つもり」「予定」「～ようと思う」「～たい」等，区分其语气和正式度。', '将「つもり」用于客观计划，而「予定」更正式；混淆「～たい」和「～ようと思う」的主观性。', '日语例句：来年日本へ行くつもりです。旅行の予定を立てています。；说明：つもり表示个人打算，予定表示安排。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('36e8f0cb-2302-5168-b01b-5a9eefc9f042', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '2c18e7e1-4ef0-65e3-24a7-6c97d562a122', '～を抜きにしては', '表示“省去～就无法”，后接否定或消极结果，强调某要素不可或缺。接名词。', '与「～なしには」混淆，两者可互换，但「～を抜きにしては」更强调“去除”。', '先生を抜きにしては、この研究は語れない。；说明：没有老师，这项研究就无从谈起。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('36f8b5de-f86f-54d8-97a1-4b5f2339d5c0', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', 'baa9b5c2-5b94-4f9b-7ced-3a8c3cde4cb3', '形容词名词化（～さ、～み）的用法区别', '形容词词干加「さ」表示程度或性质（如「高さ」），加「み」表示感觉或具有该性质的部分（如「深み」）。N4阶段需掌握常见搭配。', '混淆「～さ」与「～み」的语义，如「重さ」表示重量，「重み」表示分量感；不熟悉哪些形容词可加「み」。', '日语例句：この箱の重さを測ってください。；说明：「重さ」表示具体的重量，而「重み」多用于抽象意义。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('3741be9b-e9b4-5eac-991f-233a6c7a522b', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '5b34d8b5-bde9-c4c6-c736-84adaaae3603', '「故」的多种读音与词义', '「故」在N1中常见读音「こ」「ゆえ」，词义包括“原因、理由”“旧、过去”“去世”等。如「故郷（こきょう）」「故人（こじん）」「事故（じこ）」「故に（ゆえに）」「故買（こばい）」。', '「故に」读「ゆえに」而非「こに」；「故郷」读「こきょう」而非「ゆえさと」。', '事故（じこ）が発生した。说明：事故指意外事件。；彼は故人（こじん）となった。说明：故人指已故之人。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('37804dd6-972e-587e-bad7-e2808d085fd9', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '0545d0ec-89d1-a8aa-99f9-78b30fcbacb1', '形式名词（こと・もの・ところ・わけ・はず）的语义区分', 'N2要求区分形式名词在句中的抽象意义：「こと」表示事实/事情，「もの」表示物品/抽象事物，「ところ」表示场所/阶段，「わけ」表示理由/道理，「はず」表示推测的根据。需结合语境选择。', '将「わけ」与「はず」混用；忽视「こと」与「の」在句中的互换限制；在否定句中误用「もの」。', '日本語：彼が来なかったわけを聞いた。；说明：「わけ」指理由。／日本語：彼はもうすぐ来るはずだ。；说明：「はず」表示有根据的推测。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('37b7a6aa-d230-5e0f-83ad-97deaa61780b', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '3760dfca-44d9-3445-01cd-85de1f860da1', '～てたまらない', '表示程度非常强烈，无法忍受，相当于“……得不得了”。接形容词て形或动词て形。', '误用于客观描述，而应强调主观感受；注意与“～てならない”相近。', '日语例句：頭が痛くてたまらない。；说明：头疼得不得了。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('37d8b62e-983d-5d0e-b321-46f0cb422301', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', 'ff057d86-47bc-de16-f0f9-a7b808b968e3', 'N3自他动词成对辨析（扩展三）', '区分N3中更多自他动词对，如「壊れる/壊す」「落ちる/落とす」「消える/消す」「割れる/割る」，并掌握其使用场景和主语差异。', '混淆自动词表示状态变化、他动词表示人为动作；如「窓が割れた」与「窓を割った」的主语和含义不同。', '例句：コップが割れた。说明：自动词，强调杯子自己碎了；例句：彼がコップを割った。说明：他动词，强调他打碎了杯子。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('37e4bfb8-c5c1-57ed-89cf-9353159ca235', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '1d183755-02b3-4a6d-b727-082af1ef377c', '40ed56d1-acbd-4a8b-6284-2df8b9423e8e', '区分事实与意见', '能判断句子是客观事实还是作者主观意见，理解“～と思う”“～らしい”“～はずだ”等表达的主观性。', '将带“～と思う”的句子误认为事实；忽视“～かもしれない”的不确定性。', '日语例句：この本は去年出版された。そして、多くの人に読まれているらしい。说明：前半句是事实，后半句因“らしい”表示传闻，属于不确定信息。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('38433620-9ee5-5850-8a7a-3a0eb6e96901', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '5b34d8b5-bde9-c4c6-c736-84adaaae3603', '「さすが」的用法', '掌握「さすが」表示“不愧是、到底”的赞赏或意料之中。', '与「やはり」混淆，但「さすが」含褒义。', '日本語：さすがプロだ。；说明：不愧是专家。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('385473b2-4f27-5348-bd86-0cf2fe01cb6f', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '1af448c1-54cf-2f94-01b5-e8bc77a97f94', '～てある（状态存续）', '表示人为动作的结果状态存续，通常与表示意志动作的他动词搭配，句中有宾语时用「が」提示。', '与～ている混淆：～てある强调人为结果，～ている可表示自然状态或动作进行。', '壁に絵が掛けてあります。（墙上挂着画，是人为挂的。）／窓が開けてある。（窗户开着，是有人开的。）', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('3872ec21-3298-54b0-a887-33eee4a55110', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', 'dd4e968a-3d37-98a7-3819-a5fc4c117122', '～ば（假定条件）', '表示“如果……就……”，接续：动词ば形（え段+ば）、い形容词～ければ、な形容词/名词～なら（ば）。', '与～たら混淆，～ば强调条件与结果的必然关系，且后句不能是意志、命令等。', '日本語：春になれば、花が咲く。；说明：一到春天花就开。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('387c3527-0316-503a-9789-2139433b2916', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '1d183755-02b3-4a6d-b727-082af1ef377c', '40ed56d1-acbd-4a8b-6284-2df8b9423e8e', '根据上下文推测生词含义', '利用前后文、同义替换、反义对比、举例说明等线索推测未学单词或汉字词的大致意思。', '遇到生词立即查字典或放弃；忽略前后句的提示关系。', '日语例句：「この料理はとてもあっさりしている。油をあまり使わないからだ。」说明：从“油をあまり使わない”可推测“あっさり”意为清淡、不油腻。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('3890579e-5be0-5fb0-962a-3faf327864e8', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', 'ff057d86-47bc-de16-f0f9-a7b808b968e3', 'N3汉字复合词读音规律（扩展二）', '进一步掌握N3级别中由两个以上汉字构成的复合词的特殊读音，包括熟字训、音便、连浊等不规则现象，如「時々（ときどき）」「一人（ひとり）」「一日（ついたち/いちにち）」等。', '容易将复合词中的每个汉字按常见音读或训读机械拼读，忽视整体约定俗成的读音；混淆同形异音词在不同语境下的读法。', '日语例句：今日は一日（いちにち）中忙しかった。；说明：「一日」在此读「いちにち」，表示整天，而日期「一日」读「ついたち」。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('38fb4c1d-ccb3-5b31-9b1d-386a389aecfd', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '1af448c1-54cf-2f94-01b5-e8bc77a97f94', '～てもかまわない（许可・无妨）', '表示“即使～也没关系”，语气比～てもいい更宽容，常用于允许对方做某事。接续：动词て形＋も＋かまわない。', '误用为请求许可（应用～てもいいですか）；在拒绝时误用为“～てもかまいません”表示没关系，实际应明确拒绝。', '日本語：質問があれば、いつでもしてもかまいません。；说明：表示随时可以提问。
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('3916a0cd-35c4-5dfb-8510-e8a8bdf7c476', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', 'ff057d86-47bc-de16-f0f9-a7b808b968e3', 'N3动词て形与补助动词的组合（扩展三）', '掌握N3中「～てくる」「～ていく」「～てしまう」「～ておく」「～てみる」等补助动词的扩展用法，如表示方向、变化、完成、准备、尝试等。', '「～てくる」表示从过去到现在的变化或动作方向，如「太ってきた」；「～ていく」表示从现在到未来，如「消えていく」；「～てしまう」强调遗憾或完成。', '例句：最近太ってきた。说明：「～てくる」表示变化逐渐发生；例句：鳥が飛んでいった。说明：「～ていく」表示动作远去；例句：宿題を忘れてしまった。说明：「～てしまう」表示遗憾。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('39b983a1-432a-5519-bb64-0eb229ee657a', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '0545d0ec-89d1-a8aa-99f9-78b30fcbacb1', '表示被动与使役的复合形式（～される・～させる・～させられる）', '掌握被动「～される」、使役「～させる」、使役被动「～させられる」（被迫做）的构成和用法。', '学习者常混淆被动与使役，如「私は先生に褒めさせた」错误，应使用「褒められた」。', '日本語例：私は先生に褒められた。（我被老师表扬）／先生は学生に本を読ませた。（老师让学生读书）／私は母に買い物に行かせられた。（我被妈妈逼着去买东西）。说明：三者语态不同。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('39cdf58d-12d9-5c1a-995c-e673593bb029', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '5b34d8b5-bde9-c4c6-c736-84adaaae3603', '「鼓」的多种读音与词义', '「鼓」在N1中常见读音「こ」，词义包括“鼓”“敲鼓”“鼓起”等。如「鼓動（こどう）」「鼓膜（こまく）」「太鼓（たいこ）」「鼓舞（こぶ）」「鼓手（こしゅ）」。', '「太鼓」读「たいこ」而非「だいこ」；「鼓舞」读「こぶ」而非「こまい」。', '心臓の鼓動（こどう）が聞こえる。说明：鼓動指心跳、搏动。；太鼓（たいこ）を叩く。说明：太鼓指鼓。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('39e1d3d9-7aa1-5bd8-97da-b326eb2ccd7e', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '3760dfca-44d9-3445-01cd-85de1f860da1', '～にかかわることができる場合', '表示“能够涉及的情况”，用于限定条件。', '注意接续，后接“場合”时表示条件，需与“～にかかわることができる”区分。', '日本語：このデータにかかわることができる場合は、管理者だけだ。；说明：能够接触这些数据的情况仅限于管理员。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('3a21d8b5-5448-5bfb-abf6-19b1796bbfa7', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '0545d0ec-89d1-a8aa-99f9-78b30fcbacb1', '接尾辞「～さ」「～み」「～め」构成抽象名词', 'N2中接尾辞「～さ」表示程度，「～み」表示感觉，「～め」表示倾向，如「高さ」「重み」「多め」。', '混淆「～さ」与「～み」的语义，如将「深さ」与「深み」混用。', '例句：このビルの高さは100メートルだ。说明：「高さ」表示高度。；例句：彼の言葉には重みがある。说明：「重み」表示分量、深意。；例句：砂糖は多めに入れてください。说明：「多め」表示偏多。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('3a4481b0-5ab0-514c-8cc6-e4e0cc0a49b4', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '1d183755-02b3-4a6d-b727-082af1ef377c', '6f1477f5-00be-f963-76b6-5165f568e88e', '主题句位置识别', '在日语文章中，主题句常出现在段落开头或结尾，有时也在中间。本知识点训练读者快速定位每段的主题句，从而把握段落大意。', '误以为每段第一句一定是主题句，忽略转折词后的真正主题；或把具体例子当作主题。', '日语例句：最近の若者は本を読まないと言われるが、実際には電子書籍を読む人が増えている。説明：此句先提出普遍说法，再用转折引出真正主题，主题句在转折之后。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('3a758dea-2a65-5895-b7d7-5ff898592c25', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '2c18e7e1-4ef0-65e3-24a7-6c97d562a122', '～うる／うるない', '表示“可能”或“不可能”的意思，接动词ます形去掉ます后加「うる」或「えない」。注意「うる」有活用变化（うる、うる、うれ等）。', '「～うる」用于可能，但「～えない」表示不可能，注意「ありうる」「ありえない」的固定用法。', '日语例句：それはありうる話だ。；说明：那是可能发生的事情。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('3aba6e2c-f170-5c83-bddb-acbbc7b625d2', '9221fc32-a051-42cb-86b1-6a9917aa004e', '42de0c7b-50d9-4159-918a-4e618d83342d', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '0e03a921-5aff-e4be-f477-4d55640b198b', '书籍册数的量词「冊」', '掌握量词「冊（さつ）」用于数书、笔记本、杂志等装订成册的物品，读音无特殊变化，如一冊（いっさつ）、三冊（さんさつ）、何冊（なんさつ）。', '用「本」数书；将「一冊」读作「いちさつ」；将「三冊」读作「さんざつ」。', '日本語：本を一冊読みました。；说明：一冊读作「いっさつ」。日本語：雑誌を三冊買いました。；说明：三冊读作「さんさつ」。日本語：ノートを何冊持っていますか。；说明：何冊读作「なんさつ」。)', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('3ac2a2fe-7cd2-5b64-9afe-049936df3cc1', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '0545d0ec-89d1-a8aa-99f9-78b30fcbacb1', '表示变化的「～になる」「～する」「～てくる」「～ていく」', '掌握「～になる」（变成，自然变化）、「～する」（使变成，人为）、「～てくる」（逐渐变化，从过去到现在）、「～ていく」（逐渐变化，从现在到未来）的用法区别。', '学习者常混淆「～てくる」与「～ていく」的时间方向，如「寒くなってきた」表示变冷了，而「寒くなっていく」表示会继续变冷。', '日本語例：春になると暖かくなる。（一到春天变暖）／部屋をきれいにする。（把房间弄干净）／日本語が上手になってきた。（日语变好了）／これからもっと寒くなっていく。（今后会更冷）。说明：变化方向和时间不同。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('3ae20e93-d3e0-5a76-8862-85a42fd8c4d6', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '1af448c1-54cf-2f94-01b5-e8bc77a97f94', '～てみるか（尝试・反问）', '以反问形式表达“要不要试试…呢？”接续：动词て形+みるか。多用于自言自语或提议。', '与～てみる（尝试）混淆，该形式带疑问。注意～てみるか比～てみましょうか更口语。', '日本語：この料理を食べてみるか。；说明：提议“要不要尝尝这道菜？”', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('3b23a811-7965-5577-9547-5b6507708f80', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', 'baa9b5c2-5b94-4f9b-7ced-3a8c3cde4cb3', '动词的礼貌形（ます形）规则', '掌握动词ます形的变化规则（五段、一段、サ变、カ变），并能正确使用礼貌体。', '将五段动词ます形误变为「～り」等；混淆「来ます」与「帰ります」。', '日语例句：毎日七時に起きます。；说明：「起きます」是「起きる」的ます形，注意一段动词去る加ます。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('3b437363-f9e7-5527-a1e6-849e1c08e21c', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '2c18e7e1-4ef0-65e3-24a7-6c97d562a122', '～に心がある', '表示对某事物有心思、兴趣或牵挂。接续：名词+に心がある。', '不常用，注意与「～に気がある」（对…有意思）区分。', '彼は仕事よりも趣味に心があるようだ。说明：心思在爱好上。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('3b4453ca-1d09-57e6-8f25-43e5a1b2189c', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '5b34d8b5-bde9-c4c6-c736-84adaaae3603', '「質」的多种读音与词义', '「質」在N1中常见读音「しつ」「しち」，词义包括“质量”“本质”“抵押”等。如「質素（しっそ）」「質疑（しつぎ）」「質屋（しちや）」「人質（ひとじち）」「本質（ほんしつ）」。', '「質屋」读「しちや」而非「しつや」；「人質」读「ひとじち」而非「ひとしつ」。', '質素（しっそ）な生活を送る。说明：質素指朴素。；人質（ひとじち）を解放した。说明：人質指人质。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('3b82e873-fae7-594c-a9d0-083ec9501e18', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '3760dfca-44d9-3445-01cd-85de1f860da1', '～ように聞こえる', '表示听起来像…，从听觉判断。接动词辞书形/た形/ない形。', '与「～ように見える」混淆；误用为视觉判断。', '彼の声は悲しんでいるように聞こえる。说明：他的声音听起来好像很悲伤。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('3b906844-dc92-5c76-8032-c5996e727c17', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', 'baa9b5c2-5b94-4f9b-7ced-3a8c3cde4cb3', 'な形容词的活用与使用', '掌握N4な形容词（如「きれい」「便利」「元気」）的连体、连用、否定等活用形式。', '将な形容词误用为い形容词，如「きれいな」写成「きれいだ」；混淆「好き」与「嫌い」的用法。', '日语例句：静かな町が好きです。；说明：「静か」是な形容词，修饰名词时加「な」，注意「きれい」虽以い结尾但属于な形容词。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('3c1720c2-fe8e-5f66-b448-022f5d74061a', '9221fc32-a051-42cb-86b1-6a9917aa004e', '42de0c7b-50d9-4159-918a-4e618d83342d', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', 'ef36118d-0ba3-29ce-b2b3-76eaeb6542ca', 'たことがある（经历）', '动词た形+ことがある表示过去的经历。接续：た形+ことがある。', '与ている混淆；否定用たことがない。', '富士山に登ったことがあります。说明：爬过富士山。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('3c848844-bdbc-523f-a753-d21a48a182e8', '9221fc32-a051-42cb-86b1-6a9917aa004e', '42de0c7b-50d9-4159-918a-4e618d83342d', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '2d7157f8-afb7-58a0-85ea-b3d775f216a2', '授受、请求与敬语', '表达给予、接受、请求、许可、禁止和基础敬语。', '授受方向与受益者弄反，或把礼貌表达当作普通动词。', '先生に教えていただきました。', 'published', '2026-09-03 13:10:31.032213+08', '2026-09-03 13:10:31.032213+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('3cbd2ab5-5ac9-516d-9d37-03af44eaed68', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '1af448c1-54cf-2f94-01b5-e8bc77a97f94', '～たところだ（刚刚完成）', '表示动作刚刚结束，强调时间上的近接，常与“今”连用。', '与“～たばかり”相比，“～たところ”更强调“刚刚”的瞬间，且不能用于很久以前的事。', '日本語：今、駅に着いたところです。；说明：刚刚到达车站。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('3cbf932d-ebaf-5457-8155-f0930fd5a424', '9221fc32-a051-42cb-86b1-6a9917aa004e', '42de0c7b-50d9-4159-918a-4e618d83342d', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '0e03a921-5aff-e4be-f477-4d55640b198b', '细长物品的量词「本」', '掌握量词「本（ほん/ぼん/ぽん）」用于数瓶、笔、伞、树等细长物品，注意音变：1本（いっぽん）、3本（さんぼん）、6本（ろっぽん）、8本（はっぽん）、10本（じゅっぽん）。', '将1本读作「いちほん」、3本读作「さんほん」；用「本」数纸张或书本（书本用「冊」）。', '日本語：ビールを一本飲みました。；说明：一本读作「いっぽん」。日本語：傘を三本持っています。；说明：三本读作「さんぼん」。日本語：鉛筆を六本ください。；说明：六本读作「ろっぽん」。)', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('3cc9906d-dec8-5993-92f6-420caee9883d', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '5b34d8b5-bde9-c4c6-c736-84adaaae3603', '「主」的多种读音与词义', '「主」在N1中常见读音「しゅ」「ぬし」，词义包括“主人”“主要”“神主”等。如「主催（しゅさい）」「主役（しゅやく）」「主人（しゅじん）」「主（ぬし）」「民主（みんしゅ）」。', '「主」单独表示主人时读「ぬし」，如「家主（やぬし）」；「主人」读「しゅじん」而非「ぬし」。', 'この家の主（ぬし）は誰ですか。说明：主指主人、持有者。；主催（しゅさい）者を募集する。说明：主催指主办。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('3d11ce97-6b82-5146-abbe-dc205d0bff0a', '9221fc32-a051-42cb-86b1-6a9917aa004e', '42de0c7b-50d9-4159-918a-4e618d83342d', '1d183755-02b3-4a6d-b727-082af1ef377c', '53e79153-ad48-5407-b76a-c91a534f7659', '短文信息检索与主旨', '从通知、对话和短文中定位事实信息并理解主旨。', '只匹配单个词语，忽略时间、对象和否定等关键信息。', '案内を読んで、開館時間を確認します。', 'published', '2026-09-03 13:10:31.032213+08', '2026-09-03 13:10:31.032213+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('3d2b1329-3de2-51ae-bc09-2006c6805344', '9221fc32-a051-42cb-86b1-6a9917aa004e', '42de0c7b-50d9-4159-918a-4e618d83342d', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '0e03a921-5aff-e4be-f477-4d55640b198b', 'サ变动词的汉字读音', 'N5常见サ变动词（如「勉強する」「旅行する」「散歩する」）的汉字读音及「する」的用法。', '将「勉強」读成「べんきょう」以外的音，或忘记「する」的活用。', '日本語例：日曜日に散歩します。说明：「散歩」读作「さんぽ」，与「する」构成サ变动词。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('3d5546fd-2c14-5b6e-83fd-572161aa6bac', '9221fc32-a051-42cb-86b1-6a9917aa004e', '42de0c7b-50d9-4159-918a-4e618d83342d', '1d183755-02b3-4a6d-b727-082af1ef377c', '37a506cf-ef62-8ccc-3210-ab64e8561a4d', '识别が和でも的转折关系', '能够理解が连接两个分句时表示转折或铺垫，でも在句首表示转折，从而把握作者态度的变化。', '将が仅当作主语标记，忽略其接续助词功能。', '例句：日本語は難しいですが、おもしろいです。说明：が表示转折，前后内容相反。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('3d55d290-5593-5994-add3-c23a7c351c31', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '1d183755-02b3-4a6d-b727-082af1ef377c', '9c37478d-2388-1380-cdea-3b62d82c3fcb', '举例与论据的功能分析', '分析文中例子的作用：是支持论点、反驳观点、还是说明概念，理解例子与主旨的关系。', '将例子本身当作主旨；忽略例子前的提示语（如「例えば」）；未区分正例和反例。', '日语例句：例えば、ある研究では、睡眠不足が記憶力に悪影響を与えることが示されている。说明：例子用于支持前文的论点，证明睡眠的重要性。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('3d963a0f-5dca-5819-8aca-0ee0ef40629c', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '5b34d8b5-bde9-c4c6-c736-84adaaae3603', '「拒」的多种读音与词义', '「拒」在N1中常见读音「きょ」，词义包括“拒绝”“抵抗”等。如「拒否（きょひ）」「拒絶（きょぜつ）」「拒む（こばむ）」「拒否権（きょひけん）」。', '「拒む」读「こばむ」而非「きょむ」；「拒否」读「きょひ」而非「こばひ」。', '彼は申し出を拒否（きょひ）した。说明：拒否指拒绝。；要求を拒む（こばむ）ことはできない。说明：拒む指拒绝、阻挡。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('3dfbc383-70cb-5ad0-87f9-6e77959e7f40', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '2c18e7e1-4ef0-65e3-24a7-6c97d562a122', '～に限って', '表示限定，常带有“偏偏、唯独”的语感，有时表示“只有…才…”。接续：名词+に限って。', '与「～に限らず」（不仅…）混淆，后者表示不限于。', 'あの日に限って、バスが来なかった。说明：偏偏那天没来。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('3dfff281-b4c0-5961-81da-c51bd47b8452', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', 'ff057d86-47bc-de16-f0f9-a7b808b968e3', '频率和程度副词的用法', '掌握N3中表示频率（いつも、よく、たまに）和程度（かなり、ずいぶん、ちょっと）的副词，并能正确排序使用。', '混淆「よく」和「たまに」的频率差异；将「かなり」用于否定句造成语义矛盾。', '日语例句：彼はたまに遅刻するが、よく勉強する。；说明：たまに表示偶尔，よく表示经常。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('3eb6296b-0914-51fb-896a-26998fb1c100', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '2c18e7e1-4ef0-65e3-24a7-6c97d562a122', '～を兼ねて', '表示“兼作……，顺便……”，表示一个行为同时达到两个目的。接续：名词+を兼ねて。', '与「～がてら」混淆，但「を兼ねて」更强调目的兼带，且接名词；「がてら」接动词连用形。', '日本語：買い物を兼ねて、散歩に出かけた。；说明：兼作购物，出去散步了。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('3ee23387-b388-5d49-a7b6-90222b65c97a', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '5b34d8b5-bde9-c4c6-c736-84adaaae3603', '「顧」的读音与词义', '「顧」读「こ」，表示回顾、照顾。N1中「顧客（こきゃく）」「回顧（かいこ）」等需掌握。', '将「顧客」误读为「こかく」；混淆「顧みる」与「振り返る」的语体。', '顧客の要望に応える。（满足顾客要求）说明：「顧客」读「こきゃく」，指客户。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('3f07a344-d74b-564f-b502-4b1a3142a205', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '1af448c1-54cf-2f94-01b5-e8bc77a97f94', '～てはならない（禁止・书面）', '表示禁止，多用于规则、法律或书面语，语气比～てはいけない更正式。接续：动词て形+はならない。', '与～てはいけない混淆，后者更口语。注意～てはならない常用于客观规定，～てはいけない可用于个人禁止。', '日本語：この書類を外部に漏らしてはならない。；说明：正式规定“不得将这份文件泄露给外部”。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('3f17ec64-9258-5099-a3cf-8b3aaaa09047', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '0545d0ec-89d1-a8aa-99f9-78b30fcbacb1', '表示并列的「～たり～たり」「～し～し」「～うえに」', '掌握「～たり～たり」（列举动作）、「～し～し」（列举理由或事实）、「～うえに」（而且，累加）的接续和用法区别。', '学习者常将「～たり」用于名词，如「本たりペンたり」错误，应使用「本やペンや」。', '日本語例：日曜日は掃除したり洗濯したりする。（周日又打扫又洗衣服）／彼は頭がいいし、優しいし、人気がある。（他又聪明又温柔有人气）／この店は安いうえに美味しい。（这家店又便宜又好吃）。说明：三者列举功能不同。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('3f24f42f-400d-5894-87c1-2cdc1b1e5132', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', 'ff057d86-47bc-de16-f0f9-a7b808b968e3', 'N3条件表达相关词汇（扩展）', '掌握「場合」「なら」「と」「たら」「ば」等条件表达，以及「～さえ～ば」「～てからでないと」等复合条件。', '混淆「と」表示必然结果与「たら」表示假设条件，如「春になると暖かくなる」不能用「たら」替换。', '日语例句：雨の場合は中止します。；说明：「場合」用于客观情况。；日语例句：時間があれば行きます。；说明：「ば」表示假设条件。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('3f7ccaf2-b3fc-56d3-9708-00e4eb7812cb', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '0545d0ec-89d1-a8aa-99f9-78b30fcbacb1', '抽象名词的语义与语境', '理解N2常见抽象名词（如「概念」「傾向」「背景」「観点」）的准确含义，并能用于学术或正式语境。', '混淆相近抽象名词，如「傾向」与「動向」；或在使用时搭配不当。', '日语例句：この研究は新しい観点から分析する。；说明：「観点」意为观点、视角，常用「～から」。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('3fc5a5a8-a479-5254-bf6f-ce3c59eb361e', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '2c18e7e1-4ef0-65e3-24a7-6c97d562a122', '～をめぐっては', '表示“围绕～（有争议或讨论）”，后接对立或讨论内容。接名词。', '与「～をめぐって」混淆，后者是中性用法；「～をめぐっては」强调特定话题。', 'この問題をめぐっては、様々な意見が出ている。；说明：围绕这个问题，出现了各种意见。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('40309f67-39c7-5c24-88a7-0415c105f36d', '9221fc32-a051-42cb-86b1-6a9917aa004e', '42de0c7b-50d9-4159-918a-4e618d83342d', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '0e03a921-5aff-e4be-f477-4d55640b198b', 'ナ形容词的汉字读音', 'N5常见ナ形容词（如「静か」「有名」「便利」）的汉字读音及词干，注意词尾「だ/な」不写汉字。', '将「静か」写成「静かだ」的汉字部分误读，或把「有名」读成「ゆうめい」以外的音。', '日本語例：この町は静かです。说明：「静か」读作「しずか」，词干为「静か」。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('403644b3-5349-51c5-8d41-612f21980a84', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '3760dfca-44d9-3445-01cd-85de1f860da1', '～てはじめて', '表示“直到……之后才……”，强调经历某事之后才明白或做到。接动词て形。', '误用于单纯顺序；注意与“～てから”区别，后者仅表示时间先后。', '日语例句：病気になってはじめて、健康の大切さが分かった。；说明：生病之后才明白健康的重要性。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('4065f8bd-0b7a-58fe-82ca-df39fa8325cd', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', 'dd4e968a-3d37-98a7-3819-a5fc4c117122', '～てくださいませんか（能否请您…）', '比～てください更礼貌的请求，用于对长辈或上级。接续：动词て形＋くださいませんか。', '在亲密朋友间使用显得过于生硬；误用为～てくれませんか（对平辈）；忘记使用ませんか的疑问形式。', 'ちょっと手伝ってくださいませんか。说明：能否请您帮个忙？／駅への行き方を教えてくださいませんか。说明：能否请您告诉我怎么去车站？', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('4094a09d-22e5-5922-8f84-c240724f420c', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '2c18e7e1-4ef0-65e3-24a7-6c97d562a122', '～にとって', '表示从某立场来看，后接评价或判断。接续：名词+にとって。', '与「～にしてみれば」（从…角度来看）类似，但「にとって」更客观。', 'これは学生にとって大切な問題だ。说明：对学生来说重要。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('414eb9f0-e671-54e8-8225-03cbfed37b75', '9221fc32-a051-42cb-86b1-6a9917aa004e', '42de0c7b-50d9-4159-918a-4e618d83342d', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '0e03a921-5aff-e4be-f477-4d55640b198b', '移动动词的汉字读音', 'N5常见移动动词如「行く」「来る」「帰る」「歩く」「走る」「飛ぶ」的汉字读音及方向性。', '将「帰る」读成「かえる」以外的音，或混淆「行く」和「来る」的使用视角。', '日本語例：家に帰ります。说明：「帰る」读作「かえる」，表示返回。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('41b7961c-7a10-5f12-a897-2009060252e0', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '1d183755-02b3-4a6d-b727-082af1ef377c', '40ed56d1-acbd-4a8b-6284-2df8b9423e8e', '否定表达范围与双重否定', '理解否定词在句中的否定范围，识别双重否定、部分否定等复杂表达，准确还原句子真实含义。', '将部分否定误认为全部否定；忽略“ないわけではない”等双重否定；不理解“必ずしも～ない”的“并非一定”含义。', '日语例句：彼は必ずしも賛成しているわけではない。说明：双重否定+部分否定，实际意思是“他并非一定赞成”，即可能赞成也可能不赞成。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('41e6de85-99f1-5e78-aee8-f44f4720005d', '9221fc32-a051-42cb-86b1-6a9917aa004e', '42de0c7b-50d9-4159-918a-4e618d83342d', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', 'ef36118d-0ba3-29ce-b2b3-76eaeb6542ca', '～ている（动作进行/状态持续）', '动词て形+いる表示动作正在进行或动作结果的状态持续。注意瞬间动词（如「死ぬ」「結婚する」）的「ている」表示状态而非进行。', '将瞬间动词的「ている」误解为进行；与「～てある」混淆；在口语中省略「い」为「てる」时误用。', '今、本を読んでいます。；说明：正在读书。／彼は結婚しています。；说明：他已经结婚了（状态）。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('41eb3f8a-d573-53ca-8b1e-be4cacaa5c27', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', 'e5877362-1f27-54a5-903f-528a6d53f294', '接续、原因与逆接', '使用并列、原因、转折和补充说明的接续形式。', '「から」「ので」的语气和「でも」「しかし」的转折功能混淆。', '雨が降ったので、出かけませんでした。', 'published', '2026-09-03 13:10:31.032213+08', '2026-09-03 13:10:31.032213+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('41f6a68e-3d6e-5111-86c1-3b5048702a64', '9221fc32-a051-42cb-86b1-6a9917aa004e', '42de0c7b-50d9-4159-918a-4e618d83342d', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '0e03a921-5aff-e4be-f477-4d55640b198b', '评价类形容词辨析', '区分「いい」「良い」「上手」「得意」「好き」等表示积极评价的词汇，注意使用场景。', '将「上手」用于自己；将「好き」与「得意」混淆。', '彼はピアノが上手です。说明：「上手」用于他人技能。／私は料理が得意です。说明：「得意」可用于自己。／私は猫が好きです。说明：「好き」表示喜好。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('4226899e-01da-50da-9f62-59e15f8e3222', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', 'ff057d86-47bc-de16-f0f9-a7b808b968e3', 'N3片假名外来语的实际用法（扩展）', '掌握N3常见片假名外来语在具体语境中的使用，如「リラックス」「スケジュール」「マナー」等，理解其与和语、汉语词的语感差异及适用场合。', '将外来语用于过于正式的书面语或古典语境；忽视外来语与固有词在语感上的细微差别，如「デザイン」与「設計」的侧重不同。', '日语例句：週末はリラックスしたいです。说明：表示放松，比「休む」更强调身心放松。；日语例句：会議のスケジュールを確認してください。说明：スケジュール指日程安排，比「予定」更具体。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('4242d47c-f565-55f2-b4fc-31ab62d48c12', '9221fc32-a051-42cb-86b1-6a9917aa004e', '42de0c7b-50d9-4159-918a-4e618d83342d', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '0e03a921-5aff-e4be-f477-4d55640b198b', '礼貌的人数表达「名」', '掌握「名（めい）」作为礼貌的人数量词，用于正式场合或对他人表示敬意，如一名（いちめい）、二名（にめい）、三名（さんめい），与普通「人（にん）」相对。', '在非正式场合过度使用「名」；将「一名」读作「いちめい」时误加促音；将「三名」读作「さんめい」时误加浊音。', '日本語：参加者は三名です。；说明：三名读作「さんめい」。日本語：お客様が二名いらっしゃいました。；说明：二名读作「にめい」。日本語：一名様ですか。；说明：一名读作「いちめい」。)', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('4294933b-9ba5-59c7-b336-49bfc2bb746c', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '0545d0ec-89d1-a8aa-99f9-78b30fcbacb1', '表示样态的「～そうだ」「～ようだ」「～らしい」的区分', '掌握「～そうだ」（根据外观推测，接动词ます形或形容词词干）、「～ようだ」（根据主观判断或比喻）、「～らしい」（根据客观传闻或典型特征）的用法区别。', '学习者常混淆「～そうだ」与「～ようだ」，如「雨が降りそうだ」表示看起来要下雨，而「雨が降るようだ」表示感觉要下雨，后者更主观。', '日本語例：このケーキは美味しそうだ。（看起来好吃）／彼は疲れているようだ。（好像很累）／彼は学生らしい。（像个学生）。说明：三者根据证据和主观性不同。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('42d7a1e6-50f5-5df2-b864-2f0e73b1074d', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '2c18e7e1-4ef0-65e3-24a7-6c97d562a122', '～ぐるみ', '表示“连同……一起、整个”的意思，接续：名词＋ぐるみ。', '注意与「～ごと」区别，「ぐるみ」强调包含整体，如「家族ぐるみ」；「ごと」强调连同物体本身。', '日语例句：町ぐるみで祭りを盛り上げる。；说明：整个城镇一起搞热祭典。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('42f20c79-c5ac-5f46-8804-404b22973d6a', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '0545d0ec-89d1-a8aa-99f9-78b30fcbacb1', '形容词名词化接尾辞「～さ」「～み」的语义差异', 'N2需区分「～さ」表示性质、程度（可量化），「～み」表示感觉、深度（不可量化）。例如「深さ」指深度，「深み」指深度感、韵味。', '将「～さ」用于抽象感觉；将「～み」用于可测量属性；混淆「楽しさ」与「楽しみ」。', '日本語：この川の深さは10メートルだ。；说明：「～さ」表示可测量的程度。／日本語：彼の言葉には深みがある。；说明：「～み」表示抽象韵味。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('430ffc59-c0e5-5714-bd14-8f1b8f73c8e1', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', 'dd4e968a-3d37-98a7-3819-a5fc4c117122', '～てくれる（别人为我做）', '表示别人为说话人（或说话人一方）做某事，带有恩惠给予。接续：动词て形＋くれる。', '与～てもらう混淆（～てくれる主语是别人，～てもらう主语是我）；对长辈使用～てくださる更礼貌；忘记使用くれる的授受方向。', '友達がケーキを作ってくれた。说明：朋友给我做了蛋糕。／先生が説明してくださった。说明：老师给我解释了。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('436435e6-df3d-5342-a7bb-7c6b6d34ec2f', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '3760dfca-44d9-3445-01cd-85de1f860da1', '～ものなら', '表示“如果可能的话”或“假如能…的话”，后接可能动词或表示愿望的表达，常用于“可能なら～したい”或“できるものなら～してみろ”等。接续：动词可能形+ものなら。', '注意「ものなら」前接可能形，不能接普通动词原形；与「～なら」相比，更强调假设的不现实性。', 'できるものなら、もう一度やり直したい。；说明：如果可以的话，想重新来一次，表达强烈愿望。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('43b8a1d2-d907-5bf5-8b8a-70538037e151', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '2c18e7e1-4ef0-65e3-24a7-6c97d562a122', '～にはかならない', '表示“无非是……，正是……”，强调前项的本质或原因。接续：名词/动词辞书形+にはかならない。', '与「～にすぎない」混淆，后者强调“只是”，而「にはかならない」强调“正是”。', '日本語：彼の成功は努力の結果にはかならない。；说明：他的成功正是努力的结果。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('43de9e64-b091-5f22-8ad6-1ff7d8b8151f', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '2c18e7e1-4ef0-65e3-24a7-6c97d562a122', '～に鑑みて', '表示“鉴于……，考虑到……”，用于正式场合，基于某种情况或事实做出判断或决定。接续：名词+に鑑みて。', '误用为口语或日常场景；与「～に基づいて」混淆，后者强调依据规则，而「に鑑みて」强调考虑实际情况。', '日本語：彼の功績に鑑みて、特別賞を授与することにした。；说明：鉴于他的功绩，决定授予特别奖。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('43e098cc-256e-5aa4-9b52-4670832de729', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', 'ff057d86-47bc-de16-f0f9-a7b808b968e3', 'N3近义形容词的语感差异（扩展）', '辨析如「うれしい」与「たのしい」、「あたたかい」与「すずしい」等形容词在主观感受和客观描述上的区别。', '将「うれしい」用于描述他人心情时不加推测，实际应用「うれしそう」。', '日语例句：プレゼントをもらってうれしい。；说明：「うれしい」是个人直接喜悦。；日语例句：パーティーはたのしかった。；说明：「たのしい」指活动本身令人愉快。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('4404a8d7-ba0d-516e-824a-a96922046cb9', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '5b34d8b5-bde9-c4c6-c736-84adaaae3603', '「によって」的多种用法', '掌握「によって」表示原因、手段、被动主体等。', '与「によっては」混淆，后者表示“因情况而异”。', '日本語：地震によって家が壊れた。；说明：因地震房屋倒塌。日本語：人によって考え方が違う。；说明：因人而异。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('44fec60c-4352-5ca3-8d82-18f8bfb184c5', '9221fc32-a051-42cb-86b1-6a9917aa004e', '42de0c7b-50d9-4159-918a-4e618d83342d', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', 'ef36118d-0ba3-29ce-b2b3-76eaeb6542ca', '存在句（～に～がある/いる）', '表示人或物的存在。无生命物用「ある」，有生命物用「いる」。场所助词用「に」，存在的主体用「が」。疑问句用「ありますか/いますか」。', '混淆「ある」与「いる」的使用对象；场所助词误用「で」；否定形式「ない/いない」的活用错误。', '机の上に本があります。；说明：桌子上有书。／公園に子供がいます。；说明：公园里有孩子。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('450f6a53-99ae-5ffd-bb1f-77b3476532ab', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '0545d0ec-89d1-a8aa-99f9-78b30fcbacb1', '表示可能、困难、容易的接尾词（～やすい・～にくい・～がたい）', '掌握接尾词「～やすい」（容易…）、「～にくい」（难以…）、「～がたい」（难以…，多用于心理或抽象）的接续和语义区别。「～やすい」「～にくい」接动词ます形，「～がたい」接动词ます形，但多用于表示心理上难以做到。', '学习者常将「～がたい」用于具体动作，如「この本は読みがたい」，应使用「読みにくい」。', '日本語例：この本は読みやすい。（容易读）／この道は歩きにくい。（难走）／彼の気持ちは理解しがたい。（难以理解）。说明：前两者用于具体动作，后者用于抽象心理。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('451e012a-b270-566f-900e-cc6556a70e70', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '5b34d8b5-bde9-c4c6-c736-84adaaae3603', '「痴」的读音与词义', '「痴」读「ち」，表示愚痴、痴迷。N1中「痴漢（ちかん）」「愚痴（ぐち）」等需注意。', '将「痴漢」误读为「しがん」；混淆「愚痴」与「不平」的语感。', '彼はよく愚痴をこぼす。（发牢骚）说明：「愚痴」指无用的抱怨。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('4561fd05-c30e-56bc-8fc7-04ac4454d2cc', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '1d183755-02b3-4a6d-b727-082af1ef377c', 'fc58533f-fd29-5132-8f21-fd381828e3c8', '理解请求与指示', '在通知、说明书等文本中，识别「〜てください」「〜ないでください」「〜なければなりません」等表达，把握必须做或禁止做的事。', '混淆「〜てください」与「〜てもいいです」；忽视「〜ないでください」的禁止含义。', '日语例句：会議の前に資料を読んでください。説明：明确要求做某事。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('458831d5-6005-5ec1-bfdf-6d1b0ab350ee', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '2c18e7e1-4ef0-65e3-24a7-6c97d562a122', '～たところで', '表示即使做了前项，后项也达不到预期效果，相当于「～ても」。接续：动词た形＋ところで。', '后项多为否定或消极结果，且常与「無駄だ」「意味がない」等连用。', '今から急いだところで、間に合わないだろう。；说明：即使现在赶，也来不及了吧。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('45c15931-79ee-54ee-aecd-f034f9fc9b80', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', 'ff057d86-47bc-de16-f0f9-a7b808b968e3', '常见量词的使用', '掌握N3中用于人、动物、物品、时间等的量词，如「人（にん）」「匹（ひき）」「冊（さつ）」「時間（じかん）」等，注意读音变化。', '量词与对象不匹配，如用「匹」数人；量词数字读音错误，如「三冊」读作「さんさつ」而非「さんざつ」。', '日语例句：猫が三匹います。本を二冊買いました。；说明：匹用于小动物，冊用于书籍。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('462bdb48-ff33-5380-a41b-3bd93a6d06a7', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', 'dd4e968a-3d37-98a7-3819-a5fc4c117122', '～ために（目的）', '表示“为了……”，接续：动词辞书形/名词+の+ために，前句多为意志动词。', '与～ように混淆，～ために前句必须是意志动词。', '日本語：日本語を勉強するために、日本へ来た。；说明：为了学日语来了日本。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('467a75ac-45f7-5f7d-bb22-1c9890d18ffe', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', 'ff057d86-47bc-de16-f0f9-a7b808b968e3', 'N3抽象汉字复合词的理解', '理解如「環境」「影響」「関係」「経済」等抽象名词的构成和意义，并能根据汉字推测词义。', '望文生义，如将「経済」理解为“经过济世”，实际指经济。', '日语例句：環境問題について話し合います。；说明：「環境」指环境。；日语例句：天気は気分に影響します。；说明：「影響」指影响。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('46f58700-944a-5bbd-9ecb-3ae4f4cfea17', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '5b34d8b5-bde9-c4c6-c736-84adaaae3603', '「生」「性」「省」等「しょう」同音汉字的读音与词义区分', '「しょう」读音的汉字如「生（しょう）」「性（しょう）」「省（しょう）」「商（しょう）」「小（しょう）」等，在N1词汇中常见。本知识点训练学习者根据词义选择正确汉字。', '易将「性格」误写为「生格」，或将「省庁」与「小庁」混淆；需注意「生」多与生命相关，「性」表示性质，「省」表示行政单位或反省。', E'日语例句：性格（せいかく）は明るい。；说明：「性」读「しょう」？注意此处「性格」中「性」读「せい」，但「性」单独音读「しょう」如「性病（せいびょう）」？实际「性」在「性」字音读中可读「しょう」如「性急（しょうきゅう）」，但常见词「性格」读「せいかく」。本知识点需强调多音字，但此处示例需调整。\\n日语例句：省庁（しょうちょう）の改革が進む。；说明：「省」读「しょう」，表示行政机构。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('47267770-8260-5782-93f6-b823556e7ba4', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', 'baa9b5c2-5b94-4f9b-7ced-3a8c3cde4cb3', '时间表达（～前、～後、～間）的用法', '掌握「～前に」「～後で」「～間（に）」等表达，注意「前」接动词辞书形，「後で」接た形，以及「間」与「間に」的区别。', '混淆「後で」和「後に」；把「前に」接た形；误用「間」表示动作持续。', '日语例句：食事の前に手を洗う。／食事の後で散歩する。；说明：「前に」接名词+の或辞书形，「後で」接た形或名词+の。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('472a5be2-2b2d-5924-87eb-74917f29c6b6', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '3760dfca-44d9-3445-01cd-85de1f860da1', '～ことにする（主观决定）', '表示说话人自己做出的决定，相当于“决定…”。接动词辞书形/ない形。', '与「～ことになる」混淆；误用为客观安排。', '毎日運動することにした。说明：自己决定每天运动。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('473fe611-d400-5e1a-aa6c-0a19583a78bf', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '1d183755-02b3-4a6d-b727-082af1ef377c', '9c37478d-2388-1380-cdea-3b62d82c3fcb', '句子在段落中的功能定位', '识别段落中特定句子的功能，如主题句、过渡句、总结句、例证句等，理解其与前后句的关系。', '忽视句子的承上启下作用；将细节句当主题句；未注意段落首句常为总起。', '日语例句：このように、環境問題は個人の努力だけでは解決できない。说明：「このように」表示总结，该句为段落结论。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('478051dd-9111-5a14-9898-b4b75815179a', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '3760dfca-44d9-3445-01cd-85de1f860da1', '～ては', '表示条件，相当于“如果…的话”，后接消极结果或说话人的评价。', '常与「～てはいけない」区分，但「～ては」本身只是条件，后句常为负面内容。', 'そんなに遅く帰っては、両親が心配する。；说明：那么晚回家的话，父母会担心。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('47b22690-d231-58ef-9e66-3db608ed2bd3', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '1d183755-02b3-4a6d-b727-082af1ef377c', '9c37478d-2388-1380-cdea-3b62d82c3fcb', '隐含反义词与对比的识别', '在文章中，作者可能不直接使用反义词，而是通过上下文暗示对立概念（如「伝統」与「革新」），需要读者自行构建对比关系。', '只识别显性对比词（しかし、一方），忽略语义层面的隐含对立；将非对立概念强行对比。', '日语例句：古い建物を残すことには価値がある。しかし、新しい生活様式にも目を向けるべきだ。；说明：「古い」与「新しい」构成隐含反义，对比保护与适应。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('47bee39d-5411-584a-971b-fc9a2d419172', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '1d183755-02b3-4a6d-b727-082af1ef377c', '6f1477f5-00be-f963-76b6-5165f568e88e', '图表信息解读', '理解文章配图、表格、图表所传达的信息，并能与文字内容结合。', '只看图表不看文字说明；误读坐标或趋势。', '日语例句：グラフによると、2010年以降、利用者は急増している。説明：需结合图表趋势理解文章论述。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('482c152a-ede6-5d1a-921d-cda5870d6a84', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '3760dfca-44d9-3445-01cd-85de1f860da1', '～てはならない', '表示禁止，相当于“不可以…”，多用于规则、法律或书面语。', '与「～てはいけない」相比更正式、书面化。', 'この場所に駐車してはならない。；说明：此处禁止停车。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('484f45d2-958f-5f00-89a9-fecb5f958429', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '0545d0ec-89d1-a8aa-99f9-78b30fcbacb1', '时间相关汉字词的读音与用法', '掌握N2中时间相关词汇（如「昨今」「先日」「以来」「以後」）的准确读音和用法，区分近义词。', '混淆「以後」与「以来」的起点差异；或将「昨今」误用于过去特定时间。', '日语例句：昨今の経済状況は不安定だ。；说明：「昨今」指最近一段时间，用于当前时期。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('489a01d2-bdf0-5f28-86cb-a42d7c00747a', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '1d183755-02b3-4a6d-b727-082af1ef377c', '9c37478d-2388-1380-cdea-3b62d82c3fcb', '省略成分的补全', '理解日语中常见的省略现象，如省略主语、宾语、谓语等，并能根据上下文补全被省略的信息，从而正确理解句意和逻辑关系。', '忽略省略成分，直接按字面理解，导致逻辑断裂或误解说话人的真实意图。', '日语例句：彼は来ると言ったが、実際には来なかった。（彼は）約束を破ったことになる。；说明：第二句省略了主语「彼」，需根据上下文补全，理解其行为。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('48d6e359-c680-5966-af90-9bcaa55a502a', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', 'ff057d86-47bc-de16-f0f9-a7b808b968e3', 'N3使役被动形的构成与含义（扩展三）', '掌握N3中使役被动形（如「行かされる」「食べさせられる」）的构成，并理解其表示“被迫做某事”的含义及与使役形的区别。', '使役被动形易与使役形混淆，使役形表示“让某人做”，使役被动形表示“被迫做”；注意动词分组的变化，如五段动词「行く」→「行かされる」。', '例句：子供の頃、ピアノを練習させられた。说明：「させられる」表示被迫练习；例句：毎日残業させられる。说明：「させられる」表示被迫加班，而「させる」是让下属加班。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('48e8494d-37e7-5790-aa63-ee6a888997bb', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', 'baa9b5c2-5b94-4f9b-7ced-3a8c3cde4cb3', '形容词て形连接时的语义关系', '掌握い形容词和な形容词的て形（くて/で）用于连接多个性质，并可表示原因、并列等，注意て形后接句子的逻辑。', '误用「くて」和「で」，如把「静かで」写成「静かくて」；混淆原因与并列。', '日语例句：この部屋は明るくて広い。；说明：「明るくて」连接两个正面性质，表示并列。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('4940ad16-08cc-57a6-8ec7-2ec0ed2a0701', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '1d183755-02b3-4a6d-b727-082af1ef377c', '9c37478d-2388-1380-cdea-3b62d82c3fcb', '隐喻在篇章中的延伸与对应', '理解作者在全文或段落中持续使用同一隐喻，并利用该隐喻的各个侧面来对应不同论点或事例，需要跟踪隐喻的映射关系。', '只理解隐喻的字面意思，未能将隐喻的多个特征与文章各部分对应；忽略隐喻可能随论述发展而变化。', '日语例句：社会という船が沈みかけている。乗客はそれぞれの救命ボートを探すべきだ。；说明：船喻社会整体，乘客喻个体，救命ボート喻个人应对策略，需把握整体映射。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('49695567-5224-5364-b6ea-4b45dbb3dbc9', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '5b34d8b5-bde9-c4c6-c736-84adaaae3603', '「計」的读音与词义', '「計」在「計画」「計算」中读「けい」，表示计划、计算，但「計る」读「はかる」，需注意音训区别。', '将「計る」读作「けいする」，或混淆「計画」与「予定」。', '例句：旅行の計画を立てる。说明：「計画」读「けいかく」，指计划。；例句：時間を計ってください。说明：「計る」读「はかる」，意为测量。；例句：彼は計算が速い。说明：「計算」读「けいさん」，指计算。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('499fc8ac-0ac1-56a7-87e9-4470198f073a', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '5b34d8b5-bde9-c4c6-c736-84adaaae3603', '「卓越」与「優越」的用法区分', '「卓越」表示非常优秀、超出一般，常用于能力、技术；「優越」表示比别人优越，常与「感」「意識」搭配。', '混淆两者，如说「優越した技術」不自然；「卓越」不用于比较他人。', '彼は卓越（たくえつ）した才能を持つ。；说明：卓越。／優越感（ゆうえつかん）に浸る。；说明：优越感。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('4a2ee225-19d8-53e3-aff1-f692f64664ff', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '2c18e7e1-4ef0-65e3-24a7-6c97d562a122', '～をしりに', '表示“不顾～、无视～”，后接进行某动作，带有批评或遗憾语气。接名词。', '与「～をよそに」混淆，后者更强调“不管他人”；「～をしりに」更强调“无视事实”。', '親の心配をしりに、彼は危険な冒険に出かけた。；说明：不顾父母的担心，他去冒险了。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('4a7a84a7-6966-50b7-b91e-03b9eb49ae1f', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '0545d0ec-89d1-a8aa-99f9-78b30fcbacb1', '程度表达（副詞）的用法', '掌握N2表示程度的副词（如「かなり」「ずいぶん」「なかなか」「非常に」）的语感差异，能根据程度强弱和语境选择。', '将「なかなか」与否定搭配时误解为“非常”，实际表示“不容易”；或混淆「かなり」与「ずいぶん」的语感。', '日语例句：この本はなかなか面白い。；说明：「なかなか」与肯定句连用表示“相当”，但若与否定连用则意为“轻易不”。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('4afcd4e8-d897-5fc2-a473-cb68e5f27133', '9221fc32-a051-42cb-86b1-6a9917aa004e', '42de0c7b-50d9-4159-918a-4e618d83342d', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', 'ef36118d-0ba3-29ce-b2b3-76eaeb6542ca', '名词谓语句（～は～です）', 'N5基础句型，用「は」提示主题，「です」表示断定，构成“A是B”的肯定句。疑问句在句末加「か」，否定用「ではありません」。', '误将「は」读作「わ」；否定形式误用「じゃないです」与「ではありません」的混用；忘记在疑问句句末加「か」。', '私は学生です。；说明：表示“我是学生”。／これは本ではありません。；说明：否定“这不是书”。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('4b638bc5-e20a-584a-b3c7-601f6abf9d55', '9221fc32-a051-42cb-86b1-6a9917aa004e', '42de0c7b-50d9-4159-918a-4e618d83342d', '1d183755-02b3-4a6d-b727-082af1ef377c', '37a506cf-ef62-8ccc-3210-ab64e8561a4d', '简短通知与标识的阅读', '能够理解公共场所的简短提示（如禁止、注意、营业时间等），提取关键信息。', '忽略否定形式或敬语，误解提示含义。', '例句：ここに入らないでください。说明：表示禁止进入，理解不要进入。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('4be21e72-d0d8-5a3e-aec6-98992da0e5b4', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', 'baa9b5c2-5b94-4f9b-7ced-3a8c3cde4cb3', '动词意志形表示提议与邀请', '「～ましょう」表示提议或邀请，「～ようと思う」表示个人意志，需区分使用场合。', '将「ましょう」用于对上级的邀请，或混淆「よう」与「つもり」的语感。', '一緒に昼ご飯を食べましょう（一起吃午饭吧）；说明：表提议，语气亲切。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('4bf2bc5f-0f3f-5dc6-9835-d051c1d056bf', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', 'ff057d86-47bc-de16-f0f9-a7b808b968e3', 'N3汉字复合词读音规律（扩展四）', '针对N3级别中常见的汉字复合词，特别是含有「生」「日」「方」「上」「下」等多音字的复合词，总结其在不同词语中的音读或训读规律，帮助学习者掌握读音选择。', '学习者常根据单一汉字读音类推，忽略复合词中的特殊读音，如「生」在「生年月日」中读「せい」，但在「生け花」中读「い」。需注意词义与读音的对应。', '日语例句：彼の生年月日を確認してください。；说明：「生年月日」中「生」读「せい」，不是「なま」。日语例句：この方針は上層部の決定です。；说明：「上」在「上層部」中读「じょう」，而「上」单独时读「うえ」。日语例句：下書きをしてから清書します。；说明：「下」在「下書き」中读「した」，但在「下車」中读「か」。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('4bf57de1-0ef4-5681-bfa7-46dfc4cbcc3d', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '1d183755-02b3-4a6d-b727-082af1ef377c', '6f1477f5-00be-f963-76b6-5165f568e88e', '否定表达与双重否定', '正确理解否定句、部分否定、双重否定以及否定+推量等复杂表达的真实含义。', '将部分否定误解为全部否定；忽视「ないことはない」等双重否定。', '日语例句：彼の意見に賛成できないわけではない。説明：双重否定表示并非不赞成，即基本赞成。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('4c4a57fe-c7d5-55ea-9d15-95107507f002', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '5b34d8b5-bde9-c4c6-c736-84adaaae3603', '「禁」的多种读音与词义', '「禁」在N1中常见读音「きん」，词义包括“禁止”“监禁”“忍耐”等。如「禁止（きんし）」「禁煙（きんえん）」「禁物（きんもつ）」「禁欲（きんよく）」「拘禁（こうきん）」。', '「禁物」读「きんもつ」而非「きんぶつ」；「禁煙」读「きんえん」而非「きんけむり」。', 'ここは禁煙（きんえん）です。说明：禁煙指禁止吸烟。；油断は禁物（きんもつ）だ。说明：禁物指切忌之事。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('4d32b165-a495-5154-b7e6-05c6b27f7b67', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '0545d0ec-89d1-a8aa-99f9-78b30fcbacb1', '复合动词「～ている」的持续与结果状态', 'N2中部分复合动词与「～ている」结合时，可表示动作的持续或结果的存续，如「知っている」「持っている」「覚えている」等。需区分状态动词与动作动词的用法。', '将状态动词的「～ている」误认为进行中，如「知っている」不是“正在知道”，而是“知道”的状态。', '日本語：彼はその事実をすでに知っている。；说明：「知っている」表示“知道”这一状态的持续，而非“正在知道”。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('4d420ee1-88c9-558c-98f4-85c8050082a9', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '2c18e7e1-4ef0-65e3-24a7-6c97d562a122', '～とは限らない', '表示“不一定～”，用于否定全称判断。接动词普通形、形容词、名词+だ。', '与「～ないとは限らない」混淆，后者表示“不一定不～”；注意双重否定。', '高価なものが必ずしも良いとは限らない。；说明：贵的东西不一定好。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('4d5676ea-b88d-5463-9388-aa368db1c519', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', 'ff057d86-47bc-de16-f0f9-a7b808b968e3', 'N3常见量词的高级用法', '掌握「～台」「～本」「～枚」「～冊」等量词用于不同形状物品，以及「～回」「～度」等次数量词，注意「～日」的读法变化。', '将「本」用于扁平物品，如误说「紙を一本」；正确应为「一枚」。', '日语例句：車を一台持っています。；说明：「台」用于机械车辆。；日语例句：本を三冊買いました。；说明：「冊」用于书籍。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('4d989b18-780b-5b2c-a211-a11a930d99cb', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '5b34d8b5-bde9-c4c6-c736-84adaaae3603', '「最」的读音与词义', '「最」在「最高」「最初」中读「さい」，表示最，但「最中」读「さなか」或「さいちゅう」，需注意。', '将「最中」一律读作「さいちゅう」，混淆「最中」与「真最中」。', '例句：今日は最高の天気だ。说明：「最高」读「さいこう」，指最好。；例句：会議の最中に電話が鳴った。说明：「最中」读「さいちゅう」，意为正在…中。；例句：試合の最中に雨が降り出した。说明：「最中」也可读「さなか」，强调高潮时。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('4da0eacd-5fbb-5a19-8f3a-097a454c6990', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '3760dfca-44d9-3445-01cd-85de1f860da1', '～てくる（可能）', '表示动作方向或变化，有时也用于表达可能的状态。', '注意「～てくる」与「～ていく」的方向区别。', '駅まで走ってきた。；说明：跑着来到车站。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('4e6839ea-20a0-5ee8-8d57-74d6553c0dad', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '1af448c1-54cf-2f94-01b5-e8bc77a97f94', '～ておくか（事先准备・反问）', '以反问形式表达“要不要事先…呢？”接续：动词て形+おくか。多用于自言自语或征求同意。', '与～ておく（事先准备）混淆，该形式带疑问。注意口语中常用～ておこうか。', '日本語：明日のために、準備しておくか。；说明：自言自语“为明天事先准备一下吧。”', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('4e6da74f-d345-586f-908e-365f11165231', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '0545d0ec-89d1-a8aa-99f9-78b30fcbacb1', '接头辞「真～」「最～」「新～」的语义功能', 'N2中接头辞「真～」强调正中，「最～」表示最高程度，「新～」表示新，如「真夜中」「最前線」「新製品」。', '忽略接头辞的细微语义，随意使用。', '例句：真夜中に電話が来た。说明：「真～」强调正中。；例句：彼は最前線で働いている。说明：「最～」表示最前。；例句：新製品が発売された。说明：「新～」表示新。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('4e7de639-391c-592c-82f0-5b54977f23e6', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', 'ff057d86-47bc-de16-f0f9-a7b808b968e3', 'N3相对时间表达（扩展）', '掌握「さっき」「この間」「先ほど」「今度」「この前」等相对时间词，区分其正式程度和所指时间范围。', '将「この間」用于很久以前，实际指最近不久。', '日语例句：さっき電話がありました。；说明：「さっき」指刚才。；日语例句：先ほどお話ししました。；说明：「先ほど」比「さっき」正式。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('4eb805f9-a7c6-516e-bda4-28ce3564d54c', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '2c18e7e1-4ef0-65e3-24a7-6c97d562a122', '～ことか', '表示强烈的感叹，相当于“多么……啊”。接续：动词辞书形／た形／形容词＋ことか。', '注意与「～ことだろう」相似，但「ことか」更直接表达感叹，常与「どれほど」「なんと」等呼应。', '日语例句：どれほど待ったことか。；说明：等了多久啊。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('4eccdbbc-1630-5bb4-bba1-87bf8833b4e8', '9221fc32-a051-42cb-86b1-6a9917aa004e', '42de0c7b-50d9-4159-918a-4e618d83342d', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '0e03a921-5aff-e4be-f477-4d55640b198b', '时间表达中的汉字读音', '掌握日期、星期、时刻等时间词汇的汉字读音，如月曜日、火曜日、一時、半、分等，注意数字与量词的结合。', '将「月曜日」的「月」读成「げつ」而非「がつ」；混淆「四時」的「四」读「よ」还是「し」。', '今朝七時に起きました。说明：「七時」读作「しちじ」。／水曜日に会いましょう。说明：「水曜日」读作「すいようび」。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('4f0a1165-ff12-5911-b510-1a3aed357337', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', 'ff057d86-47bc-de16-f0f9-a7b808b968e3', 'N3片假名外来语的实际用法', '区分同义或近义外来语与和语词的使用场景，如「マンション」指公寓而非大厦，「アルバイト」与「パート」的细微差别。', '将外来语直接对应英语原词而忽略日语中的语义缩小或扩展，如「スマート」不仅指聪明，还指身材苗条。', '日语例句：彼女はマンションに住んでいます。；说明：「マンション」指公寓大楼，不是英语的mansion（豪宅）。；日语例句：週末にアルバイトをしています。；说明：「アルバイト」是打工，与「パート」相比更临时。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('4f397784-eca1-5b6c-8d21-e06fb26d2b11', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '5b34d8b5-bde9-c4c6-c736-84adaaae3603', '「逸」的读音与词义', '「逸」音读「いつ」，如「逸話」「逸脱」；训读「そ（れる）」「はや（る）」等。表示超出、散失、杰出。', '将「逸話」误读为「はなし」；混淆「逸脱」与「脱線」。', '彼には面白い逸話（いつわ）がある。；说明：轶事。／規則から逸脱（いつだつ）する。；说明：偏离。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('4f4a5833-4ce4-5b96-83c3-364877f17a4d', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', 'baa9b5c2-5b94-4f9b-7ced-3a8c3cde4cb3', '形容词送假名与活用', 'N4常用い形容词（如：高い、安い、新しい）和な形容词（如：静か、便利）的送假名及其在活用中的变化。', '将「静か」误写为「静」或「静か」的送假名混淆；「高い」的否定形「高くない」中送假名不变。', '日语例句：この店は安くて便利です。；说明：「安い」的送假名「い」在活用为「安く」时保留「く」。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('4f922348-7caf-5cf2-b570-7847dfc01d10', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '3760dfca-44d9-3445-01cd-85de1f860da1', '～によって', '表示原因、手段、根据等。接续：名词＋によって。', '注意区分「によって」的多种用法，如被动句中的施动者、原因、方法等。', '地震によって多くの家が壊れた。；说明：由于地震，许多房屋倒塌了。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('4fe0393c-0a11-5a19-872e-05676d7efef3', '9221fc32-a051-42cb-86b1-6a9917aa004e', '42de0c7b-50d9-4159-918a-4e618d83342d', '1d183755-02b3-4a6d-b727-082af1ef377c', '37a506cf-ef62-8ccc-3210-ab64e8561a4d', '识别最上級表达', '能够理解～で一番～、～が一番～等表达，找出群体中的最高程度。', '忽略比较范围，将最上級误认为一般比较。', '例句：クラスで一番背が高い人は田中さんです。说明：在班级范围内，田中最高。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('504f4535-e970-5421-a909-0e9336fd0175', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', 'baa9b5c2-5b94-4f9b-7ced-3a8c3cde4cb3', 'な形容词与名词之间的の/な切换', '部分な形容词（如「特別」「必要」「自由」）在修饰名词时用「な」，但在某些固定搭配或形式名词前可能用「の」，需根据词性和语境判断。', '误将所有形容动词都接「の」，或混淆「特別な」与「特別の」的语感差异。', '特別な理由（特别理由）；特別の措置（特别措施）；说明：两者均可，但「の」更正式，常见于书面语。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('50d00040-a66c-5cfe-906f-3b8e19426a71', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', 'dd4e968a-3d37-98a7-3819-a5fc4c117122', '～てあげる（为别人做）', '表示说话人（或主语）为别人做某事，带有恩惠给予的含义。接续：动词て形＋あげる。', '对长辈或上级使用～てあげる显得傲慢，应使用～てさしあげる或～てあげましょうか；与～てもらう混淆；有时显得施恩，需注意语境。', '友達に本を貸してあげた。说明：我借书给朋友了。／荷物を持ってあげましょうか。说明：我帮你拿行李吧？', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('511898bd-e706-57a4-b0fa-bbd2a2838c4b', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '0545d0ec-89d1-a8aa-99f9-78b30fcbacb1', '送假名对动词活用与读音的影响', 'N2需掌握动词中送假名不同导致读音和活用变化，如「行う（おこなう）」与「行く（いく）」、「話す（はなす）」与「話（はなし）」。送假名提示词性及活用类型。', '学习者常将「行う」误读为「いく」或「こう」，或混淆「行う」与「行く」的用法。', '日语例句：会議を行う。；说明：「行う」读「おこなう」，送假名「う」表示五段动词，而「行く」读「いく」。日语例句：彼は話すのが上手だ。；说明：「話す」读「はなす」，送假名「す」表示五段动词，名词「話」读「はなし」。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('5149d142-30b8-551c-836d-cc4bb0598701', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '1af448c1-54cf-2f94-01b5-e8bc77a97f94', '～ようになっている', '表示某种装置、系统或安排被设计成具有某种功能或状态，相当于“（被设计成）……的样子”。也可表示习惯或规定。', '容易与“～ようになる”（逐渐变化）混淆；本句型强调客观的构造或设定，而非自然变化。', 'このドアはボタンを押すと自動で開くようになっている。；说明：这个门被设计成按按钮就自动打开。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('515e9fa4-4ba8-5646-8783-88bb078d4230', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '2c18e7e1-4ef0-65e3-24a7-6c97d562a122', '～につけても～につけても', '表示“无论……还是……都……”，列举两个对立或并列的事项，强调结果不受影响。接续：动词辞书形/た形＋につけても＋同形＋につけても。', '注意前后两项需为同类或对立关系，且后项多为同一结论；不要与「～にしても～にしても」完全等同，后者更口语化。', '日本語：雨につけても風につけても、彼は毎日練習を欠かさない。；说明：无论下雨还是刮风，他每天都不缺练习。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('519249aa-e6ae-5839-b846-ffce8cff4c99', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '1d183755-02b3-4a6d-b727-082af1ef377c', '9c37478d-2388-1380-cdea-3b62d82c3fcb', '对比与比较关系的把握', '识别文章中两个或多个事物、观点之间的对比、相似或差异，理解比较的基准和结论。', '混淆比较对象；忽略比较的维度（如时间、条件）；未注意「に対して」「一方で」等标志词。', '日语例句：A社は低価格を重視するのに対して、B社は品質を優先している。说明：通过「に対して」明确对比，注意比较的是经营策略。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('5192dcb2-ef7c-5045-ac60-bc60832855a1', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '1d183755-02b3-4a6d-b727-082af1ef377c', '40ed56d1-acbd-4a8b-6284-2df8b9423e8e', '指示词所指内容判断', '能根据上下文准确判断「これ」「それ」「その」「こう」等指示词所指代的具体内容或前文事件。', '机械认为“それ”指代紧邻前句，忽略跨句指代；未注意“その”后接名词时的限定范围。', '日语例句：A：昨日、山田さんに会ったよ。B：そうですか。それで、何を話しましたか。说明：“それで”中的“それ”指代“昨天见到山田”这件事，而非“会った”这个动作本身。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('519602d1-501e-552c-8d60-f7bd0d02ce39', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', 'dd4e968a-3d37-98a7-3819-a5fc4c117122', '～ないといけない（必须）', '表示必须做某事，口语中常用，与～なければならない同义。接续：动词ない形+といけない。', '注意接续是ない形去掉い加といけない，不是直接加；口语中常省略为～ないと。', '日本語：宿題をしないといけません。；说明：必须做作业。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('51c1c163-347b-5ef1-816d-0f19f18354c7', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '1d183755-02b3-4a6d-b727-082af1ef377c', '6f1477f5-00be-f963-76b6-5165f568e88e', '书信邮件意图理解', '理解书信、邮件等实用文中的请求、感谢、拒绝、通知等交际意图。', '只读表面文字，忽视礼貌用语背后的真实意图；混淆发信人与收信人。', '日语例句：お忙しいところ恐縮ですが、来週の会議にご出席いただけますでしょうか。説明：委婉请求出席。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('5214babb-0dff-558b-a184-8c9a9e52153c', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '3760dfca-44d9-3445-01cd-85de1f860da1', '～ように感じる', '表示感觉、觉得像…，主观感受。接动词辞书形/た形/ない形。', '与「～ように思う」混淆；误用为客观事实。', 'この料理は少し辛いように感じる。说明：感觉这道菜有点辣。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('52d8d40a-2f68-5048-83f0-77ea40911743', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '0545d0ec-89d1-a8aa-99f9-78b30fcbacb1', '近义词在正式与口语语境中的选择', 'N2词汇中许多近义词存在语体差异，例如「しかし」偏书面，「でも」偏口语；「なお」用于正式通知，「それから」更口语。本知识点帮助学习者根据场合选择恰当词汇。', '在正式书面语中误用口语词汇，或在口语中误用过于生硬的书面语。', '日语例句：会議の結果を報告します。なお、詳細は資料をご覧ください。；说明：「なお」用于正式补充，若换成「それから」则显得不正式。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('52daf21c-bb98-5463-b6fb-59c3414d75c1', '9221fc32-a051-42cb-86b1-6a9917aa004e', '42de0c7b-50d9-4159-918a-4e618d83342d', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '2d7157f8-afb7-58a0-85ea-b3d775f216a2', '基本句型与指示词', '掌握判断、存在、指示和疑问等基础句型。', '把指示词、疑问词和助词的功能混在一起。', 'これは新しい本です。', 'published', '2026-09-03 13:10:31.032213+08', '2026-09-03 13:10:31.032213+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('52fc7bf9-7867-56de-aeac-68d4acba6f56', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '1d183755-02b3-4a6d-b727-082af1ef377c', '6f1477f5-00be-f963-76b6-5165f568e88e', '对比强调理解', '识别文章中通过对比（如「一方」「逆に」「対して」）突出某一方或强调差异的写法，理解作者的侧重点。', '只注意对比内容，忽略作者通过对比强调的重点，或误以为对比双方同等重要。', '日本語：若者はSNSをよく使う一方、高齢者は新聞を好む傾向がある。；说明：对比中可能隐含作者对代际差异的关注，需结合上下文判断强调点。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('53292fda-00a8-59a8-87e8-a5f44ac4c804', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '2c18e7e1-4ef0-65e3-24a7-6c97d562a122', '～ごとく', '表示比喻或例示，相当于「～のように」。接续：名词＋の・动词普通形＋ごとく。', '书面语，口语中不用，注意「ごとし」是终止形，接续不同。', '彼は風のごとく現れ、去っていった。；说明：他如风一般出现，又离去了。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('5372bcd9-6c91-512b-a8e1-9b7d63a999d8', '9221fc32-a051-42cb-86b1-6a9917aa004e', '42de0c7b-50d9-4159-918a-4e618d83342d', '1d183755-02b3-4a6d-b727-082af1ef377c', '37a506cf-ef62-8ccc-3210-ab64e8561a4d', '时间表达在语境中的理解', '能够理解表示时间点的词（今日、明日、昨日、今、～時、～分）以及时间顺序（前、後）在短文中的具体所指。', '将过去时间误读为将来；忽略时间词与动词时态的配合。', '例句：昨日、映画を見ました。说明：昨日表示过去，动词用ました，理解事件发生在昨天。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('53cf0d82-e9cc-5b6a-936e-937685a6b7e6', '9221fc32-a051-42cb-86b1-6a9917aa004e', '42de0c7b-50d9-4159-918a-4e618d83342d', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '0e03a921-5aff-e4be-f477-4d55640b198b', '日期与月份的特殊读音', '掌握1日至10日、14日、20日、24日等特殊日期读法，以及月份中4月（しがつ）、7月（しちがつ）、9月（くがつ）的读法，注意与普通数字读音不同。', '将4日读作「よんにち」、7日读作「ななにち」、9日读作「きゅうにち」；将4月读作「よんがつ」。', '日本語：今日は四日です。；说明：四日读作「よっか」。日本語：七月に日本へ行きます。；说明：七月读作「しちがつ」。日本語：二十日は休みです。；说明：二十日读作「はつか」。日本語：十四日は何曜日ですか。；说明：十四日读作「じゅうよっか」。)', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('53d5bf21-3ac8-57fa-bdd7-8325b443e97b', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '1af448c1-54cf-2f94-01b5-e8bc77a97f94', '～てしまう（完成・遗憾）', '表示动作彻底完成或产生遗憾、后悔等心情。接续：动词て形＋しまう。口语中常缩为～ちゃう／～じゃう。', '与～ておく的区别；～てしまう强调完结，有时含负面情绪，但也可中性。', '日本語：財布を忘れてしまいました。；说明：不小心忘了钱包，表示遗憾。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('54219f7b-b992-5a54-baf0-d4a57e191d22', '9221fc32-a051-42cb-86b1-6a9917aa004e', '42de0c7b-50d9-4159-918a-4e618d83342d', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', 'ef36118d-0ba3-29ce-b2b3-76eaeb6542ca', 'い形容词现在肯定（～いです）', 'い形容词以「い」结尾，现在肯定形式为「～いです」。修饰名词时直接接名词，作谓语时后接「です」。注意词干与词尾的区分。', '误将「い」形容词词干当作词尾；在修饰名词时误加「です」；将「いい」的活用误用为「よかった」等。', 'この花は美しいです。；说明：这花很美。／高い山ですね。；说明：好高的山啊。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('54898335-b85e-58a0-8344-4bd51c2161b6', '9221fc32-a051-42cb-86b1-6a9917aa004e', '42de0c7b-50d9-4159-918a-4e618d83342d', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '0e03a921-5aff-e4be-f477-4d55640b198b', '副词与动词的搭配', '掌握よく、たくさん、少し、とても、たいへん等副词与动词的搭配，注意程度表达。', '将「たくさん」用于修饰形容词；将「よく」与「たくさん」混淆。', 'よく食べます。说明：「よく」表示频率高。／たくさん本を読みました。说明：「たくさん」表示数量多。／少し疲れました。说明：「少し」表示程度低。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('54b6832c-b843-5fb6-a20f-90ed734a5b17', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', 'baa9b5c2-5b94-4f9b-7ced-3a8c3cde4cb3', '时间表达「～間」「～間に」的区别', '「～間」表示整个时间段内持续，「～間に」表示在某时间段内发生一次或多次动作，需区分。', '混淆两者，如「夏休みの間に」误用为持续整个假期。', '夏休みの間、ずっと日本にいた（暑假期间一直待在日本）；夏休みの間に一度旅行した（暑假期间去旅行了一次）；说明：前者持续，后者点状。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('54c9ba06-c350-525f-ac79-7e1a6453f8aa', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '2c18e7e1-4ef0-65e3-24a7-6c97d562a122', '～を離れて', '表示“脱离……，离开……”，用于抽象或具体意义，强调从某种状态或领域中脱离。接续：名词+を離れて。', '与「～を離れて」表示物理离开混淆；本句型多用于抽象，如「現実を離れて」。', '日本語：現実を離れて、夢を追うのも大切だ。；说明：脱离现实，追求梦想也很重要。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('55765ebb-1105-567c-ae60-a4d0d4002aed', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '1af448c1-54cf-2f94-01b5-e8bc77a97f94', '～てからでなければ（不…就不能）', '与“～てからでないと”同义，但更正式，后项常接否定或消极表达。', '注意接续，前项为动词て形+から；不要与“～てから”混淆。', '日本語：本人に確認してからでなければ、契約できません。；说明：不先向本人确认就无法签约。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('557f8ac6-f2a5-5887-9322-73f77461dd00', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '1d183755-02b3-4a6d-b727-082af1ef377c', '6f1477f5-00be-f963-76b6-5165f568e88e', '总结句识别', '在段落或文章末尾识别总结句，常带有“つまり”“要するに”“このように”等标记，用于概括前文内容。', '把总结句当作新观点，或忽略总结句对全文的概括作用。', '日语例句：このように、睡眠不足は健康に悪影響を及ぼすだけでなく、仕事の効率も下げる。说明：“このように”引出对前文论述的总结。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('559bdeb6-3f0c-50fc-bd84-68e3fe0be6c3', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '3760dfca-44d9-3445-01cd-85de1f860da1', '～に包まれて', '表示被……包围、笼罩在……之中。接续：名词＋に包まれて。', '常用于抽象事物，如气氛、情感等。', '家族の愛に包まれて育った。；说明：在家庭的关爱中长大。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('55c4dd24-6283-5d1c-a3e7-285018cf4c23', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '2c18e7e1-4ef0-65e3-24a7-6c97d562a122', '～ざまがない', '表示“没有……的样子”或“不像样”，接续：动词ます形去掉ます＋ざまがない，但更常见的是「～ざまだ」表示“样子”，本项为否定形式。', '注意「ざま」常含贬义，如「見苦しいざまだ」。', '日语例句：彼は慌てふためくざまがなかった。；说明：他没有慌张的样子。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('55ded911-c8fa-5ad9-9be5-3a2e2b9e9eca', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '1d183755-02b3-4a6d-b727-082af1ef377c', '6f1477f5-00be-f963-76b6-5165f568e88e', '隐含信息推断', '从文章表面信息推断未明说的内容，如背景、前提、可能的结果。', '过度推断；忽视文中暗示的线索。', '日语例句：彼は毎晩遅くまで働いている。最近、疲れているように見える。説明：可推断他可能因过劳而疲惫。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('56122ca2-ed60-5b31-bd53-a3c8c6ec9ce3', '9221fc32-a051-42cb-86b1-6a9917aa004e', '42de0c7b-50d9-4159-918a-4e618d83342d', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '0e03a921-5aff-e4be-f477-4d55640b198b', '信件邮件的量词「通」', '掌握量词「通（つう）」用于数信件、电子邮件、电话等，读音无特殊变化，如一通（いっつう）、二通（につう）、三通（さんつう）。', '用「枚」数信件；将「一通」读作「いちつう」；将「三通」读作「さんづう」。', '日本語：メールを一通送りました。；说明：一通读作「いっつう」。日本語：手紙が二通来ました。；说明：二通读作「につう」。日本語：電話を三通かけました。；说明：三通读作「さんつう」。)', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('56825103-83cc-5108-8306-5a2bfd557e46', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '1d183755-02b3-4a6d-b727-082af1ef377c', '9c37478d-2388-1380-cdea-3b62d82c3fcb', '多重因果关系的梳理', '分析文章中多个原因导致一个结果，或一个原因引发多个结果的复杂因果关系，理清因果链条的层次和主次，避免简单化理解。', '只抓住一个表面原因，忽略深层或间接原因，或混淆直接原因与根本原因。', '日语例句：経済の停滞、少子化の進行、そして価値観の変化が、地域社会の衰退を引き起こした。；说明：三个原因并列共同导致结果，需分别理解每个原因的作用。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('568c65c5-0d6e-5980-9fad-5aadac8057f1', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', 'dd4e968a-3d37-98a7-3819-a5fc4c117122', '～たほうがいい（最好…）', '表示建议或劝告，认为那样做更好。接续：动词た形+ほうがいい。', '否定形式为～ないほうがいい；注意与～てもいい（可以）区别。', '日本語：風邪をひいたら、早く寝たほうがいいです。；说明：感冒的话最好早点睡。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('569250a2-90ac-58f6-b7f2-1af4de113528', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '1af448c1-54cf-2f94-01b5-e8bc77a97f94', '～ばいい（建议・愿望）', '表示“做…就好了”，用于给对方建议或表示自己的愿望。接续：动词ば形＋いい。也可用「～たらいい」「～といい」等类似表达。', '与「～ばいいのに」区分，后者带有“要是…就好了（但现实并非如此）”的遗憾语气。', '日本語例：分からなければ、先生に聞けばいいです。；说明：不懂的话问老师就好了。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('571d3b35-6005-5f1a-a9bb-8683aa300696', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', 'ff057d86-47bc-de16-f0f9-a7b808b968e3', 'N3基础拟声拟态词（扩展）', '掌握如「わくわく」「どきどき」「ぴかぴか」「ぐっすり」等拟声拟态词，理解其修饰动作或状态的方式。', '将拟态词用于不合适的语境，如「わくわく」表示期待兴奋，不能用于悲伤场景。', '日语例句：試験の前はどきどきします。；说明：「どきどき」表示心跳加速。；日语例句：子供はわくわくして待っています。；说明：「わくわく」表示兴奋期待。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('57214dd7-91aa-5497-b131-29f999971378', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '2c18e7e1-4ef0-65e3-24a7-6c97d562a122', '～とあって', '表示因为前项的特殊情况，所以后项理所当然地发生。接续：名词・动词普通形＋とあって。', '后项多为客观事实或自然结果，注意与「～とあれば」的区别，后者表示如果条件成立。', '初の優勝とあって、ファンは大興奮だった。；说明：因为是首次夺冠，粉丝们非常兴奋。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('575605c9-b89f-579b-9e92-22ddc85e2dbe', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '5b34d8b5-bde9-c4c6-c736-84adaaae3603', '「免れる」与「逃れる」的用法区分', '「免れる」读「まぬかれる」，表示避免、免除；「逃れる」读「のがれる」，表示逃跑、逃避。', '混淆两者；「責任を免れる」表示免除责任，「責任を逃れる」表示逃避责任，语感不同。', '災難を免（まぬか）れた。；说明：避免。／現実から逃（のが）れたい。；说明：逃避。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('5763430e-8d23-53a4-8d9b-0bdadc01e87b', '9221fc32-a051-42cb-86b1-6a9917aa004e', '42de0c7b-50d9-4159-918a-4e618d83342d', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '2d7157f8-afb7-58a0-85ea-b3d775f216a2', '愿望、推量与意志', '表达愿望、计划、推测、意志和传闻。', '把说话人的意志和对事实的推测使用在同一语境中。', '日本へ行きたいです。', 'published', '2026-09-03 13:10:31.032213+08', '2026-09-03 13:10:31.032213+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('57a195ab-e2b7-5043-b8b2-14f110634a12', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '1d183755-02b3-4a6d-b727-082af1ef377c', '9c37478d-2388-1380-cdea-3b62d82c3fcb', '图表与文字信息的整合', '在含有图表、数据或图示的文章中，将视觉信息与文字说明结合，准确理解数据趋势和结论。', '只读图表忽略文字说明；误读坐标和单位；未注意图表与文字观点的一致性。', '日语例句：グラフが示すように、売上は年々増加しているが、利益率は低下している。说明：需结合图表数据理解文字中的“增加”和“降低”并存。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('57d9e102-62de-56bf-97c2-7d6dab321a85', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', 'ff057d86-47bc-de16-f0f9-a7b808b968e3', '常用汉字的音读与训读区分', '掌握N3级别常用汉字在不同单词中的音读和训读，尤其是多音字如「生」「行」「楽」等，能根据语境正确选择读音。', '混淆音读和训读，例如将「生」在「生活」中读作训读「いき」；忽视同形异音词。', '日语例句：生活（せいかつ）と生（い）きることは違う。；说明：生活用音读，生きる用训读。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('581d08b1-0afc-5a2f-9270-049a06a9e187', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '1af448c1-54cf-2f94-01b5-e8bc77a97f94', '～てしまう（非本意・过失）', '表示动作的完成或结束，但带有遗憾、后悔、无奈等非本意的语气。与已有「～てしまう（完了・遗憾）」不同，这里侧重强调动作是过失或无法挽回的。', '与表示单纯完成的「～てしまう」区分。本知识点强调说话人的消极情绪，常与「うっかり」「間違って」等副词共现。', '日本語例：うっかり財布を落としてしまいました。；说明：不小心把钱包弄丢了，表达后悔。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('5836ab4e-dcd5-56db-adf3-e181c89192ea', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '0545d0ec-89d1-a8aa-99f9-78b30fcbacb1', '汉字复合词中同字不同读音的辨析', 'N2阶段常见汉字复合词中，同一个汉字因词而异有不同音读或训读，如「生」在「生活（せいかつ）」「生年月日（せいねんがっぴ）」「生真面目（きまじめ）」中读音不同。需掌握常见多音汉字的读音规则与例外。', '误以为同一汉字在所有复合词中读音相同，如将「生真面目」读作「せいまじめ」。', '日本語：彼は生真面目（きまじめ）な性格で、生活（せいかつ）も規則正しい。；说明：「生」在「生真面目」中读训读「き」，在「生活」中读音读「せい」。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('587944b9-8792-521a-a92f-962339eaf687', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', 'ff057d86-47bc-de16-f0f9-a7b808b968e3', 'N3抽象汉字复合词的理解（扩展三）', '掌握N3中抽象汉字复合词如「影響」「関係」「状態」「傾向」「価値」等，理解其抽象含义及在句中的典型搭配。', '「影響」与「効果」混淆，影响可为正负，效果偏正面；「状態」与「様子」中，状態更客观，様子带主观观察。', '例句：天気が体に影響を与える。说明：「影響」表示影响，常用「与える」；例句：彼の健康状態が心配だ。说明：「状態」指状态，比「様子」更正式。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('58853ae0-a739-5111-9a35-aee0a092e2d0', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '5b34d8b5-bde9-c4c6-c736-84adaaae3603', '「ずいぶん」与「たいへん」的语感', '「ずいぶん」表示“相当、很”，带有感叹或意外；「たいへん」表示“非常”，也可表示“严重、麻烦”。', '「たいへん」在感谢语中常用，但「ずいぶん」不能用于感谢；混淆程度副词。', '日语例句：ずいぶん時間がかかった。；说明：表示“花了不少时间”，含感叹。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('588edaef-60b8-5a95-82eb-55fc70c10c14', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '1d183755-02b3-4a6d-b727-082af1ef377c', '6f1477f5-00be-f963-76b6-5165f568e88e', '观点与事实区分', '训练读者区分文章中哪些是客观事实（可验证），哪些是作者的主观意见或评价，避免将观点误认为事实。', '把带有“～と思う”“～だろう”等推测的表达当作事实；或忽略客观数据中的主观解读。', '日语例句：調査によれば、若者の読書時間は減少している。これは憂慮すべきことだ。说明：前半是事实，后半是作者观点。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('58a50af5-5523-5e48-8c5f-6926843d0821', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '2c18e7e1-4ef0-65e3-24a7-6c97d562a122', '～きりがない', '表示“没有尽头、无限”的意思，接续：动词て形＋きりがない，或名词＋きりがない。', '注意与「～かぎりがない」区别，但「きりがない」更口语化，且常与「言い出したら」等搭配。', '日语例句：言い出したらきりがない。；说明：一旦说起来就没完没了。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('58db5eb7-7910-5a91-9ca3-8acefc75ba5b', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '2c18e7e1-4ef0-65e3-24a7-6c97d562a122', '～によっての', '表示根据、由于、因…不同，后接名词。是～によって的连体修饰形式，强调原因或手段。', '与～による（直接修饰名词）混淆，但～によっての更强调动作性；注意后接名词。', '地域によっての習慣の違いを理解すべきだ。；说明：应该理解因地区不同而存在的习惯差异。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('58eba245-dd2f-5627-a883-70d95e9193c7', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', 'baa9b5c2-5b94-4f9b-7ced-3a8c3cde4cb3', '动词意志形表示意图与邀请', '掌握动词意志形（～よう）的构成，用于表达说话人的意志、决心，以及「～ましょう」表示提议或邀请。', '混淆意志形与可能形；在正式场合误用意志形表达自己的决定，而应使用「つもりです」等。', '一緒に昼ご飯を食べましょう。说明：表示邀请对方一起吃饭。／私は来年日本へ行こうと思います。说明：表示自己的意图，意志形+と思う。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('58f7598d-d8f8-5c51-a132-beba93e95195', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '0545d0ec-89d1-a8aa-99f9-78b30fcbacb1', '与动物相关的惯用表达', 'N2中如「猫の手も借りたい」（非常忙）、「犬猿の仲」（关系不好）、「馬が合う」（合得来）等。', '直译动物名称，忽略引申义。', '例句：忙しくて猫の手も借りたい。说明：忙得不可开交。；例句：彼らは犬猿の仲だ。说明：关系恶劣。；例句：彼とは馬が合う。说明：合得来。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('5925cff9-9307-53b9-ad63-eac8d24617f6', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', 'dd4e968a-3d37-98a7-3819-a5fc4c117122', '～なくてもいい（不必）', '表示不需要做某事，与～なければならない相对。接续：动词ない形+くてもいい。', '注意接续：ない形去い加くてもいい；不要与～てもいい（可以）混淆。', '日本語：明日は来なくてもいいです。；说明：明天不来也可以。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('59808cb5-b377-5296-96ad-68b533b69c1e', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '0545d0ec-89d1-a8aa-99f9-78b30fcbacb1', '表示目的的「～ように」与「～ために」的区分', '掌握「～ように」与「～ために」在表示目的时的区别。「～ために」前接意志动词或名词，强调直接目的；「～ように」前接非意志动词或可能形，表示期望达到的状态，且前后主语可不一致。', '学习者常将「～ために」用于非意志动词，如「合格するために勉強する」正确，但「風が吹くために」错误，应使用「風が吹くように」。', '日本語例：日本に留学するために貯金している。（为了留学存钱）／日本語が上手になるように毎日練習する。（为了日语变好每天练习）。说明：前者直接目的，后者期望状态。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('59df396a-4a80-5605-9d05-914b6bc6a100', '9221fc32-a051-42cb-86b1-6a9917aa004e', '42de0c7b-50d9-4159-918a-4e618d83342d', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', 'ef36118d-0ba3-29ce-b2b3-76eaeb6542ca', '～てもいいですか（否定回答）', '针对“～てもいいですか”的否定回答，常用“いいえ、～てはいけません”或“いいえ、～ないでください”，表示不允许。', '否定回答不能直接说“いいえ、～てもいいです”，必须用禁止或请求不要的表达。', '日本語：いいえ、ここでタバコを吸ってはいけません。；说明：对“吸ってもいいですか”的否定回答。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('5a002ec0-d974-55b2-a05d-8185d2d9605a', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '2c18e7e1-4ef0-65e3-24a7-6c97d562a122', '～を限りに', '表示“以……为最后期限，到……为止”，强调从某时点开始不再继续。接续：名词+を限りに。', '与「～を最後に」相近，但「を限りに」更强调“极限”，且常与「今日・今回」等搭配。', '日本語：今日を限りに、この店は閉店する。；说明：到今天为止，这家店将停业。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('5a055d08-b157-53bc-8b8f-228354637ab6', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '5b34d8b5-bde9-c4c6-c736-84adaaae3603', '「差」的读音与词义', '「差」在「差別」「差し出す」中读「さ」，但「差」单独读「さ」或「しゃ」？注意「差」在「差」字中读「さ」，如「差額」，但「差し支え」读「さしつかえ」。', '将「差し出す」读作「さしだす」或「さしず」，混淆「差別」与「区別」。', '例句：人種差別は許されない。说明：「差別」读「さべつ」，指歧视。；例句：彼は手紙を差し出した。说明：「差し出す」读「さしだす」，意为拿出、递交。；例句：差額を支払う必要がある。说明：「差額」读「さがく」，指差额。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('5a1ce138-e125-5f5b-b838-61e1a9dfaea6', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '1d183755-02b3-4a6d-b727-082af1ef377c', '9c37478d-2388-1380-cdea-3b62d82c3fcb', '文体与语域的理解', '识别文章是正式学术、新闻报道、随笔、书信等不同文体，理解其语言风格和表达习惯对理解的影响。', '用同一阅读策略对待所有文体；忽略敬语、口语等语域特征；未注意文体对信息呈现方式的影响。', '日语例句：拝啓、時下ますますご清栄のこととお慶び申し上げます。说明：这是书信开头，属于正式文体，理解时需注意礼貌表达和固定格式。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('5a5e3cdf-2962-5004-9e45-8c55bc30685c', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '1d183755-02b3-4a6d-b727-082af1ef377c', '9c37478d-2388-1380-cdea-3b62d82c3fcb', '段落功能的识别', '识别每个段落或段落群在整篇文章中所承担的功能，如引入话题、提供背景、展开论证、举例说明、对比对照、总结归纳等，从而把握文章的整体结构。', '将段落功能单一化，忽略段落可能兼具多种功能，或不能从整体结构出发判断段落作用。', '日语例句：第一段落では問題提起がなされ、第二段落ではその背景が説明され、最終段落で結論が述べられている。；说明：需识别各段落的功能角色，理解文章如何从问题走向结论。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('5a9a5bb5-c63c-581c-b00c-a6021ae3e5dc', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '2c18e7e1-4ef0-65e3-24a7-6c97d562a122', '～にすると', '表示从某人的角度或立场来看。接续：名词+にすると。', '与「～にとって」类似，但「にすると」更口语化。', '子供にすると、親の心配はうるさいだけかもしれない。说明：对孩子来说。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('5ab94145-252b-5218-bcc3-6bccec41ae00', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '0545d0ec-89d1-a8aa-99f9-78b30fcbacb1', '常用动词与抽象名词的固定搭配（如「影響を及ぼす」「役割を果たす」）', 'N2中动词与名词搭配常为固定，如「及ぼす」「果たす」「担う」等，需整体记忆。', '直译中文搭配，导致不自然。', '例句：環境が健康に影響を及ぼす。说明：「影響を及ぼす」为固定搭配。；例句：彼はリーダーの役割を果たした。说明：「役割を果たす」为固定搭配。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('5ac5c5c7-ea2c-5d37-822e-d2d289e31a91', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '1d183755-02b3-4a6d-b727-082af1ef377c', '9c37478d-2388-1380-cdea-3b62d82c3fcb', '语体转换与引用层次', '理解文章中正式语体与口语语体、直接引用与间接引用之间的转换，把握不同语体所代表的立场或信息来源，避免混淆叙述层次。', '忽略语体变化，将口语化的引用当作作者正式论述，或混淆直接引语与间接引语。', '日语例句：彼は「もう無理だ」と叫んだ。つまり、彼はあきらめてしまったのだ。；说明：直接引用口语表达后，作者用「つまり」进行解释，需区分引用与作者评述。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('5ada9c1f-ae23-5a3c-819b-7c75adabddcc', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '2c18e7e1-4ef0-65e3-24a7-6c97d562a122', '～に連れて', '表示随着前项的变化，后项也相应地变化。相当于「～につれて」。接在动词辞书形或名词后。', '与「～に伴って」相比，「に連れて」更口语化，且强调自然的变化过程。', '日本語：年を取るに連れて、早起きが苦手になった。；说明：随着年龄增长，变得不擅长早起了。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('5ae610fc-f8cb-50b3-9e16-fda3fedb01bb', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '2c18e7e1-4ef0-65e3-24a7-6c97d562a122', '～につき～につき', '表示“每…就…”，重复同一名词，强调每次。接续：名词+につき+名词+につき。', '与「～につけ～につけ」区分，后者表示“无论…还是…”。', '日につき日につき、彼の腕前は上がっていく。说明：一天天进步。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('5cc531fa-ca98-556c-a64e-9a48ea4d9212', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', 'e5877362-1f27-54a5-903f-528a6d53f294', '授受、请求与敬语', '表达给予、接受、请求、许可、禁止和基础敬语。', '授受方向与受益者弄反，或把礼貌表达当作普通动词。', '先生に教えていただきました。', 'published', '2026-09-03 13:10:31.032213+08', '2026-09-03 13:10:31.032213+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('5ccc39c7-c097-520b-9c60-65dcbc42bf9d', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '3760dfca-44d9-3445-01cd-85de1f860da1', '～てはいけないか', '表示请求许可的委婉说法，相当于“能不能不…？”或“可以…吗？”。', '实际使用时多用于否定疑问形式，但有时也用于肯定形式，需注意语境。', 'ここでタバコを吸ってはいけないか。；说明：能不能不在这里抽烟？', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('5cdb53fb-b2f1-53bb-9301-70f1454d9e35', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '2c18e7e1-4ef0-65e3-24a7-6c97d562a122', '～を通じては', '表示“在整个～期间/范围内”，后接状态或行为。接名词。', '与「～を通じて」混淆，后者是中性用法；此句型强调“在整个过程中”。', '一年を通じては、気温差が大きい。；说明：全年来看，温差很大。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('5d285de7-2b0c-5071-bed4-bedc0cb62b4d', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '3760dfca-44d9-3445-01cd-85de1f860da1', '～ようにいう意味', '表示“意思是…”，用于解释含义。接动词辞书形/ない形。', '与「～という意味」混淆；误用为直接定义。', 'この言葉は「頑張れ」というようにいう意味だ。说明：这个词的意思是“加油”。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('5d617923-b1a0-5180-b2c7-a1fcc3455a81', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', 'ff057d86-47bc-de16-f0f9-a7b808b968e3', 'N3动词て形与补助动词的组合（扩展二）', '掌握N3中「～てしまう」「～ておく」「～てみる」「～てある」「～ていく」「～てくる」等组合的扩展用法，如「～てしまう」表遗憾或完成，「～ておく」表事先准备。', '混淆「～てある」与「～ておく」的视点差异；「～てしまう」在口语中缩略为「～ちゃう」时误用。', '日语例句：宿題をやってしまった。／窓を開けておいてください。；说明：「～てしまう」表完成或遗憾，「～ておく」表事先做好。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('5da8f37a-a427-57ef-a4e2-819c764b59f2', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '0545d0ec-89d1-a8aa-99f9-78b30fcbacb1', '近义名词在正式与口语中的选择', 'N2需区分正式场合与口语中的名词，如「食事」与「ご飯」、「友人」与「友達」，根据语体选择合适词汇。', '在正式场合使用口语词；在口语中过度使用书面词。', '日语例句：会議の後、関係者で食事をした。；说明：「食事」较正式，适合工作场合；口语中常说「ご飯を食べる」。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('5daa3624-0bdd-5a6d-9cf0-12163ad2fe81', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', 'dd4e968a-3d37-98a7-3819-a5fc4c117122', '～てもいいよ（可以…哦・口语）', '口语中给予许可，语气轻松，常用于朋友或晚辈。接续：动词て形＋も＋いいよ。', '对长辈使用显得不礼貌；与～てもいいですか混淆（疑问与肯定）；忘记使用よ的柔和语气。', '明日来てもいいよ。说明：明天可以来哦。／使ってもいいよ。说明：可以用哦。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('5dc80d54-036c-5b98-9718-57d0363598f2', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '3760dfca-44d9-3445-01cd-85de1f860da1', '～てしまう', '表示动作完成或产生遗憾、后悔等心情。口语中常缩约为「～ちゃう」。', '注意区分「～てしまう」的完成义和遗憾义。有时两者兼有，需根据语境判断。', '大事な書類を忘れてしまった。；说明：把重要文件忘了，表示后悔。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('5e0fcab5-b0fc-5bda-86ee-27bdda680b3d', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '3760dfca-44d9-3445-01cd-85de1f860da1', '～に関して', '表示关于、就……而言。接续：名词＋に関して。', '与「について」相似，但「に関して」更正式，常用于书面语或正式场合。', 'この問題に関して、意見を聞かせてください。；说明：关于这个问题，请听听您的意见。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('5e1944ba-c02e-5848-8585-4547c07c589c', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', 'baa9b5c2-5b94-4f9b-7ced-3a8c3cde4cb3', '形容词送假名与活用规则', 'い形容词和な形容词的送假名不同，如「高い」「静かだ」，需掌握词干与词尾的区分。', '将な形容词词干误作名词使用，或混淆「大きい」与「大きな」的修饰限制。', '静かな部屋（安静的房间）；大きな声（大声）；说明：「大きな」只能连体修饰，不能作谓语。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('5e5e3a97-08e1-5d2d-a95f-b55ac3ad1dbd', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '2c18e7e1-4ef0-65e3-24a7-6c97d562a122', '～をにおいて', '表示“在……（时间、地点、领域）”的书面语，相当于「～で」。接续：名词+をにおいて。', '「をにおいて」是较古雅的表达，现代日语中常用「において」，但「をにおいて」强调对象性，多用于正式文体。注意与「～において」的区别。', '日本語：式典をにおいて、表彰が行われた。；说明：在仪式上进行了表彰。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('5ebb78e3-7a38-5ada-b7f3-e17b2b2091af', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '0545d0ec-89d1-a8aa-99f9-78b30fcbacb1', '表示程度的「～くらい/ぐらい」「～ほど」「～ばかり」', '掌握「～くらい/ぐらい」（大约，程度轻）、「～ほど」（程度高，常与否定连用）、「～ばかり」（大约，但多用于数量）的用法区别。', '学习者常将「～ほど」用于肯定句表示大约，如「10人ほど来た」正确，但「～ばかり」用于数量时略显口语。', '日本語例：10分ぐらい待ってください。（请等大约10分钟）／彼は死ぬほど疲れている。（他累得要死）／100人ばかり集まった。（聚集了大约100人）。说明：三者程度和语感不同。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('5f03ae76-28fb-5855-89b4-16e3ecb0796f', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '1af448c1-54cf-2f94-01b5-e8bc77a97f94', '～ていく（继续・消失）', '在已有～ていく（方向）基础上，强调动作的持续或向远处消失。如：～を続けていく。接续：动词て形＋いく。', '与～てくる相对，～ていく表示从说话人视角向远处或未来持续；注意与～てしまう的区别。', '日本語：これからも頑張っていきます。；说明：表示今后继续努力下去。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('5f100beb-6212-5c76-98e7-8b6d53d9d3f1', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '5b34d8b5-bde9-c4c6-c736-84adaaae3603', '「虚」的多种读音与词义', '「虚」在N1中常见读音「きょ」「こ」，词义包括“空虚、虚假”“虚弱”“空隙”等。如「虚偽（きょぎ）」「虚勢（きょせい）」「虚ろ（うつろ）」「虚無（きょむ）」「虚実（きょじつ）」。', '「虚ろ」读「うつろ」而非「きょろ」；「虚」在「虚実」中读「きょ」，不要读成「こ」。', '彼の話は虚実（きょじつ）が混ざっている。说明：虚実指虚实、真假。；心が虚ろ（うつろ）になる。说明：虚ろ指空洞、空虚。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('5f212262-c466-5059-bb5c-76fa4f05fe78', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', 'ff057d86-47bc-de16-f0f9-a7b808b968e3', 'N3常见量词的高级用法（扩展二）', '掌握N3中量词的特殊用法和搭配，如「～羽（わ）」用于鸟类和兔子，「～本（ほん）」用于细长物，「～枚（まい）」用于薄平物，以及「～軒」「～階」等，注意音变。', '将「～羽」误用于所有动物；「～本」的音变（ぽん/ぼん/ほん）混淆；「～軒」用于房屋时误用「～戸」。', '日语例句：うさぎが三羽います。／鉛筆を五本ください。；说明：「羽」用于兔子和鸟类，「本」用于细长物，注意「五本」读「ごほん」。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('5fb19325-49f8-5f6c-b104-17529d89275f', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '5b34d8b5-bde9-c4c6-c736-84adaaae3603', '「陵」的读音与词义', '「陵」读「りょう」「みささぎ」，指丘陵、陵墓。N1中「丘陵（きゅうりょう）」等需注意。', '将「陵」在「陵墓」中误读为「りょうぼ」；混淆「陵」与「丘」的语感。', 'この地域は丘陵が多い。（丘陵多）说明：「丘陵」读「きゅうりょう」。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('5fec511a-71d9-59ed-a450-fee1e250e4a9', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '0545d0ec-89d1-a8aa-99f9-78b30fcbacb1', '表示变化的自动词与他动词对应（如「変わる」与「変える」）', 'N2阶段需掌握自动词与他动词的对应关系，特别是表示变化、状态改变的动词对，如「変わる/変える」「壊れる/壊す」「落ちる/落とす」等。理解自动词强调自然变化或状态结果，他动词强调人为动作或原因。', '学习者常混淆自动词与他动词的使用场景，例如将「ドアが開ける」误用为自动词句，或忽视他动词需要宾语。', '日本語例：ドアが開いている。（自动词，表示门开着）／ドアを開ける。（他动词，表示开门）。说明：前者强调状态，后者强调动作。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('60596d98-0bca-5819-ad43-93b23926a0b7', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '3760dfca-44d9-3445-01cd-85de1f860da1', '～ずにはいられない', '与“～ないではいられない”同义，表示忍不住要做某事。接动词ない形去掉ない加ずにはいられない。', '误用于一般习惯；注意“する”变为“せずにはいられない”。', '日语例句：面白くて、笑わずにはいられなかった。；说明：因为有趣，忍不住笑了。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('60709942-850e-51a0-89d3-404e9d2d34d4', '9221fc32-a051-42cb-86b1-6a9917aa004e', '42de0c7b-50d9-4159-918a-4e618d83342d', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', 'ef36118d-0ba3-29ce-b2b3-76eaeb6542ca', 'てしまう（完成/遗憾）', '动词て形+しまう表示动作完成或产生遗憾、不可挽回的心情。接续：て形+しまう。', '忽略其遗憾语气，只当完成；口语中常缩约为ちゃう/じゃう。', 'ケーキを全部食べてしまいました。说明：把蛋糕全吃完了（遗憾或彻底）。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('607a0194-7677-5a81-8a84-0ce42dae559f', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', 'ff057d86-47bc-de16-f0f9-a7b808b968e3', 'N3动词与名词的固定搭配（扩展）', '掌握如「話に乗る」「気を使う」「世話をする」「役に立つ」等动名搭配，以及「～をきっかけに」「～を機に」等表达。', '直译中文搭配，如说「仕事をします」没问题，但「約束をします」应为「約束を交わす」。', '日语例句：彼はいつも気を使います。；说明：「気を使う」表示费心。；日语例句：この本は役に立ちます。；说明：「役に立つ」表示有用。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('608555c2-6470-56d0-987c-ba309687a93f', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '1af448c1-54cf-2f94-01b5-e8bc77a97f94', '～てある（结果状态）', '表示某人有意做的动作的结果状态，常与表示目的的を搭配。接续：他动词て形＋ある。', '与～ている的区别：～てある用于他动词，强调人为结果；～ている可用于自动词或进行。', '日本語：窓が開けてある。；说明：窗户被（某人）开着，处于开的状态。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('609458cd-15c2-5adc-8a0e-3c7fabc57eb1', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '0545d0ec-89d1-a8aa-99f9-78b30fcbacb1', '表示敬语的「お～になる」「お～する」「お～いただく」', '掌握敬语构成「お＋动词ます形＋になる」（尊敬）、「お＋动词ます形＋する」（谦让）、「お＋动词ます形＋いただく」（谦让，请对方做）的用法和限制。', '学习者常将「お～になる」用于非敬语动词，如「お食べになる」错误，应使用「召し上がる」或「お食べになる」虽口语但部分可接受。', '日本語例：先生はお読みになります。（老师读）／私はお荷物をお持ちします。（我帮您拿行李）／お待ちいただきますか。（请您等一下吗）。说明：三者敬语程度和方向不同。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('616c704d-5f8c-55dc-96ff-181100442a65', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '0545d0ec-89d1-a8aa-99f9-78b30fcbacb1', '汉字复合词的意义推测', '能根据构成汉字的字义推测N2常见复合词（如「過密」「未満」「再発」）的大致含义，提高阅读效率。', '望文生义，如将「無骨」理解为“没有骨头”，实际意为“粗鲁”；或忽视特殊读音。', '日语例句：この地域は人口過密だ。；说明：「過」表示过度，「密」表示密集，整体意为过于密集。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('6184f5f6-023c-554e-aeee-e9883f799ca0', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '5b34d8b5-bde9-c4c6-c736-84adaaae3603', '「共」的多种读音与词义', '「共」在N1中常见读音「きょう」「とも」，词义包括“共同”“一共”“连同”等。如「共同（きょうどう）」「共感（きょうかん）」「共犯（きょうはん）」「共に（ともに）」「子供共（こどもども）」。', '「共に」读「ともに」而非「きょうに」；「子供共」读「こどもども」而非「こどもきょう」。', '共に（ともに）頑張ろう。说明：共に指一起。；共同（きょうどう）で研究を進める。说明：共同指共同。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('61a3b332-aa14-5794-b7b8-a2aeda25f4a8', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '5b34d8b5-bde9-c4c6-c736-84adaaae3603', '「鑑」的读音与词义', '「鑑」读「かん」，表示镜子、鉴戒、鉴赏。N1中「鑑賞」「鑑定」「鑑みる」等需掌握。', '将「鑑みる」误读为「かんみる」；混淆「鑑賞」与「観賞」的用法。', 'この作品を鑑賞する。（鉴赏）说明：「鑑賞」指欣赏艺术品。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('625b7139-d54c-5354-b524-ca04f6311c28', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '0545d0ec-89d1-a8aa-99f9-78b30fcbacb1', '拟声词与拟态词的语义对应（如「どきどき」与「わくわく」）', 'N2中「どきどき」表示心跳加速（紧张或兴奋），「わくわく」表示期待兴奋，需区分情感类型。', '混淆「どきどき」与「わくわく」的情感色彩。', '例句：試験の前はどきどきする。说明：「どきどき」表示紧张。；例句：旅行を考えるとわくわくする。说明：「わくわく」表示期待。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('62c140d8-ebce-5189-a003-0b528b39ee83', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '1d183755-02b3-4a6d-b727-082af1ef377c', '9c37478d-2388-1380-cdea-3b62d82c3fcb', '隐喻与比喻的延伸理解', '识别文章中的隐喻、明喻等修辞手法，并理解其在本体和喻体之间建立的对应关系，能够将比喻的含义延伸到具体论述中，把握作者的表达意图。', '将比喻当作事实陈述，或只理解字面意思，忽略比喻所隐含的深层含义和情感色彩。', '日语例句：人生は旅のようなものだ。途中には山もあれば谷もある。；说明：将人生比作旅行，山和谷比喻顺境和逆境，需理解比喻的延伸含义。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('62e807c2-6768-52d4-bca0-20da6f45d209', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '1d183755-02b3-4a6d-b727-082af1ef377c', 'fc58533f-fd29-5132-8f21-fd381828e3c8', '理解隐含信息', '从文中没有直接写出的内容，通过上下文和常识推断出说话人未明说的意思、背景或后续可能发生的事。', '过度推断，脱离原文依据；只停留在字面意思，忽略省略和暗示。', '日语例句：田中さんは「あしたはちょっと…」と言った。；说明：从省略号推断田中明天不方便，但具体原因未说明。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('62f4c8de-4f2a-5389-8fc1-0ebbcea11922', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '1d183755-02b3-4a6d-b727-082af1ef377c', '40ed56d1-acbd-4a8b-6284-2df8b9423e8e', '接续词与逻辑关系理解', '理解表示因果、转折、递进、例示等接续词在句间的作用，能根据上下文判断句子之间的逻辑关系。', '只记接续词中文意思，忽略其在具体语境中的功能；混淆“しかし”与“ところが”的语感差异。', '日语例句：この店は値段が高い。しかし、味は最高だ。说明：通过“しかし”判断前后为转折关系，重点在后句。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('6394f1cb-79c1-5d1c-8c1a-ff7b4e82c437', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '3760dfca-44d9-3445-01cd-85de1f860da1', '～にかかわらないで', '表示“请不要涉及/不要管”，委婉地劝阻对方介入。', '与“～にかかわるな”相比，本句型语气较柔和，常用于口语。', '日本語：この問題にはかかわらないでください。；说明：请不要介入这个问题。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('639a1b5d-077a-5fee-a656-93c2dedc5b1c', '9221fc32-a051-42cb-86b1-6a9917aa004e', '42de0c7b-50d9-4159-918a-4e618d83342d', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '0e03a921-5aff-e4be-f477-4d55640b198b', '基本动词的近义辨析', '区分「言う」「話す」「教える」等表示“说”的动词，以及「見る」「観る」「見える」等表示“看”的动词。', '将「話す」用于单方面告知；将「見える」误用为“看”。', '先生が日本語を教えます。说明：「教える」指教授知识。／友達と話します。说明：「話す」指相互交谈。／富士山が見えます。说明：「見える」指自然映入眼帘。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('63b323cd-9019-585d-a131-7011176ed758', '9221fc32-a051-42cb-86b1-6a9917aa004e', '42de0c7b-50d9-4159-918a-4e618d83342d', '1d183755-02b3-4a6d-b727-082af1ef377c', '37a506cf-ef62-8ccc-3210-ab64e8561a4d', '短句中动作主体的识别', '在N5级别的短文中，能够根据助词（が、は、を、に等）和动词形式判断动作的发出者与接受者。', '混淆が和を，误将宾语当作主语；忽略省略主语时需根据上下文推断。', '例句：田中さんが本を読みました。说明：が标记主语（田中），を标记宾语（本），动作由田中发出。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('63d3832d-0e3b-5de6-9cd8-30ced9f123b5', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', 'e9d41203-7c2c-514e-a3a3-f1dbdcd3aaaa', '词义与近义辨析', '根据句子语境选择词义准确的基础词汇。', '只按中文直译选词，忽略搭配和上下文。', '駅の前で友だちに会いました。', 'published', '2026-09-03 13:10:31.032213+08', '2026-09-03 13:10:31.032213+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('642fdb7a-cd36-518f-8dcb-22e443e26fbf', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', 'baa9b5c2-5b94-4f9b-7ced-3a8c3cde4cb3', '接续词的逻辑关系表达', '掌握N4常用接续词如「しかし」「だから」「それに」「でも」等，理解其表示转折、因果、添加等关系。', '混淆「それに」与「そして」的添加语气；将「でも」用于正式书面语。', '日语例句：雨が降りました。しかし、試合は続きました。；说明：「しかし」表示转折，用于正式场合，口语中常用「でも」。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('64451acf-c801-5f7d-9540-e1fb8866c4ab', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '3760dfca-44d9-3445-01cd-85de1f860da1', '～ておく（可能）', '表示事先准备，有时也用于表达可能的状态。', '注意「～ておく」与「～てある」的区别，前者强调动作，后者强调状态。', '明日の会議のために資料を用意しておく。；说明：为明天的会议事先准备资料。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('6446e48f-23f7-5667-a9f5-533aae4954b1', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', 'dd4e968a-3d37-98a7-3819-a5fc4c117122', '～てもらう（请别人为自己做）', '表示说话人（或主语）请别人做某事，或别人为自己做某事，带有受惠含义。接续：动词て形＋もらう。', '误用为～てくれる（别人主动为我做）；忘记助词に表示动作主体；对长辈请求时使用～ていただく更礼貌。', '田中さんに日本語を教えてもらった。说明：我请田中教我日语了。／医者に見てもらう。说明：请医生看病。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('64684cae-bbf5-565a-b0cb-ebdea42fdc29', '9221fc32-a051-42cb-86b1-6a9917aa004e', '42de0c7b-50d9-4159-918a-4e618d83342d', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '0e03a921-5aff-e4be-f477-4d55640b198b', '大小类形容词辨析', '区分「大きい」「広い」「太い」以及「小さい」「狭い」「細い」等表示尺寸和空间的形容词。', '将「広い」用于物体大小；将「細い」用于空间狭窄。', 'この部屋は広いです。说明：「広い」指空间宽阔。／この道は狭いです。说明：「狭い」指道路狭窄。／彼は背が高いです。说明：「高い」用于身高。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('647360ca-d95a-574e-8ee3-a75765a8037c', '9221fc32-a051-42cb-86b1-6a9917aa004e', '42de0c7b-50d9-4159-918a-4e618d83342d', '1d183755-02b3-4a6d-b727-082af1ef377c', '37a506cf-ef62-8ccc-3210-ab64e8561a4d', 'て形连接句子的逻辑关系', '能够理解て形连接两个动作或状态时表示顺序、原因、方式等关系，从而把握事件流程。', '将て形仅理解为并列，忽略其表示原因或先后顺序的可能。', '例句：朝起きて、顔を洗います。说明：て表示动作先后顺序。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('647ae66a-914d-5960-9e1c-8f1aacda324d', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '1d183755-02b3-4a6d-b727-082af1ef377c', '6f1477f5-00be-f963-76b6-5165f568e88e', '流程与步骤理解', '理解说明文中操作步骤或事件发展顺序，把握先后关系。', '颠倒步骤顺序；忽略表示顺序的连接词。', '日语例句：まず材料を混ぜ、次にオーブンで20分焼く。説明：首先、其次表示顺序。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('64818ad0-b8b3-5aba-abf6-9c3b14146d7c', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '0545d0ec-89d1-a8aa-99f9-78b30fcbacb1', '复合动词中汉字部分的读音规则', 'N2阶段复合动词中，前项动词常为训读，后项动词也多为训读，但部分复合动词中前项或后项为音读汉字词（如「～じる」「～する」），需注意整体读音与意义。', '误将复合动词中汉字部分按单个汉字音读或训读机械拼读，忽略复合词整体读音习惯。', '例句：彼は一日中考え込んでいた。说明：「考え込む」中「込む」为训读，表示深入思考。；例句：この問題を解決するには時間がかかる。说明：「解決する」为サ变动词，汉字部分音读。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('6487b371-aca4-52ba-a55a-a3c06592055c', '9221fc32-a051-42cb-86b1-6a9917aa004e', '42de0c7b-50d9-4159-918a-4e618d83342d', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', 'ef36118d-0ba3-29ce-b2b3-76eaeb6542ca', '动词て形连接（～て、～）', '用て形连接两个或以上的动词，表示动作的先后顺序或并列。て形变化规则需熟练掌握，注意「書く→書いて」「飲む→飲んで」等音便。', 'て形变化错误（如将「買う」变为「買って」误为「買いて」）；连接时遗漏「、」或「て」；混淆「て」与「から」的先后顺序。', '朝ごはんを食べて、学校へ行きます。；说明：吃完早饭后去学校。／駅で電車を降りて、歩いて帰りました。；说明：在车站下电车后走回家。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('6497f41d-4b58-58f7-8ff5-a05f833624c0', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '3760dfca-44d9-3445-01cd-85de1f860da1', '～ように努める', '表示努力、致力于做某事，相当于“努力…”。接动词辞书形。', '与「～ようにする」混淆；误用为客观变化。', '健康のために早寝早起きするように努めている。说明：为了健康努力早睡早起。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('658ecf8e-68c3-520d-a9b5-720b9c6d0e97', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '0545d0ec-89d1-a8aa-99f9-78b30fcbacb1', '与身体部位相关的惯用表达', '掌握N2中由身体部位构成的惯用句（如「頭が下がる」「目がない」「足を運ぶ」）的比喻义和使用场景。', '按字面意思理解，如将「顔が広い」理解为脸大；或混淆类似惯用句。', '日语例句：彼は甘いものに目がない。；说明：「目がない」意为非常喜欢，不能按字面理解。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('6623b500-142a-5db9-b3de-e86dffe29d88', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '3760dfca-44d9-3445-01cd-85de1f860da1', '～がたい', '表示难以做到，相当于“难以……”。接动词ます形去掉ます。', '误用于具体动作，如“食べがたい”不自然；多用于心理、认知等抽象动词。', '日语例句：彼の気持ちは理解しがたい。；说明：表示难以理解他的心情。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('6640f122-ef65-575b-8ed9-e6e0b2b7fbee', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '0545d0ec-89d1-a8aa-99f9-78b30fcbacb1', '表示让步的「～ても」「～たって」「～ところで」', '掌握「～ても」（即使…也…）、「～たって」（口语，同「ても」）、「～ところで」（即使…也…，后接否定或消极结果）的用法区别。', '学习者常将「～ところで」用于积极结果，如「行ったところで楽しい」错误，应使用「行っても楽しい」。', '日本語例：雨が降っても行く。（即使下雨也去）／高くたって買う。（即使贵也买）／今から行ったところで間に合わない。（现在去也来不及）。说明：「～ところで」多用于消极结果。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('66987a71-5197-5c72-9b16-97457d57ef81', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', 'baa9b5c2-5b94-4f9b-7ced-3a8c3cde4cb3', '常用副词的用法与位置', '掌握N4常用副词如「とても」「少し」「いつも」「たまに」等，理解其修饰程度、频率和语气。', '混淆「とても」与「ぜんぜん」的肯定/否定搭配；将「たまに」误用为「よく」。', '日语例句：たまに映画を見ます。；说明：「たまに」表示偶尔，频率低于「ときどき」，注意与「よく」的区别。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('66be7c79-1c32-5f96-855c-38706b250f23', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '5b34d8b5-bde9-c4c6-c736-84adaaae3603', '「やがて」与「おとな」的读音区分', '「やがて」表示“不久、后来”；「おとな」是“大人”，注意「やがて」不能读作「おとな」。', '将「やがて」误读为「おとな」；混淆词义。', '日语例句：やがて春が来る。；说明：意为“不久春天到来”。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('67140d52-e366-50e1-bfc6-3f9b9476d965', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '1d183755-02b3-4a6d-b727-082af1ef377c', '9c37478d-2388-1380-cdea-3b62d82c3fcb', '反语与讽刺的理解', '识别作者使用反语、讽刺、夸张等修辞手法，理解其真实意图，避免按字面意思理解。', '将反语当正面肯定；忽略上下文语境；未注意语气词和标点（如「～だろうか」）。', '日语例句：なんと親切なことか、彼はいつも約束を破るのだから。说明：表面说“亲切”，实际讽刺其不守约，需结合后半句理解。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('67e3a2d9-2ffa-540c-a396-78cef6d81678', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '3760dfca-44d9-3445-01cd-85de1f860da1', '～つつある', '表示动作或变化正在进行中，相当于“正在……”。接动词ます形去掉ます。', '误用于瞬间动作或状态，如“死につつある”不自然；注意与“～ている”的区别，后者更侧重持续状态。', '日语例句：経済は回復しつつある。；说明：表示经济正在恢复过程中。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('6814344c-3291-595e-8736-d919e20bab68', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', 'ff057d86-47bc-de16-f0f9-a7b808b968e3', '动词与名词的固定搭配', '掌握N3中常见的动词与名词搭配，如「意見を述べる」「経験を積む」「努力を続ける」等，避免直译错误。', '使用不自然的搭配，如「意見を言う」虽可但「述べる」更正式；将「経験を積む」误作「経験をする」。', '日语例句：彼は長年経験を積んできた。；说明：積む与経験搭配表示积累经验。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('681930b8-91d6-5980-b137-012e1a879b00', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', 'ff057d86-47bc-de16-f0f9-a7b808b968e3', 'N3与身体部位相关的惯用表达（扩展三）', '掌握N3中更多与身体部位相关的惯用表达，如「頭が下がる」「顔が広い」「手を貸す」「足を運ぶ」「目が高い」等，理解其比喻义。', '直译身体部位表达，如「顔が広い」不是脸大，而是交际广；「手を貸す」不是借手，而是帮忙；「足を運ぶ」不是运脚，而是亲自去。', '例句：彼の努力には頭が下がる。说明：「頭が下がる」表示敬佩；例句：彼は顔が広い。说明：「顔が広い」表示人脉广；例句：手を貸してください。说明：「手を貸す」表示帮忙。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('68c5aaa8-6da1-5fc6-b417-4ac00ad21cc8', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '5b34d8b5-bde9-c4c6-c736-84adaaae3603', '「紙」「神」「髪」的同音异义', '区分「かみ」在表示纸张、神明、头发时的不同汉字。', '将「神」误写为「紙」等。', '日本語：紙に書きます。；说明：纸张。日本語：神を信じます。；说明：神明。日本語：髪を切ります。；说明：头发。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('69550bbf-dd1a-5607-9ff1-dcc1e7ee7bca', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '3760dfca-44d9-3445-01cd-85de1f860da1', '～に基づいて', '表示“基于…、根据…”，后项以此为依据。接续：名词+に基づいて/に基づく。', '与「～に応じて」的区别：「に基づいて」强调依据、基础，「に応じて」强调对应、适应。', '法律に基づいて判断しなければならない。；说明：必须基于法律进行判断。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('69e4699f-29d3-530e-8bb0-9d8a719be39b', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '0545d0ec-89d1-a8aa-99f9-78b30fcbacb1', '表示强调的副助词「こそ」「でも」「さえ」', '掌握副助词「こそ」（正是，强调）、「でも」（即使，举例）、「さえ」（甚至，举极端例）的用法和语感区别。', '学习者常混淆「こそ」与「は」，如「これこそ本物だ」强调正是，而「これは本物だ」单纯陈述。', '日本語例：これこそ私が探していた本だ。（这正是我找的书）／そんなことは子供でもできる。（那种事小孩都会）／彼は自分の名前さえ書けない。（他连自己名字都不会写）。说明：三者强调程度不同。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('6a0805fb-5bc4-5315-8041-1af9c49b263d', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '1af448c1-54cf-2f94-01b5-e8bc77a97f94', '～たばかりだ（刚刚完成・时间近）', '表示动作完成后经过的时间很短，主观上感觉“刚刚”。', '与“～たところ”相比，“～たばかり”更强调主观上的时间近，可用于稍早的事；注意与“～ばかり”区分。', '日本語：この本は先週読んだばかりです。；说明：这本书上周刚读过。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('6a3d346d-86dc-52de-9a8d-a9027035af76', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '2c18e7e1-4ef0-65e3-24a7-6c97d562a122', '～をはじめとして', '表示“以～为首”，列举代表性例子。接名词。', '与「～をはじめとする」混淆，后者作连体修饰；此句型后接动词或句子。', '社長をはじめとして、社員全員が参加した。；说明：以社长为代表，全体员工参加了。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('6a5fa8e5-9306-5075-b0e9-c584ae6ad090', '9221fc32-a051-42cb-86b1-6a9917aa004e', '42de0c7b-50d9-4159-918a-4e618d83342d', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '0e03a921-5aff-e4be-f477-4d55640b198b', '时刻表达中的时与分', '掌握「時（じ）」和「分（ふん/ぷん）」的读音规则，特别是4時（よじ）、7時（しちじ）、9時（くじ）以及1分（いっぷん）、3分（さんぷん）、4分（よんぷん）、6分（ろっぷん）、8分（はっぷん）、10分（じゅっぷん）等。', '将4時读作「よんじ」、7時读作「ななじ」；将1分读作「いちふん」、3分读作「さんふん」。', '日本語：今は四時五分です。；说明：四時读作「よじ」，五分读作「ごふん」。日本語：七時十分に起きます。；说明：七時读作「しちじ」，十分读作「じゅっぷん」。日本語：九時半に寝ます。；说明：九時读作「くじ」。日本語：八時三分です。；说明：三分读作「さんぷん」。)', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('6abe49fc-a878-5170-a9ff-a372eba75b5c', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', 'baa9b5c2-5b94-4f9b-7ced-3a8c3cde4cb3', '片假名外来语的实际含义理解', 'N4常见外来语（如：テレビ、パソコン、レストラン、コーヒー）的词义，避免望文生义。', '将「マンション」理解为公寓（实际指高级公寓或大厦），将「アルバイト」误认为英语的work。', '日语例句：週末はアルバイトをします。；说明：「アルバイト」来自德语，指兼职工作。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('6b51dd6b-c8c3-5ab8-b489-5d8b10001871', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', 'baa9b5c2-5b94-4f9b-7ced-3a8c3cde4cb3', '动词原形修饰名词的用法', '理解动词原形（辞书形）可以直接修饰名词，表示该名词所具备的动作属性或将要进行的动作，如「読む本」。', '误将动词て形或た形用于修饰名词；混淆原形修饰（一般属性）与た形修饰（已发生）的区别。', 'これは読む本です。说明：原形修饰表示“要读的书”。／あそこにいる人は先生です。说明：原形修饰表示“在那里的人”。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('6bb84dd1-fe1c-58e4-a0b3-36d1eef4162e', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '5b34d8b5-bde9-c4c6-c736-84adaaae3603', '「仰」的读音与词义', '「仰」有「ぎょう」「こう」「あおぐ」等读音，N1中「仰天（ぎょうてん）」「仰せ（おおせ）」等需区分。', '将「仰天」误读为「こうてん」；混淆「仰ぐ」与「見上げる」的语感。', 'その知らせに仰天した。（大吃一惊）说明：「仰天」读「ぎょうてん」。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('6bd89032-fc1f-5f8a-927d-9969ef54bdf6', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', 'ff057d86-47bc-de16-f0f9-a7b808b968e3', 'N3敬语动词的对应关系（扩展）', '掌握「行く/来る/いる」的尊敬语「いらっしゃる」，以及「食べる/飲む」的「召し上がる」等，注意谦让语如「参る」「伺う」。', '将尊敬语用于自己，如说「私がいらっしゃる」；应使用谦让语。', '日语例句：先生は明日いらっしゃいますか。；说明：「いらっしゃる」是「来る」的尊敬语。；日语例句：私は明日伺います。；说明：「伺う」是「行く/訪ねる」的谦让语。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('6c76f088-33b4-5f2c-bcb9-09c0fb6f6e63', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '5b34d8b5-bde9-c4c6-c736-84adaaae3603', '「語」的读音与词义', '「語」在「言語」「日本語」中读「ご」，表示语言，但「語る」读「かたる」，「物語」读「ものがたり」。', '将「語る」读作「ごる」，或混淆「語」与「話」的用法。', '例句：日本語を勉強している。说明：「日本語」读「にほんご」，指日语。；例句：彼は自分の経験を語った。说明：「語る」读「かたる」，意为讲述。；例句：この物語は有名だ。说明：「物語」读「ものがたり」，指故事。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('6ca6638a-2638-5f74-b300-5b6db0b74975', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '1d183755-02b3-4a6d-b727-082af1ef377c', '6f1477f5-00be-f963-76b6-5165f568e88e', '否定对比理解', '识别通过否定一方来肯定另一方的表达（如「AではなくB」「むしろ」），理解作者的真实意图。', '只理解否定部分，忽略被肯定的部分，或混淆「ではなく」与「だけではなく」的区别。', '日本語：失敗は悪いことではなく、むしろ成長の機会だ。；说明：通过否定「悪いこと」强调「成長の機会」，阅读时需抓住被肯定的重点。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('6cb8d26f-a221-501c-85a3-422b2039e457', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '3760dfca-44d9-3445-01cd-85de1f860da1', '～にこたえて', '表示“响应…、回应…”，后项为回应前项的行为。接续：名词+にこたえて/にこたえる。', '与「～に応えて」同义，但「にこたえて」更强调“回应期待、要求”。', '学生の要望にこたえて、図書館を24時間開放した。；说明：应学生的要求，图书馆24小时开放。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('6cbe7ade-8e47-5392-88d7-611f92f2c4f2', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '2c18e7e1-4ef0-65e3-24a7-6c97d562a122', '～に関して', '表示关于、有关。接在名词后，相当于「～について」。多用于正式场合，可后续「の」修饰名词。', '与「～について」相比，「に関して」更正式，且常出现在书面语或演讲中。注意「に関しては」表示特别提及。', '日本語：この問題に関しては、専門家の意見を聞くべきだ。；说明：关于这个问题，应该听取专家的意见。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('6ccafcf5-9e0e-50c3-91de-fd7860c9d765', '9221fc32-a051-42cb-86b1-6a9917aa004e', '42de0c7b-50d9-4159-918a-4e618d83342d', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '0e03a921-5aff-e4be-f477-4d55640b198b', '场所名词的汉字读音（非外来语）', 'N5常见场所名词如「学校」「駅」「病院」「銀行」「公園」「図書館」的汉字读音。', '将「駅」读成「えき」以外的音，或「図書館」读成「としょかん」时漏掉长音。', '日本語例：駅はあそこです。说明：「駅」读作「えき」。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('6cf5e757-8bb7-510d-9834-42d8329f8a7b', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '1d183755-02b3-4a6d-b727-082af1ef377c', '6f1477f5-00be-f963-76b6-5165f568e88e', '定义与例证理解', '理解文中对概念的定义，并能用例子验证或补充理解。', '将例子内容当作定义本身；忽视定义中的限定条件。', '日语例句：リサイクルとは、使わなくなった物を再び資源として利用することだ。説明：定义句通常有「とは…ことだ」结构。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('6d1c4335-b3b1-5d39-a794-5f8887cc8f22', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', 'dd4e968a-3d37-98a7-3819-a5fc4c117122', '～けれど（虽然・但是）', '表示逆接或对比，语气比が柔和，也可用于引出话题。接续：动词/形容词普通形+けれど，名词/な形容词+だけれど。', '口语中常为けど；注意与が的区别，けれど更口语化、柔和。', '日本語：この店は高いけれど、おいしいです。；说明：这家店虽贵但好吃。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('6d394e2f-7c0e-54cd-b1e4-4f05cf656f1c', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', 'ff057d86-47bc-de16-f0f9-a7b808b968e3', '近义形容词的语感差异', '区分N3中意思相近的形容词，如「大きい/広い」「うれしい/楽しい」「寂しい/淋しい」等，注意适用对象和感情色彩。', '将「広い」用于形容物体大小，或将「楽しい」用于表达个人对某事的喜悦。', '日语例句：この部屋は広いですが、家具が大きいです。；说明：広い指空间，大きい指物体。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('6da4e1f5-eadd-5c4a-bd77-e0fed790b485', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '0545d0ec-89d1-a8aa-99f9-78b30fcbacb1', '正式与非正式语体中动词的选择（如「致す」与「する」）', 'N2中同一意义有正式与非正式动词，如「する」的正式谦让形「致す」，「食べる」的正式形「いただく」。本知识点训练根据场合选择。', '在口语中误用「致す」显得生硬；在正式场合误用「する」显得失礼。', '日语例句：本日はお越しいただき、ありがとうございます。；说明：「いただく」是「もらう」的谦让语，用于正式感谢。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('6dab6089-d48e-5899-bb92-74a073d1b6bf', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', 'ff057d86-47bc-de16-f0f9-a7b808b968e3', 'N3表达意图和打算的词汇（扩展二）', '掌握N3中表达意图和打算的词汇如「つもり」「予定」「心積もり」「覚悟」等，注意「つもり」与「予定」的区别，以及「～つもりだ」与「～予定だ」的语感。', '将「つもり」用于客观日程安排；「予定」后接「だ」时误用为个人意志；混淆「つもり」与「つもりで」的用法。', '日语例句：来年、日本へ行くつもりです。／明日は会議の予定です。；说明：「つもり」表个人打算，「予定」表既定安排。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('6e2dd12d-8f3a-573c-8a36-d2500e5fde6f', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '5b34d8b5-bde9-c4c6-c736-84adaaae3603', '「潤」的读音与词义', '「潤」音读「じゅん」，如「潤滑」「利益」；训读「うるお（う）」「うるお（す）」。表示湿润、滋润、带来利益。', '将「潤滑油」的「潤」误读为「うるお」；混淆「潤う」与「湿る」。', '雨で地面が潤（うるお）った。；说明：湿润。／潤滑（じゅんかつ）油を使う。；说明：润滑。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('6e316c2e-a040-5bd6-90f5-2956cdfb19c5', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '3760dfca-44d9-3445-01cd-85de1f860da1', '～ものだから', '表示原因，带有辩解、强调理由的语气，后项多为导致的结果，常与「～ので」类似但更主观。接续：动词/形容词普通形+ものだから，名词+な+ものだから。', '口语中常省略为「もんだから」，注意与「ものだから」表示理由时，后项不能是命令、请求等意志表达。', '電車が遅れたものだから、会議に遅れてしまった。；说明：因为电车晚点，所以开会迟到了，强调客观原因。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('6ea6892b-e518-53bf-a3f5-bbd1e44df3d2', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', 'ff057d86-47bc-de16-f0f9-a7b808b968e3', 'N3近义形容词的语感差异（扩展三）', '辨析N3中如「うまい/美味しい」「かわいい/きれい」「つらい/苦しい」「眠い/眠たい」等近义形容词在主观评价、客观描述、口语正式度上的差异。', '「うまい」用于食物时较口语，正式场合用「美味しい」；「つらい」偏精神痛苦，「苦しい」偏身体或呼吸困难。', '例句：この料理はうまい。说明：「うまい」口语，男性多用；例句：試験がつらかった。说明：「つらい」指精神上难受，而「苦しい」多指身体。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('6eedfda6-62ea-5ea9-b84b-576ae1dc7efe', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '1d183755-02b3-4a6d-b727-082af1ef377c', 'fc58533f-fd29-5132-8f21-fd381828e3c8', '理解目的表达', '识别「〜ために」「〜ように」「〜のに」等表示目的的结构，区分动作目的与能力实现。', '混淆「〜ために」（意志目的）与「〜ように」（非意志或可能）；误将「〜のに」当目的。', '日语例句：日本語を勉強するために、日本へ来ました。说明：「ために」表示明确目的。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('6f8fd0f4-cd16-5e97-b45c-ccd4b55c13c8', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '3760dfca-44d9-3445-01cd-85de1f860da1', '～にかかわることになる', '表示“最终变成与…相关的事”，强调结果或决定。', '与“～にかかわる”相比，本句型更强调变化过程或最终结果。', '日本語：彼の行動が会社の評判にかかわることになった。；说明：他的行为最终关系到公司的声誉。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('6fc63013-08d4-5f58-acbd-48809f858667', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', 'ff057d86-47bc-de16-f0f9-a7b808b968e3', 'N3频率和程度副词的用法（扩展四）', '掌握N3中表示频率和程度的副词，如「しばしば」「たまに」「かなり」「ずいぶん」等，并区分其与「よく」「ときどき」的细微差别。', '学习者常混淆频率副词的程度，如「しばしば」比「よく」更正式且频率略低；「かなり」比「とても」程度稍弱但更客观。', '日语例句：彼はしばしば海外出張に行く。；说明：「しばしば」表示经常，但比「よく」正式。日语例句：たまに映画を見ます。；说明：「たまに」表示偶尔。日语例句：この本はかなり面白い。；说明：「かなり」表示相当程度，比「とても」稍弱。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('6fcaa60f-cc2f-5c05-b156-7f9465e507a2', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', 'baa9b5c2-5b94-4f9b-7ced-3a8c3cde4cb3', 'い形容词的否定形与用法', '掌握い形容词否定形「くない」的构成，如「高くない」，以及过去否定「くなかった」，注意「いい」的特殊变化。', '把「いい」的否定说成「いくない」；混淆「ない」作为形容词和助动词。', '日语例句：この本は面白くない。；说明：「面白い」→「面白くない」，表示“不有趣”。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('70188543-b414-5628-bb85-cfec3b400ef9', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '1d183755-02b3-4a6d-b727-082af1ef377c', '9c37478d-2388-1380-cdea-3b62d82c3fcb', '时间切换与叙事视角变化', '在叙事性文章中，识别时间轴的跳跃（回忆、未来展望）以及视角的转换（第一人称与第三人称），理解其对情节和主题的作用。', '将回忆内容误认为当前发生；忽略视角转换带来的信息限制和主观性。', '日语例句：今思えば、あの日の決断がすべてを変えた。；说明：从当前视角回述过去，时间切换标志「今思えば」。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('702d2499-f981-591d-8caa-82493267e51f', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '5b34d8b5-bde9-c4c6-c736-84adaaae3603', '「をめぐって」的用法', '掌握「をめぐって」表示“围绕”。', '与「について」混淆，但「をめぐって」强调争论焦点。', '日本語：環境問題をめぐって議論が行われた。；说明：围绕环境问题进行了讨论。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('707b33a0-9ddf-5d59-acbb-622c061059cf', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '1af448c1-54cf-2f94-01b5-e8bc77a97f94', '～てはいけないか（反问禁止）', '以反问形式表示“难道不能…吗？”或委婉禁止。接续：动词て形+はいけないか。实际使用较少，多用于书面或正式表达。', '与～てはいけないでしょう混淆。注意该形式语气较强，口语中不常用。', '日本語：ここで遊んではいけないか。；说明：反问“难道不能在这里玩吗？”（实际表示禁止）。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('70f5f009-2f31-5409-adfa-9617becdaf1d', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', 'e5877362-1f27-54a5-903f-528a6d53f294', '条件、假定与让步', '掌握「たら」「なら」「ば」以及让步表达的条件关系。', '条件成立时间和假设前提不匹配。', '時間があったら、電話してください。', 'published', '2026-09-03 13:10:31.032213+08', '2026-09-03 13:10:31.032213+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('710aec63-75e2-564b-8590-d338af3a0d82', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '3760dfca-44d9-3445-01cd-85de1f860da1', '～かねない', '表示有可能发生某种不好的事情，相当于“难免会……”“有可能……”。接动词ます形去掉ます。', '误用于积极或中性结果，如“合格するかねない”不自然；注意与“～かねる”（难以……）区分。', '日语例句：そんなに無理をすると、体を壊しかねない。；说明：表示如果那样勉强，有可能搞坏身体。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('71460500-8722-52db-b6ee-6072aa126b0b', '9221fc32-a051-42cb-86b1-6a9917aa004e', '42de0c7b-50d9-4159-918a-4e618d83342d', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '0e03a921-5aff-e4be-f477-4d55640b198b', '一天内时间段的量词「時」「時間」', '区分「時（じ）」表示钟点（如三時），「時間（じかん）」表示时长（如三時間），注意「半」表示三十分，如三時半。', '将「三時間」说成「三時」；将「三時半」理解为三小时半。', '日本語：今は三時です。；说明：三時表示三点钟。日本語：三時間勉強しました。；说明：三時間表示三个小时。日本語：五時半に会いましょう。；说明：五時半表示五点半。)', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('717dd973-d455-59ed-995c-b066e0a05490', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', 'dd4e968a-3d37-98a7-3819-a5fc4c117122', '～てもいいですかね（许可・犹豫）', '表示“可以……吗？”，带有自言自语、犹豫或向对方确认的语气，较口语。', '误用为正式请求，实际较随意；注意与～てもいいですか的区别。', '日本語：ちょっと借りてもいいですかね。；说明：稍微借一下可以吗？', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('71e25a4f-f089-5063-ba07-6cf07f704f5e', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', 'dd4e968a-3d37-98a7-3819-a5fc4c117122', '～てくださいませんか（请求・礼貌）', '用于礼貌地请求对方为自己做某事，比～てください更客气，常用于对长辈、上司或不太熟悉的人。接续：动词て形＋くださいませんか。', '误以为只能用于否定疑问，实际是肯定形式；与～てもらえませんか混淆，但前者更直接请求对方动作，后者侧重能否得到帮助。', '日本語で説明してくださいませんか。；说明：礼貌请求对方用日语说明。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('71f59f0e-3923-503a-9f99-ec48ad90688a', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', 'baa9b5c2-5b94-4f9b-7ced-3a8c3cde4cb3', '比较表达（より、ほど、一番）', '掌握N4比较句型如「AはBより～」「AはBほど～ない」「一番～」等，理解其语义和语序。', '混淆「より」与「ほど」的肯定/否定用法；将「一番」用于两者比较。', '日语例句：日本語は英語より難しいです。；说明：「より」表示比较基准，注意「ほど～ない」表示不如，如「英語は日本語ほど難しくない」。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('7248a8a4-6d44-53e8-ae7a-826888f404d8', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '1af448c1-54cf-2f94-01b5-e8bc77a97f94', '～てください（请求・指示）', '表示请求或指示对方做某事。接续：动词て形+ください。比～なさい更礼貌，比～てもらえますか更直接。', '与～てもらえませんか（更委婉）混淆。注意对长辈或上级使用时可能失礼，需用更礼貌形式。', '日本語：ちょっと待ってください。；说明：请求对方“请稍等”。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('727b8478-b89f-5e43-a10f-b5fb923eba53', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '2c18e7e1-4ef0-65e3-24a7-6c97d562a122', '～おそれがある', '表示“有……的危险、可能”，用于担心发生不好的事情。接续：动词辞书形／名词＋の＋おそれがある。', '与「～かもしれない」相比，更正式且多用于新闻、报告等，且多指负面结果。', '日语例句：台風が上陸するおそれがある。；说明：有台风登陆的危险。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('72a9b332-44c3-524c-a8fc-d345c1709ec9', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '0545d0ec-89d1-a8aa-99f9-78b30fcbacb1', '拟声拟态词中表示动作样态与心情的区分', 'N2中拟态词如「うつうつ」「いらいら」表示心情，「きちんと」「はっきり」表示动作样态，需根据语境选择。', '将表示心情的拟态词用于动作描述，反之亦然。', '例句：彼はいらいらしている。说明：「いらいら」表示焦躁。；例句：彼はきちんと並んだ。说明：「きちんと」表示整齐。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('72b2700c-dc01-5e50-8da1-5f5b0e0cc278', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', 'baa9b5c2-5b94-4f9b-7ced-3a8c3cde4cb3', '复合词中送假名的省略与保留', '在由动词连用形或い形容词词干构成的复合词中，送假名有时省略（如「引返し」→「引返し」但常写「引き返し」），有时保留。N4阶段需掌握常见复合名词如「手伝い」「物語」「近道」等，其送假名书写有固定习惯。', '误以为所有复合词都省略送假名，或随意添加送假名；混淆「話し合い」与「話合い」等正误写法。', '日语例句：手伝いを頼む。；说明：「手伝う」的连用形「手伝い」作名词时保留送假名「い」。日语例句：物語を読む。；说明：「物語」是「語る」的连用形与「物」复合，但送假名「る」省略，写作「物語」而非「物語り」。日语例句：近道を行く。；说明：「近道」由「近い」词干与「道」复合，省略「い」，不写「近い道」。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('73250a84-2b91-5da4-abcc-39cdf29a3269', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', 'ff057d86-47bc-de16-f0f9-a7b808b968e3', 'N3频率和程度副词的用法（扩展二）', '掌握N3中表示频率和程度的副词如「しばしば」「たまに」「かなり」「ずいぶん」「なかなか」「それほど」等，注意其与肯定否定句的搭配限制。', '将「なかなか」后接否定表示“不容易”与后接肯定表示“相当”混淆；「それほど」后接否定时误用为肯定。', '日语例句：彼はなかなか来ないね。／この本はなかなか面白い。；说明：「なかなか」后接否定表示迟迟不，后接肯定表示相当。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('73bd1fd6-7d89-551a-98ad-79d511ed726c', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '2c18e7e1-4ef0-65e3-24a7-6c97d562a122', '～にしてからが', '表示“就连……都……”，强调即使是程度高或特殊的人也如此，后项多为消极或意外内容。接续：名词+にしてからが。', '与「～でさえ」混淆，但「にしてからが」更强调“连……也不例外”的意外感，且多用于正式或书面语。', '日本語：専門家にしてからが、その問題を解決できない。；说明：就连专家都无法解决那个问题。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('7444282f-319b-5e9d-9961-f28c4dc50e0f', '9221fc32-a051-42cb-86b1-6a9917aa004e', '42de0c7b-50d9-4159-918a-4e618d83342d', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '0e03a921-5aff-e4be-f477-4d55640b198b', '场所名词词族', '掌握学校、会社、病院、銀行、郵便局、駅等场所名词，并理解其相关功能。', '将「銀行」与「郵便局」混淆；将「駅」与「停留所」混淆。', '銀行でお金を下ろします。说明：「銀行」办理金融业务。／郵便局で切手を買います。说明：「郵便局」办理邮政业务。／駅で電車に乗ります。说明：「駅」是铁路车站。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('748fa520-3b7d-5d0d-82fb-57ce57e71028', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '1d183755-02b3-4a6d-b727-082af1ef377c', '6f1477f5-00be-f963-76b6-5165f568e88e', '短文主旨把握', '能够快速把握200字左右短文的中心思想，区分主题句与支撑细节。', '误将具体例子或数据当作主旨；忽略转折词后的内容。', '日语例句：最近の若者は本を読まないと言われるが、実は電子書籍を含めれば読書量は増えている。説明：转折后才是作者真正观点。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('750d58bd-2b1b-57ac-9763-8d8c5cb047b0', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '3760dfca-44d9-3445-01cd-85de1f860da1', '～に沿って', '表示“沿着…、按照…”，后项沿着前项的方向或规则进行。接续：名词+に沿って/に沿った。', '与「～に基づいて」相比，「に沿って」更强调“顺着、不偏离”，常用于指示、方针等。', '計画に沿って進めましょう。；说明：按照计划进行吧。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('753ea713-9849-5cd6-a061-1c175cec318f', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '1af448c1-54cf-2f94-01b5-e8bc77a97f94', '～によって（根据・原因・手段）', '表示根据情况不同结果不同、原因、手段或被动句中的动作主体。', '与～による（名词修饰）区分；表示原因时与～で相近但更正式。', '国によって習慣が違います。（因国家不同习惯也不同。）／地震によって多くの家が壊れた。（因地震许多房子倒塌了。）／この小説は夏目漱石によって書かれた。（这本小说是夏目漱石写的。）', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('75def20f-113e-545a-84f7-738149eef41a', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '1d183755-02b3-4a6d-b727-082af1ef377c', '6f1477f5-00be-f963-76b6-5165f568e88e', '反问句功能理解', '理解反问句在文中并非提问，而是加强语气、表达作者观点或引导读者思考，常带有强烈肯定或否定含义。', '把反问句当作真疑问，误解作者态度；忽略反问句的强调作用。', '日语例句：こんな簡単な問題が解けないだろうか。说明：实际意思是“这么简单的问题应该能解”，表达肯定语气。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('7600471e-6530-506b-9e02-6d5ea4c67e1a', '9221fc32-a051-42cb-86b1-6a9917aa004e', '42de0c7b-50d9-4159-918a-4e618d83342d', '1d183755-02b3-4a6d-b727-082af1ef377c', '37a506cf-ef62-8ccc-3210-ab64e8561a4d', '礼貌体与普通体的转换理解', '能够识别短文或对话中使用的礼貌体（です/ます）与普通体（だ/である），并理解其反映的人际关系或语境。', '认为普通体只用于口语，忽略在书面叙述中普通体也常见。', '例句：友達が来た。说明：普通体，用于亲密关系或日记；例句：友達が来ました。说明：礼貌体，用于正式场合。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('769c7952-3b67-5405-8888-cf8e254fef65', '9221fc32-a051-42cb-86b1-6a9917aa004e', '42de0c7b-50d9-4159-918a-4e618d83342d', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '0e03a921-5aff-e4be-f477-4d55640b198b', '人与动物的量词', '掌握日语中数人时用「人（にん）」，但1人读「ひとり」、2人读「ふたり」；数动物时小型动物用「匹（ひき）」，大型动物用「頭（とう）」，鸟类用「羽（わ）」。', '误将1人读作「いちにん」，2人读作「ににん」；数猫狗时误用「頭」，数大象时误用「匹」。', '日本語：教室に学生が三人います。；说明：三人读作「さんにん」。日本語：犬が一匹います。；说明：一匹读作「いっぴき」。日本語：象が二頭います。；说明：二頭读作「にとう」。日本語：鳥が三羽います。；说明：三羽读作「さんわ」。)', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('76f9c918-041c-5f2e-a767-2343f68859db', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '1d183755-02b3-4a6d-b727-082af1ef377c', '6f1477f5-00be-f963-76b6-5165f568e88e', '例证功能识别', '识别文章中的具体例子是为了说明什么抽象观点或概念，理解例子与论点之间的支持关系。', '只记住例子内容，忽略例子所支撑的论点；或误把例子当作文章主旨。', '日语例句：例えば、ある調査では、週に3回運動する人は風邪を引きにくいという結果が出た。说明：此例用于支持“运动有益健康”的观点。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('77543988-9eef-5278-8c54-ec2c471be15a', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '1af448c1-54cf-2f94-01b5-e8bc77a97f94', '～たところ（刚刚完成・发现）', '表示动作刚刚结束的时点，或做完某事后发现某种结果。接续：动词た形＋ところ。与「～たばかり」相比，更强调“刚做完”的时点，且可用于“～たところ、～”表示意外发现。', '「～たばかり」强调时间间隔短，而「～たところ」强调动作刚结束，且后接结果时表示发现。', '日本語例：家に帰ったところ、友達が来ていた。；说明：刚回到家，发现朋友已经来了。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('7771b7b4-07b9-50b1-a973-bcff52bbe991', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', 'e5877362-1f27-54a5-903f-528a6d53f294', '时态、进行与状态', '区分过去、现在、进行、结果状态和先后关系。', '把动作进行「ている」与结果状态或单纯现在时混用。', '今、雨が降っています。', 'published', '2026-09-03 13:10:31.032213+08', '2026-09-03 13:10:31.032213+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('77b64de3-be3c-5c65-90d6-e4e362354cb0', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', 'ff057d86-47bc-de16-f0f9-a7b808b968e3', 'N3敬语动词的对应关系（扩展四）', '进一步掌握N3中敬语动词的对应，如「言う→おっしゃる」「行く→いらっしゃる」「食べる→召し上がる」等，并区分尊敬语和谦让语的使用场景。', '学习者常混淆尊敬语和谦让语，如对上级说「私がおっしゃる」是错误的，应使用谦让语「申す」；需根据动作主体判断。', '日语例句：先生がおっしゃったことをメモしました。；说明：「おっしゃる」是「言う」的尊敬语，用于上级。日语例句：私は部長に申し上げました。；说明：「申し上げる」是「言う」的谦让语，用于自己。日语例句：どうぞ召し上がってください。；说明：「召し上がる」是「食べる」的尊敬语。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('78320c97-24ce-5199-856a-04167872e94c', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '2c18e7e1-4ef0-65e3-24a7-6c97d562a122', '～としたって', '表示“即使～也”，口语化，后接让步或反驳。接动词普通形、形容词、名词+だ。', '与「～にしても」混淆，后者较正式；「～としたって」更口语。', '忙しいとしたって、連絡くらいはできるだろう。；说明：即使忙，也该能联系一下吧。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('784291c5-4cf3-5293-9a24-7efdfd293413', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '1af448c1-54cf-2f94-01b5-e8bc77a97f94', '～たことがある（经历）', '表示曾经有过某种经历，接动词た形。', '与～たばかり混淆；否定形式～たことがない表示从未有过。', '富士山に登ったことがあります。（爬过富士山。）／一度も海外に行ったことがありません。（从未出过国。）', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('78695732-4949-5c4e-a7ff-a2ed7ded4b3e', '9221fc32-a051-42cb-86b1-6a9917aa004e', '42de0c7b-50d9-4159-918a-4e618d83342d', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', 'ef36118d-0ba3-29ce-b2b3-76eaeb6542ca', 'な形容词现在肯定（～だ/です）', 'な形容词词干后接「だ」或「です」作谓语，修饰名词时词干后接「な」。注意与「い」形容词的区别，以及「きれい」等以「い」结尾但属于な形容词的词。', '将「きれい」「有名」等误当い形容词；修饰名词时漏掉「な」；作谓语时误用「だ」在礼貌体中的省略。', '京都は静かです。；说明：京都很安静。／有名な歌手です。；说明：是有名的歌手。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('78f88b92-6771-5db6-9276-5467578ddc2f', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '1d183755-02b3-4a6d-b727-082af1ef377c', '6f1477f5-00be-f963-76b6-5165f568e88e', '定义句理解策略', '在阅读中遇到难懂术语或概念时，通过文中给出的定义句、解释句或括号说明来理解其含义，而不是依赖词典。', '遇到生词就跳过，不利用上下文定义；或混淆定义与举例。', '日语例句：リモートワークとは、会社に出社せずに自宅などで仕事をする働き方のことだ。说明：通过“とは”和“ことだ”明确给出定义。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('791b52d7-1375-5a29-a915-cd4169449889', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '2c18e7e1-4ef0-65e3-24a7-6c97d562a122', '～につけても（ことだ）', '表示“每当……就（不由得）……”，后接「ことだ」强调感慨或自然产生的情感。接续：动词辞书形/た形＋につけても＋ことだ。', '此条为「～につけても」与「ことだ」的组合，注意「ことだ」在此表示感叹，而非“应该”之意；不要与「～ことだ」表忠告混淆。', '日本語：彼の話を聞くにつけても、人生の厳しさを感じることだ。；说明：每当听到他的话，就不由得感到人生的严峻。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('79347431-87a1-5d6b-9a36-4509a79c0edd', '9221fc32-a051-42cb-86b1-6a9917aa004e', '42de0c7b-50d9-4159-918a-4e618d83342d', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', 'ef36118d-0ba3-29ce-b2b3-76eaeb6542ca', 'てくる（方向/变化）', '表示动作由远及近或从过去到现在的变化。接动词て形后加くる。', '与ていく混淆；时间方向理解错误。', '日本に来てから、日本語が上手になってきました。；说明：来日本后，日语逐渐变好（到现在）。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('79548927-4de2-513c-a031-78541623836a', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '3760dfca-44d9-3445-01cd-85de1f860da1', '～てもいい', '表示许可，相当于“可以…”。用于征求对方同意或给予许可。', '注意「～てもいいですか」是请求许可的常用形式。不要与「～てはいけない」混淆。', 'この席に座ってもいいですか。；说明：可以坐这个座位吗？', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('79b19a2b-8eda-53e5-a3ee-ad9cf7ef5b75', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '5b34d8b5-bde9-c4c6-c736-84adaaae3603', '「それほど」与「そんなに」的用法', '两者都表示“那么、那样”，但「それほど」较书面，常与否定呼应；「そんなに」口语，可接形容词或动词。', '在正式文章中误用「そんなに」；「それほど」不能用于直接感叹。', '日语例句：それほど難しくない。；说明：表示“没那么难”。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('79b6bd66-4384-5416-99cf-9514e0e69d36', '9221fc32-a051-42cb-86b1-6a9917aa004e', '42de0c7b-50d9-4159-918a-4e618d83342d', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', 'f5aa6f4e-16ea-57eb-96bb-fb12daa45f39', '汉字读音与表记', '掌握 N4/N5 常见汉字的读音、表记和基本词形。', '音读、训读或相似汉字的读音容易混淆。', '毎朝、新聞を読みます。', 'published', '2026-09-03 13:10:31.032213+08', '2026-09-03 13:10:31.032213+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('79dc6ca5-423f-57ef-9a17-82114a36c9ea', '9221fc32-a051-42cb-86b1-6a9917aa004e', '42de0c7b-50d9-4159-918a-4e618d83342d', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '2d7157f8-afb7-58a0-85ea-b3d775f216a2', '助词与格关系', '区分主题、主格、对象、时间、地点、方向和手段等助词。', '动作场所误用「に」，或把主题「は」当成主格「が」。', '図書館で日本語を勉強します。', 'published', '2026-09-03 13:10:31.032213+08', '2026-09-03 13:10:31.032213+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('7a0e7c6e-2fe3-5e65-8259-8a43215d787d', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '1d183755-02b3-4a6d-b727-082af1ef377c', '9c37478d-2388-1380-cdea-3b62d82c3fcb', '同义替换与转述识别', '识别文章中同一概念或信息的不同表达方式，如用近义词、换一种说法、使用代词或概括词等，能够将前后信息对应起来，理解文章的一致性。', '认为不同表达代表不同内容，不能识别同义替换，导致信息整合失败。', '日语例句：この問題は複雑だ。つまり、単純な解決策は存在しないということだ。；说明：「複雑だ」被转述为「単純な解決策は存在しない」，需识别这种同义替换。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('7a1bc613-f3b6-55ca-9bdf-d67dd2dc9069', '9221fc32-a051-42cb-86b1-6a9917aa004e', '42de0c7b-50d9-4159-918a-4e618d83342d', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', 'ef36118d-0ba3-29ce-b2b3-76eaeb6542ca', 'たら（条件/完成）', '动词た形+ら表示条件，强调前件完成后的后件，后件可为意志。接续：た形+ら。', '与ば、と混淆；た形变化错误。', '時間があったら、行きます。说明：如果有时间就去。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('7a54ba4a-521b-564a-9a28-bbd03230b084', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '1d183755-02b3-4a6d-b727-082af1ef377c', '6f1477f5-00be-f963-76b6-5165f568e88e', '作者态度表达识别', '通过“～べきだ”“～てほしい”“～ではないか”等表达识别作者对话题的态度（赞成、反对、担忧、期待等）。', '只关注内容而忽略语气词和助动词，导致态度判断错误。', '日语例句：環境問題を解決するためには、一人一人が行動すべきだ。说明：“べきだ”表达作者强烈的建议态度。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('7a8b8dfb-b705-537a-9b20-022e796d0ad3', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '5b34d8b5-bde9-c4c6-c736-84adaaae3603', '「を通じて」的用法', '掌握「を通じて」表示“通过、经过”。', '与「を通して」混淆，但「を通じて」更强调媒介。', '日本語：インターネットを通じて情報を得る。；说明：通过网络获取信息。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('7acdae6d-8ed7-50b4-aca0-f2e506103c27', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '1d183755-02b3-4a6d-b727-082af1ef377c', '9c37478d-2388-1380-cdea-3b62d82c3fcb', '设问与反问的意图把握', '理解文中设问（自问自答）和反问（以问代答）的作用，把握作者通过提问引导读者思考或强调观点。', '将反问当作真问题；忽略设问后的回答；未理解反问的肯定/否定含义。', '日语例句：果たして、このままでいいのだろうか。いや、よくない。说明：设问后自答，强调现状需要改变。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('7ae34f3e-3dd8-58da-ac93-85402e4efa55', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '3760dfca-44d9-3445-01cd-85de1f860da1', '～を通じて', '表示“通过…、在整个期间/范围内”。接续：名词+を通じて。', '与「～を通して」的区别：「通じて」强调媒介或整个期间，「通して」强调通过某过程。', 'インターネットを通じて世界中と交流できる。；说明：通过互联网能与世界交流。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('7b903536-0d25-56c4-a742-21286f09b012', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '1d183755-02b3-4a6d-b727-082af1ef377c', '40ed56d1-acbd-4a8b-6284-2df8b9423e8e', '快速浏览抓大意', '在有限时间内通过标题、首尾句、关键词快速把握文章整体话题和作者态度，不逐词阅读。', '陷入细节导致时间不够；忽略标题和段落首句的提示作用。', '日语例句：文章标题「ペットと高齢者」、开头句「最近、高齢者とペットの関係についての研究が進んでいる。」说明：通过标题和首句即可判断文章主题为宠物与老年人的关系。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('7c0cbe6e-7563-50d9-b363-8312917f2d86', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '1d183755-02b3-4a6d-b727-082af1ef377c', '6f1477f5-00be-f963-76b6-5165f568e88e', '设问句与文章意图', '识别文中设问句（自问自答）的作用，理解作者通过提问引导读者思考或强调重点。', '将设问句误认为需要读者回答；忽视设问后的回答内容。', '日语例句：では、どうすればいいのだろうか。まず、…説明：设问后引出解决方案。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('7c6d94bc-7ba4-5266-a87f-7f298e5a6469', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '5b34d8b5-bde9-c4c6-c736-84adaaae3603', '「拒」的读音与词义', '「拒」读「きょ」，表示拒绝、抗拒。N1中「拒否（きょひ）」「拒絶（きょぜつ）」等需掌握。', '将「拒否」误读为「きょふ」；混淆「拒絶」与「断る」的语体。', '彼は提案を拒否した。（拒绝提案）说明：「拒否」是正式用语。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('7cc9bbf9-28c3-5ed0-8543-702b659c365e', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '2c18e7e1-4ef0-65e3-24a7-6c97d562a122', '～いかんにかかわらず', '表示“不管……如何”的意思，强调不受前项影响。接续：名词＋（の）いかんにかかわらず。', '与「～にかかわらず」相似，但「～いかんにかかわらず」更正式，常用于书面语。', '日语例句：理由のいかんにかかわらず、遅刻は認められない。；说明：不管理由如何，迟到都不被允许。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('7cd0d244-2ec7-5d02-b69a-6cab25ca8ae4', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '0545d0ec-89d1-a8aa-99f9-78b30fcbacb1', '汉字复合词中的缩略形式（略語）', 'N2阶段需识别常见汉字复合词的缩略表达，如「国連（国際連合）」「電車（電気車）」「高校（高等学校）」。缩略后读音可能保留部分音读，需掌握常用缩略词及其原形。', '学习者可能不理解缩略词与原词的关系，或将非缩略词误认为缩略，如「手帳」并非「手帳面」。', '日语例句：国連の会議が開かれた。；说明：「国連」是「国際連合」的缩略，音读「こくれん」。日语例句：この問題は文部省が管轄する。；说明：「文部省」为「文部科学省」的旧称缩略，需注意历史语境。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('7d66aa6d-2a5b-506f-a19d-3d25567a398e', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', 'baa9b5c2-5b94-4f9b-7ced-3a8c3cde4cb3', '近义动词的语境选择', '掌握如「見る」「観る」「診る」等动词在对象上的区别，以及「聞く」「聴く」的差异，根据动作对象选择正确动词。', '混用「見る」和「観る」，如把看电影说成「映画を見る」虽然可以，但「観る」更强调欣赏；把看病说成「医者を見る」应为「診てもらう」。', '日语例句：医者に診てもらう。；说明：「診る」专用于医疗检查，而「見る」一般看。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('7d814660-6648-5068-b2bc-a1fb84fec14d', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', 'ff057d86-47bc-de16-f0f9-a7b808b968e3', 'N3汉字复合词读音规律（扩展三）', '进一步掌握N3常见汉字复合词中音读与训读混合的读音，如「手伝う（てつだう）」「気配（けはい）」「物語（ものがたり）」等，注意个别字在复合词中的特殊读音变化。', '容易将「手伝う」误读为「しゅでんう」或「てつたう」，忽视「伝」的浊化；「気配」误读为「きはい」而正确为「けはい」。', '例句：彼は手伝うと言った。说明：「手伝う」中「手」训读「て」，「伝」浊化为「だ」；例句：部屋に人の気配がする。说明：「気配」读「けはい」，非「きはい」。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('7defde81-9b1a-5909-9e4e-155e58296da8', '9221fc32-a051-42cb-86b1-6a9917aa004e', '42de0c7b-50d9-4159-918a-4e618d83342d', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '2d7157f8-afb7-58a0-85ea-b3d775f216a2', '条件、假定与让步', '掌握「たら」「なら」「ば」以及让步表达的条件关系。', '条件成立时间和假设前提不匹配。', '時間があったら、電話してください。', 'published', '2026-09-03 13:10:31.032213+08', '2026-09-03 13:10:31.032213+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('7e57d9b3-dcc3-5607-af44-45e6d7834257', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '0545d0ec-89d1-a8aa-99f9-78b30fcbacb1', '送假名对动词读音与词义的影响', '动词的送假名不同可能导致读音和意义不同，如「話す（はなす）」与「話し合う（はなしあう）」，需注意送假名与派生词的关系。', '忽略送假名变化带来的读音变化；将「話し合う」误读为「はなすあう」。', '日语例句：皆で話し合って決めよう。；说明：「話し合う」中「話し」读「はなし」，送假名「し」保留，表示互相商量。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('7f349d75-c141-503b-a30c-7cbce464a001', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '2c18e7e1-4ef0-65e3-24a7-6c97d562a122', '～に疲れた', '表示因某事物而感到疲惫。接续：名词+に疲れた。', '注意与「～に疲れている」（正处于疲惫状态）区分。', '人間関係に疲れて、田舎で暮らしたい。说明：对人際关系感到疲惫。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('7f7ec024-6ee7-5850-a587-f113cc06b846', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '0545d0ec-89d1-a8aa-99f9-78b30fcbacb1', '表示原因理由的「～から」「～ので」「～ため」的语体区分', '掌握「～から」（主观原因，口语）、「～ので」（客观原因，礼貌）、「～ため」（正式原因，书面）的接续和语感区别。', '学习者常在正式场合使用「～から」，显得不礼貌，应使用「～ので」或「～ため」。', '日本語例：時間がないから急ごう。（因为没时间快点吧）／雨が降ったので、試合は中止になった。（因为下雨比赛中止）／事故のため、電車が遅れている。（由于事故电车晚点）。说明：三者的正式度递增。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('7fba2bc5-3d22-5624-abff-441353c17608', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '1d183755-02b3-4a6d-b727-082af1ef377c', '40ed56d1-acbd-4a8b-6284-2df8b9423e8e', '短新闻要点理解', '能读懂生活、社会类短新闻，抓住事件（何时、何地、何人、何事、为何）及报道倾向。', '只关注具体数字，忽略事件全貌；不理解新闻中引语的作用。', '日语例句：昨日、東京で新しい図書館が開館した。開館時間は午前9時から午後9時までで、誰でも無料で利用できる。说明：要点是开馆时间、地点、免费利用等基本信息。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('7ff05479-8456-5fdc-b277-a6c5501d0462', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '3760dfca-44d9-3445-01cd-85de1f860da1', '～ようにする（努力）', '表示努力做到某事，设法使…成为习惯。接动词辞书形/ない形。', '与「～ようになる」混淆；误用为客观变化。', '毎日野菜を食べるようにしている。说明：努力做到每天吃蔬菜。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('8037b70b-2d48-5449-8a1e-d67f5b820dcf', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '0545d0ec-89d1-a8aa-99f9-78b30fcbacb1', '当て字（借字）在复合词中的读音与意义', 'N2需掌握常见当て字复合词，如「寿司（すし）」「天麩羅（てんぷら）」「珈琲（コーヒー）」。这些词汉字仅表音，不表义，需整体记忆。', '学习者常按字面义理解，如将「寿司」理解为“寿命”，或误读「天麩羅」为「てんぷら」正确但不知其来源。', '日语例句：寿司を食べる。；说明：「寿司」为当て字，读「すし」，与“寿”和“司”的意义无关。日语例句：喫茶店で珈琲を飲む。；说明：「珈琲」为当て字，读「コーヒー」，汉字仅表音。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('804b0764-19f0-53f9-85c4-7ab5ecbfaea7', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '3760dfca-44d9-3445-01cd-85de1f860da1', '～にしては', '表示与预想不符，按……来说却……。接续：名词/动词普通形＋にしては。', '与「わりに」相似，但「にしては」强调评价基准。', '彼は新人にしては、よく仕事をこなしている。；说明：作为新人来说，他工作完成得很好。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('806a1ce4-a830-587b-a0b6-529b9a658c74', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', 'dd4e968a-3d37-98a7-3819-a5fc4c117122', '～ことになる（客观决定）', '表示“（组织、规则等）决定……”，接续：动词辞书形/ない形+ことになる。', '与～ことにする混淆，前者被动客观，后者主动。', '日本語：来月、大阪に転勤することになった。；说明：公司决定下月调我去大阪。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('80e244b5-434b-5cb4-8351-6259eeb12416', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', 'ff057d86-47bc-de16-f0f9-a7b808b968e3', 'N3敬语动词的对应关系（扩展二）', '掌握N3中更多敬语动词的对应，如「もらう→いただく」「あげる→さしあげる」「言う→おっしゃる」「行く/来る→いらっしゃる」等，并注意使用场合和对象。', '将「いただく」用于自己给他人时；混淆「おっしゃる」与「言う」的尊敬程度；在非正式场合过度使用敬语。', '日语例句：先生が何とおっしゃいましたか。／私は先生から本をいただきました。；说明：「おっしゃる」是「言う」的尊敬语，「いただく」是「もらう」的谦让语。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('8121784d-f376-50e6-861f-52f149654c27', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '0545d0ec-89d1-a8aa-99f9-78b30fcbacb1', '复合动词中前项动词的读音变化', 'N2阶段复合动词数量增多，前项动词在结合时可能发生音便（如「～込む」「～出す」），需掌握常见复合动词的读音与意义，如「思い込む」「飛び出す」。', '误将前项动词按单独读音读，忽略音便；混淆「～込む」表示深入与「～出す」表示开始/向外。', '日语例句：彼は部屋から飛び出した。；说明：「飛び出す」中「飛び」读作「とび」，表示突然向外跑出。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('813dff3f-883c-5cb8-b696-6f5c426f96f5', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '5b34d8b5-bde9-c4c6-c736-84adaaae3603', '「甲」「校」「紅」等「こう」同音汉字的读音与词义区分', 'N1文字词汇中常出现多个读作「こう」的汉字，如「甲（こう）」「校（こう）」「紅（こう）」「攻（こう）」「高（こう）」等。本知识点聚焦于这些同音汉字在不同词语中的读音与词义区分，帮助学习者根据上下文判断正确表记和含义。', '学习者容易将「甲」误读为「こう」以外的音，或将「紅」与「赤」混淆；在「甲板」「校舎」「紅茶」等词中需注意各自固定读音和语义。', E'日语例句：甲板（こうはん）で船員が働いている。；说明：「甲」读「こう」，表示第一或外壳。\\n日语例句：紅茶（こうちゃ）を一杯飲む。；说明：「紅」读「こう」，表示红色，但「紅茶」特指红茶。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('8172c5fd-bc7c-56e6-8fbd-873cfdb3d6c1', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', 'baa9b5c2-5b94-4f9b-7ced-3a8c3cde4cb3', '可能动词的构成与使用', '掌握N4可能动词（如「食べられる」「行ける」）的构成规则，理解其表示能力或可能性的用法。', '将五段动词可能形误用为「～れる」形式；混淆可能动词与被动形。', '日语例句：日本語が話せます。；说明：「話せる」是「話す」的可能形，表示会说话，注意与被动「話される」区分。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('8178bc99-70a5-5969-a427-a412b038d282', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '1d183755-02b3-4a6d-b727-082af1ef377c', '6f1477f5-00be-f963-76b6-5165f568e88e', '委婉表达与态度限定', '理解「かもしれない」「だろう」「と思われる」等表达所体现的作者不确定或谨慎态度。', '将推测当作事实；忽视程度副词（必ずしも、おそらく等）。', '日语例句：この説は正しいかもしれないが、まだ証明されていない。说明：作者持保留态度。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('819af171-fd19-566f-86f5-598e79367baf', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', 'ff057d86-47bc-de16-f0f9-a7b808b968e3', 'N3基础拟声拟态词（扩展四）', '学习N3中表示状态和样子的拟态词，如「はっきり」「ぐっすり」「そろそろ」「うっかり」等，并掌握其与动词的搭配。', '学习者常将拟态词与动词搭配错误，如「ぐっすり」只能与「眠る」搭配，不能用于「寝る」以外的动词；「うっかり」表示无意中，需与「忘れる」等搭配。', '日语例句：はっきり言ってください。；说明：「はっきり」表示清楚明确。日语例句：昨夜はぐっすり眠れた。；说明：「ぐっすり」表示熟睡。日语例句：うっかり財布を忘れた。；说明：「うっかり」表示不小心。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('81cab840-a91d-5b9e-8ef9-2af6fadb8810', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '1af448c1-54cf-2f94-01b5-e8bc77a97f94', '～ために（目的・原因）', '接动词辞书形或名词+の表示目的“为了”，接名词+の或动词普通形（过去/现在）表示原因“因为”。', '目的用法中动词必须用辞书形，不能用た形；原因用法中前后句主语可不同。', '留学するために日本語を勉強しています。（为了留学而学日语。）／事故のために遅れました。（因为事故迟到了。）', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('81f0d244-ca44-5f39-b6db-3e88f9a76072', '9221fc32-a051-42cb-86b1-6a9917aa004e', '42de0c7b-50d9-4159-918a-4e618d83342d', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '0e03a921-5aff-e4be-f477-4d55640b198b', '杯类容器的量词「杯」', '掌握量词「杯（はい/ばい/ぱい）」用于数杯中的饮料，注意音变：1杯（いっぱい）、3杯（さんばい）、6杯（ろっぱい）、8杯（はっぱい）、10杯（じゅっぱい）。', '将1杯读作「いちはい」、3杯读作「さんはい」；将「杯」与「本」混淆（瓶装用「本」，杯装用「杯」）。', '日本語：コーヒーを一杯ください。；说明：一杯读作「いっぱい」。日本語：お茶を三杯飲みました。；说明：三杯读作「さんばい」。日本語：水を六杯飲みます。；说明：六杯读作「ろっぱい」。)', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('821e647c-4241-5b00-9630-d95ce3fecdd5', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '5b34d8b5-bde9-c4c6-c736-84adaaae3603', '「師」的多种读音与词义', '「師」在N1中常见读音「し」，词义包括“老师、师傅”“军队”“专家”等。如「教師（きょうし）」「医師（いし）」「師匠（ししょう）」「師団（しだん）」「師走（しわす）」。', '「師走」读「しわす」而非「しそう」；「師匠」读「ししょう」而非「しそう」。', '彼は師匠（ししょう）から技術を学んだ。说明：師匠指师傅、老师。；師走（しわす）は何かと忙しい。说明：師走指农历十二月。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('8231d3c2-2fab-5ed9-8b9c-86b79f220446', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '1af448c1-54cf-2f94-01b5-e8bc77a97f94', '～ていくか（方向・反问）', '以反问形式表达“该…下去吗？”或“会…吗？”接续：动词て形+いくか。多用于内心疑问。', '与～ていく（方向）混淆，该形式带反问。注意口语中不常用。', '日本語：このまま進んでいくか。；说明：自问“就这样继续前进吗？”', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('8295a713-2708-5899-b556-da37110e0666', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '0545d0ec-89d1-a8aa-99f9-78b30fcbacb1', '抽象名词近义词的语境限制（如「影響」与「効果」）', 'N2中「影響」指间接作用，「効果」指直接效果，需根据作用方式选择。', '将「影響」与「効果」混用。', '例句：天気が作物に影響を与える。说明：「影響」指影响。；例句：この薬は効果がある。说明：「効果」指效果。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('82a560ca-18c0-57bd-b31b-af7e278771a5', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '3760dfca-44d9-3445-01cd-85de1f860da1', '～にかかわるように', '表示“以便与…相关”，用于说明目的或方式。', '注意与“～にかかわる”的区别，本句型强调动作的目的性。', '日本語：この制度は市民の生活にかかわるように設計されている。；说明：这项制度被设计成与市民生活相关。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('82e4e3ca-b401-53a1-b9ef-bb2a5ca6fb93', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '5b34d8b5-bde9-c4c6-c736-84adaaae3603', '「方」「方」的读音与用法区分', 'N1中「方」有「かた」「ほう」两种读音，需根据语境区分：表示方法、方向时读「かた」，表示比较、选择时读「ほう」。', '将「方」在「この方」中误读为「ほう」；混淆「方」表示方法（如「やり方」）与表示方面（如「この方」）的读音。', '日本語の勉強の仕方を教えてください。（方法，读かた）说明：此处「方」表示方法，读「かた」。／この方のほうが安いです。（方面，读ほう）说明：此处「方」表示比较选择，读「ほう」。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('832fc27b-4df0-5872-b49b-d891eca3ff71', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '3760dfca-44d9-3445-01cd-85de1f860da1', '～ことだから', '用于根据对某人的了解或已知情况，进行推测或判断。接续：名词+の+ことだから，常与「きっと」「必ず」等呼应。', '容易与「～ことだ」混淆，「ことだ」表示忠告或感叹，而「ことだから」表示依据。', '彼のことだから、約束の時間に遅れるはずがない。；说明：因为是他的性格，所以不可能迟到。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('83577b4f-8e58-5a41-aa09-768de139c089', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '5b34d8b5-bde9-c4c6-c736-84adaaae3603', '「長」「朝」「町」等「ちょう」同音汉字的读音与词义区分', '「ちょう」读音的汉字包括「長（ちょう）」「朝（ちょう）」「町（ちょう）」「超（ちょう）」「張（ちょう）」等。本知识点帮助学习者区分这些汉字在词语中的具体读音与意义。', '学习者可能将「長所」误读为「ちょうしょ」以外的音，或混淆「町」与「街」；需注意「長」多指长度或首领，「朝」指早晨或朝代。', E'日语例句：彼は長所（ちょうしょ）が多い。；说明：「長」读「ちょう」，表示长处。\\n日语例句：朝食（ちょうしょく）を抜いた。；说明：「朝」读「ちょう」，表示早晨。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('83c6e01e-6d2e-5e45-bb99-259490e8847f', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '1d183755-02b3-4a6d-b727-082af1ef377c', '6f1477f5-00be-f963-76b6-5165f568e88e', '段落衔接与逻辑关系', '理解段落之间的连接关系（承接、转折、补充、总结），把握文章整体结构。', '忽视连接词；只读单段而忽略整体脉络。', '日语例句：しかし、この方法には問題もある。説明：「しかし」提示下文与前文相反。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('841a6dc8-c15a-5a69-b8c0-4e393c6e7824', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '1af448c1-54cf-2f94-01b5-e8bc77a97f94', '～てくるか（方向・反问）', '以反问形式表达“会…过来吗？”或“该…吗？”接续：动词て形+くるか。多用于口语疑问。', '与～てくる（方向）混淆，该形式带反问。注意～てくるか也可表示“要不要…呢”。', '日本語：彼は本当に来てくるか。；说明：怀疑“他真的会来吗？”', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('844f7d44-99c7-54da-848c-7f7287fb6205', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '2c18e7e1-4ef0-65e3-24a7-6c97d562a122', '～には及ばない', '表示“不必……，用不着……”，也可表示“比不上”。接续：动词辞书形/名词+には及ばない。', '注意区分「～には及ばない」表示“不必”和「～に及ばない」表示“比不上”的用法；接续不同。', '日本語：お忙しいところ、わざわざ来るには及ばない。；说明：您很忙，不必特意前来。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('84603322-6927-5962-b18b-8e11f7acf277', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '1d183755-02b3-4a6d-b727-082af1ef377c', '9c37478d-2388-1380-cdea-3b62d82c3fcb', '词汇链与语义场的衔接识别', '通过识别同一语义场或词汇链（如同义词、上下义词、相关词）在段落间的反复出现，把握文章主题的连贯性和论述推进。', '只关注指示词和接续词，忽略词汇重复带来的衔接；误将不同语义场的词当作同义。', '日语例句：環境問題→温暖化→二酸化炭素→排出削減。；说明：这些词构成词汇链，帮助理解文章围绕环境对策展开。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('8460d479-d081-5d68-b875-cef8e4c265d7', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '3760dfca-44d9-3445-01cd-85de1f860da1', '～ことだし', '表示列举理由，相当于“又……所以……”。接动词或形容词普通形。', '误用于单纯并列；注意后句常为结论或建议。', '日语例句：時間もないことだし、早く出かけよう。；说明：又没时间了，所以快点出门吧。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('84a485b3-ec48-5254-8dc2-9dffd025c4a6', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '0545d0ec-89d1-a8aa-99f9-78b30fcbacb1', '自动词与他动词的对应关系', '掌握N2常见自他动词对（如「決まる/決める」「集まる/集める」）的用法，理解主语和动作对象的关系。', '混淆自他动词的助词使用，如「会議を決まる」误用；或在不该使用被动时使用被动。', '日语例句：会議の日程が決まった。；说明：「決まる」为自动词，主语是日程；「決める」为他动词，需带宾语。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('84e3f5b2-7b05-5f82-86d6-8b762f70de9e', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '1af448c1-54cf-2f94-01b5-e8bc77a97f94', '～ないといけない（口语义务）', '与～ないといけない同义，但更口语化，有时写作～ないと。接续：动词ない形＋と＋いけない／いかない。', '误以为～ないと可以单独使用，实际省略了いけない；在正式场合使用显得过于随便。', '日本語：早く行かないと。；说明：口语省略，表示“不去不行”。
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('85033a4d-3044-5e0a-92e7-932857a394ae', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '5b34d8b5-bde9-c4c6-c736-84adaaae3603', '「絶対に」的强调用法', '掌握「絶対に」表示“绝对”的强烈意志或禁止。', '与「必ず」混淆，但「絶対に」更主观。', '日本語：絶対に遅刻しないでください。；说明：请绝对不要迟到。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('85235d54-dc96-594c-9ec5-38de24dd3fee', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '0545d0ec-89d1-a8aa-99f9-78b30fcbacb1', '抽象名词在具体语境中的用法（如「意識」「関係」「影響」）', 'N2抽象名词如「意識」「関係」「影響」等，常与特定动词搭配，如「意識が高い」「関係がある」「影響を与える」。本知识点训练这些名词的搭配和语境。', '搭配错误，如将「影響を与える」误说成「影響をする」。', '日语例句：この政策は経済に大きな影響を与えた。；说明：「影響を与える」是固定搭配，不能省略「与える」。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('853839b7-9b8b-56e5-97fd-dc37cf67bc9d', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '1d183755-02b3-4a6d-b727-082af1ef377c', '40ed56d1-acbd-4a8b-6284-2df8b9423e8e', '图表数据与文章推断结合', '在包含图表、表格或数据的文章中，将文字信息与图表数据相互印证，推断趋势、比较差异或验证文中结论。', '只读图表忽略文字说明；将图表中的具体数值直接当作文章结论；忽略图表的时间范围或单位。', '日语例句：文章说“近年来年轻人阅读量减少”，图表显示20岁以下人群年均读书册数从5册降至2册。说明：图表数据支撑文章观点，需结合两者推断趋势。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('857e25c0-0bc9-5003-a5b6-4d1020072d1d', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '0545d0ec-89d1-a8aa-99f9-78b30fcbacb1', '表示倾向、样态的接尾词（～がち・～気味・～っぽい）', '掌握「～がち」（容易…，多用于负面倾向）、「～気味」（有点…，轻微倾向）、「～っぽい」（像…，有…味道）的接续和语感区别。「～がち」接动词ます形或名词，「～気味」接动词ます形或名词，「～っぽい」接名词、动词ます形或形容词词干。', '学习者常混淆「～がち」与「～気味」的轻重程度，「～気味」程度较轻，且「～っぽい」可表示人的性格或外观。', '日本語例：彼は遅刻しがちだ。（容易迟到）／少し疲れ気味だ。（有点累）／彼女は子供っぽい。（像孩子）。说明：三者均表示倾向，但语感不同。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('858fdaae-9414-516e-be72-3812b7576bb3', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '1d183755-02b3-4a6d-b727-082af1ef377c', '9c37478d-2388-1380-cdea-3b62d82c3fcb', '顺序标记词的利用', '利用文章中表示顺序的标记词（まず、次に、最後に、第一に、第二に等）来把握论述的步骤、层次或列举项目，理清文章的结构脉络。', '忽略顺序标记词，导致对论述层次和先后关系把握不清，无法有效组织信息。', '日语例句：まず、現状の問題点を整理する。次に、その原因を分析する。最後に、解決策を提案する。；说明：通过「まず」「次に」「最後に」清晰呈现论述的先后步骤。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('85baf2a8-ad13-5fa8-a790-62a5071f2e6f', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '2c18e7e1-4ef0-65e3-24a7-6c97d562a122', '～を踏まえて', '表示“在……基础上，根据……”，强调依据前项事实或意见。接续：名词+を踏まえて。', '与「～に基づいて」相近，但「を踏まえて」更强调考虑前项并反映在后项中，常用于建议或决定。', '日本語：調査結果を踏まえて、新しい方針を決める。；说明：根据调查结果，决定新方针。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('85ece257-5bc1-50ff-b9fa-d2cc178c5d6b', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '5b34d8b5-bde9-c4c6-c736-84adaaae3603', '「をもって」的用法', '掌握「をもって」表示“以……为手段”或“以……为界限”。', '与「をもって」的书面语混淆，注意正式场合。', '日本語：これをもって閉会とします。；说明：以此宣布闭会。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('8634d189-85df-59b4-8989-213c9c0ad46f', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '5b34d8b5-bde9-c4c6-c736-84adaaae3603', '「肢」的读音与词义', '「肢」读「し」，指四肢。N1中「四肢」「義肢」等词需掌握。', '将「肢」误读为「えだ」；混淆「肢体」与「手足」的语体。', '事故で四肢を失った。（失去四肢）说明：「四肢」读「しし」。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('8658eaeb-aa05-5343-a56a-3121c024e2d0', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '5b34d8b5-bde9-c4c6-c736-84adaaae3603', '「伴う」与「随う」的用法区分', '「伴う」读「ともなう」，表示伴随、随着；「随う」读「したがう」，表示跟随、服从。注意「伴う」常与「変化」「リスク」搭配。', '将「伴う」误读为「はん」；混淆两者，如「規則に伴う」应为「従う」。', 'リスクを伴（ともな）う決断。；说明：伴随。／指示に従（したが）う。；说明：服从。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('868789d1-6089-5398-aca2-f16d6d7e6525', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '2c18e7e1-4ef0-65e3-24a7-6c97d562a122', '～に連れては', '表示随着前项的变化，后项也变化，但带有对比或强调的语感。较少见，多用于书面语。', '与「～に連れて」相比，「に連れては」强调变化的结果或对比。', '日本語：年を取るに連れては、体力が衰えるものだ。；说明：随着年龄增长，体力自然会衰退。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('870e0e0d-7bcc-5731-9b06-f85fa6a26854', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '3760dfca-44d9-3445-01cd-85de1f860da1', '～ては困る', '表示“如果…就麻烦了”，用于表达对对方行为的担心或不满。', '注意「～ては困る」的主语常是对方，而「～てはならない」是普遍禁止。', 'そんなことを言われては困る。；说明：你那么说我会很为难。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('87912e1b-18f7-503f-a958-1aeb33b216a6', '9221fc32-a051-42cb-86b1-6a9917aa004e', '42de0c7b-50d9-4159-918a-4e618d83342d', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '0e03a921-5aff-e4be-f477-4d55640b198b', '时间名词的汉字读音（非量词）', 'N5时间名词如「朝」「昼」「夜」「午前」「午後」「今日」「昨日」「明日」的汉字读音，注意特殊读音。', '将「今日」读成「きょう」以外的音（如「こんにち」），或「昨日」读成「さくじつ」但N5常用「きのう」。', '日本語例：昨日は雨でした。说明：「昨日」读作「きのう」，是常用读音。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('87b3815e-c1c6-5dde-842d-c63b46d9bc5b', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '2c18e7e1-4ef0-65e3-24a7-6c97d562a122', '～を抜きにして（は）', '表示“省去、抛开……不谈/不做”的意思，强调在某种前提或条件下无法进行或考虑。接续：名词+を抜きにして（は）。', '与「～を抜きにして」相比，「～を抜きにしては」更强调“如果不……就……”的条件性。注意不能用于单纯列举省略，而应表示“排除某因素”。', '日本語：冗談を抜きにして、本気で考えよう。；说明：抛开玩笑，认真考虑。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('87f41720-a30f-5028-b6db-935c96ec8782', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '1d183755-02b3-4a6d-b727-082af1ef377c', '40ed56d1-acbd-4a8b-6284-2df8b9423e8e', '邮件与书信意图把握', '能读懂日常邮件、书信，把握写信目的（通知、邀请、致谢、道歉等）及需要回复的事项。', '只关注寒暄语，忽略正文核心请求；未注意“ご返事ください”等要求。', '日语例句：メール：「来週の会議の日程が変更になりました。新しい日程は下記の通りです。ご確認ください。」说明：主要目的是通知日程变更并要求确认。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('881d012e-2357-579b-ae96-7b2288c90807', '9221fc32-a051-42cb-86b1-6a9917aa004e', '42de0c7b-50d9-4159-918a-4e618d83342d', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', 'ef36118d-0ba3-29ce-b2b3-76eaeb6542ca', 'てはいけませんか（请求允许？）', '注意：此形式不用于请求许可，而是确认禁止，实际很少用。', '误用为「可以吗？」；请求许可应用「てもいいですか」。', 'ここで泳いではいけませんか。；说明：这里不能游泳吗？（确认禁止）', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('88286154-7572-5cef-a191-70727a95779e', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '1d183755-02b3-4a6d-b727-082af1ef377c', '40ed56d1-acbd-4a8b-6284-2df8b9423e8e', '段落要点概括', '能用一句话概括段落核心内容，删除冗余细节，保留关键信息。', '概括过宽或过窄；照抄原文句子而非提炼。', '日语例句：段落：環境問題を解決するためには、一人一人の努力が必要だ。例えば、ゴミを減らす、電気を節約するなど、小さなことから始められる。说明：概括为“解决环境问题需要每个人的小行动”。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('88712365-2119-5b55-9960-85cf724f491f', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', 'baa9b5c2-5b94-4f9b-7ced-3a8c3cde4cb3', '动词て形连接的顺序与方式意义', '掌握动词て形连接多个动作时表示动作先后顺序、方式或并列关系的用法，理解て形在句子中作为中顿的功能。', '误以为て形只能表示先后顺序，忽略其表示方式（如「歩いて行く」）或并列（如「歌って踊る」）的用法；混淆て形与「ながら」的区别。', '朝起きて、顔を洗って、ご飯を食べます。说明：て形连接表示动作先后顺序。／駅まで走って行きました。说明：て形表示方式，即“跑着去”。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('8939da76-ec63-540c-b81e-dc8aaf7460fd', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '0545d0ec-89d1-a8aa-99f9-78b30fcbacb1', '表示授受关系的「～てあげる」「～てもらう」「～てくれる」', '掌握授受动词「～てあげる」（给别人做）、「～てもらう」（请别人做）、「～てくれる」（别人为我做）的方向和恩惠关系。', '学习者常混淆「～てもらう」与「～てくれる」的主语，前者主语是接受者，后者主语是给予者。', '日本語例：私は彼に本を貸してあげた。（我借书给他）／私は彼に本を貸してもらった。（我请他借书给我）／彼は私に本を貸してくれた。（他借书给我）。说明：三者方向不同。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('89564b4d-004b-56db-91fe-a50630e20368', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '0545d0ec-89d1-a8aa-99f9-78b30fcbacb1', '表示情感状态的近义词辨析（如「悲しい」与「哀しい」）', 'N2需辨析情感形容词的细微差别，如「悲しい」侧重客观悲伤，「哀しい」带有文学性、主观哀愁；「寂しい」与「淋しい」也有语感差异。', '认为同义词完全可互换；忽略语体与文学色彩。', '日语例句：彼女の顔は哀しい微笑みを浮かべていた。；说明：「哀しい」比「悲しい」更书面、带有诗意，常用于文学描写。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('89aebe15-9aff-5357-8ea7-724c2f8b4d41', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', 'ff057d86-47bc-de16-f0f9-a7b808b968e3', 'N3动词与名词的固定搭配（扩展三）', '掌握N3中常见的动词与名词固定搭配，如「夢を見る」「役に立つ」「気をつける」「世話をする」「間に合う」等，并注意搭配的不可替换性。', '将「夢を見る」误说成「夢をする」；「役に立つ」不能说「役をする」；「気をつける」不能说「注意をつける」（虽然意思相近但搭配不同）。', '例句：毎晩夢を見る。说明：「夢を見る」固定搭配；例句：この本は役に立つ。说明：「役に立つ」固定搭配；例句：気をつけて帰ってください。说明：「気をつける」固定搭配。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('89eb34c6-1fed-5073-9edf-eb602e92ce0f', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '1af448c1-54cf-2f94-01b5-e8bc77a97f94', '～てしまうか（后悔・反问）', '以反问形式表达“会不会…了”或“难道…了”。接续：动词て形+しまうか。多用于自言自语或书面。', '与～てしまう（完了）混淆，该形式带反问语气。注意实际使用较少。', '日本語：こんなに遅れて、約束を忘れてしまうか。；说明：自言自语“这么晚了，难道忘了约定吗？”', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('8a07ffac-dcbd-5477-8276-9f0bbccfbdf5', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', 'dd4e968a-3d37-98a7-3819-a5fc4c117122', '～ていただく（请别人为自己做・谦逊）', '～てもらう的谦逊语，用于请求长辈或上级为自己做某事，或表示自己受惠。接续：动词て形＋いただく。', '对平辈或晚辈使用显得过于客气；误用为～てくださる（尊敬）；忘记使用いただく的谦逊含义。', '先生に推薦状を書いていただきました。说明：请老师给我写了推荐信。／説明していただけますか。说明：能请您说明一下吗？', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('8a22e0b7-3b0c-590d-b884-b3208e44d91b', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', 'dd4e968a-3d37-98a7-3819-a5fc4c117122', '～なら（假定条件・话题条件）', '表示“如果是……的话”，接续：名词/な形容词+なら，动词/い形容词普通形+なら。常承接对方话题。', '与～たら混淆，～なら强调前提，后句多为建议、意志。', '日本語：日本に行くなら、桜の季節がいいよ。；说明：如果去日本，樱花季好。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('8a8da40b-47dd-527b-940d-11c5b9c1f4d5', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '0545d0ec-89d1-a8aa-99f9-78b30fcbacb1', '送假名对汉字词读音的影响', 'N2中部分汉字词因送假名不同而读音不同，如「話（はなし）」与「話す（はなす）」、「行（こう/ぎょう）」与「行く（いく）」，需注意词性变化。', '混淆同形汉字词因送假名不同导致的读音差异。', '例句：彼は話が上手だ。说明：「話」作名词读「はなし」。；例句：彼は日本語を話す。说明：「話す」作动词读「はなす」。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('8a9a2ca6-93cc-509f-bd0b-16196eb36f54', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '3760dfca-44d9-3445-01cd-85de1f860da1', '～ようになる（变化）', '表示状态或习惯的变化，逐渐变得能够…。接动词辞书形/ない形。', '与「～ことになる」混淆；误用为一次性决定。', '最近、早く起きられるようになった。说明：最近变得能早起了。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('8b5b0b77-ebb9-5e0c-bd6a-e4e96b49caaa', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '1af448c1-54cf-2f94-01b5-e8bc77a97f94', '～ていく／～てくる（空间移动・视点）', '表示以说话人为基准的空间移动方向：～ていく表示从说话人处离开或向远处移动，～てくる表示向说话人方向移动或从远处回来。也用于心理上的接近或远离。', '容易与表示时间变化的～ていく／～てくる混淆。空间移动时强调物理位置的变化，常与移动动词搭配，如「持っていく」「持ってくる」。', '日本語例：荷物を家に持っていきます。；说明：把行李拿到家（离开说话人方向）。日本語例：友達がこちらに走ってきました。；说明：朋友朝说话人方向跑来。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('8b6008b9-5007-561f-8b09-50ca70aa63f7', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '0545d0ec-89d1-a8aa-99f9-78b30fcbacb1', '汉字复合词中易错音读与训读的辨析', 'N2需掌握常见易错复合词，如「気分（きぶん）」「気持ち（きもち）」「都合（つごう）」「世話（せわ）」。这些词读音特殊或易与近义词混淆。', '学习者常将「気持ち」误读为「きもち」正确，但将「気分」误读为「きぶん」正确，却混淆两者语义；或将「世話」误读为「せわ」正确，但不知「お世話」用法。', '日语例句：今日は気分がいい。；说明：「気分」读「きぶん」，指身体或心情状态。日语例句：お世話になります。；说明：「世話」读「せわ」，为常用训读，注意「世話」不可拆读。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('8b6a0301-8565-544c-a329-772352134e10', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '3760dfca-44d9-3445-01cd-85de1f860da1', '～にかかわる（こと）', '表示“关系到…的事情”，用于强调某事物对重要方面的影响。接续：名词＋にかかわる＋こと/問題/事件等。', '不要与「～にかかわらず」（不论）混淆；「～にかかわる」后接名词，而「～にかかわらず」后接动词/形容词。', '日本語：環境問題は人類の未来にかかわることだ。；说明：环境问题是关系到人类未来的事情。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('8bbfc6c7-ec22-57fa-9818-abf183dd0cce', '9221fc32-a051-42cb-86b1-6a9917aa004e', '42de0c7b-50d9-4159-918a-4e618d83342d', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '0e03a921-5aff-e4be-f477-4d55640b198b', '次数量词「回」', '掌握量词「回（かい）」表示次数，如一回、二回、三回，注意「一回」读作「いっかい」，「六回」读作「ろっかい」，「八回」读作「はっかい」，「十回」读作「じゅっかい」。', '将一回读作「いちかい」；将「何回」读作「なんかい」时与「何階」混淆。', '日本語：週に一回運動します。；说明：一回读作「いっかい」。日本語：この映画を三回見ました。；说明：三回读作「さんかい」。日本語：何回行きましたか。；说明：何回读作「なんかい」。)', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('8bd562af-22a6-5b14-b97b-e1129a892fd2', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '1d183755-02b3-4a6d-b727-082af1ef377c', '6f1477f5-00be-f963-76b6-5165f568e88e', '比较标记阅读', '识别“～に比べて”“～より”“～ほど”等比较标记，理清比较对象和比较结果，把握作者对不同事物的评价。', '混淆比较双方，或忽略比较的基准。', '日语例句：従来の方法に比べて、新しい方法はコストが半分で済む。说明：比较对象是传统方法和新方法，结果是新方法成本低。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('8cccb03a-bcc0-5232-aa10-f1124eea3bae', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '1af448c1-54cf-2f94-01b5-e8bc77a97f94', '～ないことはない（不是不…）', '双重否定，表示“并非完全不…”，即有可能或有时会，语气委婉。', '与～ないことはない（没有…的事）混淆，本句型表示可能性；接续为动词ない形+ことはない。', '日本語：この問題は難しくないことはないが、時間をかければ解ける。；说明：表示并非完全不难，但可以解决。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('8d237005-87f5-5f47-9caf-b7fc6511ac42', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '1d183755-02b3-4a6d-b727-082af1ef377c', '40ed56d1-acbd-4a8b-6284-2df8b9423e8e', '对比表达与强调重点', '识别文中使用“ではなく”“より”“こそ”等对比或强调表达，理解作者真正想突出的重点是什么。', '只看到对比双方，忽略强调的一方；将“より”误认为单纯比较而非选择；不理解“こそ”的排他性强调。', '日语例句：彼は失敗を恐れるより、挑戦しないことを恐れている。说明：通过“より”对比，强调重点在后半句“不挑战的恐惧”，而非对失败的恐惧。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('8d47833a-3ec8-50bb-8785-a00b60ce2ba0', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '1af448c1-54cf-2f94-01b5-e8bc77a97f94', '～てくる（表示动作的持续方向）', '表示动作从过去持续到现在，或从某一点向说话人方向移动。接续：动词て形＋くる。强调时间上的累积或空间上的接近。', '与“～ていく”相对，后者表示从现在向未来或远离说话人方向。注意区分“～てくる”表示“来”的方向性，不要与“～ておく”混淆。', '三年間日本語を勉強してきました。说明：三年来一直在学日语（持续到现在）。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('8d579f54-6bbd-5e99-a447-45bef1a2cd67', '9221fc32-a051-42cb-86b1-6a9917aa004e', '42de0c7b-50d9-4159-918a-4e618d83342d', '1d183755-02b3-4a6d-b727-082af1ef377c', '37a506cf-ef62-8ccc-3210-ab64e8561a4d', '理解から表示原因', '能够识别から在句末或句中表示原因，并区分与ので的细微差别（から主观性强）。', '将から与时间起点混淆，忽略其因果功能。', '例句：時間がないから、行きません。说明：から表示原因，解释不去的原因。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('8d620f7d-c3d5-53d6-a79e-edbabf25fbb4', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', 'baa9b5c2-5b94-4f9b-7ced-3a8c3cde4cb3', '复合词中的浊音化（連濁）现象', '理解两个和语词或汉字词结合时后词首清音变浊音的规则，如「時々（ときどき）」「手紙（てがみ）」，并能识别常见例外。', '过度应用连浊，如把「花火（はなび）」读成「はなひ」；或忽略连浊，如把「小鳥（ことり）」读成「こちょう」。', '日语例句：小鳥が鳴く。；说明：「小（こ）」+「鳥（とり）」连浊为「ことり」，但「小川（おがわ）」中「か」变「が」。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('8d86c0b2-dd3b-5463-b0ba-f23d872730d2', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '2c18e7e1-4ef0-65e3-24a7-6c97d562a122', '～を余儀なくさせる', '表示“迫使～”，使役形式，主语是迫使者。接名词。', '与「～を余儀なくされる」混淆，后者是受害被动；此句型是使役，注意方向。', '台風は住民に避難を余儀なくさせた。；说明：台风迫使居民避难。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('8e2e934b-2bf9-5899-8ca3-14c1da1639fd', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', 'dd4e968a-3d37-98a7-3819-a5fc4c117122', '～ば～ほど（越……越……）', '表示“越……越……”，接续：动词ば形+ほど，い形容词ければ+ほど，な形なら+ほど。', '接续错误，如把い形容词直接加ほど。', '日本語：練習すればするほど上手になる。；说明：越练习越熟练。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('8e7496ee-26e0-5601-a4f0-e2e0f0c766b2', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '1af448c1-54cf-2f94-01b5-e8bc77a97f94', '～たばかり（刚刚完成）', '表示动作刚刚结束，与～たところ类似，但～たばかり更强调时间间隔短，且可用于状态。接续：动词た形＋ばかり。', '～たばかり不能与表示持续时间的词语连用（如～一時間），而～たところ可以；～たばかり可修饰名词。', '日本語：この本は昨日読んだばかりです。；说明：表示这本书昨天刚读过。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('8edf9903-a323-551c-ba54-e31c7e6d8f68', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', 'dd4e968a-3d37-98a7-3819-a5fc4c117122', '～ように（目的）', '表示“为了……”，接续：动词辞书形/ない形+ように，前句多为非意志动词或可能形。', '与～ために混淆，～ように前句不能是意志动词（如「勉強するように」错误）。', '日本語：遅れないように、早く出発する。；说明：为了不迟到，早点出发。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('8f6dfe00-c2d2-5b95-8533-684143360940', '9221fc32-a051-42cb-86b1-6a9917aa004e', '42de0c7b-50d9-4159-918a-4e618d83342d', '1d183755-02b3-4a6d-b727-082af1ef377c', '37a506cf-ef62-8ccc-3210-ab64e8561a4d', '从感叹词推断说话者情感', '能够通过ああ、わあ、えっ、あれ等感叹词理解说话者的惊讶、喜悦、疑惑等情绪。', '将感叹词视为无意义填充词，忽略其情感提示作用。', '例句：わあ、きれい！说明：わあ表达赞叹，推断说话者感到惊喜。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('8fbd49f7-33b4-5b1c-a3a8-9e22d86c18b9', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '1d183755-02b3-4a6d-b727-082af1ef377c', '9c37478d-2388-1380-cdea-3b62d82c3fcb', '否定与情态表达的交互范围', '分析否定词与「べき」「かもしれない」「はず」等情态表达结合时，否定是作用于命题内容还是情态本身，从而改变句义。', '将「ないかもしれない」误解为「ない」的简单否定，忽略可能性；混淆「べきではない」与「ないべき」的差异。', '日语例句：彼が来ないかもしれないが、準備はしておくべきだ。；说明：否定的是「来る」的可能性，而非「来ない」的事实，需区分。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('8ff09a9c-9984-5c53-bf84-b78d9b90ff06', '9221fc32-a051-42cb-86b1-6a9917aa004e', '42de0c7b-50d9-4159-918a-4e618d83342d', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', 'ef36118d-0ba3-29ce-b2b3-76eaeb6542ca', '～てもいいですか（肯定回答）', '用于请求许可，回答时可用「はい、いいですよ」或「はい、どうぞ」等肯定表达。', '回答时误用「てもいいです」直接重复，或混淆「いいです」与「大丈夫です」。', '日语例句：窓を開けてもいいですか。→ はい、いいですよ。；说明：询问可否开窗，肯定回答。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('90ad5c31-5749-53d5-8935-3fc5473c706a', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', 'baa9b5c2-5b94-4f9b-7ced-3a8c3cde4cb3', 'な形容词修饰名词的用法', '掌握な形容词修饰名词时需加「な」，如「静かな部屋」，并能区分与い形容词修饰的不同。', '漏掉「な」，如说「静か部屋」；误把な形容词当い形容词活用。', '日语例句：元気な子供が遊んでいる。；说明：「元気」是な形容词，修饰名词用「元気な」。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('90ade1f9-11b3-5663-8a65-2e9abd63fe65', '9221fc32-a051-42cb-86b1-6a9917aa004e', '42de0c7b-50d9-4159-918a-4e618d83342d', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '2d7157f8-afb7-58a0-85ea-b3d775f216a2', '接续、原因与逆接', '使用并列、原因、转折和补充说明的接续形式。', '「から」「ので」的语气和「でも」「しかし」的转折功能混淆。', '雨が降ったので、出かけませんでした。', 'published', '2026-09-03 13:10:31.032213+08', '2026-09-03 13:10:31.032213+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('91a47e3b-da02-5226-aa4d-f01fdb51f1e2', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', 'ff057d86-47bc-de16-f0f9-a7b808b968e3', 'N3频率和程度副词的用法（扩展）', '掌握「たいてい」「たまに」「ほとんど」「かなり」「ずいぶん」等副词的频率和程度含义，以及它们与肯定否定句的搭配限制。', '将「ほとんど」与否定呼应时误用为肯定句，如「ほとんど食べた」应理解为“几乎全吃”，而「ほとんど食べなかった」是“几乎没吃”。', '日语例句：たいてい家で晩ご飯を食べます。；说明：「たいてい」表示大部分情况。；日语例句：たまに外食します。；说明：「たまに」频率低。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('91a6ac75-a60f-54c8-96e0-c89949037295', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', 'ff057d86-47bc-de16-f0f9-a7b808b968e3', 'N3使役被动形的构成与含义（扩展）', '掌握N3使役被动形的构成（如「行かされる」「食べさせられる」）及含义，表示被迫做某事，并注意与使役形的区别。', '将使役被动与使役混淆，如「行かされる」是“被迫去”，而「行かせる」是“让去”；忽视五段动词的缩约形「～される」。', '日语例句：子供の頃、ピアノを練習させられた。说明：被迫练习。；日语例句：毎日残業させられる。说明：被迫加班。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('91ce8410-2eef-5485-8063-b2292b4d4a90', '9221fc32-a051-42cb-86b1-6a9917aa004e', '42de0c7b-50d9-4159-918a-4e618d83342d', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '0e03a921-5aff-e4be-f477-4d55640b198b', '常用形容词的汉字读音', '掌握N5高频形容词（如大きい、小さい、新しい、古い、高い、安い等）的汉字表记与读音，注意词干与词尾的区分。', '将「大きい」的「大」读成「だい」而非「おお」；混淆「高い」表示高度和价格时的用法。', 'この本は新しいです。说明：「新しい」读作「あたらしい」。／あの山は高いです。说明：「高い」读作「たかい」。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('91db3ef5-bea2-5d92-b34a-b5752b7a1886', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '1d183755-02b3-4a6d-b727-082af1ef377c', '40ed56d1-acbd-4a8b-6284-2df8b9423e8e', '同义改写与选项识别', '在阅读题中，识别原文句子的同义改写（paraphrase），从选项中选择意思最接近的表述，排除字面相同但含义不同的选项。', '选择与原文用词相同但含义有偏差的选项；忽略改写时可能改变的语气或程度；不区分近义词的细微差别。', '日语例句：原文“彼は疲れているようだ”，选项A“彼は疲れているらしい”，选项B“彼は疲れている”。说明：A保留了推测语气，与原文更接近，B则过于肯定。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('920823e4-9c28-509e-a8c8-fe7774dc9ffb', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', 'ff057d86-47bc-de16-f0f9-a7b808b968e3', 'N3复合动词的构成与意义（扩展四）', '掌握N3中由动词连用形加补助动词构成的复合动词，如「～始める」「～続ける」「～終わる」「～直す」等，理解其表示动作的开始、持续、结束或重新进行。', '学习者常混淆「～始める」和「～出す」的区别，前者强调有意识的开始，后者强调突然发生；「～直す」表示重新做，但不可用于所有动词。', '日语例句：仕事をやり始めた。；说明：「～始める」表示开始做。日语例句：雨が降り出した。；说明：「～出す」表示突然开始。日语例句：レポートを書き直す。；说明：「～直す」表示重新写。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('9226e4ee-0944-5ce7-8f57-265968b22e9f', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', 'dd4e968a-3d37-98a7-3819-a5fc4c117122', '～ようになる（逐渐变得）', '表示“逐渐变得……”，接续：动词辞书形/ない形+ようになる，强调变化过程。', '与～ことになる混淆，～ようになる强调能力或习惯的变化。', '日本語：最近、日本語が話せるようになった。；说明：最近变得会说日语了。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('9268893d-0f21-57c8-9c31-0f9ed3d8d6bc', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '0545d0ec-89d1-a8aa-99f9-78b30fcbacb1', '程度副词中表示“相当”与“略微”的细微差别', 'N2程度副词如「かなり」「ずいぶん」表示程度高，「やや」「いくぶん」表示程度低，需根据语境选择。', '混淆「かなり」与「やや」的程度差异，导致表达不准确。', '例句：今日はかなり暑い。说明：「かなり」表示相当程度。；例句：今日はやや暑い。说明：「やや」表示略微。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('926b0a8c-9f0c-5334-9f24-341ac87acdd1', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '5b34d8b5-bde9-c4c6-c736-84adaaae3603', '「旧」的多种读音与词义', '「旧」在N1中常见读音「きゅう」，词义包括“旧、老”“从前”等。如「旧姓（きゅうせい）」「旧友（きゅうゆう）」「旧式（きゅうしき）」「旧暦（きゅうれき）」「復旧（ふっきゅう）」。', '「旧暦」读「きゅうれき」而非「きゅうこよみ」；「復旧」读「ふっきゅう」而非「ふくきゅう」。', '旧友（きゅうゆう）と再会した。说明：旧友指老朋友。；停電が復旧（ふっきゅう）した。说明：復旧指恢复。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('92cda072-6deb-5c4b-97aa-6e835c3f77dd', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '1d183755-02b3-4a6d-b727-082af1ef377c', 'fc58533f-fd29-5132-8f21-fd381828e3c8', '理解指示词所指', '正确判断「これ」「それ」「あれ」「この」「その」等在文中的具体指代对象，常需回溯前文。', '只根据距离判断，忽略上下文；混淆「それ」指代前句内容与「これ」指代即将说出的内容。', '日语例句：昨日、本を買った。それはとても面白い。说明：「それ」指代前句的「本」。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('92ddce19-5c73-5095-b929-9953868c15af', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '0545d0ec-89d1-a8aa-99f9-78b30fcbacb1', '汉字词中省略音（音便）的读音', '部分汉字词在复合或特定语境中发生音便，如「～やすい」「～にくい」中「易い」「難い」的读音变化，以及「～がたい」等。', '忽略音便规则，将「やすい」读作「よい」等。', '例句：この本は読みやすい。说明：「やすい」接动词连用形，读作「やすい」，表示容易。；例句：彼の態度は理解しがたい。说明：「がたい」表示难以，读作「がたい」。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('92f11bc0-3a69-530e-8391-a6e6394c0e80', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '0545d0ec-89d1-a8aa-99f9-78b30fcbacb1', '表示比较的「～に比べて」「～より」「～ほど～ない」', '掌握「～に比べて」（与…相比，较正式）、「～より」（比…）、「～ほど～ない」（不如…）的用法区别。', '学习者常混淆「～より」与「～ほど～ない」，前者表示比较基准，后者表示否定比较。', '日本語例：去年に比べて今年は暑い。（与去年相比今年热）／彼は私より背が高い。（他比我高）／今年は去年ほど暑くない。（今年不如去年热）。说明：三者比较方向不同。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('930b08f3-0394-5796-b878-ccc476d4a7ca', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '1af448c1-54cf-2f94-01b5-e8bc77a97f94', '～ているところだ（正在进行）', '表示动作正在进行中，强调处于某个阶段。', '与“～ている”相比，更强调“正处于…阶段”，常与“今”连用；注意与“～たところ”区分。', '日本語：今、レポートを書いているところです。；说明：正在写报告。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('93572943-0b7c-51c9-bbed-88cf26c5a2e4', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', 'baa9b5c2-5b94-4f9b-7ced-3a8c3cde4cb3', '近义词的正式与口语语感差异（扩展）', 'N4阶段需区分如「しかし」与「でも」、「とても」与「すごく」等近义词在正式/口语场合的适用性，以及语气强弱。', '在书面语中误用口语词，如用「すごく」代替「非常に」；在口语中过度使用正式接续词显得生硬。', '日语例句：あの店は高いです。しかし、おいしいです。；说明：「しかし」较正式，口语中常用「でも」。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('93cb7623-6611-54a6-8273-313814637bac', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', 'dd4e968a-3d37-98a7-3819-a5fc4c117122', '～まえに（在…之前）', '表示在某个动作或事件发生之前做某事。接续：动词辞书形/名词+の+まえに。', '注意接续：动词用辞书形而非た形；名词需加の。', '日本語：寝るまえに、歯を磨きます。；说明：睡觉前刷牙。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('941e901e-6477-573d-91d4-4d1cda14a3d7', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '2c18e7e1-4ef0-65e3-24a7-6c97d562a122', '～に伴っては', '表示随着前项的发生，后项也发生，但带有对比或强调的语感。多用于正式场合。', '与「～に伴って」相比，「に伴っては」强调伴随关系或对比。', '日本語：経済成長に伴っては、生活水準も向上する。；说明：随着经济增长，生活水平也会提高。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('9455084f-9d45-53e9-99f3-8841261a6ba2', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', 'ff057d86-47bc-de16-f0f9-a7b808b968e3', 'N3近义名词的语境区分（扩展）', '辨析如「意見」与「考え」、「理由」与「わけ」、「方法」与「手段」等名词在正式程度和语境上的差异。', '将「わけ」用于正式书面语，而「理由」更正式。', '日语例句：彼の意見を聞いてください。；说明：「意見」多用于个人主张。；日语例句：どういうわけで遅れたのですか。；说明：「わけ」口语中表示原因。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('94a55517-744e-57c0-bbc5-26854e201967', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '5b34d8b5-bde9-c4c6-c736-84adaaae3603', '「需」的读音与词义', '「需」主要音读「じゅ」，如「需要」「需給」。训读少见。注意与「要」的区别，「需要」表示需求，「必要」表示必要。', '将「需要」误读为「よう」；混淆「需要」与「要求」。', '市場の需要（じゅよう）が高まっている。；说明：需求。／需給（じゅきゅう）のバランスを保つ。；说明：供需。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('94be7157-284a-5582-8372-ab3621d493e7', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '1d183755-02b3-4a6d-b727-082af1ef377c', '9c37478d-2388-1380-cdea-3b62d82c3fcb', '具体与概括的层次转换', '理解文章中从具体事例到一般结论，或从一般原则到具体应用的层次转换，把握论述的推进方式，并能区分论点与论据。', '将具体事例误认为论点，或忽略概括性语句，不能把握文章的整体论述结构。', '日语例句：例えば、ある地域では高齢者の一人暮らしが増えている。このように、都市部では家族形態が変化している。；说明：先举具体例子，再用「このように」概括出一般趋势，需理解层次转换。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('951c03ff-f703-50d7-b045-d1f8dc8f63b6', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', 'baa9b5c2-5b94-4f9b-7ced-3a8c3cde4cb3', 'サ变动词（名词+する）的构成', '掌握N4常见サ变动词如「勉強する」「旅行する」「電話する」等，理解其构成与用法。', '将サ变动词误用为普通名词；混淆「する」与「やる」的语感。', '日语例句：週末に買い物をします。；说明：「買い物する」是サ变动词，注意「を」有时省略，但强调动作对象时可保留。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('95240114-2bac-59b8-8115-022a8d361986', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '3760dfca-44d9-3445-01cd-85de1f860da1', '～にかかわることはない', '表示“没有必要涉及/不必担心”，用于安慰或劝解。', '与“～にかかわらない”混淆，本句型强调“无需”而非“禁止”。', '日本語：そんな細かいことにかかわることはない。；说明：没有必要去管那种琐事。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('953f2fa6-8319-5445-ad2c-60a6b2333676', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '5b34d8b5-bde9-c4c6-c736-84adaaae3603', '「禁」的读音与词义', '「禁」在「禁止」「禁煙」中读「きん」，表示禁止，但「禁じる」读「きんじる」，「手弱女（たおやめ）」等词中不出现。', '将「禁じる」读作「きんじる」或「とめる」，混淆「禁止」与「制限」。', '例句：ここで喫煙は禁止されている。说明：「禁止」读「きんし」，意为禁止。；例句：法律で禁じられている行為だ。说明：「禁じる」读「きんじる」，意为禁止。；例句：禁煙席に座った。说明：「禁煙」读「きんえん」，指禁烟。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('95f3d88c-561d-5729-b594-256f36b10cb6', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '2c18e7e1-4ef0-65e3-24a7-6c97d562a122', '～というなら', '表示“如果说是～的话”，用于承接对方的话并给出自己的看法或条件。接名词或动词普通形。', '与「～なら」混淆，后者更直接；「～というなら」带有“既然你这么说”的语感。', '行くというなら、私も一緒に行くよ。；说明：如果你说要去，我也一起去。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('9640dec3-cadf-5523-b1ba-980b9fb7fd35', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', 'e5877362-1f27-54a5-903f-528a6d53f294', '动词与形容词活用', '练习动词各活用形以及い形容词、な形容词的连接。', '五段动词音变和な形容词接名词的形式容易混淆。', '本を読んで、寝ます。', 'published', '2026-09-03 13:10:31.032213+08', '2026-09-03 13:10:31.032213+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('9668973d-0ca5-5eaa-86b9-c4bcc2d8ffd6', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '2c18e7e1-4ef0-65e3-24a7-6c97d562a122', '～たるもの', '表示“作为……的人”的意思，接续：名词＋たるもの，后项常接义务、责任等。', '注意「たる」是文语「とあり」的缩约，多用于正式场合，如「教師たるもの」。', '日语例句：学生たるもの、勉強を怠るべきではない。；说明：作为学生，不应该懈怠学习。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('9678e845-996e-5649-bb73-872d1c90fd72', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '1d183755-02b3-4a6d-b727-082af1ef377c', '9c37478d-2388-1380-cdea-3b62d82c3fcb', '假设与条件句的逻辑理解', '准确把握文章中假设句（と、ば、たら、なら）所表达的条件关系，区分现实条件、反事实假设、一般条件等，理解假设对结论的支持作用。', '将反事实假设当作现实情况，或混淆充分条件与必要条件，导致逻辑推理错误。', '日语例句：もしあの時彼が来ていれば、結果は違っていただろう。；说明：这是与过去事实相反的假设，表示实际上他没来，结果也不同，需理解反事实含义。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('96ab9d88-0a5f-53ff-9bc4-062934b6322d', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '2c18e7e1-4ef0-65e3-24a7-6c97d562a122', '～につけても～につけても（强调持续）', '表示“无论……都一直……”，强调某种状态或行为不受条件影响而持续。接续：动词て形＋も＋同形＋も＋いる。', '此条为「～につけても～につけても」的变体，但实际使用较少，注意不要与「～につけても」混淆；本条目为补充性知识点。', '日本語：彼は忙しいにつけても暇につけても、いつも本を読んでいる。；说明：无论忙还是闲，他总在读书。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('96e3cb99-89df-5f32-8ba8-2708e31b07fc', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '3760dfca-44d9-3445-01cd-85de1f860da1', '～ように願う', '表示祈愿、希望，相当于“祝愿…”。接动词辞书形。', '与「～ようにする」混淆；误用为意志表达。', '合格するように願っています。说明：祝愿能合格。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('975abd5e-2abd-5aee-bc50-dc94d6784871', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '1d183755-02b3-4a6d-b727-082af1ef377c', '6f1477f5-00be-f963-76b6-5165f568e88e', '写作目的识别', '从整体上判断文章的写作目的，如告知、说服、解释、娱乐、呼吁行动等，通常与文章类型和结尾呼应。', '只关注内容细节，忽略作者为何写这篇文章；或混淆告知与说服。', '日语例句：最後に、読者の皆さんに、ぜひボランティアに参加していただきたい。说明：文章结尾呼吁行动，表明写作目的是说服读者参与。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('97a245cb-408e-5c79-a0f9-5d622f3e7c7b', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '3760dfca-44d9-3445-01cd-85de1f860da1', '～かねる', '表示难以做到某事，由于心理上或能力上的原因而“难以……”。接动词ます形去掉ます。', '误将“かねる”用于客观不可能，而应表示主观上难以接受或难以决定；与“～かねない”混淆。', '日语例句：その質問には答えかねます。；说明：表示难以回答那个问题，常用于委婉拒绝。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('97bbf889-cdde-585a-954c-2bc8bf05e3e4', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '3760dfca-44d9-3445-01cd-85de1f860da1', '～にかかわるな', '表示“不要干涉/不要涉及”，用于禁止他人介入某事物。', '与“～に関わるな”混淆，但本句型语气更强，多用于警告或命令。', '日本語：他人のプライバシーにかかわるな。；说明：不要干涉别人的隐私。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('97f0edc9-fdb8-5e9f-bac1-f8328793201e', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', 'baa9b5c2-5b94-4f9b-7ced-3a8c3cde4cb3', '形容词的汉字读音与表记', '掌握N4常用形容词的汉字读音，包括い形容词和な形容词，注意特殊读音和同音词。', '将「大きい」读作「おおきい」时误写为「大い」；混淆「新しい」与「新た」。', '日语例句：この部屋は広いです。；说明：「広い」读作「ひろい」，表示空间宽广，注意与「広がる」等动词区分。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('980ba9f6-2abc-5b0c-a786-71a9b4f2287c', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '0545d0ec-89d1-a8aa-99f9-78b30fcbacb1', 'サ变动词（～する）的构成与用法', '理解N2中由名词加「する」构成的动词（如「影響する」「失敗する」）的用法，包括自动词他动词性质及与助词的搭配。', '忽视サ变动词的自他性，如「成功する」为自动词，不能说「成功する」带宾语；或混淆「する」与「を」的用法。', '日语例句：彼は試験に失敗した。；说明：「失敗する」为自动词，用「に」表示对象，不能用「を」。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('983204af-36a1-5630-88ae-f6bbbb4cf112', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '0545d0ec-89d1-a8aa-99f9-78b30fcbacb1', '近义动词在正式与口语中的选择（如「申す」与「言う」）', 'N2中部分近义动词存在语体差异，如「申す」「存じる」用于正式场合，「言う」「思う」用于日常。', '在口语中误用正式动词，或在正式场合使用口语动词。', '例句：私はそう申しました。说明：「申す」为「言う」的谦让语，用于正式场合。；例句：彼はそう言った。说明：「言う」为普通口语。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('984f9ac3-d11e-5935-b9ef-ca6532f81106', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', 'dd4e968a-3d37-98a7-3819-a5fc4c117122', '～たら（假定条件・完成条件）', '表示“如果……的话”，接续：动词た形+ら，い形容词かったら，な形/名词だったら。可接意志、命令等。', '与～ば混淆，～たら更口语化，且可用于发现等。', '日本語：時間があったら、映画を見に行きたい。；说明：如果有时间想去看电影。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('986a92f0-0e3f-583e-8c56-d58bc5e8e903', '9221fc32-a051-42cb-86b1-6a9917aa004e', '42de0c7b-50d9-4159-918a-4e618d83342d', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '0e03a921-5aff-e4be-f477-4d55640b198b', '常用量词的读音与搭配', '掌握N5常见量词如人、本、枚、回、時間、歳等的读音及与数字搭配时的音变规则。', '将「三本」读成「さんぼん」而非「さんぼん」；「四枚」的「四」读「よん」而非「し」。', 'りんごを三つ買いました。说明：「三つ」读作「みっつ」。／友達が二人います。说明：「二人」读作「ふたり」。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('98a528bb-3ede-586d-9c7e-c0e51a389619', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '5b34d8b5-bde9-c4c6-c736-84adaaae3603', '「旧」的读音与词义', '「旧」在「旧友」「旧式」中读「きゅう」，表示旧的、以前的，与「新」相对。', '将「旧」与「古」混淆，或误读「旧」为「ふる」。', '例句：彼は旧友と再会した。说明：「旧友」读「きゅうゆう」，指老朋友。；例句：この機械は旧式だ。说明：「旧式」读「きゅうしき」，指旧式。；例句：旧市街には古い建物が多い。说明：「旧」读「きゅう」，表示以前的。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('98d4e229-d570-50c6-8c42-4aec7859fb41', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '1d183755-02b3-4a6d-b727-082af1ef377c', 'fc58533f-fd29-5132-8f21-fd381828e3c8', '提取必要信息', '在通知、广告、说明书等实用文本中，快速找到所需的具体信息（时间、地点、条件、联系方式等），并排除干扰项。', '被无关细节干扰，忽略限定条件（如「土曜日以外」「学生のみ」）；混淆不同条目下的信息。', '日语例句：図書館は月曜日休みです。火曜日から日曜日まで午前9時から午後8時まで開いています。；说明：若问“周二能借书吗”，需提取开馆时间并判断符合条件。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('98fd1825-a0b0-5b15-ab0b-bf53bd197341', '9221fc32-a051-42cb-86b1-6a9917aa004e', '42de0c7b-50d9-4159-918a-4e618d83342d', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '0e03a921-5aff-e4be-f477-4d55640b198b', 'イ形容词的汉字读音', 'N5常见イ形容词（如「大きい」「小さい」「新しい」「古い」「高い」「安い」）的汉字读音及词尾变化。', '将「大きい」读成「おおきい」时漏掉长音，或「高い」在表示“贵”和“高”时读音相同但需注意语境。', '日本語例：この本は高いです。说明：「高い」读作「たかい」，可表示价格贵或高度高。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('990cc5bd-4ef4-529b-86a1-73618f8f622e', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '2c18e7e1-4ef0-65e3-24a7-6c97d562a122', '～をめぐって', '表示“围绕……，就……”，后接争论、讨论等。接续：名词+をめぐって。', '与「～について」混淆，但「をめぐって」更强调围绕中心问题的对立或讨论。', '日本語：環境問題をめぐって、活発な議論が行われた。；说明：围绕环境问题，进行了热烈的讨论。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('99129f5d-0ae9-5f5d-843d-6630c93fd80b', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '3760dfca-44d9-3445-01cd-85de1f860da1', '～ようにいうことになる', '表示“结果变成…”，用于客观结果。接动词辞书形/ない形。', '与「～ことになる」混淆；误用为主观决定。', '結局、彼が行くようにいうことになった。说明：结果变成由他去。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('9928eed5-1fb3-55ec-b0ff-18fdfcfdda75', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '2c18e7e1-4ef0-65e3-24a7-6c97d562a122', '～ずじまい', '表示“最终没有做”的意思，带有遗憾的语气。接续：动词ない形去掉ない＋ずじまい。', '与「～ないでしまった」相似，但「ずじまい」更书面化，且强调结果。', '日语例句：聞きたいことは聞かずじまいだった。；说明：想问的事最终没问。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('994b638f-96cc-5f5f-a30e-7655454105e4', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', 'ff057d86-47bc-de16-f0f9-a7b808b968e3', 'N3基础拟声拟态词（扩展三）', '掌握N3中表示状态和样子的拟态词，如「はっきり」「すっきり」「ぐっすり」「そろそろ」「うっかり」等，并注意其副词用法和搭配动词。', '「うっかり」与「つい」混淆，「うっかり」强调无意中，「つい」强调忍不住；「そろそろ」表示“差不多该”，不是“慢慢”。', '例句：うっかり財布を忘れた。说明：「うっかり」表示不留神；例句：そろそろ帰ろう。说明：「そろそろ」表示时间接近，该做某事了。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('99657da2-b946-5d07-840d-29976654d0ef', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '0545d0ec-89d1-a8aa-99f9-78b30fcbacb1', '汉字复合词中音读与训读的混读规则（湯桶読み・重箱読み）', 'N2需掌握复合词中前音后训（重箱読み）与前训后音（湯桶読み）的常见词，如「重箱（じゅうばこ）」「湯桶（ゆとう）」。这些混读词需积累，不能按规则类推。', '学习者常将「重箱」误读为「じゅうばこ」正确，但将「台所（だいどころ）」误读为「だいしょ」；或混淆「手本（てほん）」与「見本（みほん）」。', '日语例句：台所で料理を作る。；说明：「台所」为前音「だい」后训「ところ」，读「だいどころ」。日语例句：この手本に従って練習する。；说明：「手本」为前训「て」后音「ほん」，读「てほん」。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('9985eb66-8d9b-581a-811b-e10c435f8600', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', 'dd4e968a-3d37-98a7-3819-a5fc4c117122', '～ことができる（能够）', '表示“能够做……”，接续：动词辞书形+ことができる。', '与可能动词混淆，但语法上可互换，注意～ことができる更正式。', '日本語：泳ぐことができます。；说明：会游泳。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('99949c5d-729f-5797-bd79-35707a2a4ec4', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '1d183755-02b3-4a6d-b727-082af1ef377c', '9c37478d-2388-1380-cdea-3b62d82c3fcb', '操作性定义的把握', '理解作者在文章中为特定概念或术语给出的操作性定义（即如何测量或识别该概念），并据此判断后续论述中该术语的具体所指，避免用常识定义替代。', '用日常含义理解专业术语，忽略作者给出的特定定义，导致对论述内容的理解偏差。', '日语例句：ここでは「ストレス」を、心身に負担がかかったときに生じる反応と定義する。；说明：作者明确给出了操作性定义，后续论述中的「ストレス」都应以此定义为准。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('9a05ad89-2483-5d3e-a4e8-1904cbad5985', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '5b34d8b5-bde9-c4c6-c736-84adaaae3603', '「作」的读音与词义', '「作」在「作品」「操作」中读「さく」，表示作品、做，但「作る」读「つくる」，「作業」读「さぎょう」。', '将「作る」读作「さくる」，或混淆「作品」与「制作」。', '例句：彼の作品は評価が高い。说明：「作品」读「さくひん」，指作品。；例句：この機械を操作してください。说明：「操作」读「そうさ」，指操作。；例句：彼女は料理を作る。说明：「作る」读「つくる」，意为制作。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('9a26fb87-c666-5954-8b8b-5df6c102f8d6', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', 'baa9b5c2-5b94-4f9b-7ced-3a8c3cde4cb3', '形容词て形连接', '掌握い形容词和な形容词的て形构成，用于并列多个性质或原因。', '将い形容词て形误用为「～くて」与「～で」混淆；忘记な形容词て形用「で」。', '日语例句：この部屋は明るくて広いです。；说明：「明るい」的て形是「明るくて」，表示并列或原因，注意な形容词如「静かで」。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('9a4f19f7-decc-5370-b65d-c0ee7ea67717', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '5b34d8b5-bde9-c4c6-c736-84adaaae3603', '「ただ今」与「今」的语境区分', '「ただ今」作为寒暄语表示“我回来了”，也可表示“现在、马上”；「今」单纯指时间。', '在正式场合误用「今」代替「ただ今」表示“马上”；混淆寒暄语。', '日语例句：ただ今、参ります。；说明：服务用语“马上就来”。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('9a88bb6e-79fd-5d50-a84f-e1df24b732ac', '9221fc32-a051-42cb-86b1-6a9917aa004e', '42de0c7b-50d9-4159-918a-4e618d83342d', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', 'ef36118d-0ba3-29ce-b2b3-76eaeb6542ca', '～てある（结果状态/有意为之）', '他动词て形+ある表示动作完成后留下的状态，强调人为造成的结果。主语用「が」提示对象物。与「ている」的区别：てある强调人为，ている可表自然状态。', '误用自动词+てある（应用他动词）；与「ている」混淆；助词误用「を」代替「が」。', '窓が開けてあります。；说明：窗户被（某人）开着。／壁に絵が掛けてあります。；说明：墙上挂着画（人为挂的）。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('9aea447d-8ee8-59a8-8d71-1c1cd6c1c6de', '9221fc32-a051-42cb-86b1-6a9917aa004e', '42de0c7b-50d9-4159-918a-4e618d83342d', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '0e03a921-5aff-e4be-f477-4d55640b198b', '日常生活物品的汉字读音', 'N5常见生活物品名词如「机」「椅子」「窓」「鍵」「傘」「靴」「服」的汉字读音。', '将「傘」读成「かさ」以外的音，或「靴」读成「くつ」但「靴下」读「くつした」。', '日本語例：窓を開けてください。说明：「窓」读作「まど」。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('9aee3353-0690-56f6-b6ba-0b4ff09a6c25', '9221fc32-a051-42cb-86b1-6a9917aa004e', '42de0c7b-50d9-4159-918a-4e618d83342d', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '0e03a921-5aff-e4be-f477-4d55640b198b', '楼层数词「階」', '掌握量词「階（かい/がい）」表示楼层，注意音变：1階（いっかい）、3階（さんがい）、6階（ろっかい）、8階（はっかい）、10階（じゅっかい），以及「何階（なんがい）」。', '将1階读作「いちかい」、3階读作「さんかい」；将「何階」读作「なんかい」。', '日本語：デパートは五階にあります。；说明：五階读作「ごかい」。日本語：エレベーターで三階へ行きます。；说明：三階读作「さんがい」。日本語：家は何階ですか。；说明：何階读作「なんがい」。)', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('9af49d8a-c5e8-5bda-a8e5-12db2809d33b', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', 'dd4e968a-3d37-98a7-3819-a5fc4c117122', '～ていく／～てくる（方向性・心理）', '表示动作的方向性（远离/靠近说话人）以及时间上的变化（从现在到将来/从过去到现在）。', '混淆方向与时间用法；在表示心理变化时误用方向性。', '日本語：だんだん慣れていくでしょう。说明：表示从现在到将来的逐渐变化。
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('9b20e0f8-5668-5271-bda0-3c7a2caf082d', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '1d183755-02b3-4a6d-b727-082af1ef377c', '9c37478d-2388-1380-cdea-3b62d82c3fcb', '多层引用与嵌套观点的剥离', '在文章中识别直接引用、间接引用、以及作者对引用内容的评价，区分谁的观点在哪个层面，尤其当引用中包含他人转述时。', '混淆引用者与被引用者的观点；忽略作者在引用后加上的评论可能改变原意。', '日语例句：彼女は「彼が『無理だ』と言った」と述べた。；说明：存在两层引用，需区分说话人（彼女）和原话者（彼）。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('9b3bdabb-932d-5123-82df-ce98ddc1976d', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '1d183755-02b3-4a6d-b727-082af1ef377c', '9c37478d-2388-1380-cdea-3b62d82c3fcb', '否定范围的限定', '识别否定表达（ない、ず、ぬ等）所否定的具体成分，区分否定整个命题还是仅否定部分（如否定修饰语、否定宾语等）。注意「必ずしも…ない」「決して…ない」等部分否定与全否定的区别。', '将部分否定误读为全盘否定，或忽略否定词前的限定语，导致对句意理解偏差。', '日语例句：彼の意見は必ずしも正しいとは限らない。；说明：「必ずしも…ない」表示并非完全正确，而非完全不正确，需准确理解否定的范围。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('9bcf9ab6-a3fb-569e-9212-d7ce6c51fe90', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '1d183755-02b3-4a6d-b727-082af1ef377c', '40ed56d1-acbd-4a8b-6284-2df8b9423e8e', '短文主旨把握', '能够快速阅读150字左右的说明文或随笔，准确概括作者最想传达的核心内容，区分主旨与细节。', '误将举例或背景信息当作主旨；忽略转折词后的内容。', '日语例句：最近、電車の中で本を読む人が減った。しかし、スマホで小説を読む人は増えている。読書の形は変わっても、物語を楽しむ気持ちは変わらない。说明：主旨是“读书形式变化但本质未变”，而非单纯说人数增减。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('9bd57908-a93c-562c-9d9c-aff9597034c8', '9221fc32-a051-42cb-86b1-6a9917aa004e', '42de0c7b-50d9-4159-918a-4e618d83342d', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', 'ef36118d-0ba3-29ce-b2b3-76eaeb6542ca', '动词ます形（礼貌体）', '动词的礼貌体，由动词连用形（ます形）构成。五段动词、一段动词、サ变、カ变各有变化规则。用于现在/未来肯定，否定为「ません」。', '五段动词的ます形变化错误（如将「行く」变为「行きます」时误将「く」变「き」）；一段动词误按五段变化；サ变动词误用「します」为「するます」。', '毎日七時に起きます。；说明：每天七点起床。／明日は働きません。；说明：明天不工作。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('9c1aff46-63d3-58fe-9734-7486a5c039dc', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '3760dfca-44d9-3445-01cd-85de1f860da1', '～ても', '表示让步，相当于“即使…也…”。', '注意「～ても」与「～てもいい」的区别，后者是许可。', '雨が降っても、試合は行われます。；说明：即使下雨，比赛也会举行。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('9c1e337d-ab2c-57ba-95ec-9165cad31076', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '1d183755-02b3-4a6d-b727-082af1ef377c', '9c37478d-2388-1380-cdea-3b62d82c3fcb', '反问句在论证中的立场转换', '识别反问句并非寻求答案，而是用来加强作者观点或转换论述方向，常伴随语气的强烈和隐含的否定或肯定。', '将反问句误读为疑问句，从而误解作者的真实态度；忽略反问句后常跟有结论或转折。', '日语例句：こんな状況で、本当に改革が必要だと言えるだろうか。；说明：反问暗示作者认为改革并非必要，立场与字面相反。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('9c29d05c-9fcc-565c-93f8-e8cf8c5e4ac1', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '3760dfca-44d9-3445-01cd-85de1f860da1', '～に関わらず', '表示不受前项影响，后项照常进行。接续：名词/动词辞书形＋に関わらず。', '与「にかかわらず」同义，但注意接续，名词直接接，动词用辞书形。', '天気に関わらず、試合は行われる。；说明：不管天气如何，比赛都会进行。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('9c38db78-908a-513a-b534-f303feef79fe', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '1af448c1-54cf-2f94-01b5-e8bc77a97f94', '～てもいいですかね（许可・犹豫）', '在～てもいいですか后加“ね”表示犹豫或征求同意，口语中常用。接续：动词て形+もいいですかね。', '与～てもいいですか混淆，后者更直接。注意～てもいいですかね常用于自言自语或不确定的请求。', '日本語：これ、借りてもいいですかね。；说明：犹豫地询问“这个可以借吗？”', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('9cd49eb6-e50d-58a4-a88f-f50baae2a458', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', 'baa9b5c2-5b94-4f9b-7ced-3a8c3cde4cb3', '动词た形表示经历与先后顺序', '掌握动词た形用于表示过去经历（～たことがある）以及动作先后完成（～た後で）的用法，区分与て形顺序表达的不同。', '混淆「～たことがある」与「～た」的单纯过去；误用「～た後で」与「～てから」的细微差别。', '日本に行ったことがあります。说明：表示曾经有过经历。／ご飯を食べた後で、散歩します。说明：表示动作完成之后进行下一个动作。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('9cfd9a81-f5b1-5433-82e0-0f5114194180', '9221fc32-a051-42cb-86b1-6a9917aa004e', '42de0c7b-50d9-4159-918a-4e618d83342d', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', 'f5aa6f4e-16ea-57eb-96bb-fb12daa45f39', '词义与近义辨析', '根据句子语境选择词义准确的基础词汇。', '只按中文直译选词，忽略搭配和上下文。', '駅の前で友だちに会いました。', 'published', '2026-09-03 13:10:31.032213+08', '2026-09-03 13:10:31.032213+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('9cfe207e-b800-5d1d-89ac-fd667c7f7652', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', 'dd4e968a-3d37-98a7-3819-a5fc4c117122', '～ばいい（…就好）', '表示建议或期望，意为“做…就好了”。接续：动词ば形+いい。', '与～たらいい类似，但～ばいい更直接；注意疑问形式～ばいいですか。', '日本語：わからないことがあれば、先生に聞けばいいです。；说明：有不懂的问老师就好。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('9d7be8f8-d226-513b-892c-a06248db8342', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '5b34d8b5-bde9-c4c6-c736-84adaaae3603', '「虚」的读音与词义', '「虚」读「きょ」「うつ」等，N1中「虚偽（きょぎ）」「虚ろ（うつろ）」等需区分；表示空虚、不实。', '将「虚ろ」误读为「きょろ」；混淆「虚偽」与「偽り」的语体。', '彼の話は虚偽だ。（虚假）说明：「虚偽」读「きょぎ」，正式用语。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('9d87d6f4-473f-586f-b5cc-1c84088898c3', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '1af448c1-54cf-2f94-01b5-e8bc77a97f94', '～てはならない（禁止・规范）', '表示强烈的禁止，多用于规则、法律、道德等正式场合，比～てはいけない更书面化。接续：动词て形＋は＋ならない。', '在口语中滥用显得生硬；误将～てはならない与～てはいけない完全互换，忽略语体差异。', '日本語：この情報を外部に漏らしてはならない。；说明：正式规定不得泄露信息。
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('9dcddd82-413c-5e94-a44f-0026de7be78b', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', 'ff057d86-47bc-de16-f0f9-a7b808b968e3', '条件表达相关词汇（如「場合」「なら」「と」）', '掌握N3中表示条件的词汇和接续词，如「場合」「なら」「と」「ば」等，区分其使用条件和语感。', '将「と」用于主观意志句；混淆「なら」和「ば」的假定条件。', '日语例句：雨の場合、試合は中止です。行くなら、早めに言ってください。；说明：場合用于客观情况，なら用于假定。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('9df3c346-b065-58e6-98dd-748d99e03d37', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '1d183755-02b3-4a6d-b727-082af1ef377c', 'fc58533f-fd29-5132-8f21-fd381828e3c8', '把握段落主旨', '通过段落首句或尾句等关键位置，概括一段话的中心意思，排除次要细节。', '将例子或细节当作主旨；忽视转折词后的重点。', '日语例句：多くの人は朝に運動する。しかし、夜の運動も効果がある。说明：段落主旨是夜运动也有效，转折后为重点。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('9e097764-b9b1-5dfa-a5a8-f995bc52234e', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '3760dfca-44d9-3445-01cd-85de1f860da1', '～に連れて', '表示随着前项的变化，后项也相应地变化。接续：动词辞书形/名词＋に連れて。', '常与「～に伴って」「～とともに」混淆，但「に連れて」更强调自然、渐进的变化过程，且多用于口语。', '日本語を勉強するに連れて、日本文化に興味を持つようになった。；说明：随着学习日语，逐渐对日本文化产生了兴趣。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('9e3289b5-04d8-53ea-8d4b-a50034444753', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', 'ff057d86-47bc-de16-f0f9-a7b808b968e3', 'N3同源词族的派生关系（扩展三）', '掌握N3中同源词族如「集める/集まる/集合」「開く/開ける/開会」「続く/続ける/連続」等，理解动词、名词、形容词之间的派生关系和用法差异。', '混淆自动词与他动词，如「集まる」自动词，「集める」他动词；「開く」自动词（门开）与「開ける」他动词（打开门）。', '例句：人が駅に集まる。说明：「集まる」自动词，人聚集；例句：彼は切手を集める。说明：「集める」他动词，收集；例句：会議を開く。说明：「開く」此处为他动词用法（举行），但「ドアが開く」为自动词。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('9e65aa94-9261-5b97-9e9a-c2663dc324a3', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', 'baa9b5c2-5b94-4f9b-7ced-3a8c3cde4cb3', '动词ない形表示否定请求与委婉命令', '「～ないでください」表示“请不要做”，「～ないで」可表示“不要…而…”或请求，需掌握接续和语气。', '将「ないでください」与「なくて」混淆，或漏掉「ください」导致语气不当。', 'ここで写真を撮らないでください（请不要在这里拍照）；说明：否定请求的礼貌形式。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('9e7cdde7-fe6b-5b67-8bb0-4ad67fb8641b', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', 'dd4e968a-3d37-98a7-3819-a5fc4c117122', '～しかない（只有…）', '表示“只有…”，常与否定呼应，也可表示“只好”。接续：动词辞书形+しかない；名词+しか+ない。', '注意与～だけ的区别，～しかない带有负面或无奈语气；动词时用辞书形+しかない。', '日本語：お金がないから、歩いて行くしかない。；说明：没钱所以只能走着去。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('9ebd8bed-ab8c-5997-9084-96fbea20891d', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '3760dfca-44d9-3445-01cd-85de1f860da1', '～ようにいうために', '表示“为了…”，目的表达。接动词辞书形/ない形。', '与「～ために」混淆；误用为原因。', '早く着くようにいうために、タクシーに乗った。说明：为了能早点到，坐了出租车。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('9f18d7a1-a9d7-53c2-8475-2e05f6ff0a30', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '5b34d8b5-bde9-c4c6-c736-84adaaae3603', '「突然」与「急に」的语感差异', '「突然」强调事件发生毫无预兆，客观；「急に」强调变化速度快，可含主观感受。', '在描述天气变化时误用「突然」；「急に」不能用于完全无预兆的意外。', '日语例句：急に雨が降り出した。；说明：表示“突然下起雨”，强调变化快。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('9f7c53a5-ae26-586d-b348-e289ad5f3105', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '0545d0ec-89d1-a8aa-99f9-78b30fcbacb1', '常见当て字（借字）的读音与意义', 'N2需掌握一些常见当て字，如「真面目（まじめ）」「大丈夫（だいじょうぶ）」「沢山（たくさん）」等，这些词汉字与读音无直接对应。', '按汉字音读或训读硬读；混淆「真面目」与「真剣」的意义。', '日语例句：彼は真面目に働く。；说明：「真面目」读作「まじめ」，意为认真、踏实。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('9fca4ea4-a7a3-56e7-aaf7-64ec0ff62e48', '9221fc32-a051-42cb-86b1-6a9917aa004e', '42de0c7b-50d9-4159-918a-4e618d83342d', '1d183755-02b3-4a6d-b727-082af1ef377c', '37a506cf-ef62-8ccc-3210-ab64e8561a4d', '根据上下文推断省略主语', '在对话或短文中，能够根据前后文和敬语/普通体推断省略的主语是谁。', '将省略的主语误认为说话者或听话者，忽略语境线索。', '例句：A：昨日どこへ行きましたか。B：スーパーへ行きました。说明：B的回答省略主语，推断为B自己去了超市。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('9fd8dde7-84ef-5ec3-be39-3a7ff2e7a514', '9221fc32-a051-42cb-86b1-6a9917aa004e', '42de0c7b-50d9-4159-918a-4e618d83342d', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', 'ef36118d-0ba3-29ce-b2b3-76eaeb6542ca', 'なら（条件/话题）', '名词/动词辞书形+なら表示假设或承接话题，后件常为建议。接续：名词+なら、动词辞书形+なら。', '与たら混淆；名词后不加だ。', '日本へ行くなら、飛行機が便利です。说明：如果去日本，飞机方便。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('a025ceff-cbb7-56f1-9a2f-59523aa9a5a3', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '1af448c1-54cf-2f94-01b5-e8bc77a97f94', '～たばかり（刚刚完成・时间近）', '表示动作完成后经过的时间很短。接续：动词た形＋ばかり。与「～たところ」相比，更强调“时间上刚过去不久”，不用于发现等用法。', '「～たばかり」不能用于表示动作刚结束的瞬间，而「～たところ」可以。另外「～たばかり」常与「まだ」搭配。', '日本語例：この本は先週読んだばかりです。；说明：这本书上周刚读过。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('a034ed98-ccc0-5c5d-a207-74ed301f40dd', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', 'baa9b5c2-5b94-4f9b-7ced-3a8c3cde4cb3', '程度副词的强调与减弱用法', '「とても」「かなり」「ちょっと」「あまり」等程度副词修饰形容词或动词，表达程度高低，需注意与否定呼应。', '将「あまり」用于肯定句，或混淆「とても」与「かなり」的语感差异。', 'この本はとても面白い（这本书很有趣）；あまり食べない（不太吃）；说明：「あまり」与否定呼应。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('a05bd1a5-5c95-5b53-9edc-ad06c9268119', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', 'ff057d86-47bc-de16-f0f9-a7b808b968e3', 'N3自他动词成对辨析（扩展二）', '掌握N3中更多自他动词对，如「壊れる/壊す」「落ちる/落とす」「消える/消す」「割れる/割る」等，理解其使用主体、助词搭配及自动词表状态、他动词表动作的规律。', '混淆自动词与他动词的助词使用，如将「ドアが開く」误用为「ドアを開く」；在表达自然现象时误用他动词。', '日语例句：窓が割れた。／だれが窓を割ったの。；说明：自动词「割れる」描述结果状态，他动词「割る」强调人为动作。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('a0a0fe8a-12e2-5ba1-822c-15238d05c34d', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '5b34d8b5-bde9-c4c6-c736-84adaaae3603', '「つい」的用法', '掌握「つい」表示“不知不觉、无意中”或“只不过”。', '与「うっかり」混淆，但「つい」强调习惯性。', '日本語：つい食べ過ぎた。；说明：不知不觉吃多了。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('a0be54d3-2c3d-5f75-9a66-19168ce2772d', '9221fc32-a051-42cb-86b1-6a9917aa004e', '42de0c7b-50d9-4159-918a-4e618d83342d', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '0e03a921-5aff-e4be-f477-4d55640b198b', '数量表达中的礼貌与精确', '掌握在询问或表达数量时使用「いくつ」「何～」等疑问词，以及使用「～つ」「～人」等量词时的礼貌程度。', '用「いくつ」询问人数；用「何本」询问书本数量。', 'りんごはいくつありますか。说明：「いくつ」用于询问个数。／クラスに学生が何人いますか。说明：「何人」用于询问人数。／鉛筆を何本持っていますか。说明：「何本」用于询问细长物。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('a18ad797-3573-558d-83f4-1f6299b69d06', '9221fc32-a051-42cb-86b1-6a9917aa004e', '42de0c7b-50d9-4159-918a-4e618d83342d', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '0e03a921-5aff-e4be-f477-4d55640b198b', '家庭成员名词的汉字读音（非称谓）', 'N5中表示家庭成员的普通名词如「父」「母」「兄」「姉」「弟」「妹」的汉字读音，注意与称呼用语的区分。', '将「父」读成「ちち」以外的音（如「おとうさん」是称呼），或「姉」读成「あね」但「お姉さん」读「おねえさん」。', '日本語例：父は会社員です。说明：「父」读作「ちち」，用于向他人介绍自己的父亲。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('a19c7a22-3339-579d-8c3b-0c905820a269', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '1d183755-02b3-4a6d-b727-082af1ef377c', '9c37478d-2388-1380-cdea-3b62d82c3fcb', '时间顺序与过程把握', '在叙述性文本或说明文中，理清事件发生的时间顺序、步骤或流程，理解先后关系。', '打乱顺序；忽略时间副词（如「まず」「その後」）；将同时发生误认为先后。', '日语例句：まず材料を準備し、その後、下ごしらえをして、最後に煮込む。说明：通过「まず」「その後」「最後に」明确流程。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('a1c95601-b342-5ed3-b13e-8482c37b0bed', '9221fc32-a051-42cb-86b1-6a9917aa004e', '42de0c7b-50d9-4159-918a-4e618d83342d', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', 'ef36118d-0ba3-29ce-b2b3-76eaeb6542ca', 'なくてはいけない（必须）', '表示必须，相当于なければならない。接动词ない形去い加くてはいけない。', '与てはいけない混淆；接续错误。', '宿題をしなくてはいけません。；说明：必须做作业。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('a1e102ae-7762-575a-a829-97cdab19a2f8', '9221fc32-a051-42cb-86b1-6a9917aa004e', '42de0c7b-50d9-4159-918a-4e618d83342d', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', 'ef36118d-0ba3-29ce-b2b3-76eaeb6542ca', 'てもいいですか（请求许可）', '用于礼貌地请求许可，比「てもいい？」更正式。接续：动词て形+も+いいですか。', '回答时肯定用「いいですよ」，否定用「だめです」或「いけません」；注意与「てもかまいませんか」的区别。', 'ここでタバコを吸ってもいいですか。说明：询问“可以在这里吸烟吗”。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('a220d8c9-6b23-54ab-880b-07068847e910', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '1af448c1-54cf-2f94-01b5-e8bc77a97f94', '～てから見ると／～てから見れば', '表示站在某个角度或基于某种立场来看待事物，相当于“从……来看”。多用于评价、判断或提出看法。', '容易与“～から見ると”混淆，但“～てから見ると”强调先经历某个动作或状态后再进行观察，而“～から見ると”更直接表示“从……的角度看”。', '日本語を勉強してから見ると、日本のアニメの内容がもっとよく分かるようになった。；说明：表示学了日语之后再来看动漫，理解更深了。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('a267cf86-bbc4-5e26-a702-5dbc192aaf8a', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '1d183755-02b3-4a6d-b727-082af1ef377c', 'fc58533f-fd29-5132-8f21-fd381828e3c8', '理解条件句含义', '掌握「〜と」「〜ば」「〜たら」「〜なら」在阅读中的条件关系，区分一般条件与假定条件。', '混淆「〜と」的恒常条件与「〜たら」的特定条件；忽视「なら」用于承接话题。', '日语例句：春になると、桜が咲きます。说明：「と」表示自然规律，恒常条件。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('a2ce05e8-86a8-567b-a45b-83b01c2b92d6', '9221fc32-a051-42cb-86b1-6a9917aa004e', '42de0c7b-50d9-4159-918a-4e618d83342d', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '0e03a921-5aff-e4be-f477-4d55640b198b', '薄平物品的量词「枚」', '掌握量词「枚（まい）」用于数纸张、照片、衬衫、盘子等薄平物品，读音基本为「いちまい、にまい、さんまい」等，无特殊变化。', '用「個」或「本」数纸张；将「三枚」读作「さんまい」时误加浊音。', '日本語：紙を五枚ください。；说明：五枚读作「ごまい」。日本語：写真を一枚見せてください。；说明：一枚读作「いちまい」。日本語：シャツを三枚買いました。；说明：三枚读作「さんまい」。)', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('a2f1064c-8ca2-51cf-a06c-31be21803da1', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', 'baa9b5c2-5b94-4f9b-7ced-3a8c3cde4cb3', '常用汉字的音读与训读选择', '针对N4常见汉字（如：会、同、新、高、安等）在不同单词中的读音选择，区分音读（おんよみ）和训读（くんよみ）。', '混淆音读和训读，例如把「新しい」读成「しんしい」而不是「あたらしい」；或把「会社」读成「あうしゃ」。', '日语例句：新しい会社に入りました。；说明：「新しい」中「新」读训读「あたら」，而「会社」中「会」读音读「かい」。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('a2f3c6f9-d6e1-5c05-b23f-f565b8ce0c56', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '2c18e7e1-4ef0-65e3-24a7-6c97d562a122', '～をに置いて', '表示“把～放在～”，用于比较或评价。接名词。', '与「～において」混淆，后者表示场所或时间；此句型强调“置于”。', '品質を第一に置いて、開発を進める。；说明：把品质放在第一位推进开发。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('a354bf34-1a7d-5f4f-b4a5-0f34c6382005', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '2c18e7e1-4ef0-65e3-24a7-6c97d562a122', '～を通じて', '表示“通过……，在整个期间/范围内”，可表示手段或范围。接续：名词+を通じて。', '与「～を通して」意思相近，但「を通じて」更强调媒介或整个期间，而「を通して」强调过程。', '日本語：インターネットを通じて、世界中の情報が得られる。；说明：通过互联网，可以获得世界各地的信息。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('a361d4ad-d01d-5219-8efc-44c372926dd0', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '5b34d8b5-bde9-c4c6-c736-84adaaae3603', '「議」「義」「技」等「ぎ」同音汉字的读音与词义区分', '「ぎ」读音的汉字包括「議（ぎ）」「義（ぎ）」「技（ぎ）」「疑（ぎ）」「儀（ぎ）」等。本知识点帮助学习者区分这些汉字在词语中的具体含义。', '易将「会議」误写为「会義」，或将「技術」与「義術」混淆；需注意「議」表示讨论，「義」表示道义，「技」表示技能。', E'日语例句：会議（かいぎ）に出席する。；说明：「議」读「ぎ」，表示会议。\\n日语例句：技術（ぎじゅつ）を磨く。；说明：「技」读「ぎ」，表示技术。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('a3689726-7f8f-5870-ba0a-babce534ef12', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '1d183755-02b3-4a6d-b727-082af1ef377c', '40ed56d1-acbd-4a8b-6284-2df8b9423e8e', '言外之意与弦外之音', '能根据语境和日本人常用的委婉表达，理解字面背后的真实意图，如拒绝、建议、不满等。', '按字面理解导致误解；忽略敬语和语气词的作用。', '日语例句：A：明日のパーティー、来られる？ B：ちょっと、その日は…。说明：B的省略表达暗示可能无法参加，并非在思考。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('a39789ea-d0d0-5ea1-a4fb-d623b8450895', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '0545d0ec-89d1-a8aa-99f9-78b30fcbacb1', '汉字复合词中与外来语混用的读音', 'N2需掌握部分复合词中汉字与外来语（片假名）结合时的读音，如「和食（わしょく）」「洋食（ようしょく）」虽为汉字，但「テーブル」等外来语常与汉字词搭配。本知识点聚焦汉字复合词中夹带外来语读音的特殊情况，如「生ビール（なまビール）」「消しゴム（けしゴム）」。', '学习者常将「生ビール」误读为「せいビール」，或忽略「ゴム」等外来语部分。', '日语例句：生ビールを注文する。；说明：「生」训读「なま」，后接外来语「ビール」，构成混合词。日语例句：消しゴムで消す。；说明：「消し」训读「けし」，「ゴム」为外来语，整体读「けしゴム」。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('a4036140-b3ac-564d-aeba-fdbf9f49d2f5', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '0545d0ec-89d1-a8aa-99f9-78b30fcbacb1', '表示逆接的「～にもかかわらず」「～のに」「～ながら」', '掌握「～にもかかわらず」（尽管…却…，正式）、「～のに」（明明…却…，口语）、「～ながら」（虽然…但…，接动词ます形或状态动词）的接续和语感区别。', '学习者常混淆「～のに」与「～ながら」的接续，「～ながら」前接动词ます形或名词，如「残念ながら」，而「～のに」前接句子的普通形。', '日本語例：彼は病気にもかかわらず出勤した。（尽管生病还是上班）／雨が降っているのに出かけた。（明明下雨却出门）／知っていながら教えなかった。（虽然知道却没教）。说明：三者的正式度和接续不同。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('a43137fe-34a7-5329-937c-4919176e94c6', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', 'baa9b5c2-5b94-4f9b-7ced-3a8c3cde4cb3', '量词的种类与用法', '掌握N4常用量词如「人」「本」「枚」「匹」等，理解其与不同名词的搭配规则。', '误用量词，如将书本用「枚」；混淆「匹」与「頭」的使用对象。', '日语例句：りんごを三つ買いました。；说明：「つ」是通用量词，用于无特定量词的物品，注意与「個」的区别。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('a436346f-ef8d-566d-95ed-cbd5d040e6e6', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '5b34d8b5-bde9-c4c6-c736-84adaaae3603', '「顧客」与「客」的语体区分', '「顧客」是商业正式用语，指顾客、客户；「客」是普通名词，泛指客人。N1需在商务场合使用「顧客」。', '在商务文书误用「客」；混淆「顧客」与「お客様」的语感。', '顧客満足度を高める。（提高顾客满意度）说明：「顧客」正式。／家に客が来た。（家里来了客人）说明：「客」日常。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('a44e7253-c807-5acd-a810-bac8313871dc', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '0545d0ec-89d1-a8aa-99f9-78b30fcbacb1', '「～てしまう」的完成与遗憾、后悔用法', 'N2需掌握「～てしまう」表示动作的彻底完成，以及由此产生的遗憾、后悔、不可挽回等语感。例如「本を読んでしまった」「約束を忘れてしまった」。', '只理解“完成”而忽略“遗憾”语气；在口语中误用为郑重表达；与「～ておく」混淆。', '日本語：大事な書類をなくしてしまった。；说明：表达后悔、遗憾。／日本語：この本はもう読んでしまった。；说明：表示动作已完成。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('a4a32e63-33d8-5bd9-b84b-c1a70f2d80d7', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '5b34d8b5-bde9-c4c6-c736-84adaaae3603', '「感」「観」「関」等「かん」同音汉字的读音与词义区分', '「かん」读音的汉字如「感（かん）」「観（かん）」「関（かん）」「間（かん）」「管（かん）」等。本知识点训练学习者根据词语区分这些汉字。', '易将「感情」误写为「観情」，或将「関係」与「感係」混淆；需注意「感」表示感觉，「観」表示观看或观点，「関」表示关联。', E'日语例句：感情（かんじょう）を抑える。；说明：「感」读「かん」，表示感情。\\n日语例句：関係（かんけい）が深い。；说明：「関」读「かん」，表示关系。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('a4a5f0d1-1792-56d1-8610-cf04bdb08fad', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '2c18e7e1-4ef0-65e3-24a7-6c97d562a122', '～ざるを得ない', '表示不得不做某事，由于客观原因或义务。接续：动词ない形（去掉ない）＋ざるを得ない。', '注意「する」变为「せざるを得ない」，且后项多表示无奈或被迫。', '上司の命令だから、従わざるを得ない。；说明：因为是上司的命令，不得不服从。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('a4c42923-3cac-51ea-bd86-723e06dbefa3', '9221fc32-a051-42cb-86b1-6a9917aa004e', '42de0c7b-50d9-4159-918a-4e618d83342d', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', 'ef36118d-0ba3-29ce-b2b3-76eaeb6542ca', 'ています（进行/状态）', '表示动作正在进行或状态持续。接动词て形后加います。', '与た形混淆；非持续动词误用为进行。', '今、本を読んでいます。；说明：正在读书。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('a4f1c37e-9245-5312-89d1-23b1ff2d0a42', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '0545d0ec-89d1-a8aa-99f9-78b30fcbacb1', '汉字复合词的意义推测（如「心強い」「手軽」）', 'N2中许多汉字复合词的意义可从字面推测，但需注意引申。例如「心強い」表示心里有底，「手軽」表示简便。本知识点训练推测策略。', '完全按字面理解，如将「心強い」理解为“心强”。', '日语例句：彼がいてくれて心強い。；说明：「心強い」由“心”和“强”构成，但实际表示“有依靠而安心”，不能直译。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('a5951abc-f5c4-58c3-8404-ac055b10e65e', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '5b34d8b5-bde9-c4c6-c736-84adaaae3603', '「参」的多种读音与词义', '「参」在N1中常见读音「さん」，词义包括“参加”“参考”“参拜”等。如「参加（さんか）」「参考（さんこう）」「参拝（さんぱい）」「参入（さんにゅう）」「参戦（さんせん）」。', '「参拝」读「さんぱい」而非「さんはい」；「参入」读「さんにゅう」而非「さんいり」。', '会議に参加（さんか）する。说明：参加指参加。；神社に参拝（さんぱい）する。说明：参拝指参拜。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('a5a4503d-5ca2-563d-8dfd-d75f2997f10f', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '2c18e7e1-4ef0-65e3-24a7-6c97d562a122', '～にかけての', '表示在…方面、关于…，后接名词。是～にかけて的连体修饰形式，强调在某领域或某方面的能力、经验。', '与～に関しての区分；～にかけての多用于能力、技术、经验方面，～に関しての更广泛。', '彼は英語にかけての知識が豊富だ。；说明：他在英语方面的知识很丰富。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('a5d67f06-aac3-5313-add8-1f73ac7ec159', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '5b34d8b5-bde9-c4c6-c736-84adaaae3603', '「既に」与「もう」的用法区分', '「既に」多用于书面语，表示“已经”，强调事实完成；「もう」口语常用，也可表示“再、另外”。', '「既に」不能用于“もう一度”的“再”义；「もう」在否定句中可表示“已经（不）”。', '日语例句：会議は既に始まっている。；说明：书面语“会议已经开始”。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('a5d811c7-5313-5d7b-afdd-341efcf7361f', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '2c18e7e1-4ef0-65e3-24a7-6c97d562a122', '～つつも', '表示“虽然……但是”的意思，接续：动词ます形去掉ます＋つつも。', '与「～ながらも」相似，但「つつも」更书面化，且后项常为逆接。', '日语例句：悪いと知りつつも、嘘をついてしまった。；说明：虽然知道不好，还是说了谎。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('a5e65d8d-1249-514a-a17b-2650a05bc2cc', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '1d183755-02b3-4a6d-b727-082af1ef377c', '9c37478d-2388-1380-cdea-3b62d82c3fcb', '否定表达的范围与程度', '准确把握否定词（「ない」「ぬ」「ず」）的否定范围，以及部分否定、双重否定、委婉否定等复杂表达。', '扩大或缩小否定范围；忽略「必ずしも～ない」「決して～ない」等部分否定；未识别双重否定表肯定。', '日语例句：必ずしも全員が賛成しているわけではない。说明：「必ずしも～わけではない」表示部分否定，并非所有人赞成。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('a628d18d-818f-59be-bdf0-bb92e9d67e71', '9221fc32-a051-42cb-86b1-6a9917aa004e', '42de0c7b-50d9-4159-918a-4e618d83342d', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', 'ef36118d-0ba3-29ce-b2b3-76eaeb6542ca', 'たり～たりする（列举）', '动词た形+り、た形+りする表示列举代表性动作或状态。接续：た形+り。', '只用一个たり；忘记最后加する。', '日曜日は掃除したり洗濯したりします。说明：周日做打扫和洗衣服等。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('a64ec7af-4253-59f1-9df9-900c35ec59ab', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', 'ff057d86-47bc-de16-f0f9-a7b808b968e3', 'N3汉字复合词读音规律（扩展）', '进一步掌握N3级别中常见汉字复合词的特殊读音，如「時々（ときどき）」「一日（いちにち/ついたち）」「大人（おとな）」等，理解音读与训读在复合词中的变化规则。', '混淆同形异音词，如将「一日」在所有语境中都读作「いちにち」，而不知在日期中读「ついたち」；忽视连浊现象，如「時々」读「ときどき」而非「ときとき」。', '日语例句：今日は一日（いちにち）忙しかった。说明：表示整天时读作「いちにち」；而「一日（ついたち）」指每月1号。；日语例句：時々（ときどき）映画を見ます。说明：注意「時々」的浊化读音。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('a6535ba6-3f6c-5ee8-92c0-6f21b9a9e8e8', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '5b34d8b5-bde9-c4c6-c736-84adaaae3603', '「絶対に」的肯定强调用法', '「絶対に」可用于肯定句，表示“绝对、一定”，强调说话人的强烈确信或要求。', '与「決して」混淆，后者只能接否定；「絶対に」接否定时语气更强。', '日语例句：絶対に成功してみせる。；说明：表示“一定要成功”，表达决心。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('a6f99da0-5d5f-528e-a6a5-c34c3d68966e', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '5b34d8b5-bde9-c4c6-c736-84adaaae3603', '「社」的读音与词义', '「社」在「会社」「社会」中读「しゃ」，表示公司、社会，但「社」在「社」字中读「やしろ」表示神社。', '将「神社」的「社」读作「しゃ」，混淆「会社」与「社」的用法。', '例句：彼は大きな会社に勤めている。说明：「会社」读「かいしゃ」，指公司。；例句：社会のルールを守る。说明：「社会」读「しゃかい」，指社会。；例句：地元の神社に参拝する。说明：「神社」读「じんじゃ」，但「社」单独指神社时读「やしろ」，如「社殿」读「しゃでん」。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('a700dbcb-c63a-5a22-a7c6-133dcec0dd02', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', 'dd4e968a-3d37-98a7-3819-a5fc4c117122', '～なければならない（必须）', '表示“必须做……”，接续：动词ない形+なければならない。口语中可简化为「～なきゃ」。', '与～てはいけない混淆，前者义务，后者禁止。', '日本語：毎日薬を飲まなければならない。；说明：必须每天吃药。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('a702831f-9a71-5594-a545-6a41199ba01e', '9221fc32-a051-42cb-86b1-6a9917aa004e', '42de0c7b-50d9-4159-918a-4e618d83342d', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '0e03a921-5aff-e4be-f477-4d55640b198b', '动词て形相关词族', '掌握动词て形与补助动词构成的表达，如「～ている」「～てください」「～てもいい」等，理解其功能。', '将「～ている」用于瞬间动词；将「～てください」用于请求上级。', '本を読んでいます。说明：「～ている」表示正在进行。／ここに座ってください。说明：「～てください」表示请求。／窓を開けてもいいですか。说明：「～てもいい」表示许可。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('a710519c-33d3-5705-a8bc-e678785a5e9b', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '2c18e7e1-4ef0-65e3-24a7-6c97d562a122', '～にかかわりなく', '表示“与……无关，不受……影响”，强调某事不因前项而改变。接续：名词/动词辞书形+にかかわりなく。', '与「～にかかわらず」混淆，两者意思相近，但「にかかわりなく」更正式，且常与「性別・年齢・有無」等搭配。', '日本語：性別にかかわりなく、誰でも応募できる。；说明：不论性别，谁都可以报名。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('a761d1f8-f936-5d2e-b127-e9cc1868610c', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '0545d0ec-89d1-a8aa-99f9-78b30fcbacb1', 'サ变动词的名词化与「～中」「～後」等接尾', 'N2サ变动词常与「～中」「～後」「～前」等接尾组合，如「研究中」「終了後」。本知识点掌握这些组合的读音和意义。', '将「研究中」误读为「けんきゅうちゅう」但忽略其表示“正在研究”的用法；混淆「後」的读音「ご」与「あと」。', '日语例句：ただいま研究中です。；说明：「研究中」表示正在研究，读けんきゅうちゅう，不能读作けんきゅうなか。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('a7640215-e98d-5244-b66f-48b5a858bbf3', '9221fc32-a051-42cb-86b1-6a9917aa004e', '42de0c7b-50d9-4159-918a-4e618d83342d', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '0e03a921-5aff-e4be-f477-4d55640b198b', '年龄与年数的量词「歳」「年」', '掌握年龄用「歳（さい）」，注意1歳（いっさい）、8歳（はっさい）、10歳（じゅっさい）、20歳（はたち）；年数用「年（ねん）」，如一年（いちねん）、二年（にねん）。', '将1歳读作「いちさい」、8歳读作「はちさい」；将20歳读作「にじゅっさい」而非「はたち」；将「一年」读作「いっねん」。', '日本語：娘は八歳です。；说明：八歳读作「はっさい」。日本語：私は二十歳です。；说明：二十歳读作「はたち」。日本語：日本に三年住んでいます。；说明：三年读作「さんねん」。)', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('a7a4a65a-783b-5d14-8ae2-0c32746274c7', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '2c18e7e1-4ef0-65e3-24a7-6c97d562a122', '～にかかわる', '表示与某事物有重大关系、涉及、影响到。接续：名词+にかかわる。', '与「～にかかわりなく」（不管…）混淆，后者表示不受影响。', 'これは会社の存亡にかかわる重大な問題だ。说明：强调关系重大。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('a7b3f503-544a-58da-8f36-ad9ceb607969', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '5b34d8b5-bde9-c4c6-c736-84adaaae3603', '「補う」与「埋め合わせる」的用法区分', '「補う」读「おぎなう」，表示补充、弥补不足；「埋め合わせる」读「うめあわせる」，表示补偿损失或时间。', '混淆两者；「欠点を埋め合わせる」不自然，应用「補う」；「損失を補う」也可但「埋め合わせる」更具体。', '不足を補（おぎな）う。；说明：弥补。／遅れた時間を埋め合（うめあ）わせる。；说明：补偿。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('a7b5b79c-2052-5d26-801c-c35097b75315', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', 'ff057d86-47bc-de16-f0f9-a7b808b968e3', '相对时间表达（如「さっき」「この間」「先ほど」）', '掌握N3中表示过去、现在、未来相对时间的词汇，如「さっき」「この間」「先ほど」「今度」等，注意正式度差异。', '将「さっき」用于正式场合；混淆「この間」和「最近」的时间范围。', '日语例句：さっき電話がありました。先ほどメールを送りました。；说明：さっき口语，先ほど正式。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('a85eadb3-f279-59e9-88ed-66996e6bc7c7', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '1d183755-02b3-4a6d-b727-082af1ef377c', '9c37478d-2388-1380-cdea-3b62d82c3fcb', '论据的弱点与反驳', '识别文章中论据可能存在的弱点（如以偏概全、证据不足、逻辑跳跃等），理解作者如何通过指出弱点来反驳他人观点，或读者如何批判性评估论证。', '盲目接受所有论据，缺乏批判性思维，不能识别论证中的逻辑漏洞。', '日语例句：彼は成功したから、彼の意見は正しいというわけではない。成功には偶然も影響するからだ。；说明：指出以成功为论据的弱点，说明成功不能完全证明意见的正确性。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('a85f0959-cde4-507a-8a5a-f1d5d312ae78', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '5b34d8b5-bde9-c4c6-c736-84adaaae3603', '「鼓動」与「動悸」的用法区分', '「鼓動」指心脏跳动，也比喻内心的激动；「動悸」特指心悸、心跳异常。N1需区分医学与一般用法。', '将「動悸」用于一般心跳；混淆「鼓動」与「脈拍」的语义。', '彼の鼓動が聞こえる。（能听到他的心跳）说明：「鼓動」一般。／動悸がして眠れない。（心悸睡不着）说明：「動悸」医学。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('a8a071f4-6f55-5950-9b3a-735487cf0997', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '2c18e7e1-4ef0-65e3-24a7-6c97d562a122', '～につき', '表示原因、理由，多用于正式场合或书面语，相当于「～ので」「～ために」。接续：名词+につき。', '口语中较少使用，容易与「～について」（关于）混淆。', '台風の接近につき、本日の営業を中止いたします。说明：正式通知中表示原因。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('a8c3bef2-f086-5eaf-8f5c-1ef1b8629c85', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '1d183755-02b3-4a6d-b727-082af1ef377c', 'fc58533f-fd29-5132-8f21-fd381828e3c8', '理解举例说明的作用', '识别「例えば」「〜のような」「〜など」等举例表达，理解例子对主旨的支撑作用。', '将例子当作主旨；忽视例子与观点的关联。', '日语例句：日本には美しい場所が多い。例えば、京都や北海道だ。说明：例子具体说明“美しい場所”。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('a90bba4a-2a9a-5185-b2b4-45d249c3dbf0', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '3760dfca-44d9-3445-01cd-85de1f860da1', '～ものだ', '表示感叹、回忆或理所当然，相当于“真是……”“往往……”。接动词或形容词普通形。', '误用于具体事实；注意与“～ことだ”区别，后者表示建议或感叹。', '日语例句：子供の頃はよく川で泳いだものだ。；说明：小时候常常在河里游泳（回忆）。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('a94d5f8f-411e-5c67-9bbf-a4bffc90a172', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '2c18e7e1-4ef0-65e3-24a7-6c97d562a122', '～とすれば', '表示“如果假设～的话”，用于提出假设并展开讨论。接动词普通形、名词+だ。', '与「～としたら」混淆，两者可互换，但「～とすれば」更书面、逻辑性强。', '彼が来ないとすれば、会議は延期しよう。；说明：如果他不来，会议就延期吧。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('a95aaa48-e109-549c-8918-c2e3a5e219ca', '9221fc32-a051-42cb-86b1-6a9917aa004e', '42de0c7b-50d9-4159-918a-4e618d83342d', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', 'ef36118d-0ba3-29ce-b2b3-76eaeb6542ca', 'た形（过去/完成）', '动词た形表示过去或完成，也可用于定语修饰。接续：动词ます形去ます变た（如書きます→書いた）。', '与て形混淆；否定过去用なかった。', '昨日映画を見た。说明：昨天看了电影；もう食べた人は手を挙げてください。说明：已经吃完的人举手。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('a973e720-f4c0-5164-bea2-ef8b62b94bc6', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '1af448c1-54cf-2f94-01b5-e8bc77a97f94', '～てからでないと／～てからでなければ（不…就不能）', '表示“如果不先做前项，就不能做后项”。后项多为否定或消极内容。接续：动词て形＋からでないと／からでなければ。', '与「～てから」单纯表示先后顺序不同，本句型强调条件限制，后项常为「できない」「だめだ」等。', '日本語例：資料を確認してからでないと、返事できません。；说明：不先确认资料就无法答复。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('a98397d0-88e8-53f3-b78c-3317db029c1e', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '1af448c1-54cf-2f94-01b5-e8bc77a97f94', '～てもする（强调动作）', '表示“特意做某事”或“强调动作的程度”，常与“わざわざ”等副词连用，用于强调主语主动进行某动作。接续：动词て形＋も＋する。', '容易与“～てみる”混淆，但“～てもする”不表示尝试，而是强调动作本身；注意“も”不能省略，且多用于口语或书面强调。', '日本語：わざわざ遠くから来てもしたのに、会えなくて残念だ。；说明：强调“特意来”的动作。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('a9847bbc-f84d-50b5-9d29-627a53d39c49', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '1d183755-02b3-4a6d-b727-082af1ef377c', 'fc58533f-fd29-5132-8f21-fd381828e3c8', '推断作者写作意图', '在阅读短文或书信中，根据整体内容和语气推断作者写这篇文章的目的（如告知、劝诱、感谢、道歉、请求等）。', '只根据个别句子判断，忽略全文语气和结尾常用表达；把作者意图与文中人物意图混淆。', '日语例句：この手紙は、友達にパーティーの日取りを知らせるために書いたものです。；说明：通过开头和结尾的「お知らせ」「ぜひ来てください」等判断意图。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('a9e3326c-f7c0-59b5-be25-a66f40e40f40', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '1d183755-02b3-4a6d-b727-082af1ef377c', 'fc58533f-fd29-5132-8f21-fd381828e3c8', '理解顺序标记词', '掌握表示事件先后顺序的标记词（如「まず、次に、それから、最後に」）在阅读中的作用，能够按顺序理清步骤或流程。', '容易忽略标记词之间的层级关系，或将表示并列的「そして」误认为顺序标记。', '例句：まず材料を切ります。次に、鍋で炒めます。それから、水を加えて煮ます。説明：通过「まず、次に、それから」明确操作步骤的顺序。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('aa65c8ed-5e8c-5393-b378-2246f40f9988', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '0545d0ec-89d1-a8aa-99f9-78b30fcbacb1', '汉字复合词中送假名对读音与词义的影响（如「話し合う」与「話合い」）', '在N2级别，汉字复合词中送假名的有无或位置变化会影响读音（音读/训读）和词义。例如「話し合う」（はなしあう）是训读动词，而「話合い」（はなしあい）作为名词时送假名省略，但读音仍为训读；「行き違い」（いきちがい）与「行違い」（ゆきちがい）因送假名不同导致读音和语义差异。掌握送假名规则有助于正确读写和辨析近义词。', '学习者常忽略送假名对读音的提示作用，将「話し合う」误读为「わごう」或混淆「行き違い」与「行違い」的读音；也容易在书写时随意省略送假名，导致词义不清。', '日语例句：彼らは意見を話し合った。（かれらは いけんを はなしあった。）说明：「話し合う」为训读复合动词，送假名「し」不可省略，否则读音改变。日语例句：行き違いがあって、会えなかった。（いきちがいが あって、あえなかった。）说明：「行き違い」表示“差错、分歧”，送假名「き」保留，读音为训读；若写「行違い」则可能读作「ゆきちがい」，指“来往交错”。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('aaff09b8-5e0a-52c6-a2b6-bf8c56bd165c', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '0545d0ec-89d1-a8aa-99f9-78b30fcbacb1', '程度副词中表示“非常”与“稍微”的细微差别', 'N2程度副词如「かなり」「ずいぶん」「やや」「少々」等，在程度高低和语体上有差异。例如「かなり」比「やや」程度高，「少々」偏正式。本知识点辨析这些副词的用法。', '混淆「かなり」与「やや」的程度；在口语中误用「少々」显得生硬。', '日语例句：この問題はかなり難しいが、やや簡単な方法もある。；说明：「かなり」表示相当程度，「やや」表示稍微，两者程度不同。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('ab0a46ab-6df1-54b0-913a-9a62dbfc70f1', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', 'dd4e968a-3d37-98a7-3819-a5fc4c117122', '～ていく／～てくる（时态・变化）', '表示动作的持续方向或时间上的变化。～ていく表示从现在到将来的持续或消失，～てくる表示从过去到现在的持续或出现。', '容易与方向性用法混淆，需注意时间轴上的区别。', '日本語：だんだん寒くなっていく。；说明：表示今后会逐渐变冷。日本語：最近、日本語が上手になってきた。；说明：表示从过去到现在逐渐变好。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('ab569d23-8419-5260-8645-8f15cf9959c7', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '1d183755-02b3-4a6d-b727-082af1ef377c', 'c71e2d09-187b-5f11-9aec-0911b2e39818', '短文信息检索与主旨', '从通知、对话和短文中定位事实信息并理解主旨。', '只匹配单个词语，忽略时间、对象和否定等关键信息。', '案内を読んで、開館時間を確認します。', 'published', '2026-09-03 13:10:31.032213+08', '2026-09-03 13:10:31.032213+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('ab6f1ebd-4b8b-5969-8634-c40c97231e31', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '5b34d8b5-bde9-c4c6-c736-84adaaae3603', '「師」的读音与词义', '「師」在「教師」「医師」中读「し」，表示老师、专家，但「師走」读「しわす」，指十二月。', '将「師走」读作「しそう」，或混淆「教師」与「先生」。', '例句：彼は高校の教師だ。说明：「教師」读「きょうし」，指教师。；例句：医師の診断を受ける。说明：「医師」读「いし」，指医生。；例句：師走は何かと忙しい。说明：「師走」读「しわす」，指农历十二月。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('aba093cb-468f-50f4-b600-2ee368bb93dc', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '2c18e7e1-4ef0-65e3-24a7-6c97d562a122', '～が早いか', '表示前项刚发生，后项紧接着发生，强调动作的迅速。接续：动词辞书形＋が早いか。', '后项多为瞬间动作，且主语可以不同，注意与「～や否や」的区别，后者更书面。', 'ベルが鳴るが早いか、学生たちは教室を飛び出した。；说明：铃声一响，学生们就冲出了教室。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('abb5f205-d0c1-5bae-a5ec-e7e276a12340', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '0545d0ec-89d1-a8aa-99f9-78b30fcbacb1', '复合动词「～ていく」「～てくる」的方向与时间用法', 'N2阶段需掌握「～ていく」「～てくる」在空间上表示远离/接近说话者，在时间上表示从现在到将来/从过去到现在的变化过程。例如「歩いていく」「持ってくる」「だんだん寒くなっていく」「頑張ってきた」。', '混淆方向与时间用法；将「～てくる」误用于将来持续；忽略与动词的搭配限制。', '日本語：人口は減っていくでしょう。；说明：表示从现在向将来的持续变化。／日本語：長い間日本語を勉強してきました。；说明：表示从过去到现在的经历积累。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('ac41b51b-5562-5236-b640-b591a6571fc1', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '5b34d8b5-bde9-c4c6-c736-84adaaae3603', '「所」的多种读音与词义', '「所」在N1中常见读音「しょ」「ところ」，词义包括“场所”“部分”“……之处”等。如「所々（しょしょ）」「所有（しょゆう）」「所見（しょけん）」「所得（しょとく）」「台所（だいどころ）」。', '「台所」读「だいどころ」而非「だいしょ」；「所々」读「しょしょ」而非「ところどころ」（后者也可但N1常考前者）。', '所々（しょしょ）に雪が残っている。说明：所々指各处、到处。；彼の所見（しょけん）を聞く。说明：所見指见解、看法。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('acd0a0f7-d7dd-541f-869f-b8aac512c3cf', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '0545d0ec-89d1-a8aa-99f9-78b30fcbacb1', '量词用于抽象事物（如「件」「点」「回」）', 'N2量词不仅用于具体事物，也用于抽象事件，如「件」用于事件、「点」用于要点、「回」用于次数。本知识点训练抽象搭配。', '将「件」误用于所有抽象名词，如「問題が三件ある」可能不自然，需根据内容选择。', '日语例句：質問が三点あります。；说明：「点」用于问题、要点，比「件」更合适。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('ad218011-d80f-5cc2-95ca-7704d7a0c5df', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '2c18e7e1-4ef0-65e3-24a7-6c97d562a122', '～そばから', '表示刚做完前项，后项就立刻发生，多用于反复或不如意的情况。接续：动词辞书形・た形＋そばから。', '后项多为消极或无奈的结果，且强调反复发生，注意与「が早いか」的区别。', '掃除するそばから、子供が散らかす。；说明：刚打扫完，孩子就弄乱。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('ad3497ad-9f97-511f-bfcc-7720528596a1', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '3760dfca-44d9-3445-01cd-85de1f860da1', '～てある（可能）', '表示动作结果的存续，有时也用于表达可能的状态。', '与「～ている」的区别在于「～てある」强调人为的结果，且动词为他动词。', '窓が開けてある。；说明：窗户开着（有人开的）。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('ad7303a2-a426-56df-ba03-c80793526b92', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', 'dd4e968a-3d37-98a7-3819-a5fc4c117122', '～てはだめです（禁止・口语）', '表示“不可以……”，多用于口语，比～てはいけない更随意，常用于家长对孩子等。', '误用为“不行”但接续错误；注意て形后接はだめ，は发wa。', '日本語：ゲームをしてはだめですよ。；说明：不可以玩游戏哦。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('ad7bde0c-91c7-5c55-818f-1d6e7d6f2b94', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '0545d0ec-89d1-a8aa-99f9-78b30fcbacb1', '汉字复合词中音训混合的常见词族', 'N2需掌握由音读和训读混合构成的常用复合词，如「見本（みほん）」「台所（だいどころ）」「手本（てほん）」。这些词需分类记忆，理解其构成规律。', '学习者常将「見本」误读为「けんぼん」，或将「手本」误读为「しゅほん」。', '日语例句：商品の見本を見せる。；说明：「見本」为前训「み」后音「ほん」，读「みほん」。日语例句：書道の手本を習う。；说明：「手本」为前训「て」后音「ほん」，读「てほん」。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('adcb5658-8fde-5e3e-917e-93d4f1f82263', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '1af448c1-54cf-2f94-01b5-e8bc77a97f94', '～てみる（尝试）', '表示试着做某事，看看结果。接续：动词て形＋みる。', '不要与～てみるか（反问）混淆；～てみる强调尝试，不能用于已经完成的事。', '日本語：この料理を食べてみてください。；说明：请试着吃一下这道菜。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('ae01ed7c-7252-5fb8-a39d-d758129465fd', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '1d183755-02b3-4a6d-b727-082af1ef377c', '9c37478d-2388-1380-cdea-3b62d82c3fcb', '引用与作者观点的区分', '在文章中区分作者直接表述的观点和引用他人（学者、专家、大众）的观点，避免混淆。', '将引用内容误认为作者主张；忽略引用标志（如「～と述べている」「～という考え方」）；未注意作者对引用观点的评价。', '日语例句：ある専門家は「この政策は失敗する」と警告している。しかし、筆者はそれに懐疑的だ。说明：引用是专家的观点，作者通过「しかし」表达不同态度。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('ae926229-eb55-52a7-ba77-ed617b09efc9', '9221fc32-a051-42cb-86b1-6a9917aa004e', '42de0c7b-50d9-4159-918a-4e618d83342d', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '0e03a921-5aff-e4be-f477-4d55640b198b', '家庭称谓的汉字读音', '掌握父、母、兄、姉、弟、妹等家庭成员的读音，注意称呼他人和自己家人时的不同用法。', '将「お父さん」的「父」读成「ちち」而非「とう」；混淆「姉」和「妹」的读音。', '私の父は会社員です。说明：「父」读作「ちち」，用于称呼自己的父亲。／お母さんは料理が上手です。说明：「お母さん」读作「おかあさん」，用于称呼对方的母亲。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('aeaa7f90-2277-5602-b6c9-301fbe823c53', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', 'dd4e968a-3d37-98a7-3819-a5fc4c117122', '～てから（先后顺序）', '表示一个动作完成后再进行另一个动作，强调先后顺序。接续：动词て形+から。', '与～たあとで混淆，～てから更强调紧接着进行；不能用于自然发生的事件。', '日本語：毎朝、顔を洗ってから朝ごはんを食べます。；说明：先洗脸后吃早饭，强调顺序。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('aeeddbd4-719e-524a-9b23-2f6d89142af9', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '0545d0ec-89d1-a8aa-99f9-78b30fcbacb1', '常用汉字词中易错音读与训读', 'N2中部分常用汉字词读音特殊，如「気配（けはい）」「芝居（しばい）」「時雨（しぐれ）」等，需整体记忆。', '按汉字常见音读或训读推测，导致误读。', '例句：彼女の気配を感じた。说明：「気配」读作「けはい」，意为迹象、气息。；例句：この芝居は面白い。说明：「芝居」读作「しばい」，意为戏剧。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('af437822-8958-5cb6-bf08-06574b63629c', '9221fc32-a051-42cb-86b1-6a9917aa004e', '42de0c7b-50d9-4159-918a-4e618d83342d', '1d183755-02b3-4a6d-b727-082af1ef377c', '37a506cf-ef62-8ccc-3210-ab64e8561a4d', '日常生活描述的理解', '能够理解描述日常习惯（起床、吃饭、上班等）的短文，把握时间顺序和频率。', '忽略频率副词（いつも、ときどき）导致误解习惯性。', '例句：毎朝七時に起きます。说明：理解每天早上七点起床的习惯。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('af65acc6-6378-5ea4-bb97-e1cebec7c559', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', 'baa9b5c2-5b94-4f9b-7ced-3a8c3cde4cb3', '常用复合动词的构成与意义（扩展）', 'N4阶段常见复合动词如「～始める」「～続ける」「～終わる」「～出す」等，表示动作的开始、持续、结束或突发。需掌握其接续和语义。', '将「～始める」与「～出す」混用，前者强调开始，后者强调突然发生；忽略复合动词的自他性。', '日语例句：雨が降り出しました。；说明：「降り出す」表示突然开始下雨，强调突发性。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('afaca415-ee17-50be-98c5-b6b794dba13b', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '3760dfca-44d9-3445-01cd-85de1f860da1', '～に応じて', '表示“根据…、按照…”，后项根据前项变化。接续：名词+に応じて/に応じた。', '与「～に従って」的区别：前者强调“根据要求/情况”，后者强调“随着…而…”。', '能力に応じて給料が決まる。；说明：工资根据能力决定。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('b002d96d-bcaf-596f-b3af-8389cccc52de', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '0545d0ec-89d1-a8aa-99f9-78b30fcbacb1', '礼貌语（丁寧語）动词的固定形式（如「ございます」「いたします」）', 'N2礼貌语包括「ございます」（ある的礼貌形）、「いたします」（する的谦让礼貌形）等，用于正式场合。本知识点掌握这些固定形式。', '将「ございます」用于动词「ある」以外的场合；将「いたします」误用于对方动作。', '日语例句：こちらに資料がございます。；说明：「ございます」是「あります」的礼貌语，用于正式场合。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('b0180f60-9c97-5fb6-92b4-7477ce0a14a3', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '3760dfca-44d9-3445-01cd-85de1f860da1', '～に違いない', '表示说话人非常有把握的推测，“一定是…”。接续：动词/形容词普通形+に違いない，名词/な形容词+である+に違いない。', '与「～に相違ない」同义，但「に相違ない」更正式；与「～に決まっている」相比，后者更主观。', 'あの雲の様子からすると、明日は雨に違いない。；说明：从云的样子来看，明天一定会下雨。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('b05bd1d7-cdff-54ae-bf4b-de62c94a6e6f', '9221fc32-a051-42cb-86b1-6a9917aa004e', '42de0c7b-50d9-4159-918a-4e618d83342d', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '2d7157f8-afb7-58a0-85ea-b3d775f216a2', '时态、进行与状态', '区分过去、现在、进行、结果状态和先后关系。', '把动作进行「ている」与结果状态或单纯现在时混用。', '今、雨が降っています。', 'published', '2026-09-03 13:10:31.032213+08', '2026-09-03 13:10:31.032213+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('b074b937-0252-5aab-8d17-1eaa340c2261', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '3760dfca-44d9-3445-01cd-85de1f860da1', '～をめぐって', '表示“围绕…”，后项多为争论、讨论等。接续：名词+をめぐって/をめぐる。', '注意「をめぐって」后接动词，「をめぐる」后接名词，如「をめぐる問題」。', '環境問題をめぐって議論が行われた。；说明：围绕环境问题进行了讨论。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('b07fc1d9-56dc-5473-816e-837c9542cc2a', '9221fc32-a051-42cb-86b1-6a9917aa004e', '42de0c7b-50d9-4159-918a-4e618d83342d', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', 'ef36118d-0ba3-29ce-b2b3-76eaeb6542ca', 'ない形（否定）', '动词ない形表示否定，也可用于请求（ないでください）。接续：五段动词词尾变あ段+ない等。', '五段动词音变错误（如書かない而非書あない）；ないで与なくて混淆。', 'ここでタバコを吸わないでください。说明：请不要在这里吸烟。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('b0a5115d-33a5-5e40-a4c3-6b4dc92e6120', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', 'baa9b5c2-5b94-4f9b-7ced-3a8c3cde4cb3', '片假名外来语的理解与使用', '掌握N4常见外来语（如パソコン、レストラン、コーヒー）的片假名表记、词义及使用场景。', '混淆外来语与和语同义词，如「ホテル」与「旅館」；拼写错误。', '日语例句：毎朝コーヒーを飲みます。；说明：「コーヒー」是外来语，来自英语coffee，注意长音符号「ー」。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('b0e34ddb-ddbd-5459-b6fd-d708e90c20a9', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '5b34d8b5-bde9-c4c6-c736-84adaaae3603', '「決して」的否定呼应', '「決して」必须与否定表达（ない、ません、ぬ等）呼应，表示强烈的否定意志或断言，意为“绝不、绝对不”。', '误用为肯定句；与「必ずしも」混淆（后者表示部分否定）。', '日语例句：決して諦めません。；说明：表示“绝不放弃”，强调意志。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('b0fd75ce-3303-5b03-90e2-267fe0fb3f9f', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '3760dfca-44d9-3445-01cd-85de1f860da1', '～について', '表示关于、就……而言。接续：名词＋について。', '与「に関して」相似，但「について」更口语化，使用更广泛。', '日本の文化について調べています。；说明：正在调查日本文化。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('b10f6447-6127-50ec-b99b-ba5dab6d85fc', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '1af448c1-54cf-2f94-01b5-e8bc77a97f94', '～ているか（进行・状态・确认）', '以疑问形式确认动作是否正在进行或状态是否持续。接续：动词て形+いるか。多用于口语。', '与～ている（进行・状态）混淆，该形式带确认。注意～ているか也可用于询问经历。', '日本語：今、何をしているか。；说明：询问“现在在做什么？”', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('b110ad9b-5988-560c-81a4-111b4328e861', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', 'baa9b5c2-5b94-4f9b-7ced-3a8c3cde4cb3', '常用反义词组的对应关系', '掌握如「大きい/小さい」「高い/低い」「長い/短い」「新しい/古い」等基础反义词，并能根据语境正确使用。', '混淆「高い」的反义词（低い/安い），或「厚い/薄い」与「太い/細い」的适用对象。', '日语例句：この道は広いが、あの道は狭い。；说明：「広い」反义「狭い」，用于空间。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('b118506f-d3fa-559f-9381-3c8dbe7b56ab', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '5b34d8b5-bde9-c4c6-c736-84adaaae3603', '「拠」的读音与词义', '「拠」读「きょ」「こ」，表示依据、据点。N1中「根拠（こんきょ）」「拠点（きょてん）」等需注意。', '将「根拠」误读为「こんこ」；混淆「拠る」与「基づく」的用法。', 'その説には根拠がない。（没有根据）说明：「根拠」指依据。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('b134d264-7545-532c-b63a-e7e64e2761ab', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '1af448c1-54cf-2f94-01b5-e8bc77a97f94', '～てくる（出现・开始）', '表示动作从过去到现在持续，或某种状态开始出现。如：～てきた。接续：动词て形＋くる。', '与～ていく相对，～てくる表示向说话人方向或现在；注意与～てきた（过去持续）的用法。', '日本語：最近、日本語が上手になってきました。；说明：表示最近日语逐渐变好。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('b1532504-1f71-5df0-9236-cf5d0ece958b', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', 'baa9b5c2-5b94-4f9b-7ced-3a8c3cde4cb3', '汉字音读与训读的区分与选择', '掌握N4常见汉字在单词中的音读（おんよみ）与训读（くんよみ）规则，能根据词性、复合词等判断正确读音。', '混淆音读和训读，如把「山道」读成「さんどう」而正确为「やまみち」；不熟悉个别汉字的多音读。', '日语例句：山道を歩く。；说明：「山」在「山道」中读训读「やま」，而「富士山」中读音读「さん」。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('b163654f-6272-5801-ab47-558998d46b8a', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '0545d0ec-89d1-a8aa-99f9-78b30fcbacb1', '片假名外来语的缩略形式', 'N2中常见外来语缩略，如「パソコン（パーソナルコンピューター）」「リモコン（リモートコントロール）」「スマホ（スマートフォン）」等。需掌握常见缩略外来语的原词与使用场景。', '将缩略外来语误认为完整词，或在使用时混淆缩略与全称的语体差异。', '日本語：会議の前にリモコンでプロジェクターを操作した。；说明：「リモコン」是「リモートコントロール」的缩略，常用于口语。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('b1ad5a2e-9ada-54e7-983a-92054cf5e27a', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '1d183755-02b3-4a6d-b727-082af1ef377c', '40ed56d1-acbd-4a8b-6284-2df8b9423e8e', '顺序接续词与事件排序', '利用“まず”“次に”“最後に”等顺序接续词，理解事件或步骤的先后顺序，并能正确排列打乱的句子。', '忽略接续词，仅凭内容猜测顺序；混淆“次に”与“そして”的细微差别；在时间顺序与逻辑顺序间混淆。', '日语例句：まず材料を切ります。次に、鍋で炒めます。最後に、調味料を加えます。说明：通过“まず”“次に”“最後に”明确步骤顺序，不可颠倒。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('b1d790ae-7e59-5219-99e4-ff10d087a750', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '1d183755-02b3-4a6d-b727-082af1ef377c', '9c37478d-2388-1380-cdea-3b62d82c3fcb', '对话中谓语省略的补全策略', '在小说或对话体文章中，根据上下文和发话者意图补全被省略的谓语或宾语，尤其涉及礼貌省略和言外之意。', '只按字面补全，忽略发话者的意图和人际关系；在正式文章中误用对话补全规则。', '日语例句：「明日の会議、あなたは？」「私はちょっと…」。；说明：第二句省略了「出席できない」，需根据语境补全为拒绝。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('b24d4eb6-0e81-56aa-bc65-619c8c94315f', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '1af448c1-54cf-2f94-01b5-e8bc77a97f94', '～てある（动作结果存续・他动）', '表示某人有意进行的动作的结果仍然保持着。主语是动作的对象（物），动词为他动词，强调人为造成的状态。与已有「～てある（状态存续）」不同，这里侧重与自动词「～ている」的对比。', '容易与「～ている」混淆。～てある强调是人为动作的结果，而～ている表示自然状态或动作进行中。', '日本語例：窓が開けてあります。；说明：窗户被（某人）打开着，强调人为结果。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('b2553cc5-c81d-5bd2-b586-d0c6febb7edd', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '3760dfca-44d9-3445-01cd-85de1f860da1', '～ように見える', '表示看起来像…，从外观判断。接动词辞书形/た形/ない形。', '与「～らしい」混淆；误用为事实判断。', '彼女は疲れているように見える。说明：她看起来好像很累。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('b28967ed-e407-5ab8-8dac-8e403c706edd', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '3760dfca-44d9-3445-01cd-85de1f860da1', '～ことなく', '表示“不…而…”，相当于「～しないで」。接续：动词辞书形+ことなく。', '与「～ないで」相比，「ことなく」更书面、正式，且常用于否定性评价或习惯。', '彼は一度も休むことなく、働き続けた。；说明：他一次也没休息，持续工作。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('b2c5d3ae-88c2-5e8a-b881-1746eeebca4b', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '2c18e7e1-4ef0-65e3-24a7-6c97d562a122', '～を通しての', '表示“通过……的（关系/经历）”，修饰名词。', '注意「を通して」与「を通じて」的区别，前者强调过程，后者强调媒介。', '日本語：留学を通しての経験は、私の人生を変えた。；说明：通过留学的经历改变了我的人生。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('b36028f4-319b-5ebf-b143-0f8972cbee5d', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '2c18e7e1-4ef0-65e3-24a7-6c97d562a122', '～をとわず', '表示“不论……，不分……”，强调不受时间、地点、性别等限制。接续：名词+をとわず。', '与「～にかかわらず」相近，但「をとわず」更强调“不区分”，且常与「昼夜・場所・年齢」等搭配。', '日本語：昼夜をとわず、問い合わせが来る。；说明：不分昼夜，都有咨询来。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('b4252c7c-9eb0-5449-a833-189e1249e08e', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '1d183755-02b3-4a6d-b727-082af1ef377c', 'fc58533f-fd29-5132-8f21-fd381828e3c8', '理解原因推断', '根据上下文线索（因果词、逻辑关系）推断未明说的原因，尤其在对话或短文中。', '过度推断；忽视文中的直接提示。', '日语例句：彼は遅刻した。電車が止まったからだ。说明：原因直接由「から」给出，但有时需从前文推断。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('b42977f3-afdc-508e-b387-ee7dd70c724e', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '0545d0ec-89d1-a8aa-99f9-78b30fcbacb1', '特殊量词（如「羽」「軒」「冊」）的适用范围', 'N2要求掌握一些容易混淆的量词，如「羽」用于鸟类和兔子，「軒」用于房屋，「冊」用于书籍。本知识点训练正确选择量词。', '将「羽」用于所有动物，或把「軒」用于公寓（公寓用「戸」或「軒」但需注意）。', '日语例句：庭にうさぎが三羽います。；说明：「羽」除了鸟类，也用于兔子，不能误用「匹」。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('b43fb203-31e2-51f7-9fea-9d13fcf57b2e', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '1d183755-02b3-4a6d-b727-082af1ef377c', '9c37478d-2388-1380-cdea-3b62d82c3fcb', '段落间衔接与过渡理解', '理解段落之间的逻辑关系（承接、转折、因果、补充等），把握文章的整体脉络和过渡词的作用。', '孤立看待段落；忽略段落首尾的衔接句；未识别「ところで」「さて」等转换话题的词语。', '日语例句：前段落では問題を指摘した。では、次に解決策を考えてみよう。说明：「では」表示从问题转向解决方案的过渡。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('b473802f-5cc2-5f46-a4e1-b6896421773d', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '3760dfca-44d9-3445-01cd-85de1f860da1', '～にかかわることができる', '表示“能够参与/关系到某事”，强调有能力或机会介入某事项。', '误以为与“～にかかわる”同义，但本句型侧重“可能”性，且主语多为人或组织。', '日本語：このプロジェクトに直接にかかわることができるのは、経験者だけだ。；说明：只有经验者才能直接参与该项目。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('b49a7b04-0c4f-5918-8c75-ef3fe37f2e19', '9221fc32-a051-42cb-86b1-6a9917aa004e', '42de0c7b-50d9-4159-918a-4e618d83342d', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '0e03a921-5aff-e4be-f477-4d55640b198b', '周月年的持续时长表达', '掌握「週間（しゅうかん）」「ヶ月（かげつ）」「年間（ねんかん）」表示时长，如一週間、三ヶ月、二年間；注意「ヶ月」的读音和写法，以及「一ヶ月」读作「いっかげつ」。', '将「一週間」读作「いちしゅうかん」；将「三ヶ月」读作「さんかげつ」时误加浊音；将「二年間」与「二年」混淆。', '日本語：一週間休みます。；说明：一週間读作「いっしゅうかん」。日本語：日本語を三ヶ月勉強しました。；说明：三ヶ月读作「さんかげつ」。日本語：二年間日本に住んでいました。；说明：二年間读作「にねんかん」。)', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('b4ce6efe-9f81-5ab8-8418-dc71fa1a73c5', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '0545d0ec-89d1-a8aa-99f9-78b30fcbacb1', '复合动词的构成与意义', '理解N2常见复合动词（如「～始める」「～過ぎる」「～直す」）的构成规则和整体意义，能根据前项动词推测含义。', '对复合动词的语义理解片面，如将「やり直す」理解为“再做”而非“重新做”；或忽视接续限制。', '日语例句：宿題をやり直さなければならない。；说明：「直す」接动词ます形，表示重新做。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('b4fe28a9-d30b-5cf0-98cc-e340ba2395b8', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '0545d0ec-89d1-a8aa-99f9-78b30fcbacb1', '拟声拟态词的语义与用法', '掌握N2常见拟声拟态词（如「はっきり」「ぐっすり」「そろそろ」）所表达的状态或程度，并能在适当语境中使用。', '混淆相近拟态词，如「はっきり」与「くっきり」；或忽视其副词用法。', '日语例句：彼はぐっすり眠っている。；说明：「ぐっすり」表示熟睡的样子，常与「眠る」搭配。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('b512082c-ac64-5039-97b1-15c5ed375865', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '2c18e7e1-4ef0-65e3-24a7-6c97d562a122', '～てからでないと', '表示不先做前项，后项就无法实现，相当于「～てからでなければ」。接续：动词て形＋からでないと。', '后项多为否定或困难表达，注意与「～てからでなければ」相同，但口语中常用「～てからでないと」。', '資料を確認してからでないと、返事ができない。；说明：不先确认资料就无法答复。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('b5c627ee-449c-58d9-9628-02cea3a15962', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '5b34d8b5-bde9-c4c6-c736-84adaaae3603', '「を除き」的用法', '掌握「を除き」表示“除……之外”。', '与「を除いて」混淆，但「を除き」更正式。', '日本語：日曜日を除き、毎日営業しています。；说明：除周日外每天营业。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('b5d61630-f822-5172-8b19-4905d0060c38', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', 'ff057d86-47bc-de16-f0f9-a7b808b968e3', 'N3正式与口语同义词的转换（扩展）', '掌握N3中正式与口语同义词的转换，如「しかし/でも」「ですから/だから」「～ないといけない/～なければならない」等，理解语体差异。', '在正式书面语中误用口语表达；在口语中过度使用书面语，显得生硬。', '日语例句：しかし、問題は複雑だ。（正式）说明：しかし用于书面或正式场合。；日语例句：でも、難しかった。（口语）说明：でも用于日常对话。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('b6289571-2ffa-5680-8141-4d9240c513db', '9221fc32-a051-42cb-86b1-6a9917aa004e', '42de0c7b-50d9-4159-918a-4e618d83342d', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', 'ef36118d-0ba3-29ce-b2b3-76eaeb6542ca', 'ていく（方向/变化）', '表示动作由近及远或从某时点向未来变化。接动词て形后加いく。', '与てくる混淆；方向理解错误。', 'だんだん寒くなっていきます。；说明：渐渐变冷（向未来变化）。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('b637c2bb-83a4-5b1f-85cf-66c1fe9a22c8', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '2c18e7e1-4ef0-65e3-24a7-6c97d562a122', '～を前にして', '表示“面临……，在……之前”，强调即将面对某事时的状态或心情。接续：名词+を前にして。', '与「～に直面して」混淆，但「を前にして」更强调时间上的临近，且常用于主观感受。', '日本語：試験を前にして、緊張で眠れない。；说明：面临考试，紧张得睡不着。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('b638e711-7d3f-51e4-aa96-adaa04473ade', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '2c18e7e1-4ef0-65e3-24a7-6c97d562a122', '～を通じての', '表示“通过～的”，作连体修饰语，后接名词。强调媒介或过程。', '与「～を通じた」混淆，两者可互换，但「～を通じての」更强调“全程”。', '留学を通じての経験は貴重だ。；说明：通过留学的经验很宝贵。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('b6bb7560-b78d-5f66-a42c-5cba22408598', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', 'ff057d86-47bc-de16-f0f9-a7b808b968e3', 'N3同源词族的派生关系（扩展四）', '掌握N3中同源词族的派生规律，如「決める→決まる→決定」「開ける→開く→開放」等，理解动词、名词、形容动词之间的转换关系。', '学习者常混淆自他动词与名词的对应，如「決定」是名词，但「決める」是他动词，「決まる」是自动词；需注意词性变化。', '日语例句：会議の日程を決める。；说明：「決める」是他动词。日语例句：日程が決まった。；说明：「決まる」是自动词。日语例句：決定は来週発表される。；说明：「決定」是名词。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('b6f45258-7870-527b-aed8-eeac62087481', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '1af448c1-54cf-2f94-01b5-e8bc77a97f94', '～ておく（放置・放任）', '表示有意让某动作的结果保持下去，或暂时不做处理、放置不管。与已有「～ておく（准备・放置）」不同，这里侧重“放任”的语感，常与「そのまま」搭配。', '与表示事先准备的～ておく区分。本用法强调不干预、保持原状，如「そのままにしておく」。', '日本語例：この問題はそのままにしておいてください。；说明：这个问题请先放着别管。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('b7013966-a250-5077-b239-9121508b53ad', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', 'ff057d86-47bc-de16-f0f9-a7b808b968e3', 'N3汉字复合词读音规律', '掌握N3级别常见二字汉字复合词中音读与训读的组合规律，如「手紙(てがみ)」为训读+训读，「親切(しんせつ)」为音读+音读，以及「見方(みかた)」等混合读法。', '误将不熟悉的复合词全部按音读或训读处理，忽视个别特殊读音，如「時々(ときどき)」中的浊化。', '日语例句：この手紙を読んでください。；说明：「手紙」读作「てがみ」，是训读复合词，不能读成「しゅし」。；日语例句：彼は親切な人です。；说明：「親切」读作「しんせつ」，是音读复合词。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('b71f198b-581f-5d8c-975a-3c2d071080d9', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', 'ff057d86-47bc-de16-f0f9-a7b808b968e3', '近义名词的语境区分', '区分N3中意思相近的名词，如「時間/時」「問題/質問」「意見/考え」等，注意使用场景和搭配。', '将「質問」用于需要讨论的问题，而「問題」更广泛；混淆「時間」和「時」的抽象与具体。', '日语例句：質問がありますが、時間がありません。；说明：質問指具体提问，時間指时间。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('b74261a5-8314-5bd9-91ca-f54b0c246488', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '1d183755-02b3-4a6d-b727-082af1ef377c', '40ed56d1-acbd-4a8b-6284-2df8b9423e8e', '不同题型应对策略', '掌握“内容一致/不一致”“理由”“指示词”“填空”等常见题型的解题思路，能针对性地回原文定位。', '不看题干要求，凭印象作答；未注意“正しくないもの”等否定设问。', '日语例句：問題：「筆者の考えに合わないものはどれか。」说明：需先明确作者观点，再逐一排除选项，注意“合わない”是选错误项。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('b78e6620-ea7b-5027-ad9c-7f5d1b13cef3', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '5b34d8b5-bde9-c4c6-c736-84adaaae3603', '「及ぶ」与「達する」的用法区分', '「及ぶ」表示达到某种程度或范围，常与「影響が及ぶ」搭配；「達する」表示达到数量、目标或状态。', '混淆两者；「及ぶ」不用于数量目标，如「100人に達する」不能说「100人に及ぶ」但可表示波及。', '影響が全国に及（およ）んだ。；说明：波及。／売上が1億円に達（たっ）した。；说明：达到。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('b7b2cdd7-9d38-5a57-9fae-4c3681cbfe42', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', 'baa9b5c2-5b94-4f9b-7ced-3a8c3cde4cb3', '近义动词的语感与使用场景差异', 'N4阶段需辨析如「見る／観る／診る」、「聞く／聴く」、「言う／話す／しゃべる」、「食べる／飲む／いただく」等近义动词，理解其对象、目的、正式度及语体差异，并能根据语境选择恰当动词。', '将「観る」用于所有“看”的场合（如「テレビを観る」虽可但「映画を観る」更自然）；混淆「聞く」与「聴く」；在正式场合误用「しゃべる」代替「話す」。', '日语例句：週末に映画を観に行く。；说明：「観る」强调欣赏、观看演出或电影。日语例句：音楽を聴きながら勉強する。；说明：「聴く」强调专注地听音乐等。日语例句：先生と話すときは丁寧な言葉を使う。；说明：「話す」是普通对话，比「しゃべる」正式。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('b7dae280-019e-5bf3-92a8-5d9cfc862288', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '1d183755-02b3-4a6d-b727-082af1ef377c', '40ed56d1-acbd-4a8b-6284-2df8b9423e8e', '说明书与操作指南理解', '能理解药品、电器等说明书中的使用方法、注意事项、禁止事项，并按要求执行。', '忽略“～ないでください”“～てはいけません”等禁止表达；混淆步骤顺序。', '日语例句：この薬は食後に水で飲んでください。ただし、一日に三回以上飲まないでください。说明：需注意服用时机和次数限制。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('b7dc4d41-25c0-5a7e-82e4-81756c662bab', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', 'ff057d86-47bc-de16-f0f9-a7b808b968e3', 'N3敬语动词的对应关系（扩展三）', '掌握N3中更多敬语动词的对应，如「言う→おっしゃる」「行く/来る→いらっしゃる」「食べる/飲む→召し上がる」「見る→ご覧になる」等，并注意使用场合。', '将「おっしゃる」用于自己或平辈；「召し上がる」只用于对方或长辈，不能用于自己。', '例句：先生は何とおっしゃいましたか。说明：「おっしゃる」是「言う」的尊敬语；例句：どうぞ召し上がってください。说明：「召し上がる」是「食べる/飲む」的尊敬语。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('b8421a06-fde2-55b5-9f44-2f65a2f58c50', '9221fc32-a051-42cb-86b1-6a9917aa004e', '42de0c7b-50d9-4159-918a-4e618d83342d', '1d183755-02b3-4a6d-b727-082af1ef377c', '37a506cf-ef62-8ccc-3210-ab64e8561a4d', '自我介绍文本的理解', '能够从自我介绍中提取姓名、国籍、职业、爱好等基本信息。', '混淆国籍与语言，或忽略爱好相关词汇。', '例句：私はイギリス人です。英語を話します。说明：提取国籍为英国，语言为英语。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('b863b10b-4eeb-527c-9244-0488d14a50c1', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', 'dd4e968a-3d37-98a7-3819-a5fc4c117122', '～ようにする（努力做到）', '表示“设法做到……”，接续：动词辞书形/ない形+ようにする，强调主观努力。', '与～ことにする混淆，～ようにする更强调日常习惯的养成。', '日本語：毎日、野菜を食べるようにしている。；说明：我努力做到每天吃蔬菜。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('b88351e6-7500-5199-99b7-778070c281d5', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '1d183755-02b3-4a6d-b727-082af1ef377c', '9c37478d-2388-1380-cdea-3b62d82c3fcb', '远距离照应关系的确定', '解决指示词或代词所指对象距离较远、跨越多个句子或段落时的指代问题。需要结合上下文语义和结构线索，排除干扰项，准确找到先行词。', '仅根据就近原则判断指代，忽略语义限制和段落主题，导致选错所指对象。', '日语例句：A社は新製品の開発に成功した。この製品は画期的な技術を用いている。しかし、その製品の販売には課題も多い。；说明：「その製品」指前文提到的A社的新产品，虽相隔较远，但语义上唯一对应。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('b888df52-1177-579d-841f-eac98582e7e3', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '5b34d8b5-bde9-c4c6-c736-84adaaae3603', '「なかなか」与「あまり」的否定呼应', '「なかなか」与否定呼应表示“怎么也（不）”，强调困难；「あまり」与否定呼应表示“不太”。', '「なかなか」在肯定句中表示“相当”，需区分；「あまり」不能用于强调困难。', '日语例句：なかなか眠れない。；说明：表示“怎么也睡不着”。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('b8ca5c9b-44b9-53db-8cb3-8954c51b107e', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '2c18e7e1-4ef0-65e3-24a7-6c97d562a122', '～いかんで／いかんによっては', '表示“根据……的情况”或“取决于……”，后项根据前项的变化而不同。接续：名词＋（の）いかんで／いかんによっては。', '注意「いかんによっては」后项常接可能发生的结果，而「いかんで」后项直接接决定或判断。', '日语例句：試験の結果いかんによっては、合格できないかもしれない。；说明：根据考试结果，可能无法合格。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('b9d8638f-ada9-5e6b-9877-bba7f7157e6d', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '5b34d8b5-bde9-c4c6-c736-84adaaae3603', '「至る」与「到る」的读音与用法区分', '「至る」读「いたる」，表示到达、达到某种状态；「到る」是异体字，现代日语多用「至る」。注意「至って」表示非常。', '将「至る」误读为「し」；混淆「至って」与「非常に」。', '結論に至（いた）るまで時間がかかった。；说明：到达。／至（いた）って簡単です。；说明：非常。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('ba027ecb-2fb0-505e-b404-1f4ba63b2e2b', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '3760dfca-44d9-3445-01cd-85de1f860da1', '～にしてみれば', '表示从某人的立场或角度来看。接续：名词＋にしてみれば。', '与「にとって」相似，但「にしてみれば」更强调换位思考。', '親にしてみれば、子供の安全が一番心配だ。；说明：对父母来说，孩子的安全最令人担心。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('bad6dbbb-2e0b-5530-9518-6df7a95638ac', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '2c18e7e1-4ef0-65e3-24a7-6c97d562a122', '～つつある', '表示动作正在进行或变化正在持续，多用于书面语。接续：动词ます形＋つつある。', '只能接持续动词，不能接瞬间动词，且与「～ている」相比更正式。', '経済は徐々に回復しつつある。；说明：经济正在逐渐恢复。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('bb16480e-ed56-5e90-a8d8-b95308b838ed', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '5b34d8b5-bde9-c4c6-c736-84adaaae3603', '「疎」的读音与词义', '「疎」音读「そ」，如「疎外」「疎通」；训读「うと（い）」「まば（ら）」等。表示疏远、稀疏。', '将「疎外」误读为「まばらがい」；混淆「疎い」与「遠い」。', '彼は世間に疎（うと）い。；说明：不熟悉。／人との疎通（そつう）を図る。；说明：沟通。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('bb18c878-cf3d-502c-aa0f-d5fa9577eef3', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '1d183755-02b3-4a6d-b727-082af1ef377c', '40ed56d1-acbd-4a8b-6284-2df8b9423e8e', '引用与转述理解', '能区分直接引用和间接转述，理解“～と述べている”“～と書いてある”等表达中说话者的观点。', '将转述内容误认为作者观点；忽略引用出处。', '日语例句：専門家は「睡眠時間が短いと、記憶力が下がる」と述べている。说明：这是专家观点，并非文章作者直接主张。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('bb49ac57-291a-583f-8179-2a35b19c7392', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '1d183755-02b3-4a6d-b727-082af1ef377c', '9c37478d-2388-1380-cdea-3b62d82c3fcb', '接续词省略时的逻辑关系推断', '在句子或段落间缺少显性接续词时，根据内容推断隐含的转折、因果、递进等逻辑关系，并理解作者为何省略。', '强行添加接续词导致误读；忽略省略接续词常出现在口语或意识流中，逻辑较松散。', '日语例句：彼は疲れていた。それでも仕事を続けた。；说明：即使没有「しかし」，通过「それでも」可推断转折关系。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('bb4b847a-ab52-5795-a1c2-df2ac439a0f0', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '2c18e7e1-4ef0-65e3-24a7-6c97d562a122', '～に即して', '表示依据、按照某种实际情况或规则来处理。接在名词后，相当于「～に基づいて」「～に従って」。多用于正式场合或书面语。', '与「～に沿って」混淆。「に即して」强调直接依据事实或规则本身，而「に沿って」强调沿着某方向或流程。', '日本語：実際のデータに即して分析を行う必要がある。；说明：表示必须依据实际数据进行分析。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('bb52c4b5-cb54-538a-913e-3a5a348c48c8', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '3760dfca-44d9-3445-01cd-85de1f860da1', '～てはいけない', '表示禁止，相当于“不可以…”。多用于规则、提醒或对对方的警告。', '与「～てはならない」相比，「～てはいけない」更口语化，但两者常可互换。注意「～てはいけない」前面接动词て形，不要与「～てもいい」混淆。', 'ここで写真を撮ってはいけません。；说明：禁止在此拍照。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('bb66ab81-ca4d-5dd0-9144-69c790f8f27a', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '1d183755-02b3-4a6d-b727-082af1ef377c', 'fc58533f-fd29-5132-8f21-fd381828e3c8', '理解事件发展顺序', '在叙事文中，通过时间词（〜前、〜後、〜時）和动作顺序把握事件先后。', '忽视「〜てから」的先后关系；混淆「前に」与「後で」的时点。', '日语例句：食事をしてから、散歩します。说明：「てから」表示先吃饭后散步。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('bb75d102-863b-5304-9cf1-1f28cc2a0ede', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '5b34d8b5-bde9-c4c6-c736-84adaaae3603', '「顕著」与「明白」的用法区分', '「顕著」表示效果、变化显著，多用于客观现象；「明白」表示事实清楚、明显，多用于判断。', '将「明白な効果」说成「顕著な効果」虽可但语感不同；「明白」常与「事実」搭配。', '経済成長が顕著（けんちょ）だ。；说明：显著。／彼の無実は明白（めいはく）だ。；说明：明显。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('bbc0b520-6fa6-5be8-ab2f-30051e10f2f0', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '5b34d8b5-bde9-c4c6-c736-84adaaae3603', '「京」「強」「教」等「きょう」同音汉字的读音与词义区分', '「きょう」读音的汉字如「京（きょう）」「強（きょう）」「教（きょう）」「境（きょう）」「興（きょう）」等。本知识点训练学习者根据词语判断正确汉字。', '学习者可能将「京都」误读为「きょうと」以外的音，或混淆「強度」与「教度」；需注意「京」指首都，「強」表示强大，「教」表示教育。', E'日语例句：京都（きょうと）は古い町だ。；说明：「京」读「きょう」，表示首都。\\n日语例句：強度（きょうど）を高める。；说明：「強」读「きょう」，表示强度。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('bbd07355-375f-541d-8726-926001255e6f', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '0545d0ec-89d1-a8aa-99f9-78b30fcbacb1', '近义词的语感与使用域辨析', '辨析N2常见近义词（如「確かめる/確認する」「壊れる/壊す」）在自动词他动词、语体、具体抽象等方面的差异。', '忽视自他动词区别，如将「ドアが開く」误用为「ドアを開く」；或混淆「確かめる」与「確認する」的细微差别。', '日语例句：彼は約束の時間を確かめた。；说明：「確かめる」侧重亲自核实，「確認する」更正式。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('bbd50615-9996-5449-a20a-e92d73039b17', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '2c18e7e1-4ef0-65e3-24a7-6c97d562a122', '～を離れては', '表示“离开～就无法”，强调某事物不能脱离背景或条件。接名词。', '与「～を離れて」混淆，后者是中性用法；此句型后接否定或消极。', '文化を離れては、言語の理解は難しい。；说明：离开文化，理解语言很难。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('bbe3c212-b92e-5cd7-a632-61197f61599f', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '1af448c1-54cf-2f94-01b5-e8bc77a97f94', '～たところで', '表示即使做了前项也不会有预期的结果，相当于“即使……也（不）……”。常与“無駄だ”“意味がない”等搭配，表达消极或徒劳的语气。', '注意与“～たところだ”（刚刚完成）区分；本句型后项多为否定或消极评价，不能用于积极结果。', '今から急いで行ったところで、もう間に合わないだろう。；说明：即使现在赶去，也来不及了。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('bc23301f-fb7f-52d9-8485-fddd3c9537c0', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '2c18e7e1-4ef0-65e3-24a7-6c97d562a122', '～につけても', '表示“无论……都……”或“每当……就……”，带有感慨、回忆或评价的语气。常与「～につけ、～につけ」连用，也可单独使用。接续：动词辞书形/た形＋につけても。', '易与「～につけ～につけ」混淆，后者强调并列列举两种对立情况；「～につけても」更侧重单一事项引发的感慨。', '日本語：昔の写真を見るにつけても、あの頃のことが思い出される。；说明：每当看到旧照片，就会想起那时候的事。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('bc2916f5-310f-5f66-ac2d-dbd3c311f8fd', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '0545d0ec-89d1-a8aa-99f9-78b30fcbacb1', '形容词与名词的固定搭配（如「重大な問題」「深刻な状況」）', 'N2中部分形容词与名词搭配固定，如「重大」「深刻」「著しい」等，需注意语义搭配。', '使用不搭配的形容词，如「大きい問題」而非「重大な問題」。', '例句：これは重大な問題だ。说明：「重大な」与「問題」搭配。；例句：状況は深刻だ。说明：「深刻な」与「状況」搭配。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('bc5e3553-6a21-58f4-9606-185ea34e733c', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '5b34d8b5-bde9-c4c6-c736-84adaaae3603', '「まだ」与「未だ」的读音与用法', '「まだ」表示“还、尚”，口语；「未だ」读作「いまだ」，书面语，常与否定呼应，表示“尚未”。', '将「未だ」读作「まだ」；「未だに」表示“至今仍”，多含意外。', '日语例句：未だに返事がない。；说明：书面语“至今仍无回音”。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('bc5e95f9-c150-5aac-9a43-047e92c8ad69', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '1af448c1-54cf-2f94-01b5-e8bc77a97f94', '～ことにしている（习惯・规定）', '表示自己定的习惯或规定，强调主观决定并持续执行。', '与～ことにする（一次性决定）混淆，本句型表示持续的习惯；与～ようにしている（努力习惯）区别，本句型更强调规定。', '日本語：毎朝ジョギングをすることにしている。；说明：表示自己规定的日常习惯。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('bc831f51-1e7b-547f-b4f3-68cf2ec0d23d', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '1af448c1-54cf-2f94-01b5-e8bc77a97f94', '～てからでないと（不…就不能）', '表示“如果不先做前项，就不能做后项”，强调先后顺序和必要条件。', '与“～てからでなければ”意思相同，但后者更书面。', '日本語：資料を読んでからでないと、意見を言えません。；说明：不先读资料就无法发表意见。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('bc85946c-97ea-5f7f-bc09-cb71ca362c9a', '9221fc32-a051-42cb-86b1-6a9917aa004e', '42de0c7b-50d9-4159-918a-4e618d83342d', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', 'ef36118d-0ba3-29ce-b2b3-76eaeb6542ca', 'てはいけないよ（禁止，亲密）', '口语中提醒亲密的人不要做某事，语气较强。', '对长辈使用不礼貌；与「ちゃいけないよ」同义。', 'そんなことをしてはいけないよ。；说明：可不能做那种事。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('bcd4a542-0322-52fd-83b9-108dec296e30', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', 'baa9b5c2-5b94-4f9b-7ced-3a8c3cde4cb3', '自他动词的对应与选择', '掌握N4常见自他动词对（如「開く/開ける」「壊れる/壊す」），理解其主语和宾语差异。', '混淆自动词与他动词的用法，如将「ドアが開けました」误用；忘记他动词需要宾语。', '日语例句：ドアが開きました。；说明：「開く」是自动词，主语是门；「開ける」是他动词，需要宾语，如「ドアを開けます」。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('bced7600-7631-5d3d-b3f1-8e3f8babe9a2', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '2c18e7e1-4ef0-65e3-24a7-6c97d562a122', '～に尽きる', '表示“归根到底就是～”，强调某事物最重要或最根本，用于总结观点或经验。接名词或动词辞书形。', '误用为表示原因或手段；与「～に限る」混淆，后者表示“最好”。', '日本語の上達は努力に尽きる。；说明：强调努力是最根本的。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('bd1db770-e8fa-56b7-a521-c00fee334c6d', '9221fc32-a051-42cb-86b1-6a9917aa004e', '42de0c7b-50d9-4159-918a-4e618d83342d', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '0e03a921-5aff-e4be-f477-4d55640b198b', '房屋房间的量词「軒」「室」', '掌握「軒（けん）」用于数房子、店铺，如一軒（いっけん）、二軒（にけん）；「室（しつ）」用于数房间，如一室（いっしつ）、二室（にしつ），但日常更常用「部屋（へや）」加「つ」或「個」。', '用「軒」数房间；将「一軒」读作「いちけん」；将「二軒」读作「にげん」。', '日本語：家を一軒建てました。；说明：一軒读作「いっけん」。日本語：この通りに店が三軒あります。；说明：三軒读作「さんげん」。日本語：アパートは二室借りています。；说明：二室读作「にしつ」。)', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('bd5def77-da74-5544-a54f-6dab89d9dbb7', '9221fc32-a051-42cb-86b1-6a9917aa004e', '42de0c7b-50d9-4159-918a-4e618d83342d', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', 'ef36118d-0ba3-29ce-b2b3-76eaeb6542ca', 'てもいいですか（否定回答）', '请求许可时，否定回答常用「いいえ、だめです」「いいえ、いけません」等，不用「てもいいです」否定。', '用「てもいいです」回答否定，造成误解。', 'トイレに行ってもいいですか。いいえ、だめです。；说明：可以去厕所吗？不，不行。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('bd639dbd-0a11-5d87-8883-bc2b11e540ed', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', 'ff057d86-47bc-de16-f0f9-a7b808b968e3', 'N3同源词族的派生关系', '掌握同一汉字或词根派生出的名词、动词、形容词、副词，如「決める/決まる/決定/決定的」的用法区别。', '混淆自动词与他动词的派生，如「決まる」是自动词，「決める」是他动词。', '日语例句：日程が決まった。；说明：「決まる」自动词，表示被决定。；日语例句：彼は決断が速い。；说明：「決断」是名词，表示决断。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('bd96ac76-c21d-532f-a6c8-143fce619eac', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '3760dfca-44d9-3445-01cd-85de1f860da1', '～ないではいられない', '表示忍不住要做某事，相当于“不能不……”“不由得……”。接动词ない形。', '误用于客观义务，而应表示强烈的主观冲动；注意与“～ずにはいられない”相同。', '日语例句：悲しくて、泣かないではいられなかった。；说明：因为悲伤，忍不住哭了。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('bdbc8bd8-7e31-573a-88f8-3fe706139c94', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '3760dfca-44d9-3445-01cd-85de1f860da1', '～に反して', '表示“与…相反”，后项为违反前项的结果。接续：名词+に反して/に反する。', '与「～に逆らって」相比，「に反して」更客观，常用于预期、规则等。', '予想に反して、試験は簡単だった。；说明：与预想相反，考试很简单。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('be16df4e-cd08-55fe-86e9-d266b1658cf1', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '1d183755-02b3-4a6d-b727-082af1ef377c', 'fc58533f-fd29-5132-8f21-fd381828e3c8', '理解定义与解释', '在说明文中，通过「〜とは〜のことです」「〜という意味です」等结构理解术语或概念的定义。', '忽视定义句的位置；混淆定义与例子。', '日语例句：「和食」とは日本の伝統的な料理のことです。说明：明确给出定义。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('be2986f4-f861-5347-a65f-30844d3fb4ce', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', 'baa9b5c2-5b94-4f9b-7ced-3a8c3cde4cb3', '同音异义汉字的辨识', '区分读音相同但汉字和意义不同的词，如「はかる」对应「測る」「量る」「計る」，根据语境选择正确表记。', '只看读音忽略汉字，导致书写错误或误解，如把「時間を計る」写成「測る」。', '日语例句：体重を量る。；说明：「量る」用于测量重量、数量，「測る」用于长度、速度，「計る」用于计算时间。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('be473c3f-fcc0-5634-828a-d53b237ab97c', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '1d183755-02b3-4a6d-b727-082af1ef377c', '6f1477f5-00be-f963-76b6-5165f568e88e', '设问段功能理解', '理解文中设问句（自问自答）的作用，如引出话题、承上启下或强调观点，把握文章展开逻辑。', '把设问句当作普通疑问句，忽略其引导下文的功能，导致对文章结构理解偏差。', '日本語：では、なぜこの問題が重要なのでしょうか。それは…；说明：设问句用于引出下文解释，阅读时需注意其后的回答部分。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('bed0a1b8-f2ab-535f-8b6c-d786ed70d6e5', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '5b34d8b5-bde9-c4c6-c736-84adaaae3603', '「頻」的读音与词义', '「頻」音读「ひん」，如「頻繁」「頻度」；训读「しき（りに）」表示频繁地。注意「頻りに」的用法。', '将「頻繁」误读为「はん」；混淆「頻りに」与「しばしば」的语感。', '彼は頻繁（ひんぱん）に海外へ行く。；说明：频繁。／彼女は頻（しき）りに謝った。；说明：反复地。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('bf3dc4d7-7933-50f9-9ff2-2d461699dd65', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '0545d0ec-89d1-a8aa-99f9-78b30fcbacb1', '汉字复合词中读音的アクセント（声调）差异', 'N2需注意复合词中声调模式可能改变，如「雨（あめ）」与「飴（あめ）」声调不同，复合词如「大雨（おおあめ）」声调与单独词不同。虽不要求精确掌握所有声调，但需能区分同音词。', '学习者常忽略声调，导致「橋（はし）」与「箸（はし）」混淆，或复合词中声调变化影响理解。', '日语例句：橋を渡る。；说明：「橋」读平板型「はし」，而「箸」读头高型「はし」，需靠语境区分。日语例句：大雨が降る。；说明：「大雨」读「おおあめ」，声调为「おおあめ」而非「おおあめ」。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('bf590568-0faf-5721-80d5-07c52ecadc91', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '1af448c1-54cf-2f94-01b5-e8bc77a97f94', '～にしたがって（随着・按照）', '表示随着前项变化后项也变化，或按照指示、规则等。', '与～につれて相近，但～にしたがって也可表示“按照”，～につれて无此用法。', '練習するにしたがって、上手になりました。（随着练习变得熟练了。）／指示にしたがって行動してください。（请按照指示行动。）', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('bfcfc60c-4b5b-582f-9b01-31b166cf6c21', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '0545d0ec-89d1-a8aa-99f9-78b30fcbacb1', '表示情感状态的近义词辨析（如「寂しい」与「淋しい」）', 'N2中部分情感形容词存在细微语感差异，如「寂しい」侧重客观孤独，「淋しい」侧重主观感受，但现代日语中常通用。', '忽略语感差异，随意替换。', '例句：一人暮らしは寂しい。说明：「寂しい」常用。；例句：心が淋しい。说明：「淋しい」强调内心感受。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('bfe8193f-d0be-50c1-a3dd-39d62eb25adf', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '5b34d8b5-bde9-c4c6-c736-84adaaae3603', '「致」的读音与词义', '「致」常见读音「ち」「いた（す）」。名词或汉语词中读「ち」，如「致命」「一致」；动词「致す」读「いたす」，表示做、导致（谦逊语）。', '将「致命傷」的「致」误读为「いた」；混淆「致す」与「及ぼす」的语体。', 'その事故は致命（ちめい）的な被害をもたらした。；说明：致命。／私が致（いた）します。；说明：谦逊地说自己做。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('c0024fd7-72d1-539d-8494-3a89015c9b77', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', 'e5877362-1f27-54a5-903f-528a6d53f294', '助词与格关系', '区分主题、主格、对象、时间、地点、方向和手段等助词。', '动作场所误用「に」，或把主题「は」当成主格「が」。', '図書館で日本語を勉強します。', 'published', '2026-09-03 13:10:31.032213+08', '2026-09-03 13:10:31.032213+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('c02183fe-234c-5e56-939e-897702df60b4', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', 'baa9b5c2-5b94-4f9b-7ced-3a8c3cde4cb3', '近义词的语义与语感差异', '辨析N4常见近义词如「大きい/広い」「暑い/熱い」「嬉しい/楽しい」等，理解其使用语境。', '将「暑い」用于物体温度；混淆「嬉しい」与「楽しい」的情感侧重。', '日语例句：今日はとても暑いです。；说明：「暑い」指气温高，「熱い」指物体温度高，注意区分。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('c023259d-bf76-5be0-adc8-0b653d2a06cd', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '1d183755-02b3-4a6d-b727-082af1ef377c', '6f1477f5-00be-f963-76b6-5165f568e88e', '长句拆解理解', '面对含有多个修饰成分、从句或插入语的长句，学会找出主干（主语、谓语），再逐步理解修饰关系。', '被长句吓住，逐词翻译导致逻辑混乱；或忽略主语和谓语的一致性。', '日语例句：昨日、友達からもらった、新しいレストランで食べた、とてもおいしかった料理のレシピを、母に教えた。说明：先找主干“教えた”，再理清修饰“レシピ”的多个定语。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('c0fc38ac-2884-5c9b-8cde-3a2a2e7aa1ba', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '1d183755-02b3-4a6d-b727-082af1ef377c', '9c37478d-2388-1380-cdea-3b62d82c3fcb', '隐含条件的推断', '根据文章上下文推断出未明示的前提条件或背景信息，这些隐含条件对于理解作者的论述逻辑和结论至关重要，需要结合常识和语境进行合理推断。', '忽略隐含条件，直接按字面理解，导致对论述的合理性产生误解或无法理解作者的意图。', '日语例句：この薬は効果があるが、副作用も無視できない。；说明：隐含条件是“用药需权衡利弊”，作者虽未明说，但通过转折暗示了这一前提。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('c11a0457-3bce-530e-b0db-37d9eb9470e2', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', 'dd4e968a-3d37-98a7-3819-a5fc4c117122', '～てもかまわない（可以・没关系）', '表示“做……也没关系”，比～てもいい更正式，接续：动词て形+もかまわない。', '与～てはいけない混淆，注意否定形式「～なくてもかまわない」表示不必。', '日本語：質問があってもかまいません。；说明：有问题也没关系。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('c12c6f72-2107-5add-8a63-1a3e6b507d0c', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '2c18e7e1-4ef0-65e3-24a7-6c97d562a122', '～かたわら', '表示在做主要事情的同时，兼顾另一件事，多用于长期活动。接续：动词辞书形・名词＋の＋かたわら。', '与「～ながら」不同，「かたわら」强调长期、正式的活动，且前后项不是同时进行而是兼顾。', '会社に勤めるかたわら、夜は大学院で勉強している。；说明：一边在公司工作，一边晚上在研究生院学习。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('c1576882-dc26-567d-998c-36e8885b1bd7', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '2c18e7e1-4ef0-65e3-24a7-6c97d562a122', '～ことなしに', '表示不做什么事情就进行后项，相当于「～しないで」。接续：动词辞书形＋ことなしに。', '后项多为正式动作，且常与否定或困难表达连用，注意与「～ことなく」的区别，后者更强调状态。', '彼は一言の挨拶もすることなしに、部屋を出て行った。；说明：他连一句招呼都没打就离开了房间。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('c15a4c69-cf16-5a1a-8c4f-9d4e6363339d', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', 'baa9b5c2-5b94-4f9b-7ced-3a8c3cde4cb3', '复合动词的构成与意义', '掌握N4常见复合动词如「～始める」「～続ける」「～終わる」等，理解其表示动作的阶段。', '混淆「～始める」与「～出す」的语感；将「～終わる」用于非意志动作。', '日语例句：雨が降り始めました。；说明：「降り始める」表示开始下雨，注意「～出す」更强调突然开始。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('c1bfc8e4-39a8-5ade-8ce2-ce01ff0478ae', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '5b34d8b5-bde9-c4c6-c736-84adaaae3603', '「即座に」与「即時」的用法', '「即座に」副词，表示“立刻、当场”；「即時」名词，常构成「即時に」「即時〜」，书面语。', '将「即時」当副词直接使用；混淆两者语体。', '日语例句：即座に反応する。；说明：表示“立刻反应”。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('c209977f-9f8e-5552-8920-cbd54f7d9ec9', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '3760dfca-44d9-3445-01cd-85de1f860da1', '～に対して', '表示对……、向……，表示动作的对象或态度。接续：名词＋に対して。', '注意与「にとって」区别，「に対して」强调方向性，而「にとって」表示从某立场来看。', '先生に対して失礼なことを言ってはいけない。；说明：对老师不能说失礼的话。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('c2b735a9-b06c-5bf3-846d-2915e67b5ded', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '1d183755-02b3-4a6d-b727-082af1ef377c', '9c37478d-2388-1380-cdea-3b62d82c3fcb', '引用内容的归属判断', '区分文章中引用的他人观点与作者本人的观点，明确引用的起止范围，以及作者对引用内容的态度（赞同、反对或中立）。注意引用动词和标点符号的提示。', '将引用内容误认为作者观点，或不能准确判断引用的结束位置，导致混淆不同声音。', '日语例句：ある研究者は「この方法は有効だ」と述べている。しかし、私はその結論には疑問がある。；说明：引用研究者观点后，作者用「しかし」表明自己的怀疑态度，需区分引用与作者观点。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('c2fce0c1-7bf8-5be0-9767-7c546755bd48', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '2c18e7e1-4ef0-65e3-24a7-6c97d562a122', '～を経て', '表示“经过……，通过……”，强调经过某个过程或阶段。接续：名词+を経て。', '与「～を通じて」混淆，但「を経て」更强调时间或阶段的经过，如「審査を経て」。', '日本語：厳しい審査を経て、合格者が決まった。；说明：经过严格审查，决定了合格者。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('c314b86f-db79-5941-88b4-1beb7e604757', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '2c18e7e1-4ef0-65e3-24a7-6c97d562a122', '～かぎりだ', '表示说话人强烈的感情，如高兴、遗憾、担心等，相当于「非常に～だ」。接续：形容词（感情类）＋かぎりだ。', '只能接表示感情的形容词，如「うれしい」「残念」「心配」等，不能接一般形容词。', '皆さんに祝っていただき、嬉しいかぎりです。；说明：受到大家的祝福，非常高兴。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('c3412aa7-dc7e-5f8b-86e8-c26cd37a0afc', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '1d183755-02b3-4a6d-b727-082af1ef377c', 'fc58533f-fd29-5132-8f21-fd381828e3c8', '识别同义改写', '在阅读中，理解原文中某个表达被换用其他词语或句型复述，从而把握信息对应关系。', '只认字面相同，忽略同义句；不理解「〜という意味」的释义句。', '日语例句：この店は日曜日休みです。つまり、日曜日には開いていません。说明：「休み」与「開いていません」为同义改写。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('c3d8b834-14d2-581c-a7e7-722301c424fd', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '1d183755-02b3-4a6d-b727-082af1ef377c', '9c37478d-2388-1380-cdea-3b62d82c3fcb', '让步与反驳的论证结构', '识别文章中先承认对方论点合理（让步），再通过转折提出反驳的结构，理解其增强说服力的作用。', '将让步部分误认为作者最终立场；忽略反驳后常跟有更强烈的结论。', '日语例句：確かにコストはかかる。しかし、長期的な利益を考えれば、投資する価値はある。；说明：「確かに」让步，「しかし」后为作者真正主张。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('c3f583bd-85e3-5c69-a21b-533aec84f968', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', 'ff057d86-47bc-de16-f0f9-a7b808b968e3', 'N3与身体部位相关的惯用表达（扩展）', '掌握如「頭が下がる」「顔が広い」「手を貸す」「足を運ぶ」等惯用语，理解其比喻意义。', '按字面理解，如「頭が下がる」不是低头，而是表示敬佩。', '日语例句：彼の努力には頭が下がります。；说明：「頭が下がる」表示佩服。；日语例句：彼は顔が広い。；说明：「顔が広い」表示交际广。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('c4440a0c-f2f6-5460-9336-49b07ff7b4e5', '9221fc32-a051-42cb-86b1-6a9917aa004e', '42de0c7b-50d9-4159-918a-4e618d83342d', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', 'f5aa6f4e-16ea-57eb-96bb-fb12daa45f39', '词语搭配与语境', '掌握高频词汇在具体句型和生活场景中的自然用法。', '知道单词意思，却不能判断与动词、助词或场景的搭配。', '薬を飲んで、早く寝ます。', 'published', '2026-09-03 13:10:31.032213+08', '2026-09-03 13:10:31.032213+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('c4b04344-7af9-5efb-9aab-19b70894fe45', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '0545d0ec-89d1-a8aa-99f9-78b30fcbacb1', '常用汉字音读与训读的区分使用', '掌握N2级别常用汉字在不同单词中的音读（おんよみ）和训读（くんよみ）用法，能根据语境正确选择读音。', '混淆同形汉字的音读和训读，如将「大人」读作「だいじん」而正确应为「おとな」；或对个别单词的惯用读音不熟悉。', '日语例句：大人（おとな）は子供（こども）に優しくする。；说明：「大人」为训读，而「大」在「大学（だいがく）」中为音读。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('c4d99ae3-a6e7-5e1a-9aae-d050d65400d7', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '2c18e7e1-4ef0-65e3-24a7-6c97d562a122', '～に関してはの', '表示关于……的，用于修饰名词，带有强调或对比的语感。较少见。', '与「～に関しての」相比，「に関してはの」更强调特定事项。', '日本語：この件に関してはの詳細は後ほど説明します。；说明：关于这件事的详细情况稍后说明。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('c5214af8-a9d3-5ce3-8805-be38f888db80', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', 'baa9b5c2-5b94-4f9b-7ced-3a8c3cde4cb3', '动词送假名的正确书写与读音', 'N4常用动词（如：食べる、見る、来る、する）的送假名规则，以及由此带来的读音变化。', '漏写送假名，如把「食べる」写成「食る」；或混淆「見る」和「見える」的送假名。', '日语例句：朝ご飯を食べます。；说明：「食べる」的送假名「べ」必须写出，否则无法判断读音。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('c5248099-8be7-5e9b-93cd-e7b6a0fdf5c8', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', 'e5877362-1f27-54a5-903f-528a6d53f294', '愿望、推量与意志', '表达愿望、计划、推测、意志和传闻。', '把说话人的意志和对事实的推测使用在同一语境中。', '日本へ行きたいです。', 'published', '2026-09-03 13:10:31.032213+08', '2026-09-03 13:10:31.032213+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('c529b0a1-df48-553b-8282-8f59b9b804f5', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '2c18e7e1-4ef0-65e3-24a7-6c97d562a122', '～によっては', '表示“根据情况，有时……”，强调在某些条件下可能出现例外。接续：名词+によっては。', '与「～によって」混淆，后者表示“根据……而不同”，而「によっては」强调“在某些情况下”。', '日本語：場所によっては、この薬は手に入らないかもしれない。；说明：根据地点不同，这种药可能买不到。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('c576afff-49c3-598e-b7a4-11bd0486352c', '9221fc32-a051-42cb-86b1-6a9917aa004e', '42de0c7b-50d9-4159-918a-4e618d83342d', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '0e03a921-5aff-e4be-f477-4d55640b198b', '一般小物品的量词「個」', '掌握量词「個（こ）」用于数苹果、鸡蛋、球、箱子等立体的、可数的小物品，注意音变：一個（いっこ）、六個（ろっこ）、八個（はっこ）、十個（じゅっこ）。', '用「個」数纸张、书本等；将「一個」读作「いちこ」；将「三個」读作「さんこ」时误加浊音。', '日本語：りんごを三個ください。；说明：三個读作「さんこ」。日本語：卵を一個食べました。；说明：一個读作「いっこ」。日本語：箱が六個あります。；说明：六個读作「ろっこ」。)', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('c59af8af-6981-59a7-94ea-c79ea0b48291', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '0545d0ec-89d1-a8aa-99f9-78b30fcbacb1', '身体部位惯用表达的引申义（如「頭が下がる」「足を運ぶ」）', 'N2包含许多身体部位惯用语，其意义往往引申。例如「頭が下がる」表示佩服，「足を運ぶ」表示特意前往。本知识点集中学习这些引申义。', '按字面理解，如将「頭が下がる」理解为“低头”而忽略其“佩服”的用法。', '日语例句：彼の努力には頭が下がる。；说明：「頭が下がる」不是字面低头，而是表示对他人行为感到敬佩。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('c5ba5aaa-203d-5d0f-a9e9-0d3468cc0d88', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '3760dfca-44d9-3445-01cd-85de1f860da1', '～てしょうがない', '表示程度非常强烈，相当于“……得不得了”。接形容词て形或动词て形。', '误用于正式书面语，此表达较口语化；注意与“～てたまらない”基本相同。', '日语例句：眠くてしょうがない。；说明：困得不得了。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('c6295822-f73d-5bb9-98d7-5a595ec24b7d', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', 'baa9b5c2-5b94-4f9b-7ced-3a8c3cde4cb3', '形容词与名词的派生关系（～さ、～み）', 'い形容词和な形容词可派生为名词：加「～さ」表示程度、性质（如「高さ」「静かさ」），加「～み」表示感觉、具有该性质的部分（如「甘み」「重み」）。需掌握常见派生词及其语义差异。', '混淆「～さ」与「～み」的语义，如「高さ」是高度，「高み」是高处；将「～さ」用于所有形容词（如「静かみ」错误）；误以为「～み」可加在い形容词词干后任意使用。', '日语例句：このビルの高さは何メートルですか。；说明：「高さ」表示可测量的高度。日语例句：このスープは甘みが足りない。；说明：「甘み」表示甜味、甜的感觉。日语例句：彼の話には重みがある。；说明：「重み」表示分量、重要性，是「重い」的「～み」派生。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('c66cde9a-2fba-5115-92a0-25f588db0964', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '3760dfca-44d9-3445-01cd-85de1f860da1', '～てはいけないこと', '表示“不可以做的事情”，用于列举规则或注意事项。', '注意「こと」前接「～てはいけない」整体，表示名词化。', 'ここでは走ってはいけないことになっている。；说明：规定在这里不可以跑。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('c66eff4d-2380-5a0f-b260-fb91bae8783d', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '0545d0ec-89d1-a8aa-99f9-78b30fcbacb1', '表示限定的「～だけ」「～しか～ない」「～ばかり」', '掌握「～だけ」（只有，客观限定）、「～しか～ない」（只有，强调少）、「～ばかり」（光是，偏多）的用法区别。', '学习者常将「～しか」与肯定句连用，如「しかある」错误，必须与否定呼应。', '日本語例：りんごだけ食べた。（只吃了苹果）／りんごしか食べなかった。（只吃了苹果，强调少）／りんごばかり食べている。（光吃苹果）。说明：三者限定范围和语感不同。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('c6c08567-e3ec-5b23-866b-d92c8bf72e2a', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '1d183755-02b3-4a6d-b727-082af1ef377c', '6f1477f5-00be-f963-76b6-5165f568e88e', '同义改写识别', '识别文章中同一信息的不同表达方式，理解近义词、换说法的对应。', '忽视同义表达；被华丽词藻迷惑而偏离原意。', '日语例句：この商品は安い。つまり、値段が手頃だ。説明：「安い」与「値段が手頃」同义。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('c6c854ae-e740-5da6-8190-81bec2d92e8c', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '2c18e7e1-4ef0-65e3-24a7-6c97d562a122', '～につきの', '表示关于、由于，后接名词。是～につき的连体修饰形式，但较少用，多用于正式场合，表示原因或关联。', '注意与～についての区分，～につきの更强调原因或附带关系；使用频率低，常被～についての替代。', '台風につきの欠航が相次いだ。；说明：因台风导致的航班取消接连发生。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('c6cf0690-f90f-5b85-9d74-2be9a0562863', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '2c18e7e1-4ef0-65e3-24a7-6c97d562a122', '～にしても', '表示即使作为…来说，也…；或让步。接续：名词/动词普通形+にしても。', '与「～にしても～にしても」（无论…还是…）区分。', '先生にしても、この問題は難しいだろう。说明：即使是老师也觉得难。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('c725fce6-8588-59af-afa2-9607dfc3b3d1', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '1af448c1-54cf-2f94-01b5-e8bc77a97f94', '～てくることになる（逐渐趋向）', '表示从过去到现在逐渐发展成某种结果，或从说话人视角向自己方向移动后形成的结果。', '与～てくる（单纯趋向）混淆，本句型强调最终成为某种状态；注意与～ていくことになる的方向区别。', '日本語：長い間練習してきて、やっと上手になってくることになった。；说明：表示经过长时间练习后逐渐变好的结果。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('c75619ae-dfd7-597f-8990-44bc399d11cb', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', 'dd4e968a-3d37-98a7-3819-a5fc4c117122', '～ていく（方向・持续）', '表示动作向远处移动或从说话人视角出发的移动，也可表示从现在到将来的持续变化。接续：动词て形+いく。', '与～てくる混淆，～ていく强调远离说话人，～てくる强调靠近；注意与～ていく（持续）区别。', '日本語：鳥が飛んでいきました。；说明：鸟飞走了（远离说话人）。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('c781d034-abdb-509a-b31a-bf1f5e5278b5', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '1af448c1-54cf-2f94-01b5-e8bc77a97f94', '～ことができる（可能）', '表示能力或可能性，接动词辞书形，相当于“能…”。', '与可能动词（如食べられる）互换时注意语体；口语中常省略が。', '日本語で手紙を書くことができます。（能用日语写信。）／ここで泳ぐことができません。（不能在这里游泳。）', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('c78be117-c669-5584-b52d-c8a37c94e45a', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '3760dfca-44d9-3445-01cd-85de1f860da1', '～てもいいこと', '表示“可以做的事情”，用于列举允许的事项。', '注意「こと」前接「～てもいい」整体，表示名词化。', 'この部屋では自由に使ってもいいことになっている。；说明：规定在这个房间可以自由使用。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('c7e3a6d5-88c6-5625-b660-ef2b6f8bcaab', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '3760dfca-44d9-3445-01cd-85de1f860da1', '～ようにいうこと', '表示“像…那样说”的引用结构，用于转述内容。接动词辞书形/ない形。', '与「～ように言う」混淆；误用为直接引用。', '彼は明日来るように言った。说明：他说了明天来这样的话。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('c80ac683-ba81-5ca1-bbf7-b5fc0e180072', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '1d183755-02b3-4a6d-b727-082af1ef377c', '9c37478d-2388-1380-cdea-3b62d82c3fcb', '设问句的作者意图', '分析文章中作者使用设问句（自问自答）的意图，理解设问是为了引出话题、强调观点、引导读者思考还是转换论述方向，并把握设问后的回答内容。', '将设问当作真正的疑问，忽略其修辞功能，或不能抓住设问后作者给出的答案。', '日语例句：では、なぜこのような現象が起きるのだろうか。それは、人々の意識が変化したからである。；说明：作者设问后自己回答，目的是引出原因分析，需关注回答部分。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('c84cb5e6-3850-523b-8abb-cb7f507ba617', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '2c18e7e1-4ef0-65e3-24a7-6c97d562a122', '～きらいがある', '表示有某种倾向或缺点，多用于负面评价。接续：动词辞书形・名词＋の＋きらいがある。', '只能用于消极倾向，不能用于积极方面，且主语多为第三人称或一般情况。', '彼は物事を悲観的に考えるきらいがある。；说明：他有把事情想得悲观的倾向。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('c85b0fc0-ae15-5891-9357-19d01d2afb13', '9221fc32-a051-42cb-86b1-6a9917aa004e', '42de0c7b-50d9-4159-918a-4e618d83342d', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '0e03a921-5aff-e4be-f477-4d55640b198b', '食物类外来语', '掌握サラダ、ケーキ、アイスクリーム、ジュース等食物相关外来语。', '将「アイスクリーム」简写为「アイス」时误用；混淆「ジュース」和「ソフトドリンク」。', 'ケーキを食べたいです。说明：「ケーキ」指蛋糕。／ジュースをください。说明：「ジュース」指果汁。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('c8621562-2b1e-5e2a-bcb2-786d3c2a8987', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '3760dfca-44d9-3445-01cd-85de1f860da1', '～に置いて', '表示放置于某处，或表示状态。接续：名词＋に置いて。', '注意与「において」区别，本项是动词「置く」的て形，常与「～を～に置いて」连用。', '本を机の上に置いてください。；说明：请把书放在桌子上。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('c894a1fa-3922-5dbe-a57a-e41283d31911', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '5b34d8b5-bde9-c4c6-c736-84adaaae3603', '「区」的读音与词义', '「区」在「区別」「区域」中读「く」，表示区分、区域，但「区切る」读「くぎる」，「区々」读「まちまち」。', '将「区々」误读为「くく」，或混淆「区別」与「差別」。', '例句：二つの言葉の区別が難しい。说明：「区別」读「くべつ」，指区别。；例句：この区域は立ち入り禁止だ。说明：「区域」读「くいき」，指区域。；例句：意見は区々だ。说明：「区々」读「まちまち」，意为各不相同。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('c8aebf47-5119-56c3-a606-cae4896652a0', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '3760dfca-44d9-3445-01cd-85de1f860da1', '～により', '「によって」的书面语形式，多用于正式文章或公告。接续：名词＋により。', '在口语中不常用，注意使用场合。', '台風により、列車が運休となった。；说明：因台风，列车停运了。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('c92e4077-6df4-567d-8c88-e72710edcdab', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '3760dfca-44d9-3445-01cd-85de1f860da1', '～ことなしに', '表示“在没有…的情况下”，常与「～できない」等否定表达呼应。接续：动词辞书形+ことなしに。', '与「～ことなく」的区别：「ことなしに」后常接否定或困难表达，而「ことなく」后接肯定动作。', '努力することなしに、成功はありえない。；说明：不努力就不可能成功。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('c955a3db-3c99-50f3-94df-2db37dc1bfdf', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', 'dd4e968a-3d37-98a7-3819-a5fc4c117122', '～てもいいよね（许可・确认）', '表示“可以……吧？”，用于向对方确认许可或征求同意，语气较轻松。', '误以为只能用于自己，也可用于询问对方；注意与～てもいいですか的区别，后者更直接请求。', '日本語：明日休んでもいいよね？；说明：明天休息可以吧？', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('caf6299b-eba2-5358-b6cd-73ac8ef0bcb6', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '3760dfca-44d9-3445-01cd-85de1f860da1', '～ていく', '表示动作的方向（离开说话人方向）或时间上的从现在到将来的变化。', '注意与「～てくる」的方向相反。表示变化时，「～ていく」强调从现在到将来的趋势。', 'これからも頑張っていきます。；说明：今后也要继续努力下去。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('cafd1f92-545a-5556-b2c9-68736edf83a7', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '5b34d8b5-bde9-c4c6-c736-84adaaae3603', '「偏」的读音与词义', '「偏」音读「へん」，如「偏見」「偏食」；训读「かたよ（る）」「ひとえに」等。表示偏向、不均衡。', '将「偏見」误读为「かたよみ」；混淆「偏る」与「傾く」。', '偏見（へんけん）を持たないようにする。；说明：偏见。／栄養が偏（かたよ）っている。；说明：不均衡。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('cb16bfd7-dc83-5de3-81aa-62a4aa9fba37', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '2c18e7e1-4ef0-65e3-24a7-6c97d562a122', '～にとっては', '表示从某立场或角度来看，相当于「～の立場では」。常与「～にとって」通用，但「にとっては」有对比或强调的语感。', '与「～に対して」混淆。「にとって」不表示动作对象，而是表示评价的基准。', '日本語：この計画は、会社にとっては大きな負担になる。；说明：这个计划对公司来说是个很大的负担。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('cb8d7370-001a-54ca-a738-69ef52f288c0', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '5b34d8b5-bde9-c4c6-c736-84adaaae3603', '「計」的多种读音与词义', '「計」在N1中常见读音「けい」，词义包括“计划”“计算”“合计”等。如「計画（けいかく）」「計算（けいさん）」「合計（ごうけい）」「計略（けいりゃく）」「会計（かいけい）」。', '「計略」读「けいりゃく」而非「けいろく」；「会計」读「かいけい」而非「かいけ」。', '計画（けいかく）を立てる。说明：計画指计划。；会計（かいけい）をお願いします。说明：会計指结账。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('cc5c3437-d44d-5e7c-9ffc-25df171b6ab5', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '2c18e7e1-4ef0-65e3-24a7-6c97d562a122', '～（よ）うにも～ない', '表示即使想做什么也做不到，强调客观条件不允许。接续：动词意志形＋にも＋动词可能形ない形。', '前后动词通常为同一动词，且后项为可能形否定，注意不要与「～ようにも」混淆。', '電車が止まって、出ようにも出られない。；说明：电车停了，想出去也出不去。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('cc66eb56-06b9-5f2d-a6e6-87cd33fe31b3', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '1af448c1-54cf-2f94-01b5-e8bc77a97f94', '～ようにする（努力）', '表示努力做到某事，接动词辞书形或ない形，常与「～ようにしています」连用表示习惯性努力。', '与～ようにする（使役样态）区分；本知识点只表示主观努力。', 'なるべく野菜を食べるようにしています。（尽量吃蔬菜。）／遅刻しないように気をつけてください。（请注意不要迟到。）', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('cccb0cb9-e8ee-595b-b5f0-21d51f2115c7', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '1d183755-02b3-4a6d-b727-082af1ef377c', '9c37478d-2388-1380-cdea-3b62d82c3fcb', '委婉表达与态度缓和', '识别文章中作者使用委婉语、模糊限制语（かもしれない、ようだ、と思われる等）来缓和语气或表达不确定性的策略，理解其背后的真实态度和谨慎程度。', '将委婉表达当作明确断言，或忽略模糊限制语所传达的不确定性，导致对作者态度的误判。', '日语例句：この計画は成功するかもしれないが、失敗のリスクも考えられる。；说明：使用「かもしれない」和「考えられる」表达不确定和谨慎态度，并非绝对断言。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('ccd97540-168f-5ea2-b1c5-c08836741e8d', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '0545d0ec-89d1-a8aa-99f9-78b30fcbacb1', '接尾辞「～込む」「～出す」「～過ぎる」的动词派生', 'N2中接尾辞「～込む」表示进入或深入，「～出す」表示开始，「～過ぎる」表示过度，如「飛び込む」「話し出す」「食べ過ぎる」。', '混淆「～込む」与「～入れる」等，或忽略「～過ぎる」的过度含义。', '例句：彼はプールに飛び込んだ。说明：「飛び込む」表示跳入。；例句：彼は突然話し出した。说明：「話し出す」表示开始说话。；例句：食べ過ぎてお腹が痛い。说明：「食べ過ぎる」表示吃太多。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('cd242080-9144-54df-8aad-c0b23ce82ced', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', 'dd4e968a-3d37-98a7-3819-a5fc4c117122', '～ないでください（请不要…）', '表示请求对方不要做某事。接续：动词ない形＋でください。', '误用为～なくてください；与～ないで（不做…而…）混淆；忘记使用礼貌的ください。', 'ここでたばこを吸わないでください。说明：请不要在这里吸烟。／遅刻しないでください。说明：请不要迟到。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('cd257e4c-229e-5a98-992e-b8695b418c59', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '1d183755-02b3-4a6d-b727-082af1ef377c', 'fc58533f-fd29-5132-8f21-fd381828e3c8', '理解比较与程度表达', '识别「〜より」「〜ほど」「一番」「〜と同じ」等表达，把握比较对象和程度高低。', '混淆「より」与「ほど」的用法（肯定/否定）；忽视「一番」表示最高级。', '日语例句：この本はあの本より難しいです。说明：比较两者，前者更难。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('cd2bcb57-d16c-58f3-aeb1-56fb94b9dae2', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', 'dd4e968a-3d37-98a7-3819-a5fc4c117122', '～てしまう（完成・遗憾）', '表示动作彻底完成，或带有后悔、遗憾、不可挽回的语气。', '只理解为“完成”，忽略遗憾语气。', '日本語：大事な書類を忘れてしまった。；说明：把重要文件忘了，表遗憾。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('cd5c5299-72e0-5fa0-9ef3-b73c99994e71', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '1d183755-02b3-4a6d-b727-082af1ef377c', '9c37478d-2388-1380-cdea-3b62d82c3fcb', '文章目的与意图判断', '判断作者写作的目的（如说服、告知、娱乐、警示）以及特定段落的功能（如引出话题、举例说明、总结）。', '将目的与内容混淆；忽视文章体裁（如广告、社论）；只关注局部而忽略整体意图。', '日语例句：この文章の目的は、読者に省エネの重要性を認識させることである。说明：目的常通过「～させる」「～てもらう」等表达。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('cd6c91df-84a7-56d9-baa6-757ae9cb8bba', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', 'dd4e968a-3d37-98a7-3819-a5fc4c117122', '～てくる（方向・持续）', '表示动作向说话人方向移动，或从过去到现在的持续变化。接续：动词て形+くる。', '不要与～ていく混淆；～てくる也可表示“去做一下再回来”如“行ってくる”。', '日本語：雨が降ってきました。；说明：开始下雨了（变化向现在）。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('cdbd1fce-df4e-51d0-846b-c854f0e1cf0b', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', 'ff057d86-47bc-de16-f0f9-a7b808b968e3', 'N3自他动词成对辨析（扩展四）', '进一步辨析N3中容易混淆的自他动词对，如「壊れる/壊す」「落ちる/落とす」「消える/消す」等，强调动作主体和对象的不同。', '学习者常将自动词误用为他动词，或反之。例如「ドアが開く」是自动词，而「ドアを開ける」是他动词，需根据助词「が」和「を」判断。', '日语例句：窓が壊れている。；说明：自动词「壊れる」表示状态，主语是窗户。日语例句：彼が窓を壊した。；说明：他动词「壊す」强调动作，宾语是窗户。日语例句：電気が消えた。；说明：自动词「消える」表示自然消失。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('ce832da2-cee5-5b4e-b3f5-1ae555f1bee9', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '3760dfca-44d9-3445-01cd-85de1f860da1', '～につき', '表示因为、由于，或表示每……。接续：名词＋につき。', '注意区分两种用法：表示原因时相当于「ので」，表示比例时相当于「ごとに」。', '雨天につき、試合は中止になりました。；说明：因下雨，比赛取消了。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('ce9ccad0-3920-5a70-91de-825861904edc', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '2c18e7e1-4ef0-65e3-24a7-6c97d562a122', '～といえば', '表示“提起～就想到～”，用于引出话题或联想。接名词。', '与「～というと」混淆，后者更口语；「～といえば」常用来回忆或举例。', '日本料理といえば、寿司が有名だ。；说明：提起日本菜，寿司很有名。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('cea2bf9d-34a1-5abd-8c22-f5aa655b39cb', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '0545d0ec-89d1-a8aa-99f9-78b30fcbacb1', '正式与非正式语体的词汇选择', '区分N2中同一概念在不同语体下的词汇（如「しかし/でも」「従って/だから」），能根据场合选用。', '在书面语中使用口语词，如论文中写「でも」；或在口语中过度使用书面语。', '日语例句：従って、この案は採用できない。；说明：「従って」为书面语，口语中常用「だから」。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('ceb50663-4e0c-5b9d-8964-074266abfafe', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '1af448c1-54cf-2f94-01b5-e8bc77a97f94', '～ないわけにはいかない（不得不）', '表示“不得不做”，即从义务或情理上必须做，是～わけにはいかない的否定形式。', '与～なければならない（义务）混淆，本句型更强调“不做不行”的无奈；接续为动词ない形+わけにはいかない。', '日本語：上司に頼まれたら、やらないわけにはいかない。；说明：被上司拜托，不得不做。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('cef389d3-b5af-59da-9fdb-04a33179cecd', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '1af448c1-54cf-2f94-01b5-e8bc77a97f94', '～てはいけない／～てはならない（禁止・规范）', '表示禁止或不允许做某事。～てはいけない多用于个人对他人或自己的禁止，语气较直接；～てはならない多用于社会规范、道德、法律等普遍性禁止，语气较正式、书面。接续：动词て形＋はいけない／はならない。', '容易混淆两者使用场合：～てはいけない更口语化，～てはならない更正式、客观。另外，～てはならない不能用于对特定个人的命令，而～てはいけない可以。', 'ここでタバコを吸ってはいけません。（说明：这里不能吸烟，直接禁止。）／嘘をついてはならない。（说明：不应说谎，属于道德规范。）', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('cf13dac7-e85f-5ba6-8340-800251dd8309', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '3760dfca-44d9-3445-01cd-85de1f860da1', '～ばかりに', '表示因为前项的原因，导致了后项的不如意结果，带有遗憾、后悔的语气。接续：动词た形/い形容词/な形容词+な/名词+の+ばかりに。', '容易与「～だけに」混淆，但「～ばかりに」强调原因导致坏结果，而「～だけに」强调正因为如此更…。', '日本語が下手なばかりに、いい仕事が見つからなかった。；说明：正因为日语不好，才没找到好工作，表达遗憾。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('d01a1da2-edfe-51c0-aede-d5713cf4f129', '9221fc32-a051-42cb-86b1-6a9917aa004e', '42de0c7b-50d9-4159-918a-4e618d83342d', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '0e03a921-5aff-e4be-f477-4d55640b198b', '基础片假名外来语', '掌握N5常见外来语如テレビ、ラジオ、コーヒー、パン、コンピューター等，注意长音和促音的标记。', '将「コーヒー」的长音遗漏；将「パン」误认为英语单词。', '毎朝コーヒーを飲みます。说明：「コーヒー」来自荷兰语。／テレビを見ます。说明：「テレビ」是「television」的缩写。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('d05c3945-945e-5dbd-b852-dd41b1b7ab1a', '9221fc32-a051-42cb-86b1-6a9917aa004e', '42de0c7b-50d9-4159-918a-4e618d83342d', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', 'ef36118d-0ba3-29ce-b2b3-76eaeb6542ca', '动词た形（过去/完成）', '动词た形表示过去或完成，由て形将「て/で」变为「た/だ」。用于过去肯定，否定用「なかった」。注意与「ました」的区别（普通体与礼貌体）。', '将「た形」与「ました」混用；变化错误（如「読む→読んだ」误为「読んだ」正确，但「書く→書いた」误为「書いた」正确，需注意音便）；过去否定误用「ませんでした」与「なかったです」的混用。', '昨日映画を見た。；说明：昨天看了电影。／もう宿題をした。；说明：已经做完作业了。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('d07d516c-ac40-5948-a1fd-a112058a39b4', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '3760dfca-44d9-3445-01cd-85de1f860da1', '～にとって', '表示从某人的立场或角度来说。接续：名词＋にとって。', '与「に対して」混淆，但「にとって」后常接评价、判断等。', 'これは私にとって大切な思い出です。；说明：这对我来说是重要的回忆。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('d07e89f0-d257-548a-8b4a-32b5d5389261', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '1af448c1-54cf-2f94-01b5-e8bc77a97f94', '～ことにする（决定）', '表示自己做出决定，接动词辞书形或ない形。', '与～ことになる混淆：～ことにする是主观决定，～ことになる是客观规定或结果。', '毎日運動することにしました。（决定每天运动。）／来月からたばこをやめることにした。（决定下个月戒烟。）', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('d0a7a520-e1b6-580c-a9d0-f01f9fc3bab2', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '5b34d8b5-bde9-c4c6-c736-84adaaae3603', '「凶」的读音与词义', '「凶」在「凶悪」「凶器」中读「きょう」，在「凶暴」等词中亦同，但需注意「凶」与「吉」相对，表示不吉利、恶。', '将「凶」与「凶」混淆，或误读「凶悪」为「くにお」。', '例句：その凶悪犯は逮捕された。说明：「凶悪」读「きょうあく」，意为凶恶。；例句：凶器はまだ見つかっていない。说明：「凶器」读「きょうき」，指凶器。；例句：彼は凶暴な性格だ。说明：「凶暴」读「きょうぼう」，意为凶暴。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('d0b275a4-1b78-52b9-a1ed-b36c816f4107', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '1d183755-02b3-4a6d-b727-082af1ef377c', '9c37478d-2388-1380-cdea-3b62d82c3fcb', '作者态度与主张的把握', '在议论文或评论中，准确判断作者对话题的立场（赞成、反对、中立、批判等）以及主张的核心。', '误将文中引用的他人观点当作作者观点；忽略转折词后的内容；只抓表面情绪而忽略逻辑论证。', '日语例句：筆者は「確かに便利だが、それによって失われるものも大きい」と述べている。说明：通过「確かに～だが」结构，作者先让步再转折，主张重点在转折后，即认为有损失。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('d0c225c4-b2b7-5908-a7cd-f2b761d24271', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', 'ff057d86-47bc-de16-f0f9-a7b808b968e3', 'N3自他动词成对辨析（扩展）', '掌握更多N3自他动词对，如「壊れる/壊す」「落ちる/落とす」「消える/消す」，理解其使用主语和宾语的不同。', '混淆自他动词的助词使用，如将自动词「ドアが開く」误用为他动词「ドアを開く」。', '日语例句：窓が割れた。；说明：自动词「割れる」，表示自然状态。；日语例句：彼が窓を割った。；说明：他动词「割る」，强调人为动作。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('d0ce8885-e1ed-51a3-8d4e-bdc364f26996', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '1d183755-02b3-4a6d-b727-082af1ef377c', '9c37478d-2388-1380-cdea-3b62d82c3fcb', '隐含批判与委婉表达', '识别作者通过委婉、间接方式表达批评或否定，理解其真实态度，避免因表面客气而误解。', '将委婉批评当作肯定；忽略「とは言えない」「疑問が残る」等表达；未结合整体语境。', '日语例句：この提案は一見魅力的だが、実現可能性には疑問が残る。说明：表面肯定“有魅力”，实际通过“疑问”委婉表达批评。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('d13040af-7cd3-5660-b93f-2bf8e08fdf39', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '2c18e7e1-4ef0-65e3-24a7-6c97d562a122', '～そびれる', '表示“错过机会而没有做”的意思，接续：动词ます形去掉ます＋そびれる。', '与「～そこなう」相似，但「そびれる」强调因时机错过，而「そこなう」强调失败。', '日语例句：電車が混んでいて、降りそびれた。；说明：电车太挤，错过了下车。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('d15ed2bf-ec05-56e0-af97-1cafba7f15e1', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '1d183755-02b3-4a6d-b727-082af1ef377c', '6f1477f5-00be-f963-76b6-5165f568e88e', '文章结构转折识别', '识别文章中的转折词（しかし、ところが、だが）和转折结构，理解作者如何从一种观点转向另一种观点，把握论证的推进。', '忽略转折词，把前后内容当作并列；或过度关注转折而忽略转折前的铺垫。', '日语例句：多くの人は便利さを求める。しかし、便利さの追求が失うものもある。说明：转折后引出新观点，是文章重点。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('d17bf3db-cd13-5a18-a05e-0a90b3cdb702', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '3760dfca-44d9-3445-01cd-85de1f860da1', '～つつも', '表示逆接，相当于“虽然……但是……”。接动词ます形去掉ます。', '误用为单纯并列；注意与“ながらも”相近，但“つつも”更书面化。', '日语例句：悪いと知りつつも、つい嘘をついてしまった。；说明：表示虽然知道不好，但还是说了谎。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('d1b96d21-5e97-5bbe-83f9-77571bfec3fb', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '3760dfca-44d9-3445-01cd-85de1f860da1', '～を問わず', '表示“不论、不管”，前接表示类别、性质的名词，如「年齢、性別、国籍、経験」等，后项表示不受其限制。', '与「～にかかわらず」意思相近，但「～を問わず」更书面化，且前接名词时不用加「の」。', '年齢を問わず、誰でも参加できます。；说明：不论年龄，谁都可以参加。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('d1f1f734-08a2-5739-8f71-e7970a704e7c', '9221fc32-a051-42cb-86b1-6a9917aa004e', '42de0c7b-50d9-4159-918a-4e618d83342d', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '0e03a921-5aff-e4be-f477-4d55640b198b', '形容词与名词的常见搭配', '掌握如「高い山」「安い店」「新しい車」「古い本」等形容词修饰名词的常见组合。', '将「高い」用于“便宜”；将「古い」用于“年龄大”。', '高いビルがたくさんあります。说明：「高い」修饰「ビル」。／安いレストランで食べました。说明：「安い」修饰「レストラン」。／古い映画を見ました。说明：「古い」修饰「映画」。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('d1fbdbba-e019-5da1-b540-d9b4a2f6102b', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '2c18e7e1-4ef0-65e3-24a7-6c97d562a122', '～については', '表示“关于…”，用于提示话题，后项详细说明。接续：名词+については。', '与「～について」相比，「については」更强调话题本身。', 'この問題については、後ほど詳しく説明します。说明：关于这个问题稍后详谈。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('d30ffa90-a497-52ee-af7a-53ef0868cc11', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '1af448c1-54cf-2f94-01b5-e8bc77a97f94', '～ばかり（限定・刚刚）', '接在动词て形后表示“刚刚做完”，接在名词后表示“只有、尽是”，接在动词た形后也可表示“刚刚”。', '与～ところだ混淆：～たばかり强调时间间隔短，～たところだ更强调刚结束的瞬间。', '食べたばかりです。（刚刚吃过。）／彼は文句ばかり言っている。（他净发牢骚。）', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('d318c88e-94c6-5732-ad53-6b747ecb2a62', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '5b34d8b5-bde9-c4c6-c736-84adaaae3603', '「計る」与「測る」的用法区分', '「計る」读「はかる」，用于时间、数量、计划；「測る」读「はかる」，用于长度、温度、速度等物理量。', '混淆两者，如「体重を計る」应为「測る」；「時間を測る」也可但常用「計る」。', '時間を計（はか）る。；说明：计时。／距離を測（はか）る。；说明：测量。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('d37474fe-94a0-50a1-b92f-9a05e913b83c', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '1d183755-02b3-4a6d-b727-082af1ef377c', '9c37478d-2388-1380-cdea-3b62d82c3fcb', '多义表达与歧义的消解', '根据上下文确定多义词或模糊表达的具体含义，解决因省略、指代不明等造成的理解困难。', '固守词典义，忽略语境义；未利用前后文线索；忽视文化背景知识。', '日语例句：彼は「あれ」を買った。说明：「あれ」的具体指代需从上文推断，可能指之前提到的某物。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('d3c62ab0-6dc7-5d93-aed6-488b3caa3727', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '0545d0ec-89d1-a8aa-99f9-78b30fcbacb1', '同形汉字词在不同语境下的读音选择', 'N2需根据语境区分同形词的不同读音，如「時間（じかん）」与「時（とき）」、「場所（ばしょ）」与「所（ところ）」。复合词中可能因词性、意义不同而改变读音。', '学习者常混淆音读与训读，如将「手紙（てがみ）」读作「しゅし」，或将「下手（へた/したて）」误读。', '日语例句：この本は読みやすい。；说明：「本（ほん）」为音读，但「本（もと）」表示根源时训读，如「元本（がんぽん）」与「本（もと）を正す」。日语例句：彼は上手に歌う。；说明：「上手（じょうず）」为音读，而「上手（うわて）」表示上方或优势时训读。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('d3e731e1-3d71-5c24-8b03-f5eb0ed09a81', '9221fc32-a051-42cb-86b1-6a9917aa004e', '42de0c7b-50d9-4159-918a-4e618d83342d', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', 'ef36118d-0ba3-29ce-b2b3-76eaeb6542ca', 'て形连接', '动词て形用于连接多个动作或状态，表示先后顺序、方式或原因。接续：动词て形（五段动词音便等）。', '误将て形与ます形混用；忘记音便规则（如書いて、読んで）。', '朝起きて、顔を洗います。说明：先起床后洗脸，表示动作先后。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('d41c766f-6784-5ae2-b344-27f3ba8e96b9', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', 'dd4e968a-3d37-98a7-3819-a5fc4c117122', '～てはいけない（禁止）', '表示“不可以做……”，接续：动词て形+はいけない。口语中可用「～ちゃだめ」。', '与～てもいい混淆，注意肯定否定。', '日本語：ここでタバコを吸ってはいけません。；说明：这里不可以吸烟。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('d482f806-9170-550c-8811-08511b8e72fa', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '1af448c1-54cf-2f94-01b5-e8bc77a97f94', '～ていくことになる（过程・结果）', '表示经过某个过程后最终成为某种结果或状态，强调变化的过程和最终归宿。', '与～ことになる（直接结果）混淆，本句型更强调过程性；接续为动词て形+いく+ことになる。', '日本語：何度も失敗していくことになるが、諦めないつもりだ。；说明：表示多次失败后最终的结果，强调过程。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('d489d2ba-7ce5-5aa9-9515-4c77bede74f8', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', 'dd4e968a-3d37-98a7-3819-a5fc4c117122', '～てくださる（长辈为我做・尊敬）', '～てくれる的尊敬语，用于长辈或上级为说话人做某事。接续：动词て形＋くださる（くださいます）。', '对平辈使用显得过于尊敬；误用为～ていただく（谦逊）；注意くださる的活用（くださいます）。', '先生が本を貸してくださいました。说明：老师借书给我了。／社長が挨拶してくださった。说明：社长致辞了。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('d50dafec-f0f8-5ced-a5e7-f59f2ebeb1b8', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', 'dd4e968a-3d37-98a7-3819-a5fc4c117122', '～ていただけませんか（请求・谦逊）', '用谦逊语请求对方为自己做某事，比～てくださいませんか更郑重，常用于正式场合或对上级。接续：动词て形＋いただけませんか。', '误用为对平辈或下级使用，显得过于生硬；与～てもらえませんか混淆，但前者更正式。', 'この書類にサインしていただけませんか。；说明：郑重请求对方在文件上签字。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('d520650a-dc9f-555e-9ef4-a2d8b9e9f6df', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', 'dd4e968a-3d37-98a7-3819-a5fc4c117122', '～てはいけない／～てはならない（禁止）', '表示禁止，口语常用～てはいけない，书面语或正式场合用～てはならない。接续：动词て形＋は＋いけない/ならない。', '误将～てはならない用于日常口语；忘记在て形后加は；与～てもいい混淆。', 'ここで写真を撮ってはいけません。说明：禁止在此拍照。／規則を破ってはならない。说明：不可违反规则。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('d5282d6d-a613-5e6e-8072-4113c9db82bc', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', 'baa9b5c2-5b94-4f9b-7ced-3a8c3cde4cb3', '拟声拟态词的基本用法', 'N4需掌握常见拟声拟态词如「わくわく」「どきどき」「ぴかぴか」「すらすら」「ぐっすり」等，理解其语义（心情、状态、声音）及在句中常以「と」或直接修饰动词、な形容词化修饰名词的用法。', '混淆「わくわく」（期待兴奋）与「どきどき」（心跳不安）；误将拟态词当作普通副词而漏掉「と」；用「に」代替「と」修饰动词。', '日语例句：試験の前はどきどきする。；说明：「どきどき」表示心跳加速，常与「する」搭配。日语例句：彼女はすらすらと日本語を話す。；说明：「すらすら」表示流畅，修饰「話す」时可用「と」。日语例句：子どもはわくわくしながらプレゼントを開けた。；说明：「わくわく」表示兴奋期待，可后续「しながら」。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('d533bf67-c6b1-59ec-bab3-bfaa01c979df', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '5b34d8b5-bde9-c4c6-c736-84adaaae3603', '「気」的多种读音与词义', '「気」在常用词中多读「き」，如「気分」「気持ち」，但在「気配（けはい）」「気配り（きくばり）」等词中读音不同，需区分。', '将「気配」误读为「きはい」，或混淆「気配」与「気配り」的词义。', '例句：彼女は気配を感じて振り返った。说明：「気配」读「けはい」，意为迹象、气息。；例句：彼は細かい気配りができる。说明：「気配り」读「きくばり」，意为细心照料。；例句：今日は気分がいい。说明：「気分」读「きぶん」，指心情。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('d54839b6-1422-503d-8c64-23a6415722a2', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '5b34d8b5-bde9-c4c6-c736-84adaaae3603', '「要」「用」「洋」等「よう」同音汉字的读音与词义区分', '「よう」读音的汉字包括「要（よう）」「用（よう）」「洋（よう）」「様（よう）」「曜（よう）」等。本知识点帮助学习者区分这些汉字在词语中的具体用法。', '易将「要点」误写为「用点」，或将「洋服」与「和服」混淆；需注意「要」表示重要，「用」表示使用，「洋」表示西洋。', E'日语例句：要点（ようてん）をまとめる。；说明：「要」读「よう」，表示要点。\\n日语例句：洋服（ようふく）を買う。；说明：「洋」读「よう」，表示西洋式。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('d55d161f-2111-5a14-a56f-bd55378aa255', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', 'ff057d86-47bc-de16-f0f9-a7b808b968e3', 'N3基础拟声拟态词（扩展二）', '掌握N3中常见拟声拟态词如「にこにこ」「わくわく」「どきどき」「すっきり」「さっぱり」「ぐっすり」等，注意其修饰的动作、状态及感情色彩。', '混淆「わくわく」（期待兴奋）与「どきどき」（心跳不安）；「さっぱり」与「すっきり」在清爽感上的细微差别。', '日语例句：彼女はにこにこ笑っている。／試験が終わってすっきりした。；说明：「にこにこ」形容微笑，「すっきり」表示心情舒畅。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('d682304f-6623-53d1-a067-9220537ee337', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '1af448c1-54cf-2f94-01b5-e8bc77a97f94', '～たらいいのに（要是…就好了）', '与～ばいいのに类似，但接续为动词た形+らいいのに，语气更口语化。', '与～たらいい（建议）混淆，本句型带有遗憾；注意接续不同。', '日本語：一緒に来たらいいのに、どうして来ないの？；说明：对对方不来表示遗憾。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('d68ca8a4-ef79-5a26-ba26-9bb7c966d00a', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '1d183755-02b3-4a6d-b727-082af1ef377c', '40ed56d1-acbd-4a8b-6284-2df8b9423e8e', '推断作者态度与立场', '通过措辞、反问、让步等表达方式推断作者对话题是赞成、反对还是中立，并能找出依据。', '只凭个人好恶判断；忽略“～べきだ”“～ではないか”等表达态度的句式。', '日语例句：確かにインターネットは便利だ。しかし、それに頼りすぎるのは危険ではないだろうか。说明：通过“しかし”和“ではないだろうか”可推断作者对过度依赖网络持批判态度。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('d696d00b-f2f3-5892-9ff5-eb5e0e4b4325', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '1af448c1-54cf-2f94-01b5-e8bc77a97f94', '～てもいい（许可）', '表示许可或允许。接续：动词て形+もいい（です）。口语中可省略为～ていい。疑问形式～てもいいですか用于请求许可。', '与～てはいけない（禁止）对应。注意在正式场合请求许可时常用～てもよろしいですか。', '日本語：この席を使ってもいいですか。；说明：询问“可以坐这个座位吗？”', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('d6ac4d82-f60e-5753-b43c-ab4c8d991b44', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '5b34d8b5-bde9-c4c6-c736-84adaaae3603', '「仰天」与「驚愕」的语体区分', '「仰天」较口语化，表示非常吃惊；「驚愕」是书面语，强调震惊。N1需根据文体选择。', '在正式文章中误用「仰天」；混淆「仰天」与「呆然」的语感。', 'そのニュースに仰天した。（听到那消息大吃一惊）说明：「仰天」日常。／その結果に驚愕した。（对那结果感到震惊）说明：「驚愕」书面。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('d702f9cb-643a-5500-909e-5c7739346b95', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '2c18e7e1-4ef0-65e3-24a7-6c97d562a122', '～すら／ですら', '表示“甚至”的意思，举出极端例子。接续：名词＋すら／ですら。', '与「さえ」相似，但「すら」更书面化，且「ですら」用于强调主语。', '日语例句：そんなことは子供すら知っている。；说明：那种事连小孩都知道。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('d72c4b66-fb86-5844-9747-64c87febc7e4', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', 'baa9b5c2-5b94-4f9b-7ced-3a8c3cde4cb3', '动词ない形表示否定与请求', '掌握动词ない形的基本否定意义，以及「～ないでください」表示禁止请求、「～なければなりません」表示义务的用法。', '混淆「～ないでください」与「～なくてもいいです」；忘记「なければなりません」中ない形接续的变化。', 'ここでタバコを吸わないでください。说明：表示“请不要在这里吸烟”。／宿題をしなければなりません。说明：表示“必须做作业”。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('d770ac50-e7e1-57d2-a4d3-270a71fc4094', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '0545d0ec-89d1-a8aa-99f9-78b30fcbacb1', '「～てある」与「～ておく」的结果状态与事先准备', 'N2需区分「～てある」表示动作完成后留下的状态（他动词+てある），「～ておく」表示事先做好某事或放置不管。例如「窓が開けてある」「資料をコピーしておく」。', '将「～てある」误用为自动词；混淆「～ておく」的“事先准备”与“放任”两种含义；忽视与「～ている」的区别。', '日本語：壁に絵が掛けてある。；说明：表示有人挂好后的状态。／日本語：明日の会議のために資料を読んでおく。；说明：表示事先准备。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('d7b898eb-f85f-5224-ada5-cfeadf8d6dc3', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '1d183755-02b3-4a6d-b727-082af1ef377c', '6f1477f5-00be-f963-76b6-5165f568e88e', '作者观点推断', '从文章中推断作者对某话题的态度（赞成、反对、中立等），注意委婉表达。', '将文中他人观点误认为作者观点；忽视否定句和反问句。', '日语例句：確かに便利だが、それで失うものもあるのではないか。说明：通过反问暗示作者持保留态度。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('d85a8796-a294-5be1-a515-449f95d8087c', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', 'baa9b5c2-5b94-4f9b-7ced-3a8c3cde4cb3', '频率与程度副词的用法', '掌握「いつも、よく、ときどき、あまり、ぜんぜん」等频率副词以及「とても、すこし、かなり」等程度副词，注意与否定呼应。', '把「あまり」「ぜんぜん」用于肯定句；混淆「よく」与「たくさん」。', '日语例句：あまりお酒を飲みません。；说明：「あまり」与否定呼应，表示“不太”。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('d8b3f974-876e-5fa0-960e-6804eb070373', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '3760dfca-44d9-3445-01cd-85de1f860da1', '～に限らず', '表示“不仅限于…，也…”，常与「も」「でも」等呼应，强调范围扩大。接续：名词+に限らず。', '与「～を問わず」的区别：前者强调“不仅…也…”，后者强调“不论…都…”。', '女性に限らず、男性もこの化粧品を使っています。；说明：不仅是女性，男性也用这个化妆品。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('d8e28939-e2ab-50a7-8b1f-6b3cbac800f1', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', 'ff057d86-47bc-de16-f0f9-a7b808b968e3', '自他动词成对辨析', '识别N3常见的自他动词对（如「開く/開ける」「壊れる/壊す」），理解其使用场景和主语差异。', '混淆自动词和他动词的用法，例如「ドアが開ける」误用他动词；忽视他动词需要宾语。', '日语例句：ドアが開いた。ドアを開けた。；说明：前者自动词表示状态，后者他动词表示动作。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('d9da2afd-af1e-50c3-aade-a0b50dbda32e', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '0545d0ec-89d1-a8aa-99f9-78b30fcbacb1', '表示时间的「～ところだ」「～ばかりだ」「～最中だ」', '掌握「～ところだ」（正要做/正在做/刚做完）、「～ばかりだ」（刚刚做完，强调时间近）、「～最中だ」（正在…进行中）的用法区别。', '学习者常混淆「～たばかりだ」与「～たところだ」，前者强调动作刚结束，后者强调时间点，但有时可互换。', '日本語例：今、出かけるところだ。（正要出门）／ご飯を食べたばかりだ。（刚吃完饭）／会議の最中だ。（正在开会）。说明：三者表示的时间状态不同。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('da1a15c5-59ce-5d7c-ae9e-8cba180c5dc6', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', 'dd4e968a-3d37-98a7-3819-a5fc4c117122', '～てもいいです（可以…）', '表示许可，口语中常用～てもいい。接续：动词て形＋も＋いいです。', '与～てもかまいません混淆（后者更正式）；在正式场合使用～てもいい显得随意；与～てはいけません混淆。', 'ここに座ってもいいです。说明：可以坐在这里。／質問してもいいですか。说明：可以提问吗？', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('da4695ee-8f3f-5caf-97cb-7076c000e6a4', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', 'ff057d86-47bc-de16-f0f9-a7b808b968e3', 'N3条件表达相关词汇（扩展三）', '掌握N3中条件表达相关词汇如「条件」「前提」「場合」「際」等，并区分「場合」与「際」在正式度和时间上的差异。', '「場合」一般条件，口语常用；「際」较正式，多用于书面或郑重场合，且常表示“在……的时候”；「条件」是名词，不是接续词。', '例句：雨の場合、試合は中止だ。说明：「場合」表示情况；例句：出発の際には、必ず連絡してください。说明：「際」表示在……的时候，较正式；例句：この条件を満たす必要がある。说明：「条件」名词，表示条件。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('da583a26-ff41-58a2-b1b2-f1d3a3368a30', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', 'dd4e968a-3d37-98a7-3819-a5fc4c117122', '～ている（结果状态）', '表示动作完成后留下的状态，常用于瞬间动词（如：死ぬ、結婚する、着く）后，描述当前可见的结果。', '误将瞬间动词的～ている理解为进行中，如把「結婚している」说成正在结婚。', '日本語：彼はもう結婚している。；说明：表示已经结婚，状态持续。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('da6695ac-2aa9-53ed-a271-dc77c3b8b7df', '9221fc32-a051-42cb-86b1-6a9917aa004e', '42de0c7b-50d9-4159-918a-4e618d83342d', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', 'ef36118d-0ba3-29ce-b2b3-76eaeb6542ca', 'てもいいよ（许可，亲密）', '口语中给亲密的人许可，语气轻松。', '对长辈或上级使用会失礼。', 'ここで待ってもいいよ。；说明：你可以在这里等。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('da6da93a-884e-5bb4-a325-fc23a2ea87bd', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '1d183755-02b3-4a6d-b727-082af1ef377c', '6f1477f5-00be-f963-76b6-5165f568e88e', '引用观点态度理解', '当作者引用他人观点或数据时，判断作者是赞同、反对还是中立，常通过引用后的评价句或转折词体现。', '把作者引用的话当作作者本人的观点，忽略作者的评价。', '日语例句：ある専門家は「AIが仕事を奪う」と主張している。しかし、実際には新しい仕事も生まれている。说明：作者引用后使用“しかし”表示不赞同该主张。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('da8dc477-65cc-5878-85d7-3c8d45279212', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '5b34d8b5-bde9-c4c6-c736-84adaaae3603', '「そっくり」与「そのまま」的区分', '「そっくり」表示“一模一样、完全相似”，也可表示“全部”；「そのまま」表示“原样、照旧”。', '将「そっくり」用于“保持原状”；「そのまま」不能表示相似。', '日语例句：父にそっくりだ。；说明：表示“和父亲一模一样”。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('daf8ca04-7a04-59ae-b203-7ac57022b733', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '1af448c1-54cf-2f94-01b5-e8bc77a97f94', '～ていく／～てくる（方向・変化）', '表示动作的方向（去/来）或时间上的变化过程。～ていく表示从现在到将来或远离说话人，～てくる表示从过去到现在或靠近说话人。', '混淆方向性和时间性用法；在表示变化时，～ていく用于从当前向未来变化，～てくる用于从过去到现在的变化，不能互换。', '日本語が上手になっていくでしょう。（会越来越好吧，表示将来变化。）／だんだん寒くなってきましたね。（渐渐冷起来了，表示过去到现在的变化。）', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('db04f9d6-b5b3-5d0b-92c5-d102900f37f3', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '5b34d8b5-bde9-c4c6-c736-84adaaae3603', '「素」的多种读音与词义', '「素」在N1中常见读音有「そ」「す」，词义包括“本来的、根本的”“元素”“白色”等。需根据词语区分，如「素人（しろうと）」「素顔（すがお）」「素直（すなお）」「素因（そいん）」「素朴（そぼく）」。', '误将「素人」读作「そじん」或「すじん」，实际读「しろうと」；「素顔」读「すがお」而非「そがお」。', '彼は素人（しろうと）ながら、なかなか上手だ。说明：素人指外行、非专业者。；彼女は素顔（すがお）で出かけた。说明：素顔指不化妆的脸。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('db3d5a8c-27ec-5413-9466-254ab9fe7a1e', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '0545d0ec-89d1-a8aa-99f9-78b30fcbacb1', '名词与动词的固定搭配', '掌握N2中名词与动词的惯用搭配（如「注意を払う」「影響を及ぼす」「役割を果たす」），避免直译错误。', '按汉语直译搭配，如将“产生影响”说成「影響を与える」虽可，但「影響を及ぼす」更自然；或搭配不当。', '日语例句：彼は社会に影響を及ぼした。；说明：「影響を及ぼす」为固定搭配，意为施加影响。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('db585614-d68d-5d14-bfa0-a39ee67d508e', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '3760dfca-44d9-3445-01cd-85de1f860da1', '～にかかわる', '表示“与…相关、关系到…”，强调涉及重要事情或人的命运、生命等，语气比「～に関係する」更重。接续：名词＋にかかわる。', '易与「～に関わる」混淆，但「～にかかわる」更强调重大影响；注意「～にかかわる」后接表示重要事物的名词，如「命」「名誉」「将来」等。', '日本語：これは私の名誉にかかわる問題だ。；说明：这是关系到我的名誉的问题。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('db6be76f-d776-5965-96a1-d9e8c7e43141', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '3760dfca-44d9-3445-01cd-85de1f860da1', '～ことができる（可能）', '表示能力或可能性，相当于“能够…”。接动词辞书形。', '与「～ことにする」「～ことになる」混淆；误用为意志动词的许可。', '日本語で手紙を書くことができる。说明：表示有能力用日语写信。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('dbb4a376-b623-5100-ae15-45803bc07966', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '1af448c1-54cf-2f94-01b5-e8bc77a97f94', '～ておく（事先准备）', '表示为了将来某个目的而事先做某事，或让状态保持。口语中可缩约为～とく。', '与～てある混淆：～ておく强调动作的预先性，～てある强调结果状态。', '旅行の前に切符を買っておきます。（旅行前先买好票。）／電気をつけておいてください。（请把灯开着。）', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('dbf685c7-f426-5650-97c8-f6a3df784994', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', 'ff057d86-47bc-de16-f0f9-a7b808b968e3', '基础拟声拟态词', '掌握N3中常用的拟声拟态词，如「わくわく」「どきどき」「すっきり」「ぐっすり」等，理解其表达的心理或状态。', '混淆拟声词和拟态词，如将「わくわく」（期待）与「どきどき」（紧张）混用；忽视其在句中的副词用法。', '日语例句：試験の結果を待つ間、どきどきした。；说明：どきどき表示心跳加速，用于紧张。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('dc20d37b-b304-5752-ad13-3d44a51c529b', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '2c18e7e1-4ef0-65e3-24a7-6c97d562a122', '～に対しても', '表示对某对象也……，相当于「～にも」。用于补充说明或强调。', '与「～に対して」相比，「に対しても」表示“也”，常用于列举。', '日本語：彼は親に対しても、友達に対しても、同じ態度だ。；说明：他对父母和朋友态度都一样。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('dc7c8e1c-a712-5236-b32e-473d290a896e', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '1d183755-02b3-4a6d-b727-082af1ef377c', '9c37478d-2388-1380-cdea-3b62d82c3fcb', '定义与换言表达的识别', '理解文中对术语或概念的重新定义、解释或换言（如「つまり」「すなわち」「言い換えれば」），把握核心含义。', '忽略换言标志，导致理解偏差；将具体例子当作定义；混淆定义与补充说明。', '日语例句：持続可能な開発とは、将来の世代のニーズを損なわずに現在のニーズを満たすことだ。说明：「とは」引出定义，后续是核心解释。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('dce753d2-9b7e-515f-8c29-5bde72f872e3', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '1d183755-02b3-4a6d-b727-082af1ef377c', '40ed56d1-acbd-4a8b-6284-2df8b9423e8e', '因果关系理解与区分', '能识别文章中明确或隐含的因果关系，区分原因与结果，注意“～ため”“～ので”“～から”等表达。', '颠倒因果；忽略多重原因或结果。', '日语例句：昨夜、台風が来たため、今朝の電車は止まった。说明：原因是台风，结果是电车停运。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('dd529e54-54d6-5770-86d8-d3dc9d01ad81', '9221fc32-a051-42cb-86b1-6a9917aa004e', '42de0c7b-50d9-4159-918a-4e618d83342d', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '0e03a921-5aff-e4be-f477-4d55640b198b', '常用动词的汉字读音', '掌握N5级别高频动词（如行く、来る、食べる、見る、聞く、話す、読む、書く等）的汉字表记与读音，注意音读和训读的区别。', '将训读动词误用音读，如把「行く」读成「こう」；混淆「見る」和「観る」的使用场景。', '毎日学校へ行きます。说明：「行く」读作「いく」，训读。／映画を見ます。说明：「見る」读作「みる」，表示观看。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('dd60439f-0c78-53b7-8770-6c15b0b53401', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '3760dfca-44d9-3445-01cd-85de1f860da1', '～にかかわる問題', '表示“与…相关的问题”，强调问题的重要性或严重性。', '误用为“～に関する問題”，但本句型更强调问题直接关系到核心利益或存亡。', '日本語：環境問題は人類の生存にかかわる問題だ。；说明：环境问题是关系到人类生存的问题。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('dd73b1d6-f3ec-56eb-b954-b3f4495972e6', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '3760dfca-44d9-3445-01cd-85de1f860da1', '～てくる', '表示动作的方向（向说话人方向移动）或时间上的由过去到现在的变化。', '注意与「～ていく」的方向相反。表示变化时，「～てくる」强调从过去到现在的趋势。', '日本語が上手になってきた。；说明：日语逐渐变好了（到现在）。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('dd78fa8d-b536-5669-8ee8-fa3e769e674d', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '3760dfca-44d9-3445-01cd-85de1f860da1', '～ておく', '表示事先做好某种准备，或让某种状态持续。', '注意「～ておく」与「～てある」的区别：「～ておく」强调动作的预先准备，「～てある」强调动作结果的存续。', '旅行の前にホテルを予約しておく。；说明：旅行前事先预约酒店。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('ddb9c969-c4cc-57e4-933a-6df8605f600b', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '3760dfca-44d9-3445-01cd-85de1f860da1', '～てもいいでしょう', '表示推测的许可，相当于“大概可以…吧”。', '比「～てもいい」更委婉，常用于建议或推测。', 'この本を借りてもいいでしょう。；说明：借这本书大概可以吧。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('ddca9edb-11e7-5fb7-a550-1210da5ebb97', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '5b34d8b5-bde9-c4c6-c736-84adaaae3603', '「必ずしも」的否定呼应', '掌握「必ずしも」与否定形式呼应，表示“未必”。', '误用为肯定句。', '日本語：金持ちが必ずしも幸せとは限らない。；说明：有钱人未必幸福。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('de0218ba-1b02-5adb-a379-f57da930707f', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '5b34d8b5-bde9-c4c6-c736-84adaaae3603', '「を残して」的用法', '掌握「を残して」表示“留下、剩下”。', '与「を除いて」混淆，但「を残して」强调剩余。', '日本語：三日を残して試験が始まる。；说明：还剩三天考试开始。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('de26cf47-c9f6-57e6-a763-bda8c78b53a8', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '5b34d8b5-bde9-c4c6-c736-84adaaae3603', '「拒否」与「断る」的语体区分', '「拒否」是正式书面语，表示明确拒绝；「断る」是口语常用，表示谢绝、事先打招呼。N1需根据语境选择。', '在正式场合误用「断る」；混淆「拒否」与「拒絶」的细微差别。', '政府は難民の受け入れを拒否した。（政府拒绝接收难民）说明：「拒否」用于正式决定。／友達の誘いを断った。（拒绝了朋友的邀请）说明：「断る」用于日常。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('de2d17a6-a445-500f-8081-9b80d51cb1dc', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '3760dfca-44d9-3445-01cd-85de1f860da1', '～ものがある', '表示“有……之处”“令人感到……”，相当于“有……的感觉”。接动词或形容词普通形。', '误用于具体事物；注意与“～ことがある”区别，后者表示有时发生。', '日语例句：彼の話には感動するものがある。；说明：他的话有令人感动之处。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('de48ec3a-677b-5c93-80b8-50e9f55b2405', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '3760dfca-44d9-3445-01cd-85de1f860da1', '～にかかわるほど', '表示“关系到…的程度”，强调影响之大。接续：名词＋にかかわるほど＋动词/形容词。', '注意「ほど」前接动词时用「にかかわるほど」，但更常见的是「～にかかわるほど重大な」等；不要与「～ほど」的普通用法混淆。', '日本語：彼の失敗は会社の存続にかかわるほど深刻だった。；说明：他的失败严重到关系到公司的存续。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('de4a5632-ef83-5088-9376-83d155dc6aed', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', 'dd4e968a-3d37-98a7-3819-a5fc4c117122', '～ので（原因・客观）', '表示客观原因，后句多为既成事实或自然结果，语气比から柔和。接续：动词/形容词普通形+ので，名词/な形容词+な+ので。', '注意な形容词和名词接续需加な；から更主观，ので更客观，请求时常用ので。', '日本語：風邪をひいたので、学校を休みました。；说明：因为感冒了，所以没去学校。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('ded43238-0c2b-5dae-93fb-44493d443c81', '9221fc32-a051-42cb-86b1-6a9917aa004e', '42de0c7b-50d9-4159-918a-4e618d83342d', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', 'ef36118d-0ba3-29ce-b2b3-76eaeb6542ca', '～てください（ます形接续）', '用于礼貌地请求对方做某事，接续为动词て形+ください。注意与「～てくださいませんか」等更礼貌形式区分。', '误将「ください」当作动词原形，或接续错误（如用ます形直接加ください）。', '日语例句：ここに名前を書いてください。；说明：请求对方在这里写名字。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('dfd86e57-79b9-5b95-96bf-0390805e9412', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '1d183755-02b3-4a6d-b727-082af1ef377c', 'fc58533f-fd29-5132-8f21-fd381828e3c8', '理解引用与转述', '掌握「〜と〜言う」「〜と〜思う」「〜と言っていた」等引用结构，区分直接引用与间接转述。', '混淆「と言う」与「と思う」；忽视转述中时态的变化。', '日语例句：彼は明日来ると言っていました。说明：间接转述他人的话。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('dfe9bb3f-6dc3-5db6-8927-fd94d6d1bba4', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', 'ff057d86-47bc-de16-f0f9-a7b808b968e3', 'N3正式与口语同义词的转换', '掌握如「しかし」与「でも」、「です」与「だ」、「たくさん」与「いっぱい」等在正式与口语场景中的转换。', '在正式场合使用口语词，如对上司说「でも」；应使用「しかし」。', '日语例句：しかし、問題があります。；说明：「しかし」正式。；日语例句：でも、時間がない。；说明：「でも」口语。；日语例句：たくさんあります。；说明：「たくさん」较正式，「いっぱい」口语。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('e068fd77-cd36-509a-9e5c-7f8b48cdbd56', '9221fc32-a051-42cb-86b1-6a9917aa004e', '42de0c7b-50d9-4159-918a-4e618d83342d', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '0e03a921-5aff-e4be-f477-4d55640b198b', '时间名词的近义辨析', '区分「時間」「時」「頃」「間」等表示时间的名词，注意用法差异。', '将「時間」用于具体时刻；将「間」用于时间段。', '今、時間がありますか。说明：「時間」指空闲时间。／三時に会いましょう。说明：「時」指具体时刻。／子供の頃、田舎に住んでいました。说明：「頃」指大约时期。／夏休みの間、旅行しました。说明：「間」指期间。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('e08687e1-571e-597e-8567-23e1c1122098', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '3760dfca-44d9-3445-01cd-85de1f860da1', '～ことになる（客观决定）', '表示由于外部原因或客观情况导致的结果、决定，相当于“就成了…”。接动词辞书形/ない形。', '与「～ことにする」（主观决定）混淆；误用为个人意愿。', '来月から東京で働くことになった。说明：客观决定去东京工作。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('e08c0eb3-144c-5946-bc5c-595ad451061e', '9221fc32-a051-42cb-86b1-6a9917aa004e', '42de0c7b-50d9-4159-918a-4e618d83342d', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', 'ef36118d-0ba3-29ce-b2b3-76eaeb6542ca', 'てもいい（许可）', '动词て形+もいい表示允许做某事。接续：て形+もいい。', '与てはいけない混淆；口语中も可省略。', 'ここに座ってもいいですか。说明：可以坐这里吗？', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('e0aa285c-ff68-54d1-ba26-c3ba37a29916', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '0545d0ec-89d1-a8aa-99f9-78b30fcbacb1', '拟声拟态词中表示状态持续与瞬间变化的区分', 'N2拟声拟态词如「じっと」（一动不动）、「ぱっと」（突然）等，有的表示持续状态，有的表示瞬间变化。本知识点帮助区分这两类。', '将「じっと」误用于瞬间动作，或将「ぱっと」误用于持续状态。', '日语例句：彼はじっと考え込んだ。；说明：「じっと」表示静止不动地持续，而「ぱっと」表示瞬间亮起或突然出现。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('e1238bda-2166-5fd7-93f5-2b46ac285657', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '1d183755-02b3-4a6d-b727-082af1ef377c', '6f1477f5-00be-f963-76b6-5165f568e88e', '快速略读抓要点', '在有限时间内通过略读标题、首尾句、关键词快速把握文章大意。', '逐字阅读导致时间不足；忽略段落首尾句。', '日语例句：文章のタイトルと各段落の最初の文だけを読んで、大意を把握する。说明：这是考试中的实用技巧。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('e126427e-5286-5694-8d03-478f1740b041', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '0545d0ec-89d1-a8aa-99f9-78b30fcbacb1', '接头辞・接尾辞的语义功能（如「無～」「～的」「～化」）', 'N2中常见接头辞如「無」「非」「未」等，接尾辞如「的」「化」「性」等，它们改变词义或词性。本知识点帮助推测派生词的意义。', '混淆「無」与「非」的细微差别，如「無関心」与「非関心」；误用「～的」构成不存在的形容词。', '日语例句：この計画は非現実的だ。；说明：「非」表示否定，「的」构成形容动词，整体表示“不现实”。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('e1df329e-7c2b-50fc-9752-98fea3922d71', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '2c18e7e1-4ef0-65e3-24a7-6c97d562a122', '～にしても～にしても', '表示“无论……还是……都……”，列举两个对立或同类事项，后项表示不受其影响。接续：名词/动词/形容词+にしても～にしても。', '与「～にせよ～にせよ」意思相同，但「にしても」更口语化；注意后项必须为肯定或否定的一般结论。', '日本語：行くにしても行かないにしても、連絡は必要だ。；说明：无论去还是不去，都需要联系。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('e230c65a-7ece-5cbd-877b-756f1c630e33', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '0545d0ec-89d1-a8aa-99f9-78b30fcbacb1', '表示传闻的「～そうだ」「～とのことだ」「～とか」', '掌握传闻表达「～そうだ」（听说，接普通形）、「～とのことだ」（据说，较正式）、「～とか」（听说，口语）的接续和语感区别。', '学习者常将「～そうだ」与样态「～そうだ」混淆，传闻「～そうだ」前接句子的普通形，样态前接动词ます形或形容词词干。', '日本語例：明日は雨だそうだ。（听说明天下雨）／社長は来週来るとのことだ。（据说社长下周来）／彼は結婚したとか。（听说他结婚了）。说明：三者均为传闻，但正式度不同。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('e2421d99-ca2b-5708-8209-df3363ca3046', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '3760dfca-44d9-3445-01cd-85de1f860da1', '～ように求める', '表示要求、请求对方做某事，相当于“要求…”。接动词辞书形/ない形。', '与「～ように言う」混淆；误用为命令语气。', '政府は市民に協力するように求めた。说明：政府要求市民合作。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('e2b39d12-12d0-5728-a065-fd6e33048ec5', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '0545d0ec-89d1-a8aa-99f9-78b30fcbacb1', '近义词使用域限制（如「思う」与「考える」）', 'N2近义词如「思う」表示主观感觉，「考える」表示理性思考；「見る」与「観る」等有使用域差异。本知识点辨析使用域。', '将「考える」用于瞬间感觉，或将「思う」用于长时间思考。', '日语例句：彼は将来について深く考えている。；说明：「考える」表示有逻辑的思考，而「思う」更偏向直觉，不能互换。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('e2cdee45-f6b7-58f5-9d16-ea45d7a31044', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '2c18e7e1-4ef0-65e3-24a7-6c97d562a122', '～に限りがある', '表示有限、有界限。接续：名词+に限りがある。', '注意与「～に限る」（最好…）区分。', '時間には限りがあるから、計画的に進めよう。说明：时间有限。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('e34f44fc-4799-5410-8c0d-08612d1ed8cc', '9221fc32-a051-42cb-86b1-6a9917aa004e', '42de0c7b-50d9-4159-918a-4e618d83342d', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '0e03a921-5aff-e4be-f477-4d55640b198b', '身体部位词汇的汉字读音', '掌握头、目、耳、口、手、足等身体部位名词的读音，注意与动词搭配时的用法。', '将「手」读成「しゅ」而非「て」；混淆「足」和「脚」的区别。', '手を洗ってください。说明：「手」读作「て」。／目が疲れました。说明：「目」读作「め」。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('e357c44c-95e4-5539-accb-4749c1e2f90c', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', 'ff057d86-47bc-de16-f0f9-a7b808b968e3', '与身体部位相关的惯用表达', '掌握N3中与身体部位相关的惯用语，如「頭が下がる」「足を運ぶ」「手を貸す」等，理解其比喻意义。', '按字面理解，如将「頭が下がる」理解为低头；混淆「手を貸す」和「手伝う」的细微差别。', '日语例句：彼の努力には頭が下がる。；说明：頭が下がる表示佩服。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('e3743760-88c6-5d6f-844c-85d8291d8204', '9221fc32-a051-42cb-86b1-6a9917aa004e', '42de0c7b-50d9-4159-918a-4e618d83342d', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '0e03a921-5aff-e4be-f477-4d55640b198b', '一段动词的汉字读音', 'N5常见一段动词（如「見る」「食べる」「寝る」）的汉字读音及对应假名，注意与五段动词区分。', '将「見る」读成「みる」以外的音，或混淆「食べる」与「飲む」的读音。', '日本語例：毎朝パンを食べます。说明：「食べる」读作「たべる」，是上一段动词。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('e389c3f3-e706-52f0-88c7-120c982483e8', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', 'ff057d86-47bc-de16-f0f9-a7b808b968e3', 'N3常见量词的高级用法（扩展三）', '掌握N3中量词的特殊读法和搭配，如「～軒（けん）」「～冊（さつ）」「～着（ちゃく）」「～本（ほん）」「～匹（ひき）」等，注意数字与量词结合时的音便。', '「三本（さんぼん）」「六匹（ろっぴき）」等音便易错；「～着」用于衣服，但「～席」用于座位，容易混淆。', '例句：本を三冊買った。说明：「冊」读「さつ」，三冊读「さんさつ」；例句：猫が六匹いる。说明：「匹」读「ひき」，六匹读「ろっぴき」。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('e3b9f6eb-0c81-5f6d-b6c6-f857a6e6f704', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '1d183755-02b3-4a6d-b727-082af1ef377c', '9c37478d-2388-1380-cdea-3b62d82c3fcb', '论据的强度与作者资格判断', '在阅读评论或学术文章时，判断作者所引用的证据是否充分、来源是否可靠，以及作者自身的专业背景或立场是否影响其主张的可信度。', '只关注论据数量而忽视质量，或误将作者的个人经历当作普遍证据；忽略作者立场可能导致的偏见。', '日语例句：著者は自身の体験だけを根拠に、教育制度全体を批判している。；说明：需识别出仅凭个人体验不足以支撑对全体的批判，属于论据强度不足。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('e3d43ff0-9c37-5c72-a251-16e433947ff3', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '1d183755-02b3-4a6d-b727-082af1ef377c', '6f1477f5-00be-f963-76b6-5165f568e88e', '段落功能识别', '识别段落在一篇文章中的功能，如引入、展开、举例、对比、总结、转折等，有助于理解文章整体结构。', '只关注内容而忽略段落间的功能关系，导致无法把握文章脉络。', '日语例句：まず、問題の背景を説明する。次に、具体的なデータを示す。最後に、解決策を提案する。说明：通过接续词判断段落功能。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('e3f3c9bd-2167-5a15-b268-810326f8bea8', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', 'baa9b5c2-5b94-4f9b-7ced-3a8c3cde4cb3', '敬语动词的基本用法', '掌握N4基础敬语动词如「いらっしゃる」「申す」「いただく」等，理解尊敬语与谦让语的区别。', '混淆尊敬语与谦让语的使用对象；将「お～になる」用于自己。', '日语例句：先生は何を召し上がりますか。；说明：「召し上がる」是「食べる」的尊敬语，用于对方或长辈。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('e42447ae-6c55-5bd3-8cd5-75f050e7072c', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '0545d0ec-89d1-a8aa-99f9-78b30fcbacb1', '汉字复合词中音读与训读的混读规则', 'N2阶段常出现由两个以上汉字组成的复合词，其读音有时为音读（如「毎日」まいにち），有时为训读（如「手紙」てがみ），有时为音训混读（如「見本」みほん）。本知识点训练学习者根据词义和常见搭配判断复合词的正确读音。', '误以为所有汉字复合词都读音读，或都读训读；忽略个别词的特殊读法（如「一日」有ついたち、いちにち等）。', '日语例句：この見本は新製品の参考にしてください。；说明：「見本」读みほん，为训读+音读的混读，不能读作けんぼん。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('e46ffa6d-4c5f-5ed2-9dc6-c8b6957010a9', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '1af448c1-54cf-2f94-01b5-e8bc77a97f94', '～てからでないと／～てからでなければ（不～就不能）', '表示“如果不先做前项，后项就无法实现或难以实现”。接续：动词て形＋からでないと／からでなければ＋否定表达。强调前项是后项的必要前提条件。', '容易与“～てから”混淆，但“～てから”只表示先后顺序，没有“不～就不能”的否定含义。另外注意后项常为否定或消极表达，不能接积极肯定的结论。', '日本語の勉強をしてからでないと、日本で仕事ができません。；说明：表示不先学日语就不能在日本工作，强调前提条件。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('e4b40cfc-babb-53ee-9489-6c0b224ea60e', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '1d183755-02b3-4a6d-b727-082af1ef377c', '40ed56d1-acbd-4a8b-6284-2df8b9423e8e', '观点与论据匹配判断', '在议论文中，识别作者提出的观点（主张）以及支撑该观点的论据（理由、例子、数据），判断论据是否有效支持观点。', '将论据误认为观点；忽略论据与观点之间的逻辑关联；无法区分事实论据与价值判断。', '日语例句：观点是“应该减少塑料使用”，论据是“海洋生物因塑料垃圾而死亡”。说明：论据提供事实支撑，需判断其与观点的因果关系是否成立。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('e5400f52-abcc-5365-9b22-4325f48cb499', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '2c18e7e1-4ef0-65e3-24a7-6c97d562a122', '～に鑑みて（かんがみて）', '表示“鉴于……、考虑到……”，用于正式场合，后接判断、决定、措施等。接续：名词＋に鑑みて。', '与「～に基づいて」混淆：前者强调基于某种情况或先例做出判断，后者强调依据规则或事实。注意「鑑みる」的汉字和读音。', '今回の事故に鑑みて、安全規則を改正した。；说明：鉴于这次事故，修改了安全规则。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('e563da22-85a3-567d-939a-033f8f1c5d4c', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '1d183755-02b3-4a6d-b727-082af1ef377c', '9c37478d-2388-1380-cdea-3b62d82c3fcb', '抽象论述与具体例证的对应', '理解抽象概念、理论表述与具体事例、数据之间的对应关系，能够将抽象内容具体化。', '无法匹配抽象与具体；忽略「つまり」「例えば」等连接词；将具体细节误当抽象原则。', '日语例句：社会の高齢化が進む。つまり、若年層の人口が減少し、高齢者の割合が増えている。说明：「つまり」将抽象概念具体化。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('e5871591-ddc0-563c-a3e4-ef09b8bbb3fc', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '3760dfca-44d9-3445-01cd-85de1f860da1', '～ようがない', '表示没有办法做某事，相当于“无法……”。接动词ます形去掉ます。', '误用于有办法但不想做的情况；注意与“～ようもない”相同，但“ようがない”更常用。', '日语例句：連絡先が分からないので、知らせようがない。；说明：因为不知道联系方式，所以无法通知。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('e5d2b144-3b9d-51a2-ac92-1cc1675ff219', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '1d183755-02b3-4a6d-b727-082af1ef377c', '9c37478d-2388-1380-cdea-3b62d82c3fcb', '隐含对比关系的识别', '在没有明显对比词的情况下，通过上下文语义识别出隐含的对比关系，如不同时间、不同对象、不同条件下的差异，理解作者通过对比所要强调的重点。', '忽略没有标记的对比，将对比内容当作一般陈述，不能把握作者强调的差异点。', '日语例句：昔は手紙で連絡を取り合っていた。今ではメールやSNSが主流だ。；说明：通过「昔」和「今」的对照，隐含了时代变化的对比，需识别这种隐含对比。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('e5f41465-be43-54c5-90a9-5217ccf01e40', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '1d183755-02b3-4a6d-b727-082af1ef377c', 'fc58533f-fd29-5132-8f21-fd381828e3c8', '理解说话人态度', '通过语气词、助动词（〜だろう、〜かもしれない、〜はずだ）和形容词判断说话人的确信度、积极或消极态度。', '将推测当作事实；忽视「〜はずだ」的根据性。', '日语例句：彼はたぶん来ないだろう。说明：「たぶん〜だろう」表示推测，不确定。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('e65a56f7-dacf-5a86-a71d-a725374d0d38', '9221fc32-a051-42cb-86b1-6a9917aa004e', '42de0c7b-50d9-4159-918a-4e618d83342d', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', 'ef36118d-0ba3-29ce-b2b3-76eaeb6542ca', 'てはいけないな（自言自语禁止）', '表示自己提醒自己不要做某事，带有感叹语气。', '与「てはいけない」混淆，后者用于对他人。', '忘れてはいけないな。；说明：可不能忘啊。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('e682a147-becf-544b-8158-cad9e572eebe', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', 'baa9b5c2-5b94-4f9b-7ced-3a8c3cde4cb3', '时间表达（～前、～後、～間）', '掌握N4时间相关表达如「～前に」「～後で」「～間」等，理解其接续和用法。', '混淆「～後で」与「～後」的接续；将「～間」与「～間に」混淆。', '日语例句：食事の後で散歩します。；说明：「後で」表示之后，接名词加の，注意「～後」直接接动词过去式，如「食べた後で」。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('e6c72dd4-9c81-5953-ac60-cc5ad02da519', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '2c18e7e1-4ef0-65e3-24a7-6c97d562a122', '～に関しての', '表示关于……的，用于修饰名词。相当于「～についての」。', '与「～に関する」相比，「に関しての」更口语化，但两者可互换。', '日本語：この問題に関しての意見を聞かせてください。；说明：请告诉我关于这个问题的意见。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('e73269cb-e1aa-51a3-b5c5-9b1432951eac', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '0545d0ec-89d1-a8aa-99f9-78b30fcbacb1', '汉字复合词中送假名对读音的影响', 'N2阶段需掌握汉字复合词中送假名（送り仮名）的存在如何影响整个词的读音与词性。例如「話し合う」中「話し」为训读，「合う」为训读，而「話合い」则常读作「はなしあい」但有时也写作「話し合い」。送假名不同可能导致音读/训读混用或词义变化。', '学习者常忽略送假名，将「話し合う」误读为「わごう」或「はなしごう」，或混淆「行う（おこなう）」与「行（こう）」的读音。', '日语例句：会議で意見を話し合う。；说明：「話し合う」中「話し」训读「はなし」，「合う」训读「あう」，送假名「し」提示动词活用。日语例句：この計画は実行に移す。；说明：「実行」为音读「じっこう」，送假名「す」构成サ变动词，读音与名词相同但活用不同。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('e774041a-f412-58a3-b042-cbefe85a6aaa', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '1af448c1-54cf-2f94-01b5-e8bc77a97f94', '～ようにしている（努力保持）', '表示为了达到某个目标而持续努力，强调主观意志和习惯化。', '与～ようにする（努力做）混淆，本句型强调持续状态；与～ことにしている区别，本句型更侧重努力过程。', '日本語：健康のために、野菜をたくさん食べるようにしている。；说明：表示为了健康而持续努力的习惯。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('e86a1cc9-bc5f-50b7-9ecb-338ea0d95546', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', 'baa9b5c2-5b94-4f9b-7ced-3a8c3cde4cb3', '动词て形与补助动词的复合意义（扩展）', 'N4阶段需掌握「～ている」「～てある」「～ておく」「～てしまう」等补助动词的附加意义，如状态持续、准备、完成、遗憾等。', '混淆「～ている」与「～てある」的主语视角；「～てしまう」的遗憾义与完成义不分。', '日语例句：ドアが開けてあります。；说明：「～てある」表示人为动作的结果状态，强调“已经开好”。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('e8735a63-d9e5-56fa-bef9-cdce23c3e6ba', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '1d183755-02b3-4a6d-b727-082af1ef377c', '40ed56d1-acbd-4a8b-6284-2df8b9423e8e', '时间顺序与事件排序', '能理清叙述中的时间先后顺序，理解“～てから”“～前に”“～後で”等表达，并能按顺序排列事件。', '混淆“前に”和“後で”的时间指向；忽略叙述中的倒叙。', '日语例句：朝起きて、顔を洗ってから、朝ご飯を食べた。说明：动作顺序为起床→洗脸→吃早饭。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('e87ec413-ab2f-5917-9867-eb18f14ed983', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '1d183755-02b3-4a6d-b727-082af1ef377c', '9c37478d-2388-1380-cdea-3b62d82c3fcb', '概念的定义扩展与重新定义', '作者在论述中可能先给出一个概念的初步定义，随后通过举例或对比扩展或修正该定义，读者需跟踪定义的变化。', '固守最初定义，忽略后文的修正；将扩展后的定义与原始定义混为一谈。', '日语例句：幸福とは単に快楽ではない。むしろ、困難を乗り越えたときに得られる充実感を指す。；说明：作者重新定义幸福，从否定到正面定义。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('e8b91437-527a-52c6-9d86-6fe922651cfc', '9221fc32-a051-42cb-86b1-6a9917aa004e', '42de0c7b-50d9-4159-918a-4e618d83342d', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '2d7157f8-afb7-58a0-85ea-b3d775f216a2', '动词与形容词活用', '练习动词各活用形以及い形容词、な形容词的连接。', '五段动词音变和な形容词接名词的形式容易混淆。', '本を読んで、寝ます。', 'published', '2026-09-03 13:10:31.032213+08', '2026-09-03 13:10:31.032213+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('e922a9b5-5192-5bba-804e-9054aa8860a3', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', 'ff057d86-47bc-de16-f0f9-a7b808b968e3', 'N3使役被动形的构成与含义', '掌握使役被动形如「行かされる」「食べさせられる」的构成，表示“被迫做某事”的不情愿心情。', '将使役被动与单纯被动混淆，如「私は母に買い物に行かされた」表示被迫去。', '日语例句：子供の頃、ピアノを練習させられました。；说明：「練習させられる」表示被迫练习。；日语例句：残業させられて疲れました。；说明：「させられる」表示被迫加班。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('e968f4e1-ab84-5596-a278-0589344a7747', '9221fc32-a051-42cb-86b1-6a9917aa004e', '42de0c7b-50d9-4159-918a-4e618d83342d', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', 'ef36118d-0ba3-29ce-b2b3-76eaeb6542ca', 'けど/けれども（逆接）', 'けど表示转折或缓和语气，接续普通形。', '与から混淆；口语中けど常省略も。', '高いけど、買いました。说明：虽然贵但买了。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('e9e2f614-34be-545d-aee8-89ee9e727b04', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '1af448c1-54cf-2f94-01b5-e8bc77a97f94', '～てもいい（许可・允许）', '表示允许做某事。与已有「～てもいい（许可）」重复？但本条目侧重与「～てかまわない」「～てよろしい」的语体差异，以及疑问形式「～てもいいですか」的礼貌程度。', '「～てもかまわない」更正式，「～てもよろしいですか」更尊敬。口语中常用「～ていい？」。', '日本語例：ここで写真を撮ってもいいですか。；说明：可以在这里拍照吗？', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('e9ef51e4-58ca-54a1-a85c-951ec0d47881', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '5b34d8b5-bde9-c4c6-c736-84adaaae3603', '「今日」「只今」「幾久」等「きょう」相关汉字表记与读音', 'N1文字词汇中，需掌握「今日」读作「きょう」而非「こんにち」；「只今」读作「ただいま」；「幾久」读作「いくひさ」等特殊读音。本知识点聚焦于「きょう」这一读音对应的多个汉字表记及其在具体词汇中的读音规则，避免与「今日（こんにち）」混淆。', '误将「今日」读作「こんにち」；将「只今」读作「しょこん」；将「幾久」读作「いくきゅう」。需注意「今日」在正式场合或书面语中常读「きょう」，而「こんにち」仅用于寒暄语「こんにちは」。', '今日は学校へ行きます。说明：「今日」读作「きょう」，表示今天。
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('ea1f09b0-8bdb-50d1-8d71-ce151eea47f0', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '5b34d8b5-bde9-c4c6-c736-84adaaae3603', '「を兼ねて」的用法', '掌握「を兼ねて」表示“兼带、顺便”。', '与「をかねて」的汉字混淆，注意表记。', '日本語：買い物を兼ねて散歩する。；说明：散步兼购物。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('eaa7d084-ccf4-57f1-8383-854e86228139', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '2c18e7e1-4ef0-65e3-24a7-6c97d562a122', '～についての', '「～について」修饰名词的形式，表示“关于…的”。接续：名词+についての+名词。', '注意接续，不能直接加名词。', '日本文化についての本を読んだ。说明：关于日本文化的书。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('eab3f1f8-705c-5423-9411-45b414f5d059', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '1d183755-02b3-4a6d-b727-082af1ef377c', '6f1477f5-00be-f963-76b6-5165f568e88e', '让步转折阅读', '掌握“～ても”“～けれども”“～とはいえ”等让步表达，理解作者先承认某事实再转折提出真正主张的阅读策略。', '只看到让步部分就断定作者观点，忽略转折后的重点。', '日语例句：確かに値段は高い。しかし、品質を考えれば納得できる。说明：先让步承认价格高，再转折强调品质合理。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('eabc3212-41ce-5e43-87bf-1f6d4d2ce227', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '0545d0ec-89d1-a8aa-99f9-78b30fcbacb1', 'サ变动词中自动词与他动词的对应（如「開始する」与「始まる」）', '许多サ变动词有对应的自动词（如「開始する」对应「始まる」），但并非所有サ变动词都有对应。本知识点辨析サ变动词与自动词在用法上的区别。', '将「会議を開始する」误说成「会議が開始する」（自动词用法错误）。', '日语例句：会議を開始します。；说明：「開始する」是他动词，需要宾语；若用自动词则说「会議が始まる」。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('eafffafb-1ad7-5e1f-b4fb-40805c9def11', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '5b34d8b5-bde9-c4c6-c736-84adaaae3603', '「について」的用法', '掌握复合助词「について」表示“关于”。', '与「にとって」混淆，后者表示立场。', '日本語：この問題について考えます。；说明：关于这个问题思考。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('eb3a4560-3662-56b0-8049-a1f24d063a7c', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', 'ff057d86-47bc-de16-f0f9-a7b808b968e3', 'N3近义名词的语境区分（扩展三）', '区分N3中如「理由/わけ/原因」「方法/手段/仕方」「意見/考え/思いつき」等近义名词在语境中的细微差别和搭配。', '「理由」与「原因」混用，理由偏主观说明，原因偏客观导致；「方法」与「手段」中，手段有时带贬义。', '例句：遅刻の理由を説明する。说明：「理由」主观理由；例句：事故の原因を調べる。说明：「原因」客观原因；例句：この問題を解決する方法を考える。说明：「方法」一般方法，而「手段」可能指不择手段。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('eb60fb7c-903c-5f60-a5bb-4a668c8ee8a6', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '2c18e7e1-4ef0-65e3-24a7-6c97d562a122', '～に伴っての', '表示伴随……的，用于修饰名词。相当于「～に伴う」。', '与「～に伴う」相比，「に伴っての」更强调伴随过程。', '日本語：経済成長に伴っての環境破壊が問題となっている。；说明：伴随经济增长的环境破坏成为问题。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('eb8b08b4-e060-5d06-b7ff-72ed2371a2fb', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '0545d0ec-89d1-a8aa-99f9-78b30fcbacb1', '复合动词中后项动词带来的方向或结果意义', '复合动词如「～込む」「～出す」「～上げる」等，后项动词赋予前项动作以方向或结果意义。例如「書き込む」表示写入，「飛び出す」表示飞出。本知识点训练理解复合动词的整体意义。', '将「思い出す」直译为“想出来”而忽略其“想起”的惯用义；将「話し合う」理解为“互相说话”而忽略“商量”义。', '日语例句：彼は突然部屋から飛び出した。；说明：「飛び出す」由「飛ぶ」+「出す」构成，表示突然向外冲出，不能理解为“飞出去”的简单组合。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('ebb6dea1-3b02-5b61-8c21-22da97f3277f', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '5b34d8b5-bde9-c4c6-c736-84adaaae3603', '「恵」的读音与词义', '「恵」读音有「けい」「めぐ（み）」「さいわ（い）」等。常见词「恩恵（おんけい）」「知恵（ちえ）」「恵み（めぐみ）」。需区分音读与训读。', '将「知恵」的「恵」读作「けい」；混淆「恩恵」与「利益」。', '自然の恵（めぐ）みに感謝する。；说明：恩惠。／彼は知恵（ちえ）が豊かだ。；说明：智慧。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('ebdcfa1f-1137-580a-9ca8-5319cce9c5c1', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', 'ff057d86-47bc-de16-f0f9-a7b808b968e3', '正式与口语同义词的转换', '掌握N3中同一意思的正式和口语表达，如「しかし/でも」「です/だ」「たくさん/いっぱい」等，能根据场合选用。', '在书面语中误用口语词；忽视敬体与简体的转换规则。', '日语例句：しかし、問題があります。でも、大丈夫です。；说明：しかし正式，でも口语。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('ebfbe270-91dc-597c-b854-368ab95738fa', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '2c18e7e1-4ef0-65e3-24a7-6c97d562a122', '～に連れての', '表示随着……的，用于修饰名词。较少见，多用于书面语。', '与「～に伴っての」相比，「に連れての」更口语化。', '日本語：年を取るに連れての変化は避けられない。；说明：随着年龄增长的变化是不可避免的。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('ec1ee42a-87df-5e54-8772-c9d59564ad03', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', 'dd4e968a-3d37-98a7-3819-a5fc4c117122', '～てみる（尝试）', '表示试着做某事，看看结果。接续：动词て形+みる。', '与～ようとする（想要做）区别，～てみる强调实际尝试，～ようとする强调意图。', '日本語：このケーキを食べてみてください。；说明：请试着吃一下这个蛋糕。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('ec602114-ce43-5d71-9cb3-244fd4aa9664', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '0545d0ec-89d1-a8aa-99f9-78b30fcbacb1', '多义名词「わけ」的语义区分', 'N2中「わけ」可表示原因、理由、道理、当然等，如「わけがない」「わけにはいかない」「わけだ」。', '混淆「わけがない」（不可能）与「わけにはいかない」（不能）的用法。', '例句：彼が来るわけがない。说明：不可能来。；例句：約束した以上、行かないわけにはいかない。说明：不能不去。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('ec8055b0-1a1c-5eba-bd36-86ff0d6991ab', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '1d183755-02b3-4a6d-b727-082af1ef377c', 'fc58533f-fd29-5132-8f21-fd381828e3c8', '理解因果关系表达', '识别「〜から」「〜ので」「〜ため」「〜おかげで」「〜せいで」等表达，判断原因与结果的关系。', '将「おかげで」（积极原因）与「せいで」（消极原因）混用；忽视「ので」比「から」更客观。', '日语例句：雨が降ったので、試合は中止になりました。说明：「ので」表示客观原因，结果明确。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('ec861551-35f7-5da5-bc50-f849dc088c66', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '0545d0ec-89d1-a8aa-99f9-78b30fcbacb1', '多义词在不同语境下的词义选择', '识别N2常见多义词（如「かける」「とる」「つく」）在不同搭配中的具体含义，能根据上下文确定词义。', '只掌握一个义项，导致理解偏差；如「時間をかける」误以为“花费时间”与“悬挂”混淆。', '日语例句：彼女は料理に時間をかける。；说明：「かける」在此表示花费（时间），而非悬挂。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('eccf3280-3c9e-513f-aae0-b34dc25fbd14', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', 'baa9b5c2-5b94-4f9b-7ced-3a8c3cde4cb3', '动词て形与补助动词的搭配', '掌握动词て形与「いる」「ある」「おく」「みる」「しまう」等搭配表达持续、准备、尝试、完成等意义。', '混淆「ている」与「てある」的主语和状态；将「てしまう」误用为积极意义。', '日语例句：窓が開けてあります。；说明：「てある」表示人为结果的状态，主语是物，注意与「ている」区分。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('ed5ee299-39a9-58fa-9c55-7e33a79c5472', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '0545d0ec-89d1-a8aa-99f9-78b30fcbacb1', '量词（助数詞）的正确使用', '掌握N2常见量词（如「～冊」「～台」「～本」「～枚」）的用法，能根据物体形状和种类选择。', '混淆量词，如将细长物用「枚」；或对抽象事物使用具体量词。', '日语例句：本を三冊買った。；说明：「冊」用于书本，而「本」用于细长物如铅笔。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('ed628e6b-eb59-5f2c-9616-5bf9da6fe449', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '0545d0ec-89d1-a8aa-99f9-78b30fcbacb1', '多义动词「とる」的多种用法', 'N2中「とる」可表示取、拿、摘、记录、采取等，如「写真をとる」「休みをとる」「対策をとる」。', '只掌握基本义，忽略其他常见搭配。', '例句：写真をとる。说明：拍照。；例句：休みをとる。说明：请假。；例句：対策をとる。说明：采取对策。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('ee0e6b65-0ec9-5b21-a803-9ff3146be63f', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '5b34d8b5-bde9-c4c6-c736-84adaaae3603', '「素」的读音与词义', '「素」有「そ」「す」两种读音，N1中「素人（しろうと）」「素直（すなお）」等需注意；「素」表示本来的、不加修饰的。', '将「素人」误读为「そじん」；混淆「素直」与「正直」的语义。', '彼は素人ですが、上手です。（外行）说明：「素人」读「しろうと」，指非专业者。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('ee289bfa-496a-5371-8580-1fede88c6c52', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '1d183755-02b3-4a6d-b727-082af1ef377c', '6f1477f5-00be-f963-76b6-5165f568e88e', '选项排除法阅读', '在阅读理解选择题中，学会排除绝对化、与原文不符、偷换概念、无中生有的选项，提高答题准确率。', '凭印象选答案，不逐项对照原文；或忽略选项中的细微差别。', '日语例句：問題：筆者の考えに合うものはどれか。選択肢A：環境問題は個人では解決できない。B：環境問題は政府だけが解決すべきだ。C：環境問題は個人と社会が協力して解決すべきだ。説明：原文提到“個人の努力だけでは不十分で、社会全体の取り組みが必要”，因此C正确，A和B过于绝对。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('ee3ec0fb-e0d8-5f4b-a78b-84f0b0b08d43', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '1af448c1-54cf-2f94-01b5-e8bc77a97f94', '～ように言う（转告・要求）', '表示转达别人的话或要求，接动词辞书形/ない形+ように言う。', '与～と言う直接引用混淆；～ように言う用于间接转述命令、请求。', '先生は早く来るように言いました。（老师说早点来。）／母に野菜を食べるように言われた。（被妈妈说要吃蔬菜。）', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('ee440cbf-b466-546e-b804-c0eeacae46fb', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '1af448c1-54cf-2f94-01b5-e8bc77a97f94', '～ようになっている（结构・机制）', '表示某物被设计成或自然形成某种状态，强调客观机制或结构。', '与～ようになる（变化）混淆，本句型表示静态的机制；接续为动词辞书形/ない形+ようになっている。', '日本語：この機械は、ボタンを押すと自動的に止まるようになっている。；说明：说明机械的设计机制。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('eec36254-5dda-571c-abd7-76ea1c03a4c7', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '1d183755-02b3-4a6d-b727-082af1ef377c', '40ed56d1-acbd-4a8b-6284-2df8b9423e8e', '叙事文情感脉络把握', '在记叙文中，通过人物言行、场景描写和事件发展，把握主人公或作者的情感变化脉络，理解情感从何而来、如何转变。', '只关注事件本身，忽略情感线索；将人物当下的情绪误认为一贯态度；不区分直接抒情与间接暗示。', '日语例句：彼女は最後まで笑っていたが、その笑顔はどこか寂しげだった。说明：通过“寂しげ”这一修饰，可推断表面笑容下隐藏的悲伤，需抓住情感与表象的反差。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('ef2a5c93-9f69-5fcd-b013-055bfac1a982', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '2c18e7e1-4ef0-65e3-24a7-6c97d562a122', '～につけ～につけ', '表示“无论……还是……都……”，列举两个相关事项，后项表示总是产生某种心情或结果。接续：动词辞书形/名词+につけ～につけ。', '与「～にしても～にしても」相近，但「につけ」更强调自然联想，常与「思い出す」「感じる」等动词搭配。', '日本語：雨につけ風につけ、故郷のことを思い出す。；说明：无论下雨还是刮风，都会想起故乡。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('efd93aac-8b69-59a0-aaa8-04832401546c', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '5b34d8b5-bde9-c4c6-c736-84adaaae3603', '「作」的多种读音与词义', '「作」在N1中常见读音「さく」「さ」，词义包括“制作、作品”“耕作”“发生”等。如「作品（さくひん）」「操作（そうさ）」「動作（どうさ）」「作詞（さくし）」「発作（ほっさ）」。', '「発作」读「ほっさ」而非「はつさく」；「動作」读「どうさ」而非「どうさく」。', '彼の新作（しんさく）を読んだ。说明：新作指新作品。；心臓発作（ほっさ）を起こした。说明：発作指发作。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('efde6904-b0ff-50ec-8ec1-1c1a61373514', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '1d183755-02b3-4a6d-b727-082af1ef377c', '9c37478d-2388-1380-cdea-3b62d82c3fcb', '并列结构与对应关系', '识别文章中并列的句子成分或段落，理解它们之间的对应、补充或递进关系。注意「また」「そして」「一方」等连接词，以及排比句式的运用，把握并列项之间的逻辑联系。', '将并列关系误认为因果或转折，忽略并列项之间的层次差异，不能区分对等并列与递进并列。', '日语例句：彼女は英語が堪能であり、またフランス語も日常会話レベルで話せる。；说明：「また」连接两个并列的事实，表示她掌握多种语言，需理解并列关系而非因果。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('f05f3762-5dad-5269-aeee-71b9c331c8c4', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '5b34d8b5-bde9-c4c6-c736-84adaaae3603', '「相」「総」「想」等「そう」同音汉字的读音与词义区分', 'N1中「そう」读音的汉字众多，如「相（そう）」「総（そう）」「想（そう）」「草（そう）」「争（そう）」等。本知识点训练学习者根据词语判断具体汉字及其含义，避免同音混淆。', '易将「総理」写成「想理」，或将「相違」与「相違」混淆；需注意「相」多表示互相，「総」表示全部，「想」表示思考。', E'日语例句：総合（そうごう）的な判断が必要だ。；说明：「総」读「そう」，表示综合、全部。\\n日语例句：彼は想像（そうぞう）力が豊かだ。；说明：「想」读「そう」，表示想象。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('f0dd10a1-c5db-570f-9c1e-a6a45c46aacc', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '5b34d8b5-bde9-c4c6-c736-84adaaae3603', '「こと」「もの」的抽象与具体用法', '「こと」表示抽象事、事件、经验；「もの」表示具体物体、人或抽象性质。N1中需区分在惯用表达中的选择。', '将「こと」用于具体物品，或将「もの」用于抽象事件。', '日本語：彼の成功は素晴らしいことだ。；说明：成功是抽象事，用「こと」。日本語：机の上に置いてあるものは何ですか。；说明：具体物体用「もの」。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('f0e8fb00-6deb-5dad-9aaa-de2c1bcdaa9b', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '1af448c1-54cf-2f94-01b5-e8bc77a97f94', '～てしまう（完了・遗憾）', '表示动作完全结束或产生遗憾、后悔等心情。口语中可缩约为～ちゃう／～じゃう。', '只理解为“完了”而忽略遗憾语气；在不需要遗憾语气的场合误用。', '宿題を忘れてしまいました。（把作业忘了，表示遗憾。）／この本はもう読んでしまった。（这本书已经读完了，单纯完成。）', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('f0fde04b-f981-5317-80bf-0d62b36195e8', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '5b34d8b5-bde9-c4c6-c736-84adaaae3603', '「参」的读音与词义', '「参」在「参加」「参考」中读「さん」，表示参加、参考，但「参る」读「まいる」，表示去、来或认输。', '将「参る」读作「さんる」，或混淆「参加」与「加入」。', '例句：会議に参加する。说明：「参加」读「さんか」，指参加。；例句：この本を参考にした。说明：「参考」读「さんこう」，指参考。；例句：参ったな、この問題は難しい。说明：「参る」读「まいる」，此处表示为难、服了。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('f14df3b6-fc40-54b7-ac83-06ce8385aeef', '9221fc32-a051-42cb-86b1-6a9917aa004e', '42de0c7b-50d9-4159-918a-4e618d83342d', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', 'ef36118d-0ba3-29ce-b2b3-76eaeb6542ca', 'なければならない（必须）', '动词ない形去い+ければならない表示必须。接续：ない形+ければならない。', '与なくてもいい混淆；口语中常缩约为なきゃ。', '毎日薬を飲まなければなりません。说明：必须每天吃药。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('f2754d0f-8c7f-5918-b123-73ba913a7c99', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '0545d0ec-89d1-a8aa-99f9-78b30fcbacb1', '片假名外来语的语义与使用场景', '理解N2常见片假名外来语（如「アポイント」「リスク」「マニュアル」）的准确含义，并能区分与和语、汉语词的语感差异。', '将外来语与汉语词混用，如误用「イメージ」代替「考え」；或对外来语的具体所指不明确。', '日语例句：会議の前にアポイントを取ってください。；说明：「アポイント」意为预约，比「約束」更正式。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('f275fae9-c9d3-50a1-985c-385b24f3cfd7', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '1d183755-02b3-4a6d-b727-082af1ef377c', '6f1477f5-00be-f963-76b6-5165f568e88e', '抽象与具体对应', '识别文章中的抽象论述与其对应的具体例证，理解例证如何支撑观点。', '找不到例证与观点的对应关系；误将例证当作新观点。', '日语例句：現代社会ではストレスが多い。例えば、長時間労働や人間関係の問題がある。説明：例证具体说明压力来源。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('f283d089-2249-5c5a-8778-48f5e4b0f80b', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '2c18e7e1-4ef0-65e3-24a7-6c97d562a122', '～につけても～につけても（并列强调）', '表示“无论……还是……都……”，与「～につけ～につけ」类似，但语气更正式，多用于书面语。接续：动词辞书形/た形＋につけても＋同形＋につけても。', '注意前后项需为动词或动词短语，且后项常为评价、判断或自然结果；不要与「～につけても」单独使用混淆。', '日本語：試験に合格するにつけても、落ちるにつけても、努力は無駄ではない。；说明：无论考试合格还是落榜，努力都不会白费。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('f31b785a-d7ea-56b8-a623-5fc8f6263008', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '1af448c1-54cf-2f94-01b5-e8bc77a97f94', '～てもかまわない（许可・书面）', '表示“可以、没关系”，比～てもいい更正式。接续：动词て形+もかまわない。疑问形式～てもかまいませんか。', '与～てもいい混淆，后者更口语。注意～てもかまわない常用于书面或正式场合。', '日本語：質問があれば、いつでもしてもかまいません。；说明：表示“有问题随时可以问”。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('f32e24a9-7fe1-514c-93f8-6709574e87a4', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', 'ff057d86-47bc-de16-f0f9-a7b808b968e3', 'N3复合动词的构成与意义（扩展三）', '进一步掌握N3中复合动词如「～込む」「～出す」「～過ぎる」「～直す」「～始める」等，理解其构成要素带来的意义变化。', '「～込む」表示“进入”或“充分”，如「考え込む」不是“考虑进入”而是“沉思”；「～出す」有“开始”和“取出”双重含义，需根据语境判断。', '例句：彼は深く考え込んだ。说明：「考え込む」表示陷入沉思；例句：急に雨が降り出した。说明：「降り出す」表示“开始下”，而「取り出す」表示“取出”。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('f332b82e-7bfe-5204-addb-83fc4a69452c', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', 'dd4e968a-3d37-98a7-3819-a5fc4c117122', '～てください（请做…）', '表示请求或指示对方做某事。接续：动词て形＋ください。', '对长辈或上级直接使用显得失礼，应使用～てくださいませんか；与～ないでください混淆；忘记动词て形变化。', '窓を開けてください。说明：请打开窗户。／名前を書いてください。说明：请写下名字。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('f3520c85-e838-5385-b3cc-a94a361dfed2', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '1af448c1-54cf-2f94-01b5-e8bc77a97f94', '～てある（结果状态・他动）', '表示他人或自己有意做的动作的结果仍然存在，常与“～てある”搭配表示状态。', '与“～ている”区分，前者强调人为结果，后者可表示自然状态；注意动词需为他动词。', '日本語：壁に絵が掛けてある。；说明：墙上挂着画（有人挂的）。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('f40f0c9f-7a90-5490-a08a-4f55fd0d9b58', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '2c18e7e1-4ef0-65e3-24a7-6c97d562a122', '～に対して', '表示对象、方向，相当于「～に向かって」「～に」。也可表示对比、比例，如「～に対して～」。', '与「～にとって」混淆。「に対して」强调动作指向的对象，而「にとって」表示从某立场来看。', '日本語：お客様に対しては、丁寧な言葉遣いを心がけています。；说明：对顾客要使用礼貌用语。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('f450cc30-a632-5ee9-a398-9b1feed0efb9', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '1af448c1-54cf-2f94-01b5-e8bc77a97f94', '～ないでください（请求不要做）', '表示请求对方不要做某事。接续：动词ない形+でください。注意与～ないで（不要…）的区别，后者更口语。', '与～なくてください（错误形式）混淆。注意～ないでください是标准形式，～ないでくださいませんか更礼貌。', '日本語：ここで写真を撮らないでください。；说明：请求“请不要在这里拍照”。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('f452eacc-834b-5a4a-ac0a-4603e075604f', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', 'baa9b5c2-5b94-4f9b-7ced-3a8c3cde4cb3', '同音异义汉字的辨识与语境选择', 'N4阶段需区分如「会う・合う・遭う」「聞く・効く」「話す・離す」等同音或近音汉字词，根据语境选择正确表记。', '仅凭读音书写导致错字，如将「会う」写成「合う」；忽略词义差异。', '日语例句：友達に会います。；说明：「会う」表示与人见面，而「合う」表示一致、相合，注意语境。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('f48637ea-6a04-57c3-b5f5-80e1b1bcdf83', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '3760dfca-44d9-3445-01cd-85de1f860da1', '～に伴って', '表示随着前项的变化，后项同时或相应地发生。接续：动词辞书形/名词＋に伴って。', '与「に連れて」相似，但「に伴って」更正式，常用于书面语，且可表示伴随发生的事件。', '経済の発展に伴って、環境問題が深刻になってきた。；说明：随着经济发展，环境问题变得严重了。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('f4982012-504d-5804-b91e-fcfd002854e2', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '1af448c1-54cf-2f94-01b5-e8bc77a97f94', '～わけにもいかない（也不能…）', '表示“也不能那么做”，与～わけにはいかない类似，但更强调“也不能”的无奈，常与否定形式连用。', '与～わけにはいかない混淆，本句型常表示“也不能不…”，注意否定接续；接续为动词ない形+わけにもいかない。', '日本語：忙しいが、休むわけにもいかない。；说明：虽然忙，但也不能休息。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('f4bee157-4233-51ee-b635-d1d1f36c577d', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '3760dfca-44d9-3445-01cd-85de1f860da1', '～ようにいうことができる', '表示“可以说…”，用于委婉断言。接动词辞书形/ない形。', '与「～と言える」混淆；误用为直接断定。', '彼は天才だというようにいうことができる。说明：可以说他是天才。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('f4c6dad9-efee-5b78-b1f6-fd7155144fa4', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '1af448c1-54cf-2f94-01b5-e8bc77a97f94', '～につれて（随着）', '表示随着前项变化后项也变化，接动词辞书形或名词。', '与～にしたがって、～とともに辨析；～につれて强调自然伴随，前后项多为同一方向变化。', '年を取るにつれて、体力が落ちてきます。（随着年龄增长体力下降。）／音楽が大きくなるにつれて、みんな踊り始めた。（随着音乐变大，大家开始跳舞。）', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('f4e64695-3270-520a-af96-51d9319eccc9', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', 'ff057d86-47bc-de16-f0f9-a7b808b968e3', 'N3频率和程度副词的用法（扩展三）', '掌握N3中表示频率和程度的副词如「たまに」「めったに」「かなり」「ずいぶん」「なかなか」等，并注意与否定、肯定句的搭配限制。', '「めったに」后接否定，「なかなか」后接肯定表示“相当”，但「なかなか～ない」表示“不容易”；「たまに」频率低，不用于否定。', '例句：めったに映画を見ない。说明：「めったに」必须与否定呼应；例句：この本はなかなか面白い。说明：「なかなか」肯定句中表示“相当”，但「なかなか終わらない」表示“迟迟不结束”。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('f569d75c-b94a-59d8-8f5a-2102ba38f883', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '1af448c1-54cf-2f94-01b5-e8bc77a97f94', '～ばいいのに（要是…就好了）', '表示对对方或现状的遗憾、建议或轻微责备，含有“如果那样做就好了”的语气。', '与～ばいい（建议）混淆，本句型带有遗憾或责备；接续为动词ば形+いいのに。', '日本語：もっと早く寝ればいいのに、いつも夜遅くまで起きている。；说明：对对方熬夜表示遗憾和建议。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('f571d540-6ef2-5281-8c0d-c823e403160d', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '3760dfca-44d9-3445-01cd-85de1f860da1', '～と一緒に', '表示与某人或某事物共同进行，或表示随着某动作同时发生。接续：名词＋と一緒に。', '注意与「に伴って」的区别，「と一緒に」更强调共同性，而「に伴って」强调因果关系。', '友達と一緒に映画を見に行った。；说明：和朋友一起去看电影了。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('f59533a0-e5a8-547f-b578-3f9300861d99', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '5b34d8b5-bde9-c4c6-c736-84adaaae3603', '「士」「史」「始」等「し」同音汉字的读音与词义区分', '「し」读音的汉字极多，如「士（し）」「史（し）」「始（し）」「氏（し）」「紙（し）」等。本知识点聚焦N1常见词语中这些汉字的区分。', '学习者容易将「歴史」误写为「歴士」，或将「開始」与「開史」混淆；需注意「士」表示人士，「史」表示历史，「始」表示开始。', E'日语例句：歴史（れきし）を学ぶ。；说明：「史」读「し」，表示历史。\\n日语例句：開始（かいし）の合図。；说明：「始」读「し」，表示开始。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('f5b587cf-f418-52e9-83c5-de667a4d735f', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', 'baa9b5c2-5b94-4f9b-7ced-3a8c3cde4cb3', '外来语的缩略形式', '掌握常见外来语缩略词，如「パソコン（パーソナルコンピューター）」「スマホ（スマートフォン）」，理解其构成和用法。', '不认识缩略词，或把缩略词误认为完整词；随意创造不存在的缩略。', '日语例句：スマホで写真を撮る。；说明：「スマホ」是「スマートフォン」的缩略，日常口语常用。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('f5d3d826-3848-5111-bd4d-fec1c4f3f0f6', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '5b34d8b5-bde9-c4c6-c736-84adaaae3603', '「まるで」与「全然」的用法区分', '「まるで」常与「ようだ」「みたい」搭配，表示“简直像”；也可与否定呼应表示“完全不”。「全然」多与否定或口语肯定搭配，表示“完全”。', '「まるで」后直接接名词时需加「の」；「全然」在正式书面语中避免用于肯定。', '日语例句：まるで夢のようだ。；说明：意为“简直像梦一样”。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('f5dde26e-f87f-5d45-9e0a-379da2568c60', '9221fc32-a051-42cb-86b1-6a9917aa004e', '42de0c7b-50d9-4159-918a-4e618d83342d', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '0e03a921-5aff-e4be-f477-4d55640b198b', '场所类外来语', '掌握ホテル、レストラン、デパート、スーパー等场所名词的片假名表记和读音。', '将「デパート」写成「デパートメント」；混淆「スーパー」和「マーケット」。', '駅の近くにレストランがあります。说明：「レストラン」指西餐厅。／デパートで買い物をします。说明：「デパート」指百货商店。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('f5eef38e-edc3-5d1f-bd70-a23428015a85', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '1d183755-02b3-4a6d-b727-082af1ef377c', '6f1477f5-00be-f963-76b6-5165f568e88e', '因果标记阅读', '识别“～ため”“～ので”“～から”“～によって”等因果标记，明确原因和结果，理解事件之间的逻辑链条。', '将因果关系与时间顺序混淆，或忽略多因一果的情况。', '日语例句：台風が近づいているため、明日の試合は中止になった。说明：“ため”前为原因，后为结果。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('f60335ec-1d9a-5921-b6b8-f40903a0f030', '9221fc32-a051-42cb-86b1-6a9917aa004e', '42de0c7b-50d9-4159-918a-4e618d83342d', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', 'ef36118d-0ba3-29ce-b2b3-76eaeb6542ca', 'ば（条件）', '动词ば形（假定形+ば）表示条件，后件可为意志或建议。接续：动词ば形。', '与と混淆；五段动词ば形变化错误（如書けば）。', '安ければ買います。说明：如果便宜就买。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('f62c0a7f-cd97-591c-989b-aa2ec46891d0', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '3760dfca-44d9-3445-01cd-85de1f860da1', '～ように気をつける', '表示注意、小心做某事，相当于“注意…”。接动词辞书形/ない形。', '与「～ようにする」混淆；误用为一般习惯。', '事故を起こさないように気をつけてください。说明：请注意不要引发事故。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('f6500f13-4fe9-5f26-8ad2-210182ee778f', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '5b34d8b5-bde9-c4c6-c736-84adaaae3603', '「最」的多种读音与词义', '「最」在N1中常见读音「さい」，词义包括“最、极”“首先”等。如「最中（さなか）」「最寄り（もより）」「最優先（さいゆうせん）」「最悪（さいあく）」「最善（さいぜん）」。', '「最中」读「さなか」而非「さいちゅう」（后者也有但N1常考前者）；「最寄り」读「もより」而非「さいより」。', '会議の最中（さなか）に電話が鳴った。说明：最中指正在进行中。；最寄り（もより）の駅はどこですか。说明：最寄り指最近的。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('f66e0d55-cedd-5806-b885-a6e2504f590e', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', 'baa9b5c2-5b94-4f9b-7ced-3a8c3cde4cb3', '二字汉字复合词音读的规则与例外', '多数二字词用音读，但存在熟字训和特殊读音，需积累常见例外。', '将所有二字词都读音读，忽略「時計（とけい）」「今日（きょう）」等特殊读音。', '学校（がっこう）；時計（とけい）；说明：前者音读，后者为熟字训。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('f6a6bc2b-656c-55c8-ab0b-cd068fd6a49c', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '1d183755-02b3-4a6d-b727-082af1ef377c', '6f1477f5-00be-f963-76b6-5165f568e88e', '指示词连锁指代', '理解文中“それ”“この”“その”等指示词可能指代前文某个短语、句子甚至多个句子，并能追踪指代链条。', '只按就近原则找指代，忽略指代对象可能是整个段落或隐含内容。', '日语例句：彼は毎日練習を続けた。しかし、その努力が実るまでには時間がかかった。说明：“その努力”指代前句的“毎日練習を続けた”这一行为。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('f6a960b6-6f93-5242-bf28-960b043cbc50', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '1d183755-02b3-4a6d-b727-082af1ef377c', '40ed56d1-acbd-4a8b-6284-2df8b9423e8e', '段落大意概括与选项匹配', '在阅读题中，针对某一段落，从多个选项中选出最准确概括其中心意思的一项，排除过宽、过窄或偏离的选项。', '选择包含段落中细节但非中心的选项；选择范围超出段落内容的选项；被选项中的原文词句迷惑而忽略整体。', '日语例句：段落主要讲“睡眠不足对记忆的影响”，选项A说“睡眠不足会导致记忆力下降”，选项B说“睡眠很重要”。说明：A更贴合段落具体内容，B过于宽泛。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('f6d691a2-036f-5753-b81b-d20f9b5663dc', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', 'dd4e968a-3d37-98a7-3819-a5fc4c117122', '～てもいいですよね（许可・确认）', '表示“可以……吧？”，用于向对方确认许可，比～てもいいよね更礼貌。', '误用为直接请求，实际是确认；注意与～てもいいですか的区别。', '日本語：ここに座ってもいいですよね。；说明：坐这里可以吧？', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('f6e8232e-0485-5a09-ab6b-1f3208e9ec32', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '1d183755-02b3-4a6d-b727-082af1ef377c', '40ed56d1-acbd-4a8b-6284-2df8b9423e8e', '定义与例证关系理解', '在说明文中，识别概念定义与后续举例之间的对应关系，理解例子如何支撑或阐释定义。', '将例子内容误当作定义本身；忽略例子中的限定条件；无法判断例子与定义是否匹配。', '日语例句：「ペット」とは家族のように飼う動物のことだ。例えば、犬や猫がそれにあたる。说明：定义是“像家人一样饲养的动物”，例子犬猫具体化该定义，需注意例子并非定义的全部。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('f6eec2e6-6944-599a-9d6b-6d4635a2fe4d', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '3760dfca-44d9-3445-01cd-85de1f860da1', '～てある', '表示动作结果的存续，通常用于说明某物处于被做过的状态。', '注意「～てある」的主语是物，动词用他动词，且常与「が」搭配；「～ておく」则强调动作本身。', '壁に絵が掛けてある。；说明：墙上挂着画（有人挂的）。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('f70788fc-2341-5f24-9517-26a955979a12', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '1af448c1-54cf-2f94-01b5-e8bc77a97f94', '～なければならない（义务）', '表示必须、不得不做某事。接续：动词ない形+なければならない。口语中常省略为～なきゃならない/～なくちゃ。', '与～てはいけない（禁止）对应。注意～なければならない侧重客观义务，～べきだ侧重主观建议。', '日本語：毎日薬を飲まなければなりません。；说明：表示“必须每天吃药”，强调义务。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('f8073b46-58d0-58e2-a232-d9533b66a9c7', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', 'baa9b5c2-5b94-4f9b-7ced-3a8c3cde4cb3', '动词与同源名词的读音与表记区分', '同一汉字词既可作动词（带送假名）又可作名词（无送假名或不同送假名），如「話す（はなす）」与「話（はなし）」、「帰る（かえる）」与「帰り（かえり）」、「休む（やすむ）」与「休み（やすみ）」。需掌握其读音、表记及在句中的词性功能。', '将动词的ます形（如「話し」）误当作名词使用；混淆「帰り」与「帰る」的读音；把「休み」写成「休み」时误读为「やすみ」以外的音。', '日语例句：話を聞いてください。；说明：「話」是名词，读「はなし」，与动词「話す（はなす）」读音不同。日语例句：帰りにスーパーに寄った。；说明：「帰り」是名词，读「かえり」，表示归途。日语例句：明日は休みです。；说明：「休み」是名词，读「やすみ」，表示休息日。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('f83aca04-15a7-5215-ac67-cdd8aa049762', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '5b34d8b5-bde9-c4c6-c736-84adaaae3603', '「少し」与「少ない」的词性区分', '「少し」是副词/名词，表示“少量”；「少ない」是形容词，表示“数量少”。', '将「少ない」当副词使用；「少し」不能直接修饰名词需加「の」。', '日语例句：時間が少ない。；说明：表示“时间少”，用形容词。「少し待ってください。」；说明：表示“稍等”，用副词。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('f869e7ed-05ce-575f-89fe-ec8161737427', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', 'ff057d86-47bc-de16-f0f9-a7b808b968e3', '使役被动形的构成与含义', '理解N3中使役被动形（如「行かされる」「食べさせられる」）的构成，表示被迫做某事，并掌握其用法。', '将使役被动形与普通被动形混淆；忽视动词的变形规则，如五段动词的「～される」与「～させられる」区别。', '日语例句：子供の頃、ピアノを練習させられた。；说明：させられる表示被迫练习。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('f8755d82-b046-5ead-8e5a-b58a62145219', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '5b34d8b5-bde9-c4c6-c736-84adaaae3603', '「一番」与「最も」的语体区分', '「一番」口语常用，可作副词或名词；「最も」书面语，只能作副词，表示“最”。', '在学术论文中误用「一番」；「最も」不能用于口语寒暄。', '日语例句：これは最も重要な問題だ。；说明：书面语“这是最重要的问题”。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('f8aa93ee-ec72-5833-838a-f6668ced74fd', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', 'dd4e968a-3d37-98a7-3819-a5fc4c117122', '～てある（有意留下的状态）', '表示某人有意做某动作后，其结果状态持续存在，常与场所、对象搭配，暗示有人为因素。', '与～ている混淆，～てある强调人为安排，～ている只表状态。', '日本語：窓が開けてある。；说明：窗户被（某人）打开着，强调人为。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('f90836e9-2d28-57d5-a169-a18e207ce6fb', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '1af448c1-54cf-2f94-01b5-e8bc77a97f94', '～ことがある（有时）', '接动词辞书形或ない形，表示“有时会…”。', '与～たことがある（经历）混淆；注意接续不同。', '時々、朝ごはんを食べないことがあります。（有时不吃早饭。）／この道は混むことがある。（这条路有时会堵。）', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('f9581439-1740-5ad4-a4b3-e1becb1ef33f', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '2c18e7e1-4ef0-65e3-24a7-6c97d562a122', '～を限りにして', '表示“以～为最后界限”，后接终止或改变。接名词。', '与「～を限りに」混淆，后者更强调“以～为限”；此句型强调“从此不再”。', '今日を限りにして、タバコをやめるつもりだ。；说明：以今天为界，我打算戒烟。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('fa377161-31a5-5271-84f1-7e1ac7457af2', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', 'dd4e968a-3d37-98a7-3819-a5fc4c117122', '～てほしい（希望别人做）', '表示说话人希望对方或他人做某事。接续：动词て形+ほしい。', '与～たい（自己想要）区别；～てほしい的对象用に；不用于对长辈直接要求。', '日本語：もっと早く来てほしいです。；说明：希望你早点来。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('fa4e8564-3e7f-572c-b50f-1ff9a0b68d43', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', 'e9d41203-7c2c-514e-a3a3-f1dbdcd3aaaa', '词语搭配与语境', '掌握高频词汇在具体句型和生活场景中的自然用法。', '知道单词意思，却不能判断与动词、助词或场景的搭配。', '薬を飲んで、早く寝ます。', 'published', '2026-09-03 13:10:31.032213+08', '2026-09-03 13:10:31.032213+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('fa7c34b3-a420-5143-bfef-d8ba6c4d5aef', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', 'dd4e968a-3d37-98a7-3819-a5fc4c117122', '～てさしあげる（为长辈做・谦逊）', '～てあげる的谦逊语，用于为长辈或上级做某事，表示敬意。接续：动词て形＋さしあげる。', '对平辈或晚辈使用显得过于郑重；现代口语中较少使用，常被～てあげる替代；误用为～ていただく。', 'お客様にお茶を入れてさしあげました。说明：我给客人沏了茶。／部長に資料を渡してさしあげた。说明：我把资料交给了部长。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('fa8384fe-273b-5fab-9ab4-484d0cc0f91c', '9221fc32-a051-42cb-86b1-6a9917aa004e', '42de0c7b-50d9-4159-918a-4e618d83342d', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '0e03a921-5aff-e4be-f477-4d55640b198b', '成对物品的量词「足」「組」', '掌握「足（そく）」用于数鞋、袜等成对物品，如一足（いっそく）、二足（にそく）；「組（くみ）」用于数成套物品或组，如一組（いちくみ）、二組（にくみ）。', '用「個」数鞋；将「一足」读作「いちそく」；将「組」与「足」混淆。', '日本語：靴を一足買いました。；说明：一足读作「いっそく」。日本語：靴下を二足ください。；说明：二足读作「にそく」。日本語：このクラスは三組です。；说明：三組读作「さんくみ」。)', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('fa90e2ca-845d-54b5-8392-e91236c67e1b', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', 'baa9b5c2-5b94-4f9b-7ced-3a8c3cde4cb3', '常用复合名词的读音与表记', 'N4阶段常见的二字或三字复合名词，如「電車」「地下鉄」「新聞」「映画館」等，需掌握其音读或训读组合规则及特殊读音。', '将训读与音读混用，如把「手紙」读成「てがみ」以外的音；忽略促音或长音变化，如「学校（がっこう）」的促音。', '日语例句：駅の近くに新しい映画館があります。；说明：「映画館（えいがかん）」是音读复合词，注意「館」读「かん」。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('fac5189b-28bc-5ecd-9903-cdf8502c21a5', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', 'baa9b5c2-5b94-4f9b-7ced-3a8c3cde4cb3', '动词的汉字读音与送假名', '掌握N4常见动词的汉字写法与送假名，如「食べる」「見る」「来る」等，注意同音异字动词的区分。', '混淆「開く」与「空く」的读音和意义；忘记送假名导致读音错误。', '日语例句：ドアを開けます。；说明：「開ける」是他动词，读作「あける」，注意与自动词「開く（あく）」区分。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('fadffc80-4a3d-5fea-a642-37d7080e9a96', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '1d183755-02b3-4a6d-b727-082af1ef377c', '40ed56d1-acbd-4a8b-6284-2df8b9423e8e', '对话中说话人身份判断', '在多人对话或引语中，根据上下文、称呼、语气、敬语使用等线索，判断某句话是谁说的，以及说话人之间的关系。', '忽略敬语和称呼线索；混淆“私”所指代的人物；在间接引语中误判转述者。', '日语例句：「先生、これ、どうぞ」と彼は言った。先生は「ありがとう」と微笑んだ。说明：通过“先生”和“どうぞ”可判断前句是学生对老师说的，后句是老师的回应。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('fb029bcf-2bf4-5444-b92a-25ac59e9a96a', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '5b34d8b5-bde9-c4c6-c736-84adaaae3603', '「確か」的确认与推测用法', '掌握「確か」作为副词表示“记得、大概”的推测。', '与「確かに」混淆，后者表示确实。', '日本語：確か明日は休みです。；说明：记得明天是休息日。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('fb090d1b-2052-5e63-b46b-7b875acb5677', '9221fc32-a051-42cb-86b1-6a9917aa004e', '42de0c7b-50d9-4159-918a-4e618d83342d', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', 'ef36118d-0ba3-29ce-b2b3-76eaeb6542ca', 'ている（进行/状态）', '动词て形+いる表示动作正在进行或动作结果的状态持续。接续：て形+いる。', '将瞬间动词（如結婚する）的ている误用为进行，实际表示状态。', '今本を読んでいます。说明：正在读书；もう結婚しています。说明：已经结婚（状态）。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('fb2661ce-7fc4-58f1-9ea7-8cc1313e29bc', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '2c18e7e1-4ef0-65e3-24a7-6c97d562a122', '～をもってすれば', '表示“如果用～的话（就能做到）”，后接可能或成功的结果，带有条件假设语气。接名词。', '与「～をもって」混淆，后者表示手段或时间界限；此句型强调条件性。', '彼の実力をもってすれば、この問題は簡単に解けるだろう。；说明：用他的实力的话，问题就能解决。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('fb44585e-7f85-576c-bb69-5067e947d497', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '2c18e7e1-4ef0-65e3-24a7-6c97d562a122', '～にかけても', '表示“即使以…为赌注、即使拼上…”，强调决心。接续：名词+にかけても。', '较少用，注意与「～にかけては」区分。', '命にかけても、この約束は守る。说明：拼上性命也要守约。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('fb782560-12ca-5168-a436-a91325e3c6de', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', 'dd4e968a-3d37-98a7-3819-a5fc4c117122', '～てはいけません（不可以…・正式）', '正式场合的禁止表达，比～てはいけない更礼貌。接续：动词て形＋は＋いけません。', '在口语中显得过于生硬；误用为～てはなりません（更书面）；与～てもいいですか混淆。', 'ここでたばこを吸ってはいけません。说明：这里不可以吸烟。／携帯電話を使ってはいけません。说明：不可以使用手机。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('fb811a6f-1991-5fe7-8c59-180fe2690543', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '2c18e7e1-4ef0-65e3-24a7-6c97d562a122', '～に対しては', '表示针对特定对象或情况时的处理方式，强调对比或限定。相当于「～については」但更强调动作指向。', '与「～に対して」相比，「に対しては」有对比或强调的语感，常用于提出不同意见时。', '日本語：上司に対しては、いつも敬語を使うようにしている。；说明：对上司，我总是使用敬语。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('fb8e5bd5-4522-595b-abde-7dfb26861ccf', '9221fc32-a051-42cb-86b1-6a9917aa004e', '3d5ec24b-5bbc-4943-ac55-004cdeb0232c', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '1af448c1-54cf-2f94-01b5-e8bc77a97f94', '～ているところ（正在进行）', '表示动作正在进行中。接续：动词て形＋いるところ。强调“正处于…的阶段”。与「～ている」相比，更突出“进行中”的时点。', '「～ている」可表示状态或习惯，而「～ているところ」只表示动作进行中，且常与「今」「ちょうど」搭配。', '日本語例：今、食事をしているところです。；说明：现在正在吃饭。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('fc2cb51f-0b81-5724-979f-e4dd92c08f2f', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '5b34d8b5-bde9-c4c6-c736-84adaaae3603', '「拠点」与「基地」的用法区分', '「拠点」指活动或发展的根据地，可抽象；「基地」多指军事或具体设施。N1需根据语境选择。', '将「拠点」用于军事设施；混淆「拠点」与「本拠」的语感。', 'この都市は経済活動の拠点だ。（这个城市是经济活动的据点）说明：「拠点」抽象。／米軍基地が沖縄にある。（美军基地在冲绳）说明：「基地」具体。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('fc818f04-f028-57cd-8add-42eb3a31785b', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', 'baa9b5c2-5b94-4f9b-7ced-3a8c3cde4cb3', '近义词的正式与口语语感差异', '区分意思相近但语体不同的词，如「たくさん」与「多く」、「とても」与「非常に」，在会话和文章中选择合适表达。', '在正式场合使用过于口语化的词，或在口语中显得生硬；忽略语感差异。', '日语例句：非常に残念です。；说明：「非常に」比「とても」正式，用于书面或郑重场合。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('fcee863d-c0e8-581b-afb4-fea95bee91d4', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '0545d0ec-89d1-a8aa-99f9-78b30fcbacb1', '身体部位惯用表达中表示态度与能力的用法', 'N2中如「顔が広い」（交际广）、「手が足りない」（人手不足）、「頭が切れる」（头脑灵活）等，需整体记忆。', '按字面意思理解，导致误用。', '例句：彼は顔が広い。说明：交际广。；例句：今、手が足りない。说明：人手不足。；例句：彼女は頭が切れる。说明：头脑灵活。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('fd09efd9-03d2-5fbc-a0e5-e7775863df26', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '5b34d8b5-bde9-c4c6-c736-84adaaae3603', '「趣」的多种读音与词义', '「趣」在N1中常见读音有「おもむき」「しゅ」等。「おもむき」表示趣味、韵味、旨趣；「しゅ」用于「趣旨（しゅし）」等复合词。需根据语境判断读音与含义。', '误将「趣旨」读作「おもむきし」；混淆「趣」与「興味」的用法。', 'この庭園は趣（おもむき）がある。；说明：表示有韵味。／会議の趣旨（しゅし）を説明する。；说明：表示宗旨。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('fd2e5e11-1a51-57ef-8dd9-8c677092c47e', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '1d183755-02b3-4a6d-b727-082af1ef377c', '6f1477f5-00be-f963-76b6-5165f568e88e', '因果关系理解', '识别文章中事件之间的因果链条，区分直接原因与间接原因。', '混淆原因和结果；忽略多重原因中的主次。', '日语例句：交通渋滞がひどくなったのは、車の台数が増えたからだ。说明：明确原因在前，结果在后。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('fd501ebb-6d66-5d4b-8100-a6d5c203ef43', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', 'dd4e968a-3d37-98a7-3819-a5fc4c117122', '～たことがある（经历）', '表示“曾经做过……”，接续：动词た形+ことがある。', '与～たばかり混淆，～たことがある强调经验，～たばかり强调刚完成。', '日本語：富士山に登ったことがあります。；说明：曾经登过富士山。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('fdd4976d-06ce-5403-afed-3a977c40e047', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', 'baa9b5c2-5b94-4f9b-7ced-3a8c3cde4cb3', '动词汉字读音与送假名的对应关系', 'N4阶段常见动词的汉字写法与送假名（送り仮名）对应关系，如「帰る（かえる）」「決める（きめる）」「始まる（はじまる）」等。掌握送假名有助于正确读音和书写。', '容易将送假名写错或漏写，如把「帰る」写成「帰る」以外的形式；混淆同汉字不同送假名的动词（如「決める」与「決まる」）。', '日语例句：毎日七時に家を出ます。；说明：「出ます」的原形是「出る」，送假名为「る」，读音为「でる」，注意与「出す（だす）」区分。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('fdf1f954-8c21-5a5a-ac69-a75982102692', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', 'dd4e968a-3d37-98a7-3819-a5fc4c117122', '～と（条件・习惯）', '表示恒常条件、习惯、发现等，当前句成立时后句必然或自然发生。接续：动词辞书形/ない形+と。', '与～ば、～たら区别：～と后句不能是意志、命令、请求；常用于自然现象或习惯。', '日本語：春になると、花が咲きます。；说明：一到春天花就开。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('fe07b6f9-7c66-5c42-a196-2fd2836ffd8d', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '3760dfca-44d9-3445-01cd-85de1f860da1', '～てならない', '表示无法抑制的心情或感觉，相当于“……得不得了”“不由得……”。接形容词て形或动词て形。', '误用于一般程度；注意与“～てたまらない”区别，后者更强调生理感受。', '日语例句：彼のことが心配でならない。；说明：不由得担心他。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('fe6cf1bc-7a81-550f-bd6d-ec9be3d50bc4', '9221fc32-a051-42cb-86b1-6a9917aa004e', '42de0c7b-50d9-4159-918a-4e618d83342d', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', 'ef36118d-0ba3-29ce-b2b3-76eaeb6542ca', '～てみる（尝试做）', '动词て形+みる表示尝试做某事，含有“试试看”的意思。注意「みる」在此为补助动词，不写汉字「見る」。', '将「みる」写成汉字「見る」；与「～ておく」混淆；在否定形式「てみない」中误用。', 'この料理を食べてみてください。；说明：请尝尝这道菜。／新しい方法を試してみます。；说明：我试试新方法。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('fe76f0b3-4a5b-5a8b-beb4-9b43d9e1dfe7', '9221fc32-a051-42cb-86b1-6a9917aa004e', '04919166-9568-470c-85d9-c0e320a81378', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', 'dd4e968a-3d37-98a7-3819-a5fc4c117122', '～たあとで（之后）', '表示在某动作完成之后做另一件事，时间间隔可长可短。接续：动词た形+あとで。', '与～てから相比，～たあとで不强调紧接着，也可用于已发生的事；注意不要用辞书形接续。', '日本語：仕事が終わったあとで、映画を見に行きました。；说明：工作结束后去看了电影，不强调紧接。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('fec90183-3804-524e-8e79-1e7a1a51cac1', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '4ce71c86-4fc8-4b25-9556-5859c3e16a93', '0545d0ec-89d1-a8aa-99f9-78b30fcbacb1', '复合动词中汉字部分的读音与送假名', 'N2需掌握复合动词中前项或后项为汉字词时的读音，如「見直す（みなおす）」「話し合う（はなしあう）」「読み取る（よみとる）」。汉字部分可能为音读或训读，送假名影响活用。', '学习者常将「見直す」误读为「けんちょくす」，或混淆「読み取る」与「読取る」的读音。', '日语例句：計画を見直す必要がある。；说明：「見直す」中「見」训读「み」，「直す」训读「なおす」，整体读「みなおす」。日语例句：データを読み取る。；说明：「読み取る」中「読」训读「よ」，「取る」训读「とる」，读「よみとる」。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('ff447a1d-0289-54c6-9615-82d852eb5f15', '9221fc32-a051-42cb-86b1-6a9917aa004e', 'b15048a9-c286-4f5b-b511-c24dfcfba713', '1d183755-02b3-4a6d-b727-082af1ef377c', '9c37478d-2388-1380-cdea-3b62d82c3fcb', '意见的转折与修正', '把握文章中作者或说话人意见在中途发生转折、修正或部分撤回的阅读能力。注意转折词如「だが」「しかし」「ところが」以及表示修正的「いや」「むしろ」「というより」等，理解前后意见的变化及其理由。', '只关注转折后的内容而忽略转折前的铺垫，或把修正当作完全否定，未能区分部分修正与全面推翻。', '日语例句：当初はこの案に賛成だったが、実行可能性を考えると、やはり反対せざるを得ない。；说明：前半表示赞成，后半用「が」转折，表明最终意见为反对，需把握意见的转变过程。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status, created_at, updated_at) VALUES ('ff4652b2-af85-50b5-9f56-49202ef1372c', '9221fc32-a051-42cb-86b1-6a9917aa004e', '41a0bfe6-192b-4e9a-9d8b-3f88d22f952f', '23a7b19c-356f-4b45-ae10-a0ebf8f52fa8', '3760dfca-44d9-3445-01cd-85de1f860da1', '～ようにいう風に', '表示“像…那样地”，用于比喻或举例。接动词辞书形/ない形。', '与「～ように」混淆；误用为直接比较。', '彼はまるで鳥のようにいう風に飛んだ。说明：他像鸟一样地飞了。', 'published', '2026-09-03 18:34:09.824405+08', '2026-09-03 18:39:39.374133+08') ON CONFLICT (id) DO NOTHING;
